-- Gerado por scripts/import-questoes.ts. Não editar à mão.
insert into public.questoes (id_planilha, tipo, simulado_numero, numero_na_prova, area, subtema, dificuldade, ano_origem, fonte, enunciado, alternativa_a, alternativa_b, alternativa_c, alternativa_d, resposta_correta, comentario_correta, comentario_erros, status, tabela_dados, grafico_svg, imagens)
values
  ('SIM1-001', 'simulado', '1', '1', 'Clínica Médica', 'Síndrome coronariana aguda (IAMCSST)', 'Difícil', null, null, 'Homem de 62 anos, tabagista, hipertenso em uso irregular de losartana, procura o pronto-socorro com dor precordial em aperto, de forte intensidade, iniciada há 90 minutos enquanto subia uma escada, irradiando para o braço esquerdo e mandíbula, associada a sudorese fria e náuseas. Refere dois episódios semelhantes, de menor intensidade, nas últimas 48 horas, que cederam espontaneamente em poucos minutos. Ao exame: PA 148x94mmHg, FC 102bpm, ausculta cardíaca sem sopros, estertores finos em base pulmonar esquerda. O ECG mostra supradesnivelamento do segmento ST de 3mm em V2-V4. É solicitada dosagem seriada de troponina, cujo resultado é mostrado a seguir.

Diante do quadro clínico e eletrocardiográfico, a conduta mais adequada é', 'Iniciar terapia de reperfusão imediata (angioplastia primária ou trombólise, conforme o tempo porta-balão disponível)', 'Solicitar ecocardiograma transtorácico antes de qualquer decisão terapêutica', 'Prescrever apenas dupla antiagregação plaquetária e observação em leito monitorado por 24 horas', 'Aguardar o resultado da segunda dosagem de troponina antes de definir a estratégia de reperfusão', 'A', 'O quadro é de infarto agudo do miocárdio com supradesnivelamento de ST (IAMCSST): diagnóstico clínico-eletrocardiográfico, não se aguarda troponina para decidir reperfusão. A prioridade é restaurar o fluxo coronariano o mais rápido possível.', 'B: ecocardiograma não deve atrasar a reperfusão em IAMCSST. C: antiagregação isolada não trata a oclusão coronariana já estabelecida. D: atrasar a reperfusão aguardando exame laboratorial aumenta a área de necrose miocárdica sem necessidade — o ECG já fecha o diagnóstico.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-002', 'simulado', '1', '2', 'Clínica Médica', 'Pneumonia adquirida na comunidade', 'Médio', null, null, 'Paciente de 45 anos, previamente hígido, procura a UBS com tosse produtiva, febre de 38,5°C há 3 dias e dispneia leve aos esforços moderados iniciada nas últimas 24 horas. Nega dor torácica pleurítica ou confusão mental. Trabalha como professor e relata que dois colegas de trabalho apresentaram quadro respiratório semelhante recentemente. Ao exame físico: orientado, corado, hidratado; FR 22irpm; PA 118x76mmHg; FC 92bpm; saturação 95% em ar ambiente; estertores crepitantes em base pulmonar direita, sem sinais de derrame associado. Radiografia de tórax confirma consolidação lobar em lobo inferior direito, sem derrame pleural.

Considerando os critérios de gravidade (CURB-65 = 0), a conduta mais adequada é', 'Internação hospitalar para antibioticoterapia intravenosa imediata', 'Tratamento ambulatorial com amoxicilina e reavaliação clínica em 48-72 horas', 'Solicitar tomografia de tórax antes de decidir a conduta terapêutica', 'Encaminhar diretamente para UTI por insuficiência respiratória', 'B', 'CURB-65 = 0 indica baixo risco de mortalidade em 30 dias, permitindo tratamento ambulatorial. Amoxicilina é a primeira escolha para PAC leve em paciente sem comorbidades, com reavaliação em 48-72h para checar resposta clínica.', 'A: internação é desnecessária em baixo risco, aumentando custo e exposição a infecção hospitalar sem benefício adicional. C: TC não é rotina quando a radiografia já confirma o diagnóstico e não há critérios de gravidade. D: saturação preservada e ausência de sinais de gravidade contraindicam UTI.', 'Em revisão', null, null, null),
  ('SIM1-003', 'simulado', '1', '3', 'Clínica Médica', 'Urgência x emergência hipertensiva', 'Médio', null, null, 'Paciente de 62 anos, hipertenso em uso irregular de medicação, comparece à UBS com cefaleia occipital há 2 dias, que piorou progressivamente, sem melhora com analgésico comum. Nega turvação visual, dor torácica, dispneia ou déficit motor. Em duas aferições com intervalo de 15 minutos, a PA se mantém em 200x110mmHg. Ao exame neurológico: orientado, sem déficits focais, sem rigidez de nuca. Fundoscopia sem hemorragias, exsudatos ou papiledema. ECG sem alterações agudas. Função renal e exame de urina dentro da normalidade.

Diante da ausência de sinais de lesão aguda de órgão-alvo, a conduta mais adequada é', 'Encaminhar para internação em UTI para monitorização hemodinâmica contínua', 'Solicitar tomografia de crânio de urgência antes de qualquer conduta terapêutica', 'Ajustar/reiniciar medicação oral, reduzindo a PA gradualmente ao longo de 24-48h, com retorno agendado', 'Reduzir a PA para valores normais em minutos com anti-hipertensivo endovenoso', 'C', 'Trata-se de urgência hipertensiva (PA muito elevada, sem lesão aguda de órgão-alvo confirmada pelos exames): o manejo padrão é redução gradual da PA em 24-48h com medicação oral, evitando quedas abruptas que podem causar hipoperfusão de órgãos.', 'A: não há indicação de UTI sem sinais de emergência. B: sem sinais neurológicos focais ou rigidez de nuca, TC não é obrigatória com urgência. D: redução rápida por via IV é reservada para emergência hipertensiva (com lesão de órgão-alvo), podendo causar isquemia se usada aqui.', 'Em revisão', null, null, null),
  ('SIM1-004', 'simulado', '1', '4', 'Clínica Médica', 'Insuficiência cardíaca descompensada', 'Médio', null, null, 'Paciente de 68 anos, com histórico de insuficiência cardíaca com fração de ejeção reduzida (FEVE 30%) diagnosticada há 3 anos, procura o PS com piora da dispneia aos mínimos esforços, ortopneia de 3 travesseiros e edema de membros inferiores progressivo há 5 dias. Relata ter parado de tomar furosemida há 2 semanas por conta própria. Ao exame: dispneico em repouso, estertores crepitantes bibasais até terço médio, turgência jugular a 45°, refluxo hepatojugular presente, edema de membros inferiores 3+/4+. PA 128x82mmHg, FC 98bpm, saturação 89% em ar ambiente.

A conduta inicial mais adequada é', 'Diurético de alça endovenoso associado a oxigenoterapia e monitorização contínua', 'Alta com reforço da orientação sobre adesão medicamentosa e retorno ambulatorial em 30 dias', 'Betabloqueador em dose plena imediatamente para reduzir a frequência cardíaca', 'Reposição volêmica com cristaloide para melhorar o débito cardíaco', 'A', 'Paciente com sinais claros de congestão (estertores, turgência jugular, refluxo hepatojugular, edema) e hipoxemia necessita de diurético IV para depleção de volume e oxigenoterapia, com monitorização contínua nesse cenário de descompensação aguda.', 'B: sinais de gravidade (hipoxemia, congestão importante) contraindicam alta sem tratamento hospitalar. C: iniciar/aumentar betabloqueador na fase aguda descompensada pode piorar o quadro hemodinâmico; é indicado após estabilização. D: paciente congesto não deve receber volume adicional.', 'Em revisão', null, null, null),
  ('SIM1-005', 'simulado', '1', '5', 'Clínica Médica', 'DPOC - exacerbação aguda', 'Difícil', null, null, 'Paciente de 65 anos, tabagista com carga de 40 maços/ano, portador de DPOC diagnosticado há 6 anos, é trazido ao PS por piora da dispneia, aumento do volume e mudança da coloração do escarro (de esbranquiçado para amarelo-esverdeado) há 3 dias. Faz uso domiciliar de broncodilatador de longa ação. Ao exame: uso de musculatura acessória, sibilos difusos, tempo expiratório prolongado, FR 28irpm, saturação 88% em ar ambiente. É colhida gasometria arterial em ar ambiente:

Considerando o quadro clínico e gasométrico, a conduta mais adequada é', 'Broncodilatador de curta ação, corticoide sistêmico e antibiótico, com oxigenoterapia titulada', 'Apenas broncodilatador de longa ação, aguardando resposta antes de outras medidas', 'Observação em leito comum sem tratamento farmacológico, por se tratar de quadro autolimitado', 'Ventilação mecânica invasiva imediata, independentemente da resposta ao tratamento clínico inicial', 'A', 'Exacerbação de DPOC com aumento do volume e purulência do escarro (critérios de Anthonisen) associada a acidose respiratória hipercápnica indica broncodilatador de curta ação, corticoide sistêmico e antibiótico, com oxigenoterapia cuidadosamente titulada para evitar piora da hipercapnia.', 'B: broncodilatador de longa ação não trata a crise aguda. C: quadro com acidose respiratória e hipoxemia não deve ser apenas observado. D: ventilação invasiva é reservada para falha do tratamento clínico e da ventilação não invasiva.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-006', 'simulado', '1', '6', 'Clínica Médica', 'AVC isquêmico - janela terapêutica', 'Difícil', null, null, 'Paciente de 70 anos é trazido ao PS pela esposa com hemiparesia direita súbita e disartria, com início dos sintomas há exatamente 2 horas, segundo relato confiável e consistente. Nega histórico de sangramento recente, cirurgia de grande porte ou uso de anticoagulante. Glicemia capilar 118mg/dL. PA 172x96mmHg. Ao exame neurológico: hemiparesia direita de predomínio braquial, disartria, sem rebaixamento do nível de consciência. Tomografia de crânio sem contraste não evidencia sinais de hemorragia nem de isquemia estabelecida extensa.

Diante da janela terapêutica e dos achados de imagem, a conduta mais adequada é', 'Indicar craniotomia descompressiva de urgência como primeira conduta', 'Aguardar reavaliação em 24 horas para repetir a tomografia antes de definir tratamento', 'Iniciar anticoagulação plena imediatamente, independentemente de outros exames', 'Avaliar critérios de elegibilidade e considerar trombólise endovenosa', 'D', 'Dentro da janela de até 4,5 horas do início dos sintomas, com TC excluindo hemorragia, deve-se avaliar critérios de elegibilidade (contraindicações, tempo, gravidade do déficit) para trombólise endovenosa, tratamento capaz de reduzir sequelas no AVC isquêmico.', 'A: craniotomia descompressiva é reservada para casos específicos de edema maligno, não é conduta inicial. B: atraso reduz a janela terapêutica e a eficácia do tratamento. C: anticoagulação plena não é a conduta inicial no AVC isquêmico agudo, podendo aumentar risco de transformação hemorrágica.', 'Em revisão', null, null, null),
  ('SIM1-007', 'simulado', '1', '7', 'Clínica Médica', 'Hipotireoidismo - diagnóstico e tratamento', 'Médio', null, null, 'Mulher de 68 anos, com diagnóstico prévio de hipotireoidismo há 8 anos, em uso irregular de levotiroxina 75mcg/dia, é trazida pela filha à UBS por relato de piora progressiva de fadiga, ganho de peso de 6kg e constipação intensa nos últimos 4 meses. A filha relata que a mãe também está mais lentificada no raciocínio e com voz mais rouca. Nega dor torácica ou dispneia. Ao exame físico: bradicárdica (52bpm), pele seca e fria, edema periorbital, reflexo aquileu com relaxamento lentificado. Os exames laboratoriais atuais, comparados aos de 6 meses atrás (já em uso irregular da medicação), são mostrados a seguir.

Considerando a evolução laboratorial e clínica, a conduta mais adequada é', 'Solicitar apenas ultrassonografia de tireoide antes de qualquer ajuste terapêutico', 'Suspender a levotiroxina e iniciar propiltiouracila para controle dos sintomas', 'Reforçar a importância da adesão à levotiroxina na dose atual e reavaliar em 6 meses', 'Ajustar a dose de levotiroxina conforme o peso, reforçar a adesão e reavaliar TSH em 6-8 semanas', 'D', 'A piora clínica e laboratorial (TSH em elevação acentuada, T4 livre em queda) reflete hipotireoidismo primário não controlado, provavelmente por má adesão; a conduta é ajustar a dose de levotiroxina ao peso da paciente, reforçar a adesão e reavaliar TSH em 6-8 semanas.', 'A: USG não é necessária para o manejo do hipotireoidismo primário sem nódulos palpáveis. B: propiltiouracila trata hipertireoidismo, não hipotireoidismo — conduta oposta à indicada. C: manter a mesma dose sem ajuste não corrige um quadro já claramente descompensado.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-008', 'simulado', '1', '8', 'Clínica Médica', 'Doença renal crônica - estadiamento', 'Médio', null, null, 'Paciente de 60 anos, diabético e hipertenso há 15 anos, em acompanhamento irregular na UBS, comparece para revisão de exames de rotina. Nega edema, dispneia ou alteração do volume urinário. Está em uso de losartana e metformina. Ao exame: PA 148x90mmHg, sem edema, restante do exame físico sem alterações. Traz dois exames de creatinina realizados com intervalo de 4 meses, ambos com cálculo de taxa de filtração glomerular estimada (TFGe), além de albuminúria atual moderadamente elevada.

Considerando a evolução laboratorial apresentada, a classificação e conduta mais adequadas são', 'Insuficiência renal aguda; suspender toda a medicação em uso imediatamente', 'DRC estágio 5; iniciar diálise imediatamente, independentemente de sintomas', 'Função renal normal para a idade; não é necessária nenhuma conduta específica', 'DRC estágio 3b; controle rigoroso de pressão arterial e glicemia, com encaminhamento ao nefrologista', 'D', 'TFGe entre 30-44 mL/min/1,73m² confirmada em duas medições com intervalo maior que 3 meses caracteriza DRC estágio 3b; a conduta envolve controle rigoroso dos fatores de progressão (PA, glicemia) e encaminhamento para acompanhamento especializado.', 'A: a alteração é crônica (persistente por mais de 3 meses), não aguda; suspender toda a medicação sem avaliação é inadequado. B: estágio 5 corresponde a TFGe <15 mL/min/1,73m², bem abaixo do valor apresentado. C: TFGe reduzida de forma persistente e albuminúria elevada não são achados normais para a idade e requerem conduta ativa.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-009', 'simulado', '1', '9', 'Clínica Médica', 'Tuberculose - tratamento', 'Fácil', null, null, 'Paciente de 35 anos, morador de área de alta vulnerabilidade social, procura a UBS com tosse produtiva há 4 semanas, febre vespertina, sudorese noturna e emagrecimento de 5kg no período. Nega histórico prévio de tuberculose ou contato conhecido com caso ativo. Ao exame: emagrecido, afebril no momento da consulta, ausculta pulmonar com estertores em ápice pulmonar direito. Radiografia de tórax mostra cavitação em lobo superior direito. Baciloscopia de escarro positiva para BAAR, sem realização de teste de sensibilidade à rifampicina disponível no momento.

O esquema terapêutico inicial mais adequado, segundo o protocolo do Ministério da Saúde, é', 'Amoxicilina com ácido clavulânico por 14 dias', 'Isoniazida isolada por 6 meses', 'Esquema básico com rifampicina, isoniazida, pirazinamida e etambutol por 2 meses, seguido de rifampicina e isoniazida por 4 meses', 'Apenas repouso domiciliar e acompanhamento clínico, sem antibioticoterapia', 'C', 'O esquema básico para tuberculose pulmonar no Brasil é RIPE (rifampicina, isoniazida, pirazinamida, etambutol) por 2 meses na fase intensiva, seguido de rifampicina e isoniazida por mais 4 meses na fase de manutenção, totalizando 6 meses.', 'A: antibiótico de amplo espectro comum não trata tuberculose, que requer esquema específico contra micobactérias. B: isoniazida isolada é usada para tratamento de infecção latente, não de tuberculose ativa. D: tuberculose ativa exige tratamento antimicrobiano específico, não apenas suporte.', 'Em revisão', null, null, null),
  ('SIM1-010', 'simulado', '1', '10', 'Clínica Médica', 'HIV - profilaxia pós-exposição', 'Médio', null, null, 'Técnica de enfermagem de 29 anos sofre acidente com agulha usada em paciente com sorologia positiva para HIV há 45 minutos, durante coleta de sangue. A agulha estava visivelmente contaminada com sangue e a lesão foi profunda, com sangramento espontâneo. A profissional não sabe informar a carga viral do paciente-fonte nem se ele está em tratamento antirretroviral regular. Procura o serviço de saúde ocupacional imediatamente após o acidente, assustada e questionando se deve aguardar resultado de exames antes de qualquer conduta.

A conduta mais adequada nesse momento é', 'Aguardar o resultado da sorologia da profissional antes de iniciar qualquer medida', 'Não iniciar profilaxia, pois a carga viral do paciente-fonte é desconhecida', 'Iniciar profilaxia pós-exposição (PEP) o mais rápido possível, idealmente nas primeiras 2 horas, e coletar sorologias basais em seguida', 'Iniciar profilaxia apenas se a profissional apresentar sintomas de infecção aguda pelo HIV', 'C', 'A profilaxia pós-exposição ao HIV deve ser iniciada o quanto antes, idealmente nas primeiras 2 horas, com eficácia decrescente até o limite de 72 horas — a exposição percutânea profunda com sangramento é classificada como de risco significativo, justificando início imediato.', 'A: não se deve aguardar sorologia da profissional para iniciar a profilaxia, dado o tempo crítico de eficácia. B: carga viral desconhecida do paciente-fonte não contraindica a PEP; pelo contrário, reforça a indicação diante do risco. D: a profilaxia é preventiva, não depende de sintomas já estabelecidos, que indicariam infecção instalada.', 'Em revisão', null, null, null),
  ('SIM1-011', 'simulado', '1', '11', 'Clínica Médica', 'Emergência hipertensiva / edema agudo de pulmão', 'Difícil', null, null, 'Paciente de 74 anos, hipertensa em uso irregular de anti-hipertensivos, é trazida ao PS pelo filho com dispneia súbita e intensa, iniciada durante o sono há 40 minutos, obrigando-a a permanecer sentada. Relata tosse com expectoração rósea e espumosa. Nega dor torácica. Ao exame: agitada, ortopneica, PA 226x134mmHg, FC 118bpm, saturação 84% em ar ambiente, estertores crepitantes até ápices bilateralmente, terceira bulha presente. ECG sem sinais de isquemia aguda. Radiografia de tórax evidencia infiltrado alveolar bilateral em asa de morcego.

Diante desse quadro, a conduta mais adequada é', 'Reduzir a PA por via oral, gradualmente, ao longo de 24-48h', 'Reduzir a PA rapidamente com anti-hipertensivo IV (ex: nitroglicerina), associado a diurético de alça e suporte ventilatório', 'Priorizar apenas sedação para reduzir a ansiedade, sem tratar a pressão arterial', 'Aguardar estabilização espontânea antes de qualquer intervenção farmacológica', 'B', 'Emergência hipertensiva com edema agudo de pulmão (dispneia súbita, hipoxemia, infiltrado bilateral, PA muito elevada) exige redução rápida mas controlada da PA por via IV, associada a diurético e suporte de oxigenação, para reverter a congestão pulmonar aguda.', 'A: redução gradual é para urgência hipertensiva, sem lesão aguda de órgão-alvo; aqui há EAP estabelecido. C: sedação isolada não trata a causa hemodinâmica do quadro. D: atraso pode ser fatal em EAP hipertensivo com hipoxemia grave.', 'Em revisão', null, null, null),
  ('SIM1-012', 'simulado', '1', '12', 'Clínica Médica', 'Síndrome nefrótica', 'Médio', null, null, 'Criança de 4 anos é levada à UBS pela mãe por edema periorbital que piora pela manhã e melhora ao longo do dia, presente há 5 dias, associado a edema de membros inferiores nas últimas 48 horas e urina espumosa. Nega febre, hematúria macroscópica ou infecção recente de vias aéreas. Ao exame: edema periorbital bilateral, edema de membros inferiores com cacifo positivo, PA 96x60mmHg (normal para idade). Exames laboratoriais mostram proteinúria maciça em amostra de 24h, albumina sérica 1,8g/dL e colesterol total 320mg/dL, sem hematúria no sumário de urina.

Com base na principal hipótese diagnóstica, a conduta inicial mais adequada é', 'Infecção urinária; iniciar antibiótico empírico', 'Síndrome nefrótica; iniciar corticoterapia e investigar complicações (infecção, trombose)', 'Insuficiência renal aguda; iniciar diálise imediata', 'Síndrome nefrítica; iniciar anti-hipertensivo isolado', 'B', 'A tríade de edema, proteinúria maciça, hipoalbuminemia e hiperlipidemia caracteriza síndrome nefrótica; em crianças, a causa mais comum é a doença de lesões mínimas, respondendo bem a corticoterapia, com atenção às complicações associadas (infecções, eventos trombóticos).', 'A: quadro não é compatível com infecção urinária isolada, sem sintomas miccionais ou febre. C: não há indicação de diálise sem sinais de IRA/uremia grave. D: síndrome nefrítica cursa com hematúria e hipertensão, achados ausentes aqui.', 'Em revisão', null, null, null),
  ('SIM1-013', 'simulado', '1', '13', 'Clínica Médica', 'Anemia ferropriva', 'Fácil', null, null, 'Mulher de 35 anos, previamente hígida, procura a UBS com fadiga progressiva, palidez e episódios de tontura ao se levantar nas últimas semanas. Relata menstruações intensas e prolongadas (mais de 7 dias, com necessidade de troca de absorvente a cada 2 horas nos primeiros dias) há aproximadamente 6 meses, sem investigação prévia. Nega sangramento digestivo ou perda de peso. Ao exame: palidez de mucosas ++/4+, taquicardia leve, restante sem alterações. Hemograma mostra hemoglobina 9,5g/dL, VCM 68fL, RDW elevado, e ferritina sérica 8ng/mL.

A conduta mais adequada é', 'Suplementação isolada de vitamina B12, sem necessidade de ferro', 'Observação sem tratamento, pois anemia leve não requer conduta', 'Transfusão sanguínea imediata, independente da estabilidade clínica', 'Suplementação de ferro oral, investigação e tratamento da causa do sangramento (menorragia)', 'D', 'Anemia microcítica com ferritina baixa confirma deficiência de ferro; a conduta é reposição oral de ferro associada à investigação e tratamento da causa (aqui, menorragia), evitando recorrência.', 'A: B12 trata anemia macrocítica, não microcítica ferropriva. B: hemoglobina 9,5 com sintomas exige tratamento, não é apenas observação. C: transfusão não é indicada rotineiramente em anemia estável sem repercussão hemodinâmica.', 'Em revisão', null, null, null),
  ('SIM1-014', 'simulado', '1', '14', 'Clínica Médica', 'Doença péptica / H. pylori', 'Fácil', null, null, 'Paciente de 42 anos procura atendimento com dor epigástrica em queimação há 2 meses, que piora à noite e melhora parcialmente com a alimentação, associada a plenitude pós-prandial. Nega emagrecimento, disfagia, hematêmese ou melena. Faz uso ocasional de anti-inflamatório para cefaleia. Endoscopia digestiva alta revela úlcera duodenal única, de bordas regulares, sem sinais de sangramento ativo. Teste da urease realizado na biópsia da mucosa gástrica é positivo.

A conduta mais adequada é', 'Cirurgia de urgência para tratamento definitivo da úlcera', 'Terapia de erradicação do H. pylori (IBP + dois antibióticos, esquema tríplice) por 14 dias', 'Apenas IBP isolado por 4 semanas, sem necessidade de erradicar H. pylori', 'Antiácidos isolados, sem necessidade de outros tratamentos', 'B', 'Úlcera duodenal associada a H. pylori positivo tem indicação de terapia de erradicação (esquema tríplice) por 14 dias, reduzindo recorrência e complicações.', 'A: cirurgia é reservada para complicações (perfuração, sangramento refratário). C: sem erradicar o H. pylori, a recorrência é alta. D: antiácidos isolados não tratam a causa nem favorecem a erradicação bacteriana.', 'Em revisão', null, null, null),
  ('SIM1-015', 'simulado', '1', '15', 'Clínica Médica', 'Cirrose hepática - ascite', 'Médio', null, null, 'Paciente de 58 anos, com diagnóstico de cirrose hepática por consumo crônico de álcool, é trazido pela esposa com aumento progressivo do volume abdominal há 3 semanas, associado a desconforto e saciedade precoce. Nega febre ou dor abdominal intensa. Ao exame: ictérico leve, abdome globoso, com macicez móvel à percussão e piparote positivo, sem sinais de irritação peritoneal. É realizada paracentese diagnóstica, que mostra líquido amarelo-citrino, com albumina do líquido ascítico de 0,8g/dL e albumina sérica simultânea de 3,4g/dL (gradiente de albumina soro-ascite = 2,6).

A conduta inicial mais adequada é', 'Paracentese de grande volume diária, independentemente dos sintomas', 'Antibioticoterapia empírica para todos os casos de ascite, sem necessidade de investigação', 'Restrição de sódio na dieta e diurético (espironolactona ± furosemida)', 'Transplante hepático imediato como única opção terapêutica', 'C', 'Gradiente de albumina soro-ascite ≥1,1 confirma ascite por hipertensão portal; o tratamento inicial é restrição de sódio e diuréticos, reservando paracentese terapêutica para ascite tensa/refratária.', 'A: paracentese diária não é rotina fora de ascite tensa/refratária. B: antibiótico é indicado se houver suspeita de peritonite bacteriana espontânea, não em toda ascite. D: transplante é considerado em estágios avançados, não é conduta imediata para esse quadro.', 'Em revisão', null, null, null),
  ('SIM1-016', 'simulado', '1', '16', 'Clínica Médica', 'Fibrilação atrial - anticoagulação', 'Médio', null, null, 'Paciente de 76 anos, hipertenso, diabético e com histórico de AVC isquêmico há 2 anos, é identificado com fibrilação atrial persistente em ECG de rotina durante consulta geriátrica, assintomático do ponto de vista cardiovascular. Nega palpitações, dispneia ou síncope. Ao exame: ritmo cardíaco irregularmente irregular, FC 78bpm, PA 138x84mmHg, sem sinais de insuficiência cardíaca.

A conduta mais adequada em relação à prevenção de eventos tromboembólicos é', 'Não é necessária anticoagulação, pois o paciente está assintomático', 'Cardioversão elétrica imediata, sem avaliação de risco tromboembólico', 'Calcular o escore CHA2DS2-VASc e considerar anticoagulação oral conforme o risco', 'Indicar apenas AAS em dose antiagregante, sem necessidade de anticoagulante', 'C', 'Em FA, a decisão de anticoagular independe de sintomas e deve ser guiada pelo CHA2DS2-VASc; paciente idoso, hipertenso, diabético e com AVC prévio já tem escore elevado, indicando anticoagulação oral.', 'A: risco tromboembólico não depende de sintomas. B: cardioversão sem avaliação de risco/anticoagulação prévia aumenta risco de embolização. D: AAS isolado é inferior ao anticoagulante oral em FA com risco elevado.', 'Em revisão', null, null, null),
  ('SIM1-017', 'simulado', '1', '17', 'Clínica Médica', 'Choque séptico', 'Difícil', null, null, 'Paciente de 67 anos, com histórico de infecção urinária de repetição, é trazido ao PS pela família por confusão mental de início há 6 horas, associada a febre e calafrios. Relata disúria e polaciúria há 3 dias, sem tratamento. Ao exame: confuso, PA 78x48mmHg, FC 132bpm, FR 26irpm, temperatura 39,2°C, extremidades quentes e bem perfundidas inicialmente. Lactato sérico 4,2mmol/L (referência < 2). Exame de urina com piúria importante.

A conduta inicial mais adequada é', 'Iniciar vasopressor isolado, sem reposição volêmica prévia', 'Aguardar resultado de hemocultura antes de iniciar qualquer antibiótico', 'Reposição volêmica agressiva com cristaloide, coleta de culturas e início precoce de antibiótico de amplo espectro', 'Alta com antibiótico oral e retorno se piora', 'C', 'Choque séptico (hipotensão, lactato elevado, foco infeccioso provável) exige reposição volêmica precoce, coleta de culturas e antibiótico de amplo espectro na primeira hora.', 'A: vasopressor geralmente é iniciado após ou concomitante à reposição volêmica inicial. B: atrasar o antibiótico aguardando cultura aumenta a mortalidade em sepse. D: sinais de choque contraindicam alta hospitalar.', 'Em revisão', null, null, null),
  ('SIM1-018', 'simulado', '1', '18', 'Clínica Médica', 'Dengue - classificação de gravidade', 'Médio', null, null, 'Paciente de 28 anos, previamente hígido, apresenta quadro compatível com dengue (febre, mialgia, cefaleia retro-orbitária) há 5 dias, com defervescência da febre há 12 horas. Nas últimas 4 horas, relata dor abdominal intensa e contínua, vômitos repetidos e letargia progressiva, sem sangramento evidente. Ao exame: hipotenso leve, extremidades frias, tempo de enchimento capilar de 3 segundos, hematócrito elevado em relação ao basal.

A classificação e conduta mais adequadas são', 'Dengue com sinais de alarme evoluindo para gravidade; internação para hidratação venosa e monitorização rigorosa', 'Dengue grave apenas se houver sangramento ativo confirmado; manter conduta ambulatorial até então', 'Não é dengue, pois a febre já cedeu, descartando o diagnóstico', 'Dengue sem sinais de alarme; alta com orientações e retorno se necessário', 'A', 'O período de defervescência é justamente o de maior risco de evolução para gravidade; dor abdominal intensa, vômitos persistentes, letargia e sinais de má perfusão indicam necessidade de internação e hidratação venosa rigorosa.', 'B: sinais de má perfusão já indicam gravidade, sem precisar aguardar sangramento. C: a defervescência não descarta dengue — é justamente a fase crítica da doença. D: os sinais descritos já são de alarme/gravidade, contraindicando conduta ambulatorial.', 'Em revisão', null, null, null),
  ('SIM1-019', 'simulado', '1', '19', 'Clínica Médica', 'Hanseníase - diagnóstico e classificação', 'Médio', null, null, 'Paciente de 34 anos, residente em região endêmica, procura a UBS com queixa de manchas na pele há 8 meses, inicialmente atribuídas a manifestação alérgica. Relata que as lesões não coçam, mas notou diminuição da sensibilidade ao calor na área afetada. Ao exame físico: três máculas hipocrômicas de bordas bem definidas em tronco e membro superior direito, com hipoestesia térmica e dolorosa confirmada à avaliação; espessamento palpável do nervo ulnar direito, sem outras alterações.

A hipótese diagnóstica mais provável e a conduta são', 'Micose superficial; iniciar antifúngico tópico', 'Hanseníase; classificar (paucibacilar ou multibacilar) e iniciar poliquimioterapia específica', 'Vitiligo; encaminhar para acompanhamento dermatológico estético', 'Dermatite atópica; iniciar corticoide tópico', 'B', 'Lesões de pele com alteração de sensibilidade associadas a espessamento de nervo periférico são características de hanseníase; a conduta é classificar a forma clínica e iniciar a poliquimioterapia recomendada.', 'A e D: não explicam a hipoestesia nem o comprometimento neural, achados-chave para hanseníase. C: vitiligo não causa alteração de sensibilidade nem espessamento de nervos.', 'Em revisão', null, null, null),
  ('SIM1-020', 'simulado', '1', '20', 'Clínica Médica', 'Doença de Chagas - fase crônica cardíaca', 'Difícil', null, null, 'Paciente de 55 anos, natural de área rural endêmica para doença de Chagas, com sorologia positiva conhecida há 10 anos sem acompanhamento regular, procura atendimento por palpitações e dispneia aos esforços moderados há 2 meses. Nega dor torácica ou síncope. ECG mostra bloqueio completo de ramo direito associado a bloqueio divisional ântero-superior esquerdo. Ecocardiograma solicitado evidencia disfunção ventricular esquerda leve com aneurisma apical.

A fase da doença e a conduta mais adequadas são', 'Fase crônica cardíaca; avaliação cardiológica completa (ecocardiograma, Holter) e tratamento das complicações', 'Fase aguda; iniciar benzonidazol como única conduta necessária', 'Doença não relacionada a Chagas, pois sorologia positiva isolada não tem significado clínico', 'Fase indeterminada; não é necessária nenhuma avaliação adicional', 'A', 'Alterações eletrocardiográficas típicas (BRD + BDAS) associadas a disfunção ventricular e aneurisma apical em paciente com sorologia positiva indicam fase crônica cardíaca, exigindo avaliação cardiológica completa.', 'B: fase aguda tem apresentação clínica diferente, geralmente anos antes. C: os achados são clinicamente relevantes e compatíveis com cardiopatia chagásica. D: fase indeterminada não apresenta alterações cardíacas; este caso já mostra comprometimento estrutural.', 'Em revisão', null, null, null),
  ('SIM1-021', 'simulado', '1', '21', 'Clínica Médica', 'Hepatite B - interpretação sorológica', 'Difícil', null, null, 'Paciente de 40 anos, assintomático, realiza sorologia de rotina para hepatite B durante exame admissional: HBsAg positivo, Anti-HBc IgG positivo, HBeAg negativo, Anti-HBe positivo, transaminases normais em duas dosagens com intervalo de 6 meses, carga viral de HBV-DNA baixa (menor que 2.000 UI/mL).

A interpretação mais adequada é', 'Hepatite B aguda; iniciar tratamento antiviral imediato', 'Hepatite B crônica ativa; iniciar antiviral de forma obrigatória', 'Imunidade vacinal; não há necessidade de acompanhamento', 'Estado de portador inativo do HBsAg; acompanhamento periódico sem tratamento antiviral imediato', 'D', 'HBsAg positivo com HBeAg negativo, Anti-HBe positivo, transaminases normais e carga viral baixa sustentada sugerem estado de portador inativo, que requer acompanhamento periódico sem tratamento antiviral imediato.', 'A: hepatite aguda cursaria com IgM anti-HBc positivo e quadro clínico compatível, ausentes aqui. B: hepatite crônica ativa geralmente cursa com transaminases elevadas e/ou carga viral alta, ausentes neste caso. C: imunidade vacinal cursaria com Anti-HBs positivo isolado, não HBsAg positivo.', 'Em revisão', null, null, null),
  ('SIM1-022', 'simulado', '1', '22', 'Clínica Médica', 'Hipertireoidismo - Doença de Graves', 'Médio', null, null, 'Paciente de 27 anos, sexo feminino, procura atendimento com perda de peso de 8kg em 3 meses apesar do apetite aumentado, palpitações, tremores nas mãos e irritabilidade. Relata também sensação de ''olhos saltados'', notada pela família. Ao exame: taquicárdica (FC 118bpm), bócio difuso palpável, exoftalmia bilateral, tremor fino de extremidades. TSH suprimido, T4 livre elevado.

A hipótese diagnóstica mais provável e a conduta inicial são', 'Tireoidite subaguda; apenas anti-inflamatório, sem necessidade de outro tratamento', 'Doença de Graves; iniciar tionamida (ex: metimazol) e betabloqueador para controle sintomático', 'Nódulo tireoidiano isolado; encaminhar para biópsia sem tratamento medicamentoso inicial', 'Hipotireoidismo; iniciar levotiroxina', 'B', 'Exoftalmia, bócio difuso e hipertireoidismo laboratorial (TSH suprimido, T4 livre elevado) sugerem doença de Graves; o tratamento inicial envolve tionamida e betabloqueador para controle dos sintomas adrenérgicos.', 'A: tireoidite subaguda geralmente cursa com dor cervical e é autolimitada, diferente do quadro com exoftalmia. C: exoftalmia e bócio difuso não são compatíveis com nódulo isolado. D: quadro é de hipertireoidismo, com achados opostos aos do hipotireoidismo.', 'Em revisão', null, null, null),
  ('SIM1-023', 'simulado', '1', '23', 'Clínica Médica', 'Pancreatite aguda', 'Médio', null, null, 'Paciente de 48 anos, etilista crônico, é trazido ao PS com dor abdominal intensa em faixa, de início súbito há 6 horas, irradiando para o dorso, associada a náuseas e vômitos incoercíveis. Refere ingestão alcoólica importante na noite anterior. Ao exame: taquicárdico, desidratado, dor à palpação profunda em andar superior do abdome, sem sinais de irritação peritoneal franca. Exames laboratoriais coletados na admissão:', 'Antibioticoterapia profilática de rotina para todos os casos', 'Cirurgia de urgência imediata, independente da gravidade', 'Jejum, hidratação venosa vigorosa e analgesia, com monitorização de sinais de gravidade', 'Dieta hiperproteica imediata para recuperação nutricional', 'C', 'Pancreatite aguda (dor característica + amilase/lipase muito acima do valor de referência) tem manejo inicial conservador: jejum, hidratação venosa vigorosa, analgesia e monitorização de gravidade.', 'A: antibiótico profilático de rotina não é recomendado para todos os casos. B: cirurgia é reservada para complicações específicas, não é conduta inicial na maioria dos casos. D: dieta hiperproteica imediata pode agravar a inflamação pancreática.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-024', 'simulado', '1', '24', 'Clínica Médica', 'Embolia pulmonar - probabilidade clínica', 'Difícil', null, null, 'Paciente de 58 anos, no 6º dia de pós-operatório de artroplastia de quadril, sem profilaxia adequada para tromboembolismo venoso, desenvolve dispneia súbita associada a dor torácica pleurítica e taquicardia, com início há 30 minutos. Nega hemoptise. Ao exame: taquipneico, FC 118bpm, saturação 91% em ar ambiente, panturrilha direita com edema e dor à palpação. O escore de Wells calculado indica alta probabilidade clínica de embolia pulmonar.

A conduta mais adequada é', 'Aguardar D-dímero antes de qualquer conduta, mesmo com alta probabilidade clínica', 'Iniciar anticoagulação empírica e solicitar angiotomografia de tórax para confirmação diagnóstica', 'Trombólise sistêmica imediata sem confirmação diagnóstica em paciente estável', 'Alta hospitalar com anti-inflamatório, pois dor pleurítica é geralmente benigna', 'B', 'Em paciente com alta probabilidade clínica de embolia pulmonar (fator de risco cirúrgico recente, TVP provável, dispneia súbita), deve-se iniciar anticoagulação empírica enquanto se confirma o diagnóstico com angiotomografia.', 'A: D-dímero tem valor limitado em pacientes de alta probabilidade clínica, não deve atrasar a anticoagulação. C: trombólise sistêmica é reservada para EP maciça com instabilidade hemodinâmica, ausente aqui. D: o quadro é sugestivo de doença potencialmente grave.', 'Em revisão', null, null, null),
  ('SIM1-025', 'simulado', '1', '25', 'Clínica Médica', 'Meningite bacteriana', 'Difícil', null, null, 'Paciente de 22 anos, universitário morador de alojamento estudantil, é trazido ao PS por familiares com febre alta de início há 10 horas, cefaleia holocraniana intensa, fotofobia e um episódio de vômito em jato. Nos últimos 30 minutos, apresentou confusão mental progressiva. Ao exame: febril (39,8°C), rigidez de nuca presente, sinal de Kernig positivo, petéquias esparsas em tronco.

A conduta inicial mais adequada é', 'Iniciar antibioticoterapia empírica imediatamente, sem aguardar exames confirmatórios, e realizar punção lombar assim que possível', 'Solicitar ressonância magnética antes de qualquer conduta terapêutica', 'Aguardar resultado de punção lombar antes de iniciar qualquer antibiótico', 'Iniciar apenas analgesia e observação, pois o quadro pode ser enxaqueca', 'A', 'Suspeita de meningite bacteriana (febre, rigidez de nuca, Kernig positivo, petéquias, rebaixamento de consciência) é emergência médica; antibioticoterapia empírica deve ser iniciada imediatamente, sem aguardar confirmação laboratorial.', 'B: RM não deve atrasar o início do tratamento em suspeita de meningite bacteriana. C: atrasar antibiótico aguardando punção lombar aumenta significativamente a mortalidade. D: os sinais não são compatíveis com enxaqueca simples.', 'Em revisão', null, null, null),
  ('SIM1-026', 'simulado', '1', '26', 'Clínica Médica', 'Leptospirose', 'Médio', null, null, 'Paciente de 38 anos, morador de área que sofreu enchente recente, procura atendimento com febre alta, mialgia intensa em panturrilhas, cefaleia e hiperemia conjuntival há 4 dias. Nos últimos 2 dias, notou olhos e pele amarelados, além de urina escura. Ao exame: ictérico +++/4+, sufusão conjuntival bilateral, dor à palpação de panturrilhas, sem sinais de irritação peritoneal. Exames mostram elevação de bilirrubina direta, creatinina elevada e plaquetopenia leve.

A hipótese diagnóstica mais provável e a conduta são', 'Leptospirose; iniciar antibioticoterapia precoce e monitorar função renal/hepática', 'Dengue clássica; apenas hidratação oral', 'Hepatite viral aguda isolada; apenas suporte clínico', 'Infecção urinária; iniciar antibiótico oral ambulatorial', 'A', 'Mialgia intensa em panturrilhas, icterícia, sufusão conjuntival e exposição a área alagada, associadas a disfunção renal, são sugestivas de leptospirose; a conduta é antibioticoterapia precoce e monitorização de função renal/hepática pelo risco de síndrome de Weil.', 'B: dengue não costuma cursar com icterícia e disfunção renal dessa magnitude. C: hepatite viral isolada não explica a mialgia intensa nem a sufusão conjuntival característica. D: quadro sistêmico grave não deve ser tratado apenas como infecção urinária ambulatorial.', 'Em revisão', null, null, null),
  ('SIM1-027', 'simulado', '1', '27', 'Clínica Médica', 'Síndrome metabólica', 'Médio', null, null, 'Paciente de 50 anos, sedentário, procura a UBS para check-up de rotina. Nega sintomas específicos. Ao exame: circunferência abdominal de 108cm, PA 148x94mmHg, IMC 31kg/m². Exames laboratoriais em jejum coletados na consulta:', 'Indicar cirurgia bariátrica como primeira conduta', 'Iniciar estatina em dose máxima imediatamente, independentemente de outros fatores de risco', 'Nenhuma conduta é necessária, pois os valores estão apenas discretamente alterados', 'Diagnóstico de síndrome metabólica; orientar mudança de estilo de vida e tratar os componentes individuais conforme indicado', 'D', 'A combinação de obesidade abdominal, PA elevada, glicemia alterada e dislipidemia (triglicerídeos altos, HDL baixo) caracteriza síndrome metabólica; a conduta inicial é mudança de estilo de vida associada ao tratamento individualizado.', 'A: cirurgia bariátrica é reservada para casos específicos, não é primeira linha aqui. B: estatina em dose máxima sem avaliação individualizada de risco não é a conduta inicial padrão. C: a combinação de fatores de risco justifica intervenção ativa.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-028', 'simulado', '1', '28', 'Clínica Médica', 'DPOC vs Asma - diagnóstico diferencial', 'Médio', null, null, 'Paciente de 58 anos, ex-tabagista (parou há 5 anos, carga tabágica de 35 maços/ano), procura atendimento com dispneia crônica progressiva aos esforços e tosse produtiva matinal há 3 anos. Nega sibilância noturna ou variação sazonal dos sintomas. É realizada espirometria com prova broncodilatadora:', 'DPOC; a obstrução ao fluxo aéreo é predominantemente irreversível, diferente da reversibilidade típica da asma', 'Asma; a obstrução é sempre parcialmente irreversível, igual à DPOC', 'Bronquite aguda; quadro autolimitado sem necessidade de espirometria', 'Ambas as doenças têm o mesmo padrão espirométrico e não podem ser diferenciadas', 'A', 'O padrão obstrutivo com resposta mínima ao broncodilatador (variação de VEF1 < 12%), associado a tabagismo e dispneia progressiva, é característico de DPOC — obstrução predominantemente fixa, ao contrário da asma, tipicamente reversível.', 'B: reversibilidade significativa aproxima do diagnóstico de asma, não de DPOC; a afirmação inverte esse conceito. C: quadro crônico e progressivo de 3 anos não é compatível com bronquite aguda autolimitada. D: os padrões podem ser diferenciados pela resposta ao broncodilatador e pelo contexto clínico.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-029', 'simulado', '1', '29', 'Ginecologia e Obstetrícia', 'Síndromes hipertensivas da gestação', 'Difícil', null, null, 'Gestante de 33 semanas, primigesta, comparece à consulta de pré-natal com queixa de cefaleia occipital persistente há 2 dias, sem melhora com analgésico comum, associada a percepção de manchas luminosas na visão. Nega dor epigástrica. PA aferida em duas ocasiões com intervalo de 15 minutos: 162x108mmHg. Proteinúria de fita 3+. Exames laboratoriais coletados na consulta:', 'Orientar repouso domiciliar e retorno em 7 dias para reavaliação da pressão arterial', 'Prescrever apenas analgésico para a cefaleia e liberar a paciente para casa', 'Iniciar sulfato de magnésio, anti-hipertensivo e providenciar internação de urgência para avaliação de interrupção da gestação', 'Solicitar apenas ultrassonografia obstétrica ambulatorial em 2 semanas', 'C', 'PA ≥160/110mmHg associada a sintomas de iminência de eclâmpsia (cefaleia persistente, distúrbios visuais) e alteração laboratorial caracteriza pré-eclâmpsia grave; a conduta é internação de urgência, sulfato de magnésio para profilaxia de convulsões, anti-hipertensivo e avaliação da via de interrupção da gestação.', 'A e B: subestimam a gravidade do quadro, que tem sinais de iminência de eclâmpsia e risco materno-fetal imediato. D: não é aceitável adiar a avaliação diante de sinais de gravidade já presentes.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-030', 'simulado', '1', '30', 'Ginecologia e Obstetrícia', 'Gravidez ectópica / abdome agudo na gestação', 'Difícil', null, null, 'Mulher de 27 anos, atraso menstrual de 7 semanas, dá entrada no PS com dor pélvica súbita em fossa ilíaca direita, iniciada há 2 horas, e sangramento vaginal discreto de coloração escura. Refere síncope momentânea no trajeto até o hospital. PA 90x60mmHg, FC 118bpm, abdome doloroso à palpação com defesa em FID e sinal de Blumberg positivo. Beta-hCG positivo.

A hipótese diagnóstica mais provável e a conduta inicial são', 'Gravidez ectópica rota; estabilização hemodinâmica seguida de cirurgia de urgência', 'Doença inflamatória pélvica; iniciar antibioticoterapia empírica', 'Cisto de ovário roto; conduta expectante com analgesia', 'Abortamento incompleto; realizar curetagem uterina de urgência', 'A', 'Atraso menstrual + beta-hCG positivo + dor abdominal aguda + instabilidade hemodinâmica (hipotensão, taquicardia, síncope) sugerem gravidez ectópica rota, emergência cirúrgica: estabilização hemodinâmica seguida de cirurgia imediata.', 'B: DIP não explica beta-hCG positivo nem a instabilidade hemodinâmica aguda. C: conduta expectante é inadequada diante de sinais de choque hipovolêmico. D: não há evidência de gestação intrauterina; os achados apontam para ectópica.', 'Em revisão', null, null, null),
  ('SIM1-031', 'simulado', '1', '31', 'Ginecologia e Obstetrícia', 'Distócia / partograma', 'Difícil', null, null, 'Gestante de 39 semanas, em trabalho de parto há 8 horas, apresenta dilatação cervical estacionada em 6cm há 4 horas, apesar de contrações regulares e efetivas (3 em 10 minutos, boa intensidade à palpação), membranas rotas há 3 horas, apresentação cefálica insinuada em plano 0 de DeLee. O partograma mostra a curva de dilatação ultrapassando a linha de ação.

A conduta mais adequada é', 'Aguardar evolução espontânea por mais 4 horas antes de qualquer intervenção', 'Indicar cesariana imediata sem avaliação adicional', 'Avaliar proporção céfalo-pélvica e considerar ocitocina ou via de parto conforme a avaliação', 'Realizar manobra de Kristeller para acelerar a descida fetal', 'C', 'Parada de progressão com curva ultrapassando a linha de ação indica distócia funcional; avalia-se adequação da bacia/apresentação e, na ausência de desproporção, considera-se correção da dinâmica uterina (ocitocina) antes de indicar cesariana.', 'A: atraso na intervenção aumenta o risco materno-fetal. B: cesariana sem avaliação prévia é precipitada. D: a manobra de Kristeller é contraindicada pelo risco de lesões materno-fetais.', 'Em revisão', null, null, null),
  ('SIM1-032', 'simulado', '1', '32', 'Ginecologia e Obstetrícia', 'Diabetes mellitus gestacional', 'Médio', null, null, 'Gestante de 26 semanas, sem diagnóstico prévio de diabetes, realiza teste oral de tolerância à glicose (TOTG 75g) de rotina do segundo trimestre, com os seguintes valores:', 'Resultado inconclusivo; repetir o exame em 4 semanas sem qualquer orientação', 'Resultado normal; manter apenas o pré-natal de rotina', 'Diagnóstico de diabetes mellitus gestacional; iniciar orientação nutricional e monitorização glicêmica', 'Diagnóstico de diabetes mellitus prévio à gestação; iniciar insulina em dose plena imediatamente', 'C', 'Valores de jejum ≥92, 1h ≥180 ou 2h ≥153mg/dL no TOTG confirmam diabetes gestacional; a conduta inicial é orientação nutricional e monitorização glicêmica, com insulina reservada para casos sem controle adequado com dieta.', 'A: o resultado já é diagnóstico, não inconclusivo. B: os valores excedem os pontos de corte diagnósticos. D: diabetes prévio é diagnosticado por critérios diferentes, geralmente no primeiro trimestre.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-033', 'simulado', '1', '33', 'Ginecologia e Obstetrícia', 'Climatério - terapia hormonal', 'Médio', null, null, 'Mulher de 52 anos, sem menstruar há 14 meses, relata fogachos intensos, sudorese noturna e insônia que afetam significativamente sua qualidade de vida e produtividade no trabalho há cerca de 6 meses. Nega histórico pessoal de câncer de mama, tromboembolismo venoso, doença hepática ou sangramento vaginal anormal. Exame físico e mamografia recente sem alterações.

A conduta mais adequada é', 'Terapia hormonal sistêmica (estrogênio + progestagênio, já que possui útero), após avaliação de riscos e benefícios', 'Nenhum tratamento é indicado, pois sintomas climatéricos não podem ser tratados', 'Ooforectomia bilateral para eliminar a produção hormonal residual', 'Antibioticoterapia para tratar os sintomas vasomotores', 'A', 'Na ausência de contraindicações, a terapia hormonal é a opção mais eficaz para sintomas vasomotores moderados a intensos no climatério; como a paciente tem útero, é necessário associar progestagênio ao estrogênio para proteção endometrial.', 'B: existem tratamentos eficazes com indicação clara pela intensidade dos sintomas. C: cirurgia não é indicada apenas para tratar sintomas climatéricos. D: antibiótico não tem relação com o mecanismo dos sintomas vasomotores.', 'Em revisão', null, null, null),
  ('SIM1-034', 'simulado', '1', '34', 'Ginecologia e Obstetrícia', 'Sangramento uterino anormal - investigação', 'Médio', null, null, 'Mulher de 42 anos relata sangramento menstrual intenso e prolongado (mais de 10 dias, com necessidade de troca frequente de absorvente) há 3 ciclos consecutivos, sem dor associada. Refere fadiga progressiva no período. Exame especular sem lesões visíveis, útero de tamanho normal à palpação. Hemograma coletado na consulta mostra hemoglobina 9,8g/dL.

A conduta inicial mais adequada é', 'Solicitar ultrassonografia transvaginal e avaliação laboratorial adicional (função tireoidiana, coagulação) para investigar a causa', 'Tranquilizar a paciente, pois sangramento irregular nessa idade é sempre fisiológico', 'Indicar histerectomia diretamente, sem investigação prévia', 'Prescrever apenas anticoncepcional hormonal combinado, sem investigação adicional', 'A', 'Sangramento uterino anormal com repercussão hematológica requer investigação estruturada (USG transvaginal, avaliação de causas sistêmicas) antes de definir a conduta terapêutica.', 'B: sangramento anormal com anemia não deve ser assumido como fisiológico sem investigação, pelo risco de causas estruturais/neoplásicas. C: histerectomia não deve ser indicada sem diagnóstico prévio. D: tratamento hormonal empírico sem investigação pode mascarar uma causa importante.', 'Em revisão', null, null, null),
  ('SIM1-035', 'simulado', '1', '35', 'Ginecologia e Obstetrícia', 'Rotura prematura de membranas pré-termo', 'Difícil', null, null, 'Gestante de 32 semanas relata perda súbita de líquido claro pela vagina há 2 horas, sem contrações associadas. Exame especular confirma saída de líquido amniótico pelo colo, com teste de cristalização positivo. Ausência de sinais de infecção: afebril, sem taquicardia materna (FC 82bpm) ou fetal (BCF 140bpm), sem odor fétido do líquido.

A conduta mais adequada é', 'Conduta expectante com internação, corticoterapia para maturação pulmonar fetal e vigilância de sinais de infecção', 'Indicar parto imediato por via alta, independentemente da idade gestacional', 'Alta hospitalar com orientação de retorno apenas se houver febre', 'Iniciar antibioticoterapia de amplo espectro e aguardar o trabalho de parto espontâneo em casa', 'A', 'Na rotura prematura de membranas pré-termo sem sinais de infecção ou sofrimento fetal, a conduta é conservadora: internação, corticoterapia para maturação pulmonar fetal e vigilância rigorosa de sinais de corioamnionite.', 'B: interrupção imediata sem indicação materna/fetal aumenta a prematuridade desnecessariamente. C: alta domiciliar não permite vigilância adequada de sinais de infecção. D: antibiótico empírico e acompanhamento domiciliar não são condutas padrão nesse cenário.', 'Em revisão', null, null, null),
  ('SIM1-036', 'simulado', '1', '36', 'Ginecologia e Obstetrícia', 'Planejamento familiar - escolha de método contraceptivo', 'Difícil', null, null, 'Mulher de 30 anos, tabagista (15 cigarros/dia), procura a UBS para orientação contraceptiva. Relata episódios recorrentes de enxaqueca com aura visual (escotomas cintilantes) nos últimos 2 anos, cerca de uma vez por mês. Nega outras comorbidades.

O método contraceptivo mais adequado considerando suas características é', 'Nenhum método é seguro; deve-se orientar apenas abstinência', 'Anel vaginal combinado, pois evita o metabolismo hepático de primeira passagem', 'Método contraceptivo apenas de progestagênio (ex: DIU hormonal ou minipílula) ou método não hormonal', 'Anticoncepcional oral combinado (estrogênio + progestagênio)', 'C', 'Enxaqueca com aura é contraindicação absoluta para métodos com estrogênio (risco aumentado de AVC), independente da idade; a paciente deve usar métodos apenas de progestagênio ou não hormonais.', 'A: existem opções seguras e eficazes sem necessidade de abstinência. B: anel vaginal combinado também contém estrogênio, mesma contraindicação se aplica. D: contraindicado pelo risco vascular aumentado com estrogênio na presença de enxaqueca com aura.', 'Em revisão', null, null, null),
  ('SIM1-037', 'simulado', '1', '37', 'Ginecologia e Obstetrícia', 'Placenta prévia', 'Médio', null, null, 'Gestante de 34 semanas apresenta sangramento vaginal vermelho vivo, indolor, sem contrações, iniciado há 1 hora enquanto estava em repouso. Nega trauma. USG obstétrica realizada na 28ª semana já havia identificado placenta recobrindo totalmente o orifício interno do colo. BCF 138bpm, sinais vitais maternos estáveis.

A conduta mais adequada é', 'Toque vaginal para avaliar dilatação antes de qualquer conduta', 'Indicar parto vaginal imediato, independentemente da localização placentária', 'Conduta expectante com internação se sangramento importante, evitando toque vaginal, e via de parto cesariana planejada', 'Alta hospitalar com repouso domiciliar absoluto, sem necessidade de reavaliação', 'C', 'Placenta prévia total contraindica toque vaginal (risco de hemorragia maciça); a conduta é expectante, se sangramento controlável, com via de parto cesariana planejada devido à obstrução do canal de parto.', 'A: toque vaginal é contraindicado pelo risco de hemorragia grave. B: parto vaginal é contraindicado quando a placenta recobre totalmente o orifício interno. D: sangramento ativo requer avaliação e possível internação.', 'Em revisão', null, null, null),
  ('SIM1-038', 'simulado', '1', '38', 'Ginecologia e Obstetrícia', 'Descolamento prematuro de placenta', 'Difícil', null, null, 'Gestante de 36 semanas, hipertensa crônica em uso irregular de metildopa, apresenta dor abdominal súbita e intensa, iniciada há 30 minutos, associada a sangramento vaginal escuro em pequena quantidade. Ao exame: útero hipertônico e doloroso à palpação, BCF 90bpm com desacelerações. PA 168x104mmHg.

A hipótese diagnóstica e a conduta mais adequadas são', 'Trabalho de parto normal; acompanhar a evolução sem intervenção', 'Placenta prévia; conduta expectante ambulatorial', 'Descolamento prematuro de placenta; interrupção imediata da gestação, geralmente por via cesariana de urgência', 'Rotura uterina; aguardar exame de imagem antes de qualquer conduta', 'C', 'Dor abdominal súbita, útero hipertônico, sangramento escuro e sofrimento fetal em gestante hipertensa são clássicos de descolamento prematuro de placenta, exigindo interrupção imediata da gestação.', 'A: o quadro é de emergência obstétrica, não trabalho de parto normal. B: placenta prévia cursa tipicamente com sangramento vermelho vivo indolor, sem hipertonia. D: a gravidade do quadro não permite aguardar exame de imagem.', 'Em revisão', null, null, null),
  ('SIM1-039', 'simulado', '1', '39', 'Ginecologia e Obstetrícia', 'Amenorreia secundária - investigação', 'Médio', null, null, 'Mulher de 28 anos relata ausência de menstruação há 4 meses, sem uso de método contraceptivo hormonal. Nega relação sexual desprotegida recente. Beta-hCG sérico negativo. Refere também ganho de peso, queda de cabelo e sensação de frio constante nos últimos meses.

A conduta inicial mais adequada para investigação é', 'Tranquilizar a paciente, pois amenorreia secundária nunca tem causa patológica', 'Investigação hormonal (TSH, prolactina, FSH/LH) e avaliação de causas estruturais/funcionais', 'Iniciar reposição hormonal empírica sem investigação prévia', 'Indicar histerectomia para investigação diagnóstica', 'B', 'Amenorreia secundária com beta-hCG negativo e sintomas sugestivos de disfunção tireoidiana requer investigação hormonal estruturada, incluindo TSH, prolactina e gonadotrofinas.', 'A: amenorreia secundária pode ter diversas causas patológicas que precisam ser investigadas. C: tratamento hormonal empírico sem diagnóstico pode mascarar a causa de base. D: histerectomia não é procedimento diagnóstico apropriado para amenorreia.', 'Em revisão', null, null, null),
  ('SIM1-040', 'simulado', '1', '40', 'Ginecologia e Obstetrícia', 'Câncer de colo uterino - lesões precursoras', 'Difícil', null, null, 'Paciente com citologia oncótica alterada (lesão intraepitelial de alto grau) é encaminhada para colposcopia, que evidencia epitélio acetobranco denso com mosaico grosseiro na junção escamocolunar. A biópsia dirigida confirma neoplasia intraepitelial cervical grau 3 (NIC 3), sem sinais colposcópicos de invasão.

A conduta mais adequada é', 'Exérese da zona de transformação (conização) para tratamento e diagnóstico histológico definitivo', 'Indicar histerectomia radical imediatamente, sem confirmação histológica adicional', 'Repetir apenas a citologia em 1 ano, sem outra conduta', 'Tranquilizar a paciente, pois NIC 3 regride espontaneamente na maioria dos casos e não requer conduta', 'A', 'NIC 3 é lesão precursora de alto grau com risco significativo de progressão para câncer invasor; o tratamento padrão é a exérese da zona de transformação (conização), que trata e fornece material para confirmação histológica.', 'B: histerectomia radical é excessiva para lesão intraepitelial pré-invasora. C: NIC 3 não deve ser apenas acompanhada, pelo risco de progressão. D: NIC 3 tem baixa taxa de regressão espontânea e alto potencial de progressão.', 'Em revisão', null, null, null),
  ('SIM1-041', 'simulado', '1', '41', 'Ginecologia e Obstetrícia', 'Doença inflamatória pélvica', 'Médio', null, null, 'Mulher de 24 anos, sexualmente ativa com múltiplos parceiros e uso inconsistente de preservativo, apresenta dor pélvica há 3 dias, corrimento vaginal purulento e febre (38,2°C). Ao exame ginecológico: dor à mobilização do colo uterino (sinal de Chandelier) e à palpação de anexos bilateralmente, sem massa palpável.

A hipótese diagnóstica mais provável e a conduta são', 'Apendicite aguda; indicar cirurgia imediata sem outra avaliação', 'Endometriose; iniciar apenas analgesia sintomática', 'Cistite simples; iniciar antibiótico de curso curto para infecção urinária', 'Doença inflamatória pélvica; iniciar antibioticoterapia empírica cobrindo os principais agentes envolvidos', 'D', 'Dor pélvica, corrimento purulento, febre e dor à mobilização do colo (sinal de Chandelier) são característicos de DIP; a conduta é antibioticoterapia empírica cobrindo gonococo, clamídia e anaeróbios.', 'A: o quadro aponta mais para DIP; cirurgia imediata sem avaliação adequada não é a conduta correta. B: endometriose tem quadro mais crônico e cíclico, sem febre. C: cistite não costuma causar dor à mobilização do colo nem corrimento purulento típico.', 'Em revisão', null, null, null),
  ('SIM1-042', 'simulado', '1', '42', 'Ginecologia e Obstetrícia', 'Endometriose', 'Difícil', null, null, 'Mulher de 30 anos relata dismenorreia progressiva e intensa (piorando a cada ciclo nos últimos 2 anos), dispareunia de profundidade e infertilidade há 1 ano de tentativas. Exame físico com nodularidade dolorosa palpável em fundo de saco posterior à toque vaginal.

A hipótese diagnóstica mais provável e a conduta inicial são', 'Miomatose uterina; indicar cirurgia imediata sem tentativa de tratamento clínico', 'Endometriose; considerar tratamento clínico (hormonal) inicial e investigação adicional conforme gravidade dos sintomas/desejo reprodutivo', 'Vaginose bacteriana; iniciar metronidazol', 'Gravidez ectópica; solicitar beta-hCG e conduta cirúrgica de urgência', 'B', 'Dismenorreia progressiva, dispareunia profunda, infertilidade e nodularidade em fundo de saco posterior são sugestivos de endometriose; a conduta inicial costuma ser tratamento clínico hormonal.', 'A: miomatose não costuma causar nodularidade em fundo de saco posterior. C: vaginose não explica dismenorreia progressiva ou nodularidade pélvica. D: não há dados sugestivos de gestação no caso.', 'Em revisão', null, null, null),
  ('SIM1-043', 'simulado', '1', '43', 'Ginecologia e Obstetrícia', 'Miomatose uterina - conduta', 'Médio', null, null, 'Mulher de 38 anos, sem desejo reprodutivo futuro, relata sangramento menstrual intenso e sensação de peso pélvico progressivo há 8 meses. USG identifica múltiplos miomas submucosos, o maior medindo 4cm. Hemograma mostra hemoglobina 10,2g/dL.

A conduta mais adequada é', 'Discutir opções terapêuticas conforme sintomas e desejo da paciente, incluindo tratamento clínico, miomectomia ou histerectomia', 'Iniciar apenas anticoncepcional oral combinado, sem outras considerações', 'Indicar histerectomia como única opção possível, sem discutir alternativas', 'Conduta expectante obrigatória, sem qualquer tratamento, independente dos sintomas', 'A', 'O manejo de miomatose sintomática com repercussão hematológica deve ser individualizado, considerando gravidade dos sintomas, localização dos miomas e desejo reprodutivo.', 'B: anticoncepcional isolado pode não ser suficiente para miomas submucosos sintomáticos importantes. C: histerectomia não é a única opção; alternativas devem ser discutidas. D: sintomas significativos com anemia justificam intervenção.', 'Em revisão', null, null, null),
  ('SIM1-044', 'simulado', '1', '44', 'Ginecologia e Obstetrícia', 'Assistência pré-natal - exames de rotina', 'Fácil', null, null, 'Gestante de 8 semanas realiza sua primeira consulta de pré-natal na UBS, sem queixas, com história obstétrica e clínica sem particularidades.

Segundo o protocolo do Ministério da Saúde, o conjunto de exames a ser solicitado na primeira consulta inclui', 'Nenhum exame é necessário antes da 20ª semana de gestação', 'Apenas exame de urina tipo I, sem necessidade de sorologias', 'Apenas hemograma e glicemia de jejum', 'Tipagem sanguínea/Rh, hemograma, glicemia de jejum, sorologias (HIV, sífilis, hepatite B, toxoplasmose), urina tipo I e urocultura', 'D', 'O protocolo de pré-natal recomenda, na primeira consulta, um conjunto amplo de exames para rastreio precoce de condições que impactam o desfecho gestacional.', 'A: exames devem ser solicitados desde a primeira consulta. B: sorologias são essenciais desde o início do pré-natal. C: conjunto incompleto, deixa de rastrear infecções importantes.', 'Em revisão', null, null, null),
  ('SIM1-045', 'simulado', '1', '45', 'Ginecologia e Obstetrícia', 'Hemorragia pós-parto - atonia uterina', 'Difícil', null, null, 'Puérpera apresenta sangramento vaginal abundante 30 minutos após parto vaginal, com útero amolecido e mal contraído à palpação (atonia uterina). Estima-se perda sanguínea de aproximadamente 800mL. PA 96x58mmHg, FC 112bpm.', 'Aguardar resolução espontânea, pois sangramento pós-parto é sempre autolimitado', 'Massagem uterina bimanual e uso de uterotônicos (ex: ocitocina), com avaliação de outras causas se não houver resposta', 'Alta hospitalar com orientação de retorno se o sangramento persistir', 'Histerectomia imediata, sem tentativa de medidas conservadoras', 'B', 'A atonia uterina é a causa mais comum de hemorragia pós-parto; a conduta inicial envolve massagem uterina bimanual e uterotônicos, progredindo para outras medidas se não houver resposta.', 'A: hemorragia pós-parto pode levar a choque hipovolêmico rapidamente. C: sangramento volumoso ativo com instabilidade contraindica alta hospitalar. D: histerectomia é medida de última linha.', 'Em revisão', '[object Object]', null, null),
  ('SIM1-046', 'simulado', '1', '46', 'Ginecologia e Obstetrícia', 'Vulvovaginites - candidíase', 'Fácil', null, null, 'Mulher relata corrimento vaginal branco, grumoso (''leite coalhado''), com prurido intenso, sem odor característico, há 4 dias. Exame a fresco da secreção vaginal mostra hifas e pseudo-hifas ao microscópio; teste das aminas negativo.

O diagnóstico mais provável e o tratamento indicado são', 'Clamídia; azitromicina em dose única', 'Candidíase vulvovaginal; antifúngico tópico ou oral (ex: fluconazol)', 'Vaginose bacteriana; metronidazol oral ou vaginal', 'Tricomoníase; metronidazol com tratamento do parceiro obrigatório', 'B', 'Corrimento branco grumoso, prurido intenso e hifas ao exame a fresco são característicos de candidíase vulvovaginal; tratamento com antifúngico tópico ou oral.', 'A: clamídia geralmente é assintomática ou causa corrimento diferente. C: vaginose bacteriana cursa com corrimento acinzentado, odor fétido e clue cells, não hifas. D: tricomoníase cursa com corrimento amarelo-esverdeado espumoso.', 'Em revisão', null, null, null),
  ('SIM1-047', 'simulado', '1', '47', 'Ginecologia e Obstetrícia', 'Síndrome dos ovários policísticos', 'Médio', null, null, 'Mulher de 24 anos relata ciclos menstruais irregulares (intervalos de 45 a 90 dias) desde a menarca, acne persistente e hirsutismo em região de mento e linha alba. USG transvaginal mostra ovários com mais de 12 folículos de 2-9mm cada, em disposição periférica.

A hipótese diagnóstica mais provável e a conduta inicial são', 'Hipotireoidismo isolado; iniciar levotiroxina sem outra investigação', 'Insuficiência ovariana prematura; iniciar reposição hormonal em altas doses imediatamente', 'Síndrome dos ovários policísticos; orientar mudança de estilo de vida e considerar tratamento hormonal conforme sintomas/desejo reprodutivo', 'Gravidez ectópica; solicitar beta-hCG e conduta cirúrgica de urgência', 'C', 'Irregularidade menstrual, hiperandrogenismo clínico e aspecto ovariano policístico (critérios de Rotterdam) sugerem SOP; a conduta inicial inclui mudança de estilo de vida e tratamento hormonal individualizado.', 'A: hipotireoidismo isolado não explica todos os achados apresentados. B: insuficiência ovariana prematura cursa com hipoestrogenismo e amenorreia, quadro diferente. D: não há dados sugestivos de gestação.', 'Em revisão', null, null, null),
  ('SIM1-048', 'simulado', '1', '48', 'Ginecologia e Obstetrícia', 'Aleitamento materno - contraindicações (HIV)', 'Médio', null, null, 'Mãe HIV positivo, em uso regular de terapia antirretroviral com carga viral indetectável nos últimos dois exames, pergunta na maternidade sobre amamentação do recém-nascido, que testou negativo na primeira sorologia.

A orientação mais adequada, segundo as diretrizes brasileiras atuais, é', 'Amamentação pode ser considerada apenas se a mãe não usar nenhuma medicação', 'Amamentação é contraindicada; orientar aleitamento artificial exclusivo com fórmula infantil', 'Amamentação mista (leite materno e fórmula) é a opção mais segura', 'Amamentação é obrigatória, independentemente da carga viral materna', 'B', 'No Brasil, mães vivendo com HIV não devem amamentar, independentemente da carga viral, devido ao risco de transmissão vertical pelo leite materno; orienta-se aleitamento artificial exclusivo com fórmula fornecida pelo sistema de saúde.', 'A: a contraindicação independe do uso ou não de medicação materna. C: amamentação mista não elimina o risco de transmissão. D: amamentação não é recomendada em mães HIV positivo no Brasil, mesmo com carga viral indetectável.', 'Em revisão', null, null, null),
  ('SIM1-049', 'simulado', '1', '49', 'Ginecologia e Obstetrícia', 'Violência sexual - conduta na emergência', 'Difícil', null, null, 'Mulher de 22 anos comparece ao PS relatando violência sexual ocorrida há 3 horas, sem boletim de ocorrência registrado. Está em choro constante, mas colaborativa com a entrevista clínica. Nega lesões físicas visíveis.

A conduta mais adequada quanto às profilaxias é', 'Não é necessária nenhuma profilaxia se a paciente não apresentar lesões físicas visíveis', 'Iniciar apenas contracepção de emergência, sem necessidade de profilaxias infecciosas', 'Aguardar boletim de ocorrência policial antes de iniciar qualquer profilaxia', 'Oferecer profilaxia para IST não virais, profilaxia para HIV e contracepção de emergência, respeitando a autonomia da paciente', 'D', 'Em casos de violência sexual, o atendimento não deve ser condicionado a boletim de ocorrência; deve-se oferecer profilaxia para IST não virais, profilaxia para HIV (idealmente nas primeiras horas) e contracepção de emergência.', 'A: ausência de lesões físicas visíveis não afasta a necessidade de profilaxias. B: profilaxias infecciosas são igualmente importantes. C: o atendimento em saúde não deve ser condicionado à realização de boletim de ocorrência.', 'Em revisão', null, null, null),
  ('SIM1-050', 'simulado', '1', '50', 'Cirurgia', 'Abdome agudo inflamatório', 'Médio', null, null, 'Paciente de 24 anos com dor abdominal iniciada em região periumbilical há 18 horas, de intensidade progressiva, migrando para a fossa ilíaca direita nas últimas 6 horas, associada a náuseas, vômito único e febre baixa (37,8°C). Ao exame: dor à palpação em ponto de McBurney, sinal de Blumberg positivo, sinal de Rovsing presente. Leucocitose com desvio à esquerda.

A conduta mais adequada é', 'Solicitar apenas exames laboratoriais seriados por 48h antes de decidir', 'Indicar apendicectomia após avaliação/confirmação diagnóstica', 'Iniciar antibioticoterapia isolada e observar evolução ambulatorial', 'Prescrever analgesia e liberar o paciente, com retorno se houver piora', 'B', 'Quadro clínico clássico de apendicite aguda (dor migratória, sinais de irritação peritoneal, leucocitose) tem indicação cirúrgica; apendicectomia é o tratamento definitivo.', 'A: observação prolongada aumenta o risco de perfuração. C: antibiótico isolado não é conduta padrão fora de protocolos específicos de tratamento não operatório seletivo. D: alta sem tratamento definitivo expõe o paciente a complicações graves.', 'Em revisão', null, null, null),
  ('SIM1-051', 'simulado', '1', '51', 'Cirurgia', 'Colecistite aguda', 'Médio', null, null, 'Mulher de 45 anos, obesa, com dor em hipocôndrio direito há 2 dias, contínua, irradiando para o dorso, associada a febre (38,4°C) e náuseas. Sinal de Murphy positivo. USG mostra vesícula biliar espessada (5mm), com múltiplos cálculos e líquido perivesicular, sem dilatação de vias biliares.

A conduta mais adequada é', 'Drenagem percutânea da vesícula como único tratamento definitivo', 'Alta hospitalar com analgesia e retorno apenas se houver piora', 'Tratamento clínico exclusivo com antibiótico e colecistectomia eletiva após 6 meses', 'Colecistectomia videolaparoscópica precoce, idealmente dentro das primeiras 72h', 'D', 'Colecistite aguda litiásica confirmada por USG tem indicação de colecistectomia videolaparoscópica precoce, associada a menor morbidade comparado à cirurgia tardia.', 'A: drenagem percutânea é reservada a pacientes com alto risco cirúrgico. B: colecistite aguda não deve ser conduzida apenas ambulatorialmente. C: adiar a cirurgia aumenta o risco de recorrência/complicações.', 'Em revisão', null, null, null),
  ('SIM1-052', 'simulado', '1', '52', 'Cirurgia', 'Trauma abdominal / atendimento inicial ao politraumatizado', 'Difícil', null, null, 'Paciente vítima de acidente automobilístico chega ao PS 20 minutos após o trauma, com dor abdominal difusa progressiva. PA 88x56mmHg, FC 122bpm, FR 24irpm, Glasgow 15. Abdome distendido e doloroso difusamente à palpação, sem lesões externas evidentes.

A conduta inicial mais adequada segundo o protocolo de atendimento ao trauma é', 'Iniciar reposição volêmica e realizar FAST (avaliação ultrassonográfica focada em trauma) à beira-leito', 'Aguardar estabilização espontânea antes de qualquer exame', 'Indicar laparotomia exploradora imediata, sem avaliação complementar', 'Solicitar tomografia de abdome antes de qualquer outra medida', 'A', 'Paciente instável com suspeita de trauma abdominal segue o ABCDE do trauma: reposição volêmica imediata e FAST à beira-leito para identificar líquido livre/hemorragia, sem atrasar o atendimento com exames demorados.', 'B: o atraso pode ser fatal diante de sinais de choque. C: laparotomia sem qualquer avaliação, mesmo rápida, pode ser desnecessária ou mal direcionada. D: a TC demanda transporte e tempo, inadequada em paciente instável.', 'Em revisão', null, null, null),
  ('SIM1-053', 'simulado', '1', '53', 'Cirurgia', 'Hérnia inguinal encarcerada', 'Médio', null, null, 'Paciente de 55 anos com hérnia inguinal direita conhecida há anos apresenta dor intensa e abaulamento irredutível na região inguinal há 6 horas, associado a náuseas e um episódio de vômito. Ao exame: massa dolorosa, tensa, sem sinais de eritema ou toxemia, sem febre.

A conduta mais adequada é', 'Tentativa de redução manual cuidadosa; se sem sucesso ou com sinais de sofrimento, correção cirúrgica de urgência', 'Observação domiciliar com analgesia, pois hérnias encarceradas resolvem espontaneamente', 'Alta com orientação de cirurgia eletiva em 3 meses', 'Aplicação de calor local para reduzir o edema antes de qualquer manipulação', 'A', 'Hérnia encarcerada exige tentativa cuidadosa de redução manual; na falha ou presença de sinais de estrangulamento, a correção cirúrgica de urgência é necessária para evitar isquemia/necrose intestinal.', 'B: encarceramento não resolve espontaneamente e pode evoluir para estrangulamento. C: adiar a cirurgia expõe o paciente a risco de estrangulamento. D: calor local não é conduta indicada e pode mascarar sinais de gravidade.', 'Em revisão', null, null, null),
  ('SIM1-054', 'simulado', '1', '54', 'Cirurgia', 'Obstrução intestinal', 'Médio', null, null, 'Paciente de 70 anos, com cirurgia abdominal prévia (colectomia há 5 anos), apresenta dor abdominal em cólica, distensão progressiva, parada de eliminação de gases e fezes há 2 dias, associada a vômitos biliosos. Radiografia de abdome mostra níveis hidroaéreos e distensão de alças de delgado.

A conduta inicial mais adequada é', 'Cirurgia de urgência imediata, sem qualquer medida prévia', 'Laxante oral para estimular o trânsito intestinal', 'Descompressão com sonda nasogástrica, reposição hidroeletrolítica e jejum, com reavaliação da necessidade cirúrgica', 'Alta com dieta leve e retorno se piora dos sintomas', 'C', 'Obstrução intestinal mecânica (sugerida por cirurgia prévia, distensão, parada de eliminação e níveis hidroaéreos) é inicialmente manejada com descompressão nasogástrica, correção hidroeletrolítica e jejum, reservando cirurgia para sinais de estrangulamento.', 'A: cirurgia imediata sem tentativa conservadora é excessiva na ausência de sinais de estrangulamento. B: laxante é contraindicado em obstrução mecânica. D: sinais de obstrução contraindicam alta e dieta oral.', 'Em revisão', null, null, null),
  ('SIM1-055', 'simulado', '1', '55', 'Cirurgia', 'Queimaduras - reposição volêmica', 'Difícil', null, null, 'Paciente de 30 anos, 70kg, sofre queimadura de segunda espessura em tronco anterior (18% da superfície corporal) e todo o membro superior direito (9%), em acidente doméstico há 1 hora. Sem sinais de lesão de via aérea.

A conduta mais adequada em relação à reposição volêmica, segundo a fórmula de Parkland, é', 'Repor volume fixo de 1000 mL de soro fisiológico, independente da superfície queimada', 'Calcular a superfície corporal queimada e repor 4 mL x peso(kg) x %SCQ nas primeiras 24h, com metade nas primeiras 8h', 'Repor apenas por via oral, evitando acesso venoso', 'Restringir líquidos para evitar edema pulmonar', 'B', 'A fórmula de Parkland orienta a reposição volêmica em queimados: 4 mL x peso(kg) x %SCQ de cristaloide nas primeiras 24h, com metade nas primeiras 8h a partir do momento da queimadura.', 'A: volume fixo não considera a extensão da queimadura. C: via oral é inadequada para reposição de grande volume em fase aguda. D: restringir líquidos em queimado extenso pode levar a choque hipovolêmico.', 'Em revisão', null, null, null),
  ('SIM1-056', 'simulado', '1', '56', 'Cirurgia', 'Nódulo de mama - investigação (BI-RADS)', 'Médio', null, null, 'Mulher de 45 anos identifica nódulo endurecido, indolor, de bordas irregulares na mama direita durante autoexame, há 3 semanas. Mamografia classificada como BI-RADS 4, com microcalcificações agrupadas pleomórficas.

A conduta mais adequada é', 'Indicar mastectomia diretamente, sem confirmação histológica prévia', 'Tranquilizar a paciente, pois nódulos indolores raramente são malignos', 'Biópsia da lesão para definição histológica', 'Repetir a mamografia em 1 ano, pois BI-RADS 4 tem baixa suspeita', 'C', 'BI-RADS 4 indica suspeita moderada a alta de malignidade, exigindo biópsia para definição diagnóstica antes de qualquer conduta terapêutica definitiva.', 'A: cirurgia definitiva sem confirmação histológica prévia é inadequada. B: a ausência de dor não exclui malignidade; muitos cânceres de mama são indolores. D: BI-RADS 4 não é de baixa suspeita; requer investigação adicional.', 'Em revisão', null, null, null),
  ('SIM1-057', 'simulado', '1', '57', 'Cirurgia', 'Hemorragia digestiva alta', 'Difícil', null, null, 'Paciente de 55 anos, etilista crônico, apresenta hematêmese volumosa e melena há 6 horas, com dois episódios de vômito com sangue vivo. PA 90x60mmHg, FC 118bpm, palidez cutânea importante, extremidades frias.

A conduta inicial mais adequada é', 'Iniciar apenas inibidor de bomba de prótons oral e observação ambulatorial', 'Endoscopia digestiva alta imediata, antes de qualquer estabilização hemodinâmica', 'Estabilização hemodinâmica (acesso venoso calibroso, reposição volêmica/hemocomponentes) seguida de endoscopia digestiva alta', 'Alta com orientação de retorno se houver nova hematêmese', 'C', 'Paciente com hemorragia digestiva alta e instabilidade hemodinâmica deve ser estabilizado primeiro, e então submetido a endoscopia digestiva alta para diagnóstico e tratamento da causa do sangramento.', 'A: IBP oral e observação são insuficientes diante de instabilidade hemodinâmica. B: realizar endoscopia sem estabilização prévia expõe o paciente a risco durante o procedimento. D: sinais de choque contraindicam alta hospitalar.', 'Em revisão', null, null, null),
  ('SIM1-058', 'simulado', '1', '58', 'Cirurgia', 'Pancreatite aguda biliar - indicação cirúrgica', 'Difícil', null, null, 'Paciente com pancreatite aguda leve de etiologia biliar (colelitíase identificada em USG), internado há 4 dias, com melhora clínica completa após tratamento conservador (dor resolvida, tolerando dieta, amilase/lipase em queda).

A conduta mais adequada em relação à colecistectomia é', 'Não há indicação de colecistectomia, apenas acompanhamento clínico', 'Colecistectomia de urgência antes de qualquer tratamento da pancreatite', 'Colecistectomia eletiva após 6 meses, independentemente da gravidade', 'Colecistectomia durante a mesma internação, após resolução do quadro agudo', 'D', 'Na pancreatite aguda biliar leve, recomenda-se colecistectomia durante a mesma internação, reduzindo o risco de recorrência antes de nova internação.', 'A: a causa biliar identificada deve ser tratada definitivamente. B: cirurgia antes do tratamento/estabilização aumenta o risco cirúrgico. C: adiar para 6 meses aumenta o risco de recorrência.', 'Em revisão', null, null, null),
  ('SIM1-059', 'simulado', '1', '59', 'Cirurgia', 'Câncer colorretal - sinais de alarme', 'Médio', null, null, 'Paciente de 55 anos relata mudança do hábito intestinal (alternância entre constipação e diarreia) há 2 meses, sangue nas fezes em pequena quantidade e perda de peso não intencional de 5kg no período. Nega histórico familiar de câncer.

A conduta mais adequada é', 'Tranquilizar o paciente, pois esses sintomas são sempre relacionados a hemorroidas', 'Solicitar apenas exame de fezes para parasitas, sem outra investigação', 'Colonoscopia para investigação diagnóstica', 'Prescrever apenas laxante e reavaliar em 6 meses', 'C', 'Sinais de alarme (mudança do hábito intestinal, sangramento, perda de peso) em paciente acima de 50 anos exigem investigação com colonoscopia para descartar neoplasia colorretal.', 'A: sinais de alarme não devem ser atribuídos automaticamente a causas benignas sem investigação. B: exame parasitológico não avalia a hipótese de neoplasia colorretal. D: laxante atrasa o diagnóstico de uma possível neoplasia.', 'Em revisão', null, null, null),
  ('SIM1-060', 'simulado', '1', '60', 'Cirurgia', 'Diverticulite aguda', 'Médio', null, null, 'Paciente de 60 anos apresenta dor em fossa ilíaca esquerda há 2 dias, progressiva, febre baixa (37,9°C) e alteração do hábito intestinal. TC de abdome mostra espessamento da parede do cólon sigmoide com pequena coleção líquida adjacente (18mm), sem sinais de perfuração livre ou pneumoperitônio.

A conduta mais adequada é', 'Alta hospitalar sem tratamento, pois diverticulite é sempre autolimitada', 'Cirurgia de urgência (colectomia) imediata, independentemente da gravidade', 'Colonoscopia imediata para confirmação diagnóstica antes de qualquer tratamento', 'Tratamento clínico com antibioticoterapia e dieta conforme tolerância, com reavaliação da evolução', 'D', 'Diverticulite aguda não complicada (sem perfuração livre, abscesso grande ou peritonite generalizada) é tratada inicialmente de forma clínica, com antibioticoterapia e dieta conforme tolerância.', 'A: diverticulite com sinais de complicação não deve ser deixada sem tratamento. B: cirurgia de urgência é reservada para complicações graves, ausentes neste caso. C: colonoscopia na fase aguda tem risco aumentado de perfuração.', 'Em revisão', null, null, null),
  ('SIM1-061', 'simulado', '1', '61', 'Cirurgia', 'Politrauma - avaliação primária ABCDE', 'Médio', null, null, 'Vítima de acidente motociclístico chega ao PS com via aérea pérvia, respiração superficial e assimétrica, PA 100x70mmHg, FC 110bpm, Glasgow 14, agitada.

A sequência de avaliação inicial mais adequada é', 'Avaliação exclusivamente neurológica primeiro, pelo Glasgow reduzido', 'Avaliação sistematizada ABCDE: via aérea com proteção cervical, respiração/ventilação, circulação com controle de hemorragia, estado neurológico e exposição', 'Solicitar exames de imagem completos antes de qualquer intervenção', 'Aguardar avaliação especializada de cada sistema separadamente, sem sequência definida', 'B', 'O atendimento inicial ao politraumatizado segue a sequência ABCDE, permitindo identificar e tratar rapidamente as condições que ameaçam a vida.', 'A: a avaliação neurológica isolada não identifica problemas mais imediatamente fatais, como via aérea ou respiração comprometidas. C: exames de imagem completos não devem atrasar a avaliação inicial. D: a ausência de sequência sistematizada aumenta o risco de não identificar condições fatais.', 'Em revisão', null, null, null),
  ('SIM1-062', 'simulado', '1', '62', 'Cirurgia', 'Fratura exposta - conduta inicial', 'Médio', null, null, 'Paciente sofre fratura exposta de tíbia após acidente de trânsito, com ferida contaminada por terra e fragmentos visíveis, sangramento moderado local, sem sinais de comprometimento vascular distal (pulsos pediosos presentes).

A conduta inicial mais adequada é', 'Aguardar avaliação ortopédica ambulatorial em até 7 dias', 'Redução da fratura no local do acidente antes de qualquer outra medida', 'Cobertura da ferida com curativo estéril, imobilização, antibioticoterapia precoce e profilaxia antitetânica, com encaminhamento para debridamento cirúrgico', 'Apenas limpeza local com água corrente, sem necessidade de antibiótico', 'C', 'Fratura exposta é uma emergência ortopédica; a conduta inicial envolve cobertura estéril, imobilização, antibioticoterapia precoce e profilaxia antitetânica, com debridamento cirúrgico a seguir.', 'A: fratura exposta exige avaliação e tratamento de urgência. B: manipulação/redução no local sem condições adequadas pode agravar lesões associadas. D: a contaminação da ferida exige antibioticoterapia.', 'Em revisão', null, null, null),
  ('SIM1-063', 'simulado', '1', '63', 'Cirurgia', 'Isquemia mesentérica aguda', 'Difícil', null, null, 'Paciente de 75 anos, com fibrilação atrial sem anticoagulação regular, apresenta dor abdominal intensa de início súbito há 3 horas, desproporcional ao exame físico (abdome relativamente flácido apesar da dor relatada como 9/10). Gasometria arterial mostra acidose metabólica com lactato elevado.

A hipótese diagnóstica mais provável e a conduta são', 'Isquemia mesentérica aguda; angiotomografia de urgência e avaliação cirúrgica precoce', 'Constipação intestinal; prescrever laxante e orientar dieta rica em fibras', 'Cólica biliar; apenas analgesia e alta hospitalar', 'Gastrite aguda; iniciar apenas inibidor de bomba de prótons', 'A', 'Dor abdominal desproporcional ao exame físico em paciente com fibrilação atrial (fonte embólica) associada a acidose metabólica é altamente sugestiva de isquemia mesentérica aguda, exigindo investigação de imagem urgente.', 'B: constipação não causa dor desproporcional nem acidose metabólica. C: cólica biliar não costuma cursar com acidose metabólica nem dor tão desproporcional. D: gastrite não explica a gravidade sistêmica do quadro.', 'Em revisão', null, null, null),
  ('SIM1-064', 'simulado', '1', '64', 'Cirurgia', 'Torção testicular', 'Difícil', null, null, 'Adolescente de 14 anos apresenta dor testicular súbita e intensa à direita, iniciada há 4 horas durante atividade física, com edema local e náuseas associadas. Ao exame: testículo direito elevado e horizontalizado, sem melhora da dor à elevação da bolsa escrotal (sinal de Prehn negativo), reflexo cremastérico ausente à direita.

A conduta mais adequada é', 'Exploração cirúrgica de urgência, sem atraso para exames complementares se a suspeita clínica for alta', 'Aguardar ultrassonografia Doppler antes de qualquer conduta, mesmo com alta suspeita clínica', 'Repouso e analgesia, pois o quadro tende à resolução espontânea em poucos dias', 'Antibioticoterapia oral e retorno em 48 horas para reavaliação', 'A', 'Torção testicular é emergência cirúrgica; diante de alta suspeita clínica, a exploração cirúrgica não deve ser atrasada, já que a viabilidade testicular depende do tempo até a correção.', 'B: aguardar imagem quando a suspeita clínica é alta atrasa o tratamento. C: torção não se resolve espontaneamente sem risco de necrose. D: antibiótico é indicado em epididimite/orquite infecciosa, não em torção testicular.', 'Em revisão', null, null, null),
  ('SIM1-065', 'simulado', '1', '65', 'Cirurgia', 'Nódulo tireoidiano - investigação', 'Médio', null, null, 'Paciente apresenta nódulo tireoidiano palpável de 2,2cm, identificado ao exame físico de rotina, sem sintomas compressivos. Ultrassonografia classifica o nódulo como TI-RADS 4 (suspeita moderada), com margens irregulares e hipoecogenicidade.

A conduta mais adequada é', 'Iniciar levotiroxina para tentar reduzir o tamanho do nódulo', 'Tireoidectomia total imediata, sem confirmação citológica prévia', 'Apenas repetir a ultrassonografia em 2 anos, sem outra conduta', 'Punção aspirativa por agulha fina (PAAF) guiada por ultrassonografia para avaliação citológica', 'D', 'Nódulos TI-RADS 4 e tamanho relevante têm indicação de PAAF guiada por USG para avaliação citológica, definindo a conduta subsequente.', 'A: levotiroxina supressiva não é o tratamento padrão para nódulos com suspeita de malignidade. B: cirurgia definitiva sem confirmação citológica prévia é conduta precipitada. C: a classificação de suspeita moderada não permite apenas seguimento prolongado.', 'Em revisão', null, null, null),
  ('SIM1-066', 'simulado', '1', '66', 'Cirurgia', 'Úlcera péptica perfurada', 'Difícil', null, null, 'Paciente de 50 anos, em uso crônico de anti-inflamatório para artrose, apresenta dor abdominal súbita e intensa em andar superior do abdome há 2 horas, com abdome em tábua (rigidez difusa) e ausência de ruídos hidroaéreos. Radiografia de abdome mostra pneumoperitônio.

A conduta mais adequada é', 'Colonoscopia de urgência para diagnóstico complementar antes de qualquer conduta', 'Tratamento clínico exclusivo com inibidor de bomba de prótons, sem necessidade de cirurgia', 'Laparotomia/laparoscopia de urgência para correção da perfuração', 'Alta hospitalar com analgesia oral e retorno se piora', 'C', 'Abdome em tábua com pneumoperitônio confirma perfuração de víscera oca (provável úlcera péptica perfurada); a conduta é cirúrgica de urgência.', 'A: colonoscopia é contraindicada em abdome agudo perfurativo. B: perfuração confirmada com peritonite exige correção cirúrgica. D: quadro de abdome agudo perfurativo contraindica alta hospitalar.', 'Em revisão', null, null, null),
  ('SIM1-067', 'simulado', '1', '67', 'Cirurgia', 'Pé diabético - avaliação e conduta', 'Médio', null, null, 'Paciente diabético de longa data (18 anos de doença, controle irregular) apresenta úlcera plantar indolor, com bordas calejadas, em região de proeminência óssea do pé esquerdo, há 3 semanas, sem sinais de infecção ativa (sem eritema, secreção purulenta ou febre).

A conduta mais adequada é', 'Amputação preventiva imediata, independentemente da gravidade da lesão', 'Apenas curativo oclusivo, sem necessidade de avaliação adicional', 'Avaliação vascular e neurológica, desbridamento quando indicado, alívio de pressão local (descarga) e controle glicêmico rigoroso', 'Repouso absoluto sem qualquer intervenção local na ferida', 'C', 'Úlcera neuropática em pé diabético requer avaliação vascular e neurológica, desbridamento quando indicado, alívio da pressão sobre a área e controle glicêmico rigoroso.', 'A: amputação é medida extrema, reservada para casos graves. B: curativo isolado sem avaliação global não trata adequadamente a causa. D: repouso absoluto sem cuidado local adequado não favorece a cicatrização.', 'Em revisão', null, null, null),
  ('SIM1-068', 'simulado', '1', '68', 'Cirurgia', 'Hemorroidas - conduta clínica', 'Fácil', null, null, 'Paciente relata sangramento vermelho vivo ao evacuar, indolor, associado a prolapso de mucosa anal que retorna espontaneamente após a evacuação, há 2 meses. Nega tumoração persistente ou dor. Exame proctológico confirma hemorroida interna grau II.

A conduta mais adequada é', 'Hemorroidectomia cirúrgica imediata, independentemente do grau', 'Tratamento clínico inicial (dieta rica em fibras, hidratação, higiene local) e medidas conservadoras, reservando procedimentos para casos refratários', 'Nenhuma conduta é necessária, pois hemorroidas nunca requerem tratamento', 'Colonoscopia de urgência antes de qualquer orientação, mesmo com quadro típico', 'B', 'Hemorroidas internas de grau II geralmente respondem a medidas conservadoras, sendo os procedimentos reservados para casos refratários ou graus mais avançados.', 'A: cirurgia não é a primeira conduta para hemorroidas de grau II. C: sintomas presentes justificam orientação e tratamento. D: colonoscopia de urgência não é obrigatória diante de quadro típico.', 'Em revisão', null, null, null),
  ('SIM1-069', 'simulado', '1', '69', 'Pediatria', 'Diarreia aguda / planos de hidratação', 'Fácil', null, null, 'Criança de 2 anos é trazida à UBS com diarreia líquida há 2 dias, sem sangue, cerca de 5 evacuações por dia, aceitando líquidos por via oral avidamente. Está alerta, brincando, sem olheiras ou sinais de desidratação ao exame físico. Sinal da prega cutânea normal.

Segundo o protocolo do Ministério da Saúde, a conduta mais adequada é', 'Plano B: hidratação oral supervisionada na unidade de saúde por 4-6 horas', 'Plano C: hidratação venosa imediata', 'Internação hospitalar para observação por 48 horas', 'Plano A: manter alimentação habitual, aumentar oferta de líquidos e SRO em casa, orientar sinais de alarme', 'D', 'Criança sem sinais de desidratação segue o Plano A: manejo domiciliar com aumento da oferta de líquidos, SRO após cada evacuação líquida, manutenção da alimentação e orientação sobre sinais de alarme.', 'A: Plano B é indicado para desidratação leve/moderada, ausente neste caso. B: Plano C é reservado para desidratação grave/choque. C: não há indicação de internação em quadro sem sinais de gravidade.', 'Em revisão', null, null, null),
  ('SIM1-070', 'simulado', '1', '70', 'Pediatria', 'Sepse neonatal precoce', 'Difícil', null, null, 'Recém-nascido de 18 horas de vida, filho de mãe com bolsa rota há 20 horas antes do parto e sem profilaxia para Streptococcus agalactiae, apresenta-se taquipneico (FR 68irpm), hipoativo e com temperatura instável (36,2°C axilar). Ao exame: gemência leve, tiragem subcostal discreta, perfusão periférica lentificada (TEC 3s).

A conduta mais adequada é', 'Alta hospitalar com orientações aos pais sobre sinais de alerta', 'Aguardar resultado de hemocultura antes de iniciar qualquer tratamento', 'Observação clínica ambulatorial com retorno em 24h', 'Iniciar investigação (hemograma, PCR, hemocultura) e antibioticoterapia empírica precoce', 'D', 'Fatores de risco para sepse neonatal precoce (bolsa rota prolongada, ausência de profilaxia para GBS) associados a sinais clínicos sugestivos indicam início imediato de investigação e antibioticoterapia empírica, sem aguardar confirmação laboratorial completa.', 'A: a alta é contraindicada diante de sinais clínicos e fatores de risco significativos. B: aguardar a hemocultura atrasa um tratamento essencial em quadro de alto risco. C: observação ambulatorial expõe o RN a risco de deterioração rápida.', 'Em revisão', null, null, null),
  ('SIM1-071', 'simulado', '1', '71', 'Pediatria', 'Calendário Nacional de Vacinação', 'Fácil', null, null, 'Mãe leva filho de 4 meses à UBS para consulta de puericultura. A caderneta mostra que a criança recebeu apenas a primeira dose de pentavalente, VIP e pneumocócica 10-valente, aos 2 meses, e não retornou desde então devido a mudança de cidade.

A conduta mais adequada em relação à vacinação é', 'Reiniciar todo o esquema vacinal desde a primeira dose, pois houve atraso', 'Aplicar as doses atrasadas, retomando o esquema a partir do ponto em que parou, sem reiniciar da primeira dose', 'Aguardar até os 6 meses para retomar o esquema vacinal completo de uma vez', 'Não é possível vacinar crianças com esquema atrasado fora do calendário padrão', 'B', 'Vacinas do calendário nacional não exigem reinício do esquema em caso de atraso; a conduta correta é retomar a partir da dose onde parou, respeitando os intervalos mínimos entre doses.', 'A: reiniciar do zero não é necessário e atrasa ainda mais a proteção vacinal. C: adiar aumenta o tempo de exposição da criança a doenças imunopreveníveis. D: esquemas atrasados podem e devem ser retomados; é conduta padrão da atenção básica.', 'Em revisão', null, null, null),
  ('SIM1-072', 'simulado', '1', '72', 'Pediatria', 'Asma - crise aguda na infância', 'Médio', null, null, 'Criança de 6 anos, asmática conhecida, é trazida ao PS com falta de ar, tosse e sibilância progressiva há algumas horas, sem melhora com salbutamol domiciliar. Ao exame: fala frases incompletas, uso de musculatura acessória, sibilos difusos audíveis à distância, saturação 92% em ar ambiente, FC 128bpm.

A classificação de gravidade e a conduta inicial mais adequadas são', 'Crise moderada a grave; broncodilatador de curta ação inalatório repetido, corticoide sistêmico e oxigenoterapia se necessário', 'Crise leve; apenas antitussígeno e retorno se piora', 'Crise leve; apenas observação domiciliar sem medicação', 'Parada respiratória iminente; intubação orotraqueal imediata sem tentativa de tratamento medicamentoso', 'A', 'Sinais como fala entrecortada, uso de musculatura acessória e saturação reduzida indicam crise moderada a grave, tratada com broncodilatador de curta ação inalatório repetido, corticoide sistêmico e oxigenoterapia se necessário.', 'B e C: os sinais de gravidade descritos excluem crise leve e exigem tratamento imediato; antitussígeno não trata broncoespasmo. D: não há descrição de sinais de parada iminente; tratamento medicamentoso deve ser tentado antes de intubação.', 'Em revisão', null, null, null),
  ('SIM1-073', 'simulado', '1', '73', 'Pediatria', 'Icterícia neonatal - indicação de fototerapia', 'Médio', null, null, 'Recém-nascido a termo, com 4 dias de vida, apresenta icterícia progredindo até tronco e coxas. Bilirrubina total sérica de 16mg/dL, dentro da faixa de indicação de fototerapia pela curva de Bhutani para a idade pós-natal, sem sinais de hemólise (Coombs direto negativo, tipagem materna e do RN compatíveis).

A conduta mais adequada é', 'Suspender o aleitamento materno definitivamente', 'Indicar exsanguineotransfusão imediatamente', 'Aguardar resolução espontânea, sem qualquer intervenção', 'Iniciar fototerapia e monitorar níveis de bilirrubina', 'D', 'Bilirrubina em nível indicativo de fototerapia pela curva específica para idade pós-natal justifica o início de fototerapia, com monitorização seriada para avaliar resposta.', 'A: suspensão definitiva do aleitamento não é indicada rotineiramente. B: exsanguineotransfusão é reservada para níveis muito mais elevados ou sinais de encefalopatia aguda. C: aguardar sem tratamento expõe o RN a risco de encefalopatia bilirrubínica.', 'Em revisão', null, null, null),
  ('SIM1-074', 'simulado', '1', '74', 'Pediatria', 'Desnutrição infantil - classificação', 'Médio', null, null, 'Criança de 18 meses é trazida à UBS para consulta de puericultura. Peso para idade abaixo do percentil 3 na curva de crescimento, sem edema, com apetite preservado. Mãe relata dificuldades socioeconômicas importantes na alimentação da família nos últimos meses.

A classificação e conduta mais adequadas são', 'Desnutrição grave; internação hospitalar imediata obrigatória', 'Obesidade infantil; orientar restrição calórica', 'Peso adequado para a idade; não é necessária nenhuma conduta', 'Baixo peso para idade; investigação de causas, orientação nutricional e acompanhamento próximo do crescimento', 'D', 'Peso abaixo do percentil 3 caracteriza baixo peso para a idade; a conduta envolve investigar causas, orientar nutrição adequada e acompanhar de perto a curva de crescimento, sem exigir internação na ausência de sinais de gravidade.', 'A: sem sinais de gravidade (edema, complicações agudas), internação imediata não é a primeira conduta. B: o quadro descrito é de baixo peso, não excesso. C: o percentil descrito indica déficit de peso, não peso adequado.', 'Em revisão', null, null, null),
  ('SIM1-075', 'simulado', '1', '75', 'Pediatria', 'Convulsão febril', 'Médio', null, null, 'Criança de 2 anos apresenta episódio de convulsão tônico-clônica generalizada, com duração de 3 minutos, durante quadro febril (39°C) por infecção viral de vias aéreas superiores iniciada no mesmo dia. Recuperação completa da consciência após o episódio, sem sinais neurológicos focais, primeiro episódio da vida.

A conduta mais adequada é', 'Solicitar tomografia de crânio de urgência em todos os casos, independentemente da avaliação clínica', 'Tranquilizar os pais, tratar a causa da febre, orientar sinais de alarme e não é necessário anticonvulsivante de rotina', 'Iniciar anticonvulsivante profilático contínuo imediatamente', 'Investigação com punção lombar obrigatória em todos os casos', 'B', 'Trata-se de convulsão febril simples; a conduta é tranquilizar a família, tratar a causa da febre e orientar sinais de alarme, sem necessidade rotineira de exames de imagem, punção lombar ou anticonvulsivante profilático.', 'A: TC de crânio não é rotina sem sinais neurológicos focais ou outros achados de alarme. C: anticonvulsivante profilático contínuo não é indicado após episódio isolado. D: punção lombar não é obrigatória em toda convulsão febril simples.', 'Em revisão', null, null, null),
  ('SIM1-076', 'simulado', '1', '76', 'Pediatria', 'Bronquiolite viral aguda', 'Médio', null, null, 'Lactente de 4 meses apresenta coriza, tosse e sibilância há 2 dias, primeiro episódio da vida, com desconforto respiratório leve (FR 52irpm, tiragem subcostal discreta) e saturação 95% em ar ambiente, aceitando bem a alimentação, sem períodos de apneia.

A conduta mais adequada é', 'Iniciar antibioticoterapia empírica de amplo espectro', 'Iniciar corticoide sistêmico e broncodilatador inalatório de rotina', 'Manejo de suporte ambulatorial: desobstrução nasal, manutenção da hidratação/alimentação e orientação de sinais de alarme', 'Internação hospitalar obrigatória para todo primeiro episódio de sibilância', 'C', 'Bronquiolite viral aguda leve, sem sinais de gravidade, é manejada de forma ambulatorial com medidas de suporte: desobstrução nasal, manutenção de hidratação e orientação sobre sinais de piora.', 'A: bronquiolite tem etiologia viral; antibiótico não está indicado rotineiramente. B: corticoide sistêmico e broncodilatador não têm benefício comprovado de rotina na bronquiolite. D: internação não é obrigatória na ausência de sinais de gravidade.', 'Em revisão', null, null, null),
  ('SIM1-077', 'simulado', '1', '77', 'Pediatria', 'Coqueluche', 'Médio', null, null, 'Lactente de 2 meses apresenta tosse paroxística intensa, seguida de guincho inspiratório característico e episódios de cianose facial, há 1 semana, sem febre significativa. Mãe relata que a tosse piora à noite e é seguida de vômitos pós-tussígenos.

A hipótese diagnóstica mais provável e a conduta são', 'Coqueluche; iniciar macrolídeo (ex: azitromicina) e notificar o caso, com atenção a sinais de gravidade (apneia)', 'Asma; iniciar corticoide inalatório de manutenção', 'Refluxo gastroesofágico; iniciar inibidor de bomba de prótons', 'Bronquiolite viral; apenas suporte, sem necessidade de antibiótico ou notificação', 'A', 'Tosse paroxística com guincho inspiratório e cianose em lactente jovem é característica de coqueluche, doença de notificação compulsória; o tratamento é com macrolídeo, com atenção ao risco de apneia.', 'B: asma não é a hipótese mais provável nesse padrão característico. C: refluxo não explica o padrão paroxístico com guincho e cianose. D: o padrão de tosse paroxística com guincho não é típico de bronquiolite viral simples.', 'Em revisão', null, null, null),
  ('SIM1-078', 'simulado', '1', '78', 'Pediatria', 'Doença de Kawasaki', 'Difícil', null, null, 'Criança de 3 anos apresenta febre alta há 6 dias, refratária a antitérmicos, associada a hiperemia conjuntival bilateral não exsudativa, língua em framboesa, edema endurado de mãos e pés e exantema polimorfo em tronco. Sem foco infeccioso identificável.

A hipótese diagnóstica mais provável e a conduta são', 'Escarlatina; iniciar apenas penicilina oral, sem necessidade de avaliação cardiológica', 'Doença de Kawasaki; iniciar imunoglobulina intravenosa e AAS em dose anti-inflamatória, com avaliação cardiológica (risco de aneurisma coronariano)', 'Sarampo; apenas suporte clínico, sem necessidade de tratamento específico', 'Reação alérgica medicamentosa; suspender qualquer medicação e observar', 'B', 'Febre prolongada associada a conjuntivite não exsudativa, língua em framboesa, edema de extremidades e exantema polimorfo preenche critérios para doença de Kawasaki; o tratamento com imunoglobulina IV e AAS visa reduzir o risco de aneurismas coronarianos.', 'A: escarlatina tem outros achados distintos, sem o mesmo risco cardiológico específico. C: sarampo tem apresentação diferente e não gera esse risco coronariano. D: o quadro não é sugestivo de reação alérgica isolada.', 'Em revisão', null, null, null),
  ('SIM1-079', 'simulado', '1', '79', 'Pediatria', 'Refluxo gastroesofágico no lactente', 'Fácil', null, null, 'Lactente de 3 meses, em bom estado geral, ganho de peso adequado (curva ascendente regular), apresenta regurgitações frequentes após as mamadas, sem choro excessivo, recusa alimentar ou sinais de desconforto importante.

A conduta mais adequada é', 'Solicitar endoscopia digestiva alta em todos os casos de regurgitação', 'Iniciar inibidor de bomba de prótons imediatamente, independentemente da gravidade', 'Suspender o aleitamento materno e substituir por fórmula anti-refluxo obrigatoriamente', 'Orientar medidas posturais e fracionamento das mamadas, tranquilizando os pais quanto ao caráter fisiológico do refluxo do lactente', 'D', 'Regurgitações frequentes em lactente com bom estado geral e ganho de peso adequado, sem sinais de alarme, caracterizam refluxo fisiológico; orientação de medidas posturais e tranquilização dos pais.', 'A: endoscopia não é exame de rotina para regurgitação fisiológica. B: IBP não é indicado rotineiramente no refluxo fisiológico sem sinais de doença do refluxo. C: suspensão do aleitamento materno não é indicada rotineiramente.', 'Em revisão', null, null, null),
  ('SIM1-080', 'simulado', '1', '80', 'Pediatria', 'Constipação intestinal funcional', 'Fácil', null, null, 'Criança de 5 anos apresenta evacuações dolorosas e infrequentes (a cada 4-5 dias), fezes endurecidas em cíbalos, com esforço evacuatório visível, sem sinais de doença orgânica ao exame físico, sem distensão abdominal significativa ou massa palpável.

A conduta inicial mais adequada é', 'Orientação dietética (fibras, hidratação), desimpactação se necessário e uso de laxante conforme protocolo, com acompanhamento', 'Cirurgia para investigação de doença de Hirschsprung em todos os casos, sem outra avaliação', 'Nenhuma conduta é necessária, pois constipação na infância sempre se resolve sozinha', 'Restrição hídrica para reduzir o volume fecal', 'A', 'Constipação intestinal funcional é tratada com orientação dietética, desimpactação fecal quando necessário e laxantes conforme protocolo, com acompanhamento.', 'B: doença de Hirschsprung é diagnóstico diferencial em casos com sinais de alarme, não investigação de rotina. C: constipação funcional sem tratamento pode cronificar. D: restrição hídrica pode piorar a consistência das fezes.', 'Em revisão', null, null, null),
  ('SIM1-081', 'simulado', '1', '81', 'Pediatria', 'TDAH - avaliação diagnóstica', 'Médio', null, null, 'Criança de 8 anos apresenta dificuldade de concentração, desatenção e agitação motora em múltiplos ambientes (escola e casa) há mais de 6 meses, afetando o desempenho escolar e as relações sociais. Professora relata dificuldade de a criança permanecer sentada durante as aulas.

A conduta mais adequada para avaliação diagnóstica é', 'Avaliação clínica multidisciplinar, com critérios diagnósticos padronizados, considerando os sintomas em múltiplos ambientes e o impacto funcional', 'Iniciar metilfenidato empiricamente antes de qualquer avaliação diagnóstica estruturada', 'Diagnóstico imediato de TDAH apenas com base no relato dos pais, sem outra avaliação', 'Atribuir os sintomas exclusivamente a problemas comportamentais familiares, sem investigação adicional', 'A', 'O diagnóstico de TDAH requer avaliação clínica estruturada, com critérios padronizados, considerando sintomas em múltiplos ambientes e o impacto funcional, muitas vezes multidisciplinar.', 'B: tratamento medicamentoso não deve ser iniciado empiricamente antes de avaliação adequada. C: diagnóstico baseado apenas em relato dos pais, sem critérios estruturados, é insuficiente. D: atribuir exclusivamente a fatores familiares pode atrasar o diagnóstico correto.', 'Em revisão', null, null, null),
  ('SIM1-082', 'simulado', '1', '82', 'Pediatria', 'Anemia ferropriva na infância', 'Fácil', null, null, 'Criança de 18 meses, em aleitamento materno prolongado sem introdução adequada de alimentos ricos em ferro (dieta ainda predominantemente láctea), apresenta palidez notada pela mãe. Hemograma mostra hemoglobina 9,8g/dL, VCM baixo, ferritina reduzida.

A conduta mais adequada é', 'Nenhuma conduta é necessária, pois anemia nessa idade é sempre fisiológica', 'Transfusão sanguínea de rotina, independentemente da gravidade da anemia', 'Suplementação isolada de vitamina D, sem necessidade de ferro', 'Suplementação de ferro oral e orientação sobre alimentação complementar rica em ferro', 'D', 'Anemia ferropriva na infância, comum quando há atraso na introdução de alimentos ricos em ferro, é tratada com suplementação oral de ferro associada à orientação nutricional adequada.', 'A: anemia com hemoglobina reduzida e sintomas não deve ser considerada apenas fisiológica. B: transfusão não é rotina para anemia ferropriva sem repercussão hemodinâmica grave. C: vitamina D não trata a deficiência de ferro específica descrita.', 'Em revisão', null, null, null),
  ('SIM1-083', 'simulado', '1', '83', 'Pediatria', 'Púrpura de Henoch-Schönlein', 'Difícil', null, null, 'Criança de 6 anos apresenta púrpura palpável em membros inferiores e nádegas, dor abdominal em cólica e artralgia em joelhos e tornozelos, há 3 dias, uma semana após quadro de infecção de vias aéreas superiores. Hemograma com plaquetas normais. Exame de urina mostra hematúria microscópica.

A hipótese diagnóstica mais provável e a conduta são', 'Púrpura de Henoch-Schönlein; tratamento sintomático e monitorização de função renal (risco de nefrite)', 'Meningococcemia; iniciar antibioticoterapia de amplo espectro imediatamente, independente do estado geral', 'Alergia alimentar; apenas suspender possíveis alérgenos, sem outra investigação', 'Púrpura trombocitopênica idiopática; iniciar corticoide em altas doses imediatamente', 'A', 'Púrpura palpável em membros inferiores/nádegas associada a dor abdominal, artralgia e hematúria, com plaquetas normais, é característica de púrpura de Henoch-Schönlein; conduta sintomática com monitorização renal.', 'B: meningococcemia geralmente cursa com toxemia importante e evolução rápida. C: o padrão descrito não é explicado apenas por alergia alimentar. D: PTI cursa com trombocitopenia, ausente neste caso.', 'Em revisão', null, null, null),
  ('SIM1-084', 'simulado', '1', '84', 'Pediatria', 'Escabiose - manejo', 'Fácil', null, null, 'Criança apresenta prurido intenso, principalmente noturno, com lesões papulares e sulcos em espaços interdigitais, punhos e região genital, há 2 semanas. Outros três membros da família relatam sintomas semelhantes iniciados na mesma época.

A conduta mais adequada é', 'Tratamento apenas do paciente índice, sem necessidade de tratar os contactantes', 'Apenas anti-histamínico oral, sem necessidade de tratamento tópico específico', 'Corticoide tópico isolado, sem necessidade de tratamento específico para o ácaro', 'Tratamento com escabicida tópico (ex: permetrina) para o paciente e contactantes domiciliares, com lavagem de roupas de cama', 'D', 'Escabiose é tratada com escabicida tópico, aplicado no paciente e em todos os contactantes domiciliares simultaneamente, associado a medidas de higiene das roupas.', 'A: não tratar os contactantes permite reinfestação. B: anti-histamínico pode aliviar o prurido, mas não trata a infestação. C: corticoide tópico isolado não elimina o ácaro, podendo mascarar o quadro.', 'Em revisão', null, null, null),
  ('SIM1-085', 'simulado', '1', '85', 'Pediatria', 'Otite média aguda', 'Médio', null, null, 'Criança de 2 anos apresenta febre (38,7°C), irritabilidade importante e choro ao manipular o pavilhão auricular direito há 2 dias, com recusa alimentar. Otoscopia mostra membrana timpânica hiperemiada, abaulada e com perda do triângulo luminoso.

A conduta mais adequada é', 'Apenas analgesia, sem necessidade de antibiótico em nenhum caso de otite média aguda', 'Miringotomia de urgência em todos os casos, independentemente da gravidade', 'Observação sem qualquer tratamento, pois otite média sempre resolve espontaneamente', 'Antibioticoterapia (ex: amoxicilina) e analgesia, considerando gravidade e idade da criança', 'D', 'Otite média aguda em criança pequena (<2 anos) com sinais de gravidade geralmente tem indicação de antibioticoterapia associada a analgesia adequada.', 'A: em menores de 2 anos com sinais de gravidade, o antibiótico costuma ser indicado. B: miringotomia é reservada para casos específicos, não é conduta de rotina. C: otite com sinais de gravidade não deve ser deixada sem tratamento.', 'Em revisão', null, null, null),
  ('SIM1-086', 'simulado', '1', '86', 'Pediatria', 'Faringoamigdalite estreptocócica', 'Fácil', null, null, 'Criança de 7 anos apresenta febre (38,9°C), dor de garganta intensa de início súbito, exsudato amigdaliano purulento bilateral e linfadenopatia cervical anterior dolorosa, sem tosse, coriza ou rouquidão associadas.

A conduta mais adequada é', 'Iniciar apenas anti-histamínico, pois o quadro é provavelmente alérgico', 'Considerar tratamento com penicilina (ou amoxicilina) para faringoamigdalite estreptocócica, conforme critérios clínicos/teste rápido quando disponível', 'Não tratar com antibiótico em nenhuma circunstância, pois faringite é sempre viral', 'Indicar amigdalectomia de urgência como tratamento do episódio agudo', 'B', 'Febre, exsudato purulento, linfadenopatia cervical dolorosa e ausência de sintomas de via aérea superior sugerem etiologia estreptocócica; tratamento com penicilina ou amoxicilina.', 'A: o quadro não é sugestivo de processo alérgico. C: o quadro apresentado tem características clássicas de etiologia estreptocócica, que se beneficia de antibiótico. D: amigdalectomia não é tratamento do episódio agudo.', 'Em revisão', null, null, null),
  ('SIM1-087', 'simulado', '1', '87', 'Pediatria', 'Aleitamento materno exclusivo - recomendações', 'Fácil', null, null, 'Mãe de recém-nascido saudável, sem contraindicações, pergunta na UBS até quando deve manter o aleitamento materno exclusivo antes de iniciar a alimentação complementar.

A orientação mais adequada segundo o Ministério da Saúde é', 'Aleitamento materno exclusivo por tempo indeterminado, sem necessidade de alimentação complementar', 'Aleitamento materno exclusivo até os 6 meses de vida, com introdução de alimentação complementar a partir de então, mantendo o aleitamento até os 2 anos ou mais', 'Introdução de água e chás já a partir do primeiro mês de vida, associada ao leite materno', 'Aleitamento materno exclusivo até os 3 meses, com introdução obrigatória de fórmula a partir de então', 'B', 'A recomendação do Ministério da Saúde é aleitamento materno exclusivo até os 6 meses, com introdução da alimentação complementar a partir dessa idade, mantendo o aleitamento até os 2 anos ou mais.', 'A: alimentação complementar é necessária a partir dos 6 meses. C: água e chás não devem ser introduzidos antes dos 6 meses em aleitamento exclusivo. D: introdução de fórmula aos 3 meses não é a recomendação padrão.', 'Em revisão', null, null, null),
  ('SIM1-088', 'simulado', '1', '88', 'Medicina Preventiva e Social', 'Vigilância epidemiológica / notificação compulsória', 'Fácil', null, null, 'Médico de UBS atende paciente de 22 anos com diagnóstico clínico de dengue apresentando sinais de alarme (dor abdominal intensa, vômitos persistentes, letargia). Além da conduta clínica de internação, a equipe discute os próximos passos administrativos do caso.

A providência de saúde pública obrigatória nesse momento é', 'Notificação apenas por meio do serviço de vigilância hospitalar, não cabendo à UBS', 'Notificação facultativa, a critério do médico assistente', 'Notificação apenas se houver óbito confirmado', 'Notificação compulsória imediata às autoridades de vigilância epidemiológica', 'D', 'Dengue com sinais de alarme é doença de notificação compulsória imediata (até 24h) no Brasil, dado seu potencial de gravidade e importância para vigilância epidemiológica e controle de surtos.', 'A: a notificação é responsabilidade de qualquer serviço de saúde que atenda o caso. B: notificação compulsória não é facultativa, é obrigação legal do profissional de saúde. C: notificação não depende de óbito; casos suspeitos/confirmados já exigem notificação.', 'Em revisão', null, null, null),
  ('SIM1-089', 'simulado', '1', '89', 'Medicina Preventiva e Social', 'Atributos da Atenção Primária à Saúde', 'Médio', null, null, 'Uma Unidade Básica de Saúde organiza seu atendimento de forma que o mesmo paciente é sempre acompanhado pela mesma equipe de referência ao longo do tempo, integrando cuidados de diferentes especialidades quando necessário, com troca sistemática de informações entre os níveis de atenção.

Esse conjunto de características corresponde a quais atributos da Atenção Primária à Saúde?', 'Descentralização administrativa', 'Longitudinalidade e coordenação do cuidado', 'Universalidade e integralidade exclusivamente', 'Regionalização e hierarquização', 'B', 'Longitudinalidade refere-se ao vínculo contínuo entre paciente e equipe ao longo do tempo; coordenação do cuidado refere-se à integração de diferentes pontos de atenção — ambos atributos essenciais da APS segundo Starfield.', 'A: descentralização é princípio organizativo do SUS, não atributo da APS descrito no caso. C: universalidade/integralidade são princípios do SUS, mas não descrevem especificamente o cenário. D: regionalização/hierarquização dizem respeito à organização da rede, não ao vínculo longitudinal descrito.', 'Em revisão', null, null, null),
  ('SIM1-090', 'simulado', '1', '90', 'Medicina Preventiva e Social', 'Indicadores de saúde / mortalidade infantil', 'Médio', null, null, 'Em um município com 3.000 nascidos vivos em determinado ano, ocorreram 30 óbitos de crianças menores de 1 ano no mesmo período e local, sendo 18 óbitos no período neonatal e 12 no período pós-neonatal.

O coeficiente de mortalidade infantil desse município é, e o que ele reflete', '10 por mil nascidos vivos; reflete principalmente condições socioeconômicas e acesso a serviços de saúde', '30 por mil nascidos vivos; reflete apenas mortalidade neonatal precoce', '1 por mil nascidos vivos; reflete exclusivamente causas obstétricas', '100 por mil nascidos vivos; indicador exclusivo de mortalidade por causas infecciosas', 'A', 'Coeficiente de mortalidade infantil = (óbitos <1 ano / nascidos vivos) x 1000 = (30/3000)x1000 = 10 por mil nascidos vivos. É indicador sensível a condições de vida, saneamento e qualidade da assistência.', 'B: erro de cálculo (30 é o número absoluto de óbitos, não o coeficiente). C: cálculo incorreto e definição incompleta. D: cálculo e afirmação incorretos; o indicador engloba múltiplas causas.', 'Em revisão', null, null, null),
  ('SIM1-091', 'simulado', '1', '91', 'Medicina Preventiva e Social', 'Rastreamento de câncer de colo uterino', 'Médio', null, null, 'Mulher de 30 anos, sem comorbidades, com vida sexual ativa desde os 18 anos, procura a UBS para rotina ginecológica. Nunca realizou exame preventivo.

Segundo as diretrizes do Ministério da Saúde, a conduta de rastreamento mais adequada é', 'Não é necessário rastreamento antes dos 40 anos', 'Realizar citologia oncótica (Papanicolau) anualmente, indefinidamente', 'Realizar apenas exame de HPV isolado, sem necessidade de citologia', 'Realizar citologia oncótica; se dois exames anuais consecutivos normais, repetir a cada 3 anos', 'D', 'O rastreamento do câncer de colo do útero no Brasil é feito por citologia oncótica, iniciando aos 25 anos em mulheres com vida sexual ativa; após dois exames anuais normais consecutivos, o intervalo passa a ser trienal.', 'A: o rastreamento se inicia aos 25 anos, não aos 40. B: rastreamento anual indefinido não é a recomendação após dois exames normais consecutivos. C: o protocolo nacional ainda é baseado na citologia oncótica na maior parte da rede.', 'Em revisão', null, null, null),
  ('SIM1-092', 'simulado', '1', '92', 'Medicina Preventiva e Social', 'Transição demográfica / pirâmide etária', 'Médio', null, null, 'Um município apresenta pirâmide etária com base estreita e topo alargado, refletindo redução progressiva da natalidade e aumento da expectativa de vida ao longo das últimas três décadas, segundo dados do censo demográfico local.

Esse padrão está associado a qual mudança esperada nas necessidades de saúde da população?', 'Nenhuma mudança relevante na organização dos serviços de saúde', 'Redução da demanda por doenças crônico-degenerativas e aumento da demanda por saúde materno-infantil', 'Aumento da demanda por cuidados relacionados a doenças crônico-degenerativas e menor pressão sobre serviços materno-infantis', 'Aumento exclusivo da mortalidade infantil como principal desafio de saúde pública', 'C', 'Uma pirâmide com base estreita e topo alargado reflete população envelhecendo — a transição demográfica —, associada a maior demanda por doenças crônico-degenerativas e menor pressão proporcional sobre serviços materno-infantis.', 'A: a mudança demográfica exige reorganização relevante dos serviços de saúde. B: o padrão descrito é o oposto do afirmado. D: o padrão reflete população envelhecida, não aumento de mortalidade infantil.', 'Em revisão', null, null, null),
  ('SIM1-093', 'simulado', '1', '93', 'Medicina Preventiva e Social', 'Redes de Atenção à Saúde - referência e contrarreferência', 'Médio', null, null, 'Uma UBS encaminha um paciente com suspeita de neoplasia para avaliação especializada em hospital de referência regional. Após a consulta, o especialista devolve relatório detalhado com orientações de seguimento para a equipe da atenção primária continuar o cuidado.

Esse fluxo caracteriza qual princípio organizativo do SUS?', 'Hierarquização, apenas', 'Sistema de referência e contrarreferência, dentro da Rede de Atenção à Saúde (RAS)', 'Municipalização exclusiva dos serviços de saúde', 'Universalidade de acesso', 'B', 'O fluxo descrito — encaminhamento à referência e retorno de informações para continuidade do cuidado — caracteriza o sistema de referência e contrarreferência, essencial para a coordenação do cuidado na RAS.', 'A: hierarquização descreve a organização por níveis de complexidade, mas não capta o fluxo de ida e volta descrito. C: o caso não trata de municipalização, mas de articulação entre níveis assistenciais. D: universalidade refere-se ao acesso garantido a todos, não ao fluxo de comunicação.', 'Em revisão', null, null, null),
  ('SIM1-094', 'simulado', '1', '94', 'Medicina Preventiva e Social', 'Indicadores epidemiológicos - incidência e prevalência', 'Fácil', null, null, 'Em uma cidade com população estável de 100.000 habitantes, foram registrados 500 novos casos de determinada doença ao longo de um ano, e o total de casos existentes (novos e antigos) no fim do ano foi de 2.000.

Os conceitos epidemiológicos que correspondem a esses dois números, respectivamente, são', 'Prevalência (500 novos casos) e incidência (2.000 casos totais)', 'Incidência (500 novos casos) e prevalência (2.000 casos totais)', 'Ambos os números representam apenas incidência, em períodos diferentes', 'Ambos os números representam apenas prevalência, em momentos diferentes', 'B', 'Incidência refere-se ao número de casos novos em um período (500 no ano); prevalência refere-se ao total de casos existentes em um determinado momento (2.000 ao fim do ano).', 'A: inverte os conceitos corretos. C: o segundo número caracteriza prevalência, não incidência. D: os dois números representam conceitos diferentes.', 'Em revisão', null, null, null),
  ('SIM1-095', 'simulado', '1', '95', 'Medicina Preventiva e Social', 'Sensibilidade e especificidade de testes diagnósticos', 'Médio', null, null, 'Um novo teste diagnóstico para determinada doença apresenta alta sensibilidade e baixa especificidade, segundo estudo de validação realizado em população de referência.

A implicação mais adequada do uso desse teste na prática clínica é', 'O teste é adequado apenas para confirmar diagnóstico em pacientes já sintomáticos, não para rastreamento', 'O teste é ideal tanto para rastreamento quanto para confirmação diagnóstica definitiva, sem necessidade de outros exames', 'O teste é útil para rastreamento inicial (poucos falsos negativos), mas resultados positivos exigem confirmação com teste mais específico, pelo risco de falsos positivos', 'O teste deve ser evitado, pois alta sensibilidade sempre indica baixa qualidade do exame', 'C', 'Um teste com alta sensibilidade tem poucos falsos negativos, sendo útil para rastreamento; a baixa especificidade gera mais falsos positivos, exigindo confirmação com teste mais específico.', 'A: testes de alta sensibilidade são particularmente úteis para rastreamento. B: baixa especificidade compromete o uso do teste como confirmatório isolado. D: alta sensibilidade não indica baixa qualidade; depende do objetivo do teste.', 'Em revisão', null, null, null),
  ('SIM1-096', 'simulado', '1', '96', 'Medicina Preventiva e Social', 'Determinantes sociais da saúde', 'Médio', null, null, 'Um estudo municipal demonstra que famílias de baixa renda, com menor escolaridade e moradia precária, apresentam maior incidência de doenças infecciosas e maior mortalidade infantil em comparação a famílias de maior renda na mesma cidade.

Esse achado ilustra principalmente qual conceito em saúde coletiva?', 'Fenômeno restrito a países de baixa renda, sem relevância para o contexto brasileiro', 'Acaso estatístico, sem relação causal entre condição socioeconômica e saúde', 'Determinantes exclusivamente biológicos das doenças infecciosas, sem relação com fatores sociais', 'Determinantes sociais da saúde, que influenciam diretamente as condições de saúde e adoecimento das populações', 'D', 'A associação entre condições socioeconômicas e piores desfechos de saúde ilustra o conceito de determinantes sociais da saúde, que reconhece que fatores sociais, econômicos e ambientais influenciam o processo saúde-doença.', 'A: determinantes sociais são relevantes em todos os contextos, incluindo o Brasil. B: a associação é amplamente documentada, não sendo mero acaso. C: fatores biológicos isolados não explicam as diferenças entre grupos socioeconômicos na mesma cidade.', 'Em revisão', null, null, null),
  ('SIM1-097', 'simulado', '1', '97', 'Medicina Preventiva e Social', 'Vigilância sanitária', 'Fácil', null, null, 'Um restaurante é fiscalizado por apresentar condições inadequadas de armazenamento de alimentos, resultando em interdição parcial do estabelecimento até a regularização, conforme auto de infração lavrado pela equipe responsável.

Essa ação é de responsabilidade de qual área da vigilância em saúde?', 'Vigilância sanitária, responsável por normatizar e fiscalizar produtos, serviços e ambientes que possam representar risco à saúde da população', 'Vigilância epidemiológica, responsável exclusivamente pelo monitoramento de doenças transmissíveis', 'Vigilância ambiental, responsável apenas pelo monitoramento da qualidade da água e do ar', 'Atenção primária à saúde, responsável pela fiscalização de estabelecimentos comerciais', 'A', 'A vigilância sanitária é responsável por ações de fiscalização e regulação de produtos, serviços e ambientes, visando eliminar, diminuir ou prevenir riscos à saúde da população.', 'B: a vigilância epidemiológica atua no monitoramento e controle de doenças e agravos, não na fiscalização de estabelecimentos. C: a vigilância ambiental tem outro escopo. D: a atenção primária não tem como atribuição a fiscalização sanitária.', 'Em revisão', null, null, null),
  ('SIM1-098', 'simulado', '1', '98', 'Medicina Preventiva e Social', 'Imunização - contraindicações vacinais', 'Médio', null, null, 'Criança de 6 meses, em tratamento com corticoide sistêmico em dose imunossupressora para doença de base há 3 semanas, comparece à UBS para receber as vacinas de rotina previstas no calendário nacional para a idade.

A orientação mais adequada em relação às vacinas de vírus vivo atenuado é', 'O uso de corticoide não tem nenhuma relação com a segurança de vacinas de vírus vivo', 'Todas as vacinas do calendário devem ser aplicadas normalmente, independentemente do uso de imunossupressores', 'Vacinas de vírus vivo atenuado devem ser adiadas enquanto a criança estiver em uso de corticoide em dose imunossupressora, sendo administradas após suspensão adequada da medicação', 'Vacinas inativadas também devem ser suspensas nesse contexto', 'C', 'Crianças em uso de corticoide sistêmico em dose imunossupressora têm contraindicação temporária para vacinas de vírus vivo atenuado, pelo risco de doença vacinal disseminada.', 'A: há relação direta e relevante entre imunossupressão e segurança de vacinas de vírus vivo. B: vacinas de vírus vivo têm contraindicação específica nesse contexto. D: vacinas inativadas geralmente podem ser mantidas mesmo em imunossupressão.', 'Em revisão', null, null, null),
  ('SIM1-099', 'simulado', '1', '99', 'Medicina Preventiva e Social', 'Saúde do trabalhador - notificação de agravos', 'Médio', null, null, 'Um trabalhador de fábrica desenvolve perda auditiva progressiva relacionada à exposição ocupacional a ruído intenso sem uso adequado de proteção auricular, confirmada por audiometria ocupacional seriada ao longo de 3 anos.

Além da conduta clínica individual, a providência de saúde pública esperada é', 'Notificação apenas se houver afastamento do trabalho superior a 15 dias', 'Notificação do agravo relacionado ao trabalho e investigação das condições de segurança no ambiente laboral', 'Nenhuma notificação é necessária, pois perda auditiva não é considerada doença ocupacional', 'A responsabilidade é exclusivamente da empresa, sem necessidade de notificação pelos serviços de saúde', 'B', 'Perda auditiva induzida por ruído ocupacional é agravo relacionado ao trabalho de notificação compulsória; deve-se notificar e investigar as condições de segurança do ambiente laboral.', 'A: a notificação não depende do tempo de afastamento. C: perda auditiva induzida por ruído é reconhecida como doença ocupacional e deve ser notificada. D: a notificação pelos serviços de saúde é complementar à responsabilidade da empresa.', 'Em revisão', null, null, null),
  ('SIM1-100', 'simulado', '1', '100', 'Medicina Preventiva e Social', 'Política Nacional de Atenção Básica - territorialização', 'Médio', null, null, 'Uma equipe de Estratégia Saúde da Família atua com território adscrito bem definido, realizando cadastramento sistemático das famílias, visitas domiciliares regulares e acompanhamento longitudinal da população residente na área, conforme diagnóstico situacional construído pela equipe.

Esses elementos são característicos de qual princípio organizativo previsto na PNAB?', 'Regionalização da alta complexidade hospitalar', 'Hierarquização exclusiva dos níveis de atenção, sem relação com território', 'Livre demanda, sem necessidade de território definido', 'Territorialização e adscrição de clientela, associadas ao vínculo longitudinal entre equipe e população', 'D', 'A definição de território adscrito, o cadastramento das famílias e o acompanhamento longitudinal caracterizam os princípios de territorialização e adscrição de clientela da Política Nacional de Atenção Básica.', 'A: regionalização da alta complexidade não é o conceito ilustrado. B: hierarquização refere-se à organização por níveis de complexidade, não ao território e vínculo descritos. C: livre demanda sem território definido é o oposto do modelo descrito.', 'Em revisão', null, null, null),
  ('SIM2-001', 'simulado', '2', '1', 'Clínica Médica', 'Insuficiência cardíaca crônica - otimização terapêutica', 'Médio', null, null, 'Paciente de 60 anos, com IC de fração de ejeção reduzida (FEVE 32%) diagnosticada há 1 ano, em uso apenas de furosemida, encontra-se estável, classe funcional II (NYHA), sem sinais de congestão. PA 118x76mmHg, FC 78bpm, função renal e potássio normais.

Além do diurético, a conduta mais adequada para otimização terapêutica é', 'Iniciar bloqueador de canal de cálcio como primeira linha para IC com FE reduzida', 'Introduzir IECA (ou BRA) e betabloqueador específico para IC, com titulação progressiva da dose', 'Manter apenas furosemida, sem necessidade de outros medicamentos enquanto estável', 'Iniciar anticoagulação plena de rotina, independente de fibrilação atrial', 'B', 'Na IC com FE reduzida, IECA/BRA e betabloqueador específico reduzem mortalidade e devem ser introduzidos e titulados progressivamente, mesmo em paciente estável, como parte do tratamento modificador de doença.', 'A: bloqueador de canal de cálcio não é primeira linha em ICFEr. C: diurético isolado trata sintomas, não modifica a progressão da doença. D: anticoagulação de rotina não é indicada sem indicação específica (ex: FA, trombo).', 'Em revisão', null, null, null),
  ('SIM2-002', 'simulado', '2', '2', 'Clínica Médica', 'Crise asmática grave em adulto', 'Difícil', null, null, 'Paciente de 32 anos, asmático, é trazido ao PS com dispneia intensa há 2 horas, sem resposta a broncodilatador domiciliar. Fala apenas palavras isoladas, uso importante de musculatura acessória, sibilos que se tornaram menos audíveis nos últimos minutos, saturação 89% em ar ambiente, FC 128bpm.

A conduta mais adequada é', 'Alta com broncodilatador de resgate e retorno se piora', 'Apenas observação, pois a diminuição dos sibilos indica melhora do broncoespasmo', 'Broncodilatador de curta ação contínuo/repetido, corticoide sistêmico, oxigenoterapia e considerar sulfato de magnésio IV, com preparo para via aérea avançada se piora', 'Iniciar antibioticoterapia empírica como conduta prioritária', 'C', 'A diminuição dos sibilos em paciente grave pode indicar ''tórax silencioso'' por obstrução quase completa, sinal de gravidade extrema — a conduta é tratamento intensivo (broncodilatador contínuo, corticoide, magnésio) com preparo para via aérea avançada.', 'A: gravidade do quadro contraindica alta hospitalar. B: a diminuição dos sibilos aqui é sinal de alarme, não de melhora. D: antibiótico não é prioridade na crise asmática sem sinais de infecção.', 'Em revisão', null, null, null),
  ('SIM2-003', 'simulado', '2', '3', 'Clínica Médica', 'Cetoacidose diabética', 'Médio', null, null, 'Paciente de 19 anos, diabético tipo 1, é trazido ao PS com dor abdominal, vômitos e hálito cetônico, após 2 dias sem aplicar insulina por falta de recursos. Glicemia capilar 480mg/dL, desidratado, taquipneico com respiração de Kussmaul.

Além da insulinoterapia e hidratação venosa, a conduta inicial deve incluir', 'Administração de bicarbonato de sódio de rotina, independente do pH', 'Suspensão da insulina até normalização completa da glicemia', 'Restrição hídrica para evitar sobrecarga volêmica', 'Monitorização rigorosa do potássio sérico antes e durante a reposição de insulina, corrigindo hipocalemia se presente', 'D', 'Na CAD, a insulinoterapia desloca potássio para o intracelular, podendo causar hipocalemia grave; deve-se monitorar e corrigir o potássio antes/durante o tratamento, mesmo com potássio inicial normal ou levemente elevado.', 'A: bicarbonato não é rotina, reservado para acidose muito grave (pH <6,9). B: a insulina deve ser mantida continuamente até resolução da cetoacidose, não suspensa precocemente. C: hidratação venosa vigorosa é necessária, não restrição.', 'Em revisão', null, null, null),
  ('SIM2-004', 'simulado', '2', '4', 'Clínica Médica', 'Estado hiperosmolar hiperglicêmico', 'Difícil', null, null, 'Paciente de 72 anos, diabético tipo 2, é trazido pela família com rebaixamento progressivo do nível de consciência ao longo de 3 dias, associado a poliúria e polidipsia importantes. Glicemia capilar 780mg/dL, sem hálito cetônico, gasometria com pH 7,32 e cetonúria ausente. Osmolaridade sérica calculada muito elevada.

A conduta inicial mais adequada é', 'Administrar bicarbonato de sódio como primeira medida terapêutica', 'Hidratação venosa vigorosa com solução salina, seguida de insulinoterapia, com correção lenta e cuidadosa da osmolaridade', 'Iniciar insulinoterapia em bolus isolada, sem priorizar reposição volêmica', 'Restringir líquidos pelo risco de edema cerebral no idoso', 'B', 'No estado hiperosmolar hiperglicêmico, a desidratação é acentuada; a prioridade inicial é reposição volêmica vigorosa, seguida de insulinoterapia, com correção lenta da osmolaridade para evitar edema cerebral por queda rápida.', 'A: não há acidose significativa que justifique bicarbonato. C: insulina isolada sem hidratação prévia pode agravar o colapso circulatório. D: restringir líquidos é contrário ao tratamento, que exige reposição volêmica vigorosa.', 'Em revisão', null, null, null),
  ('SIM2-005', 'simulado', '2', '5', 'Clínica Médica', 'Hipoglicemia grave', 'Médio', null, null, 'Paciente de 68 anos, diabético em uso de glibenclamida, é encontrado pela família confuso e sudoreico, sem resposta adequada a comandos verbais. Glicemia capilar 38mg/dL. Não é possível obter acesso venoso rapidamente.

A conduta mais adequada nesse momento é', 'Aguardar a obtenção de acesso venoso antes de qualquer intervenção terapêutica', 'Oferecer alimento sólido por via oral imediatamente, apesar do rebaixamento do nível de consciência', 'Administrar apenas água com açúcar por via oral, independente do nível de consciência', 'Administrar glucagon intramuscular, seguido de glicose assim que houver acesso venoso disponível', 'D', 'Em hipoglicemia grave com rebaixamento de consciência e sem acesso venoso disponível, o glucagon intramuscular é a conduta inicial mais adequada, complementado por glicose IV assim que possível.', 'A: atrasar o tratamento em hipoglicemia grave pode causar lesão neurológica. B e C: oferecer alimento/líquido por via oral em paciente com rebaixamento de consciência tem risco de broncoaspiração.', 'Em revisão', null, null, null),
  ('SIM2-006', 'simulado', '2', '6', 'Clínica Médica', 'Anemia megaloblástica (deficiência de B12)', 'Médio', null, null, 'Paciente de 65 anos, vegetariano estrito há 20 anos, sem reposição vitamínica, apresenta fadiga progressiva, parestesias em mãos e pés e dificuldade de marcha nos últimos meses. Hemograma mostra anemia macrocítica (VCM 118fL) com neutrófilos hipersegmentados. Exame neurológico com alteração da propriocepção em membros inferiores.

A conduta mais adequada é', 'Iniciar reposição de ferro isolada, sem necessidade de outros exames', 'Solicitar dosagem de vitamina B12 e ácido fólico, e iniciar reposição de B12 parenteral se confirmada a deficiência', 'Iniciar transfusão sanguínea imediata, independente da gravidade clínica', 'Tranquilizar o paciente, pois dieta vegetariana não causa deficiências nutricionais relevantes', 'B', 'Anemia macrocítica com neutrófilos hipersegmentados e sintomas neurológicos (parestesias, alteração proprioceptiva) em paciente com dieta restritiva sugere deficiência de B12; deve-se confirmar e repor por via parenteral, especialmente com acometimento neurológico.', 'A: ferro trata anemia microcítica, não macrocítica. C: transfusão não é a conduta inicial para anemia crônica sem repercussão hemodinâmica grave. D: dieta vegetariana estrita sem suplementação é fator de risco real para deficiência de B12.', 'Em revisão', null, null, null),
  ('SIM2-007', 'simulado', '2', '7', 'Clínica Médica', 'Anemia hemolítica autoimune', 'Difícil', null, null, 'Paciente de 45 anos, com lúpus eritematoso sistêmico conhecido, apresenta icterícia, colúria e fadiga intensa de início recente. Teste de Coombs direto positivo. Exames laboratoriais coletados na admissão:', 'Anemia ferropriva; iniciar suplementação de ferro oral', 'Anemia aplásica; encaminhar para transplante de medula óssea imediato', 'Anemia hemolítica autoimune; iniciar corticoterapia sistêmica em dose imunossupressora', 'Talassemia maior; iniciar quelação de ferro', 'C', 'Icterícia, reticulocitose, bilirrubina indireta e LDH elevados com Coombs direto positivo em paciente lúpico confirmam anemia hemolítica autoimune; o tratamento inicial é corticoterapia sistêmica em dose imunossupressora.', 'A: ferropriva cursaria com reticulócitos baixos e Coombs negativo, quadro oposto ao descrito. B: aplásica cursa com pancitopenia e reticulócitos baixos, não hemólise. D: talassemia não explica o Coombs positivo nem o início agudo do quadro.', 'Em revisão', '[object Object]', null, null),
  ('SIM2-008', 'simulado', '2', '8', 'Clínica Médica', 'Doença celíaca', 'Médio', null, null, 'Paciente de 30 anos apresenta diarreia crônica intermitente, distensão abdominal e perda de peso não intencional há 6 meses, associada a episódios de anemia recorrente sem causa aparente. Sorologia para anticorpo antitransglutaminase IgA é fortemente positiva.

A conduta mais adequada para confirmação diagnóstica é', 'Iniciar dieta sem glúten imediatamente, sem necessidade de biópsia confirmatória', 'Iniciar corticoterapia empírica, sem investigação adicional', 'Solicitar apenas exame de fezes para parasitas, sem necessidade de outros exames', 'Biópsia de intestino delgado (duodeno) por endoscopia digestiva alta, mantendo a dieta com glúten até a confirmação', 'D', 'A sorologia positiva sugere doença celíaca, mas a confirmação diagnóstica padrão-ouro é a biópsia duodenal, que deve ser realizada com o paciente ainda em dieta contendo glúten, para não mascarar as alterações histológicas.', 'A: iniciar a dieta sem glúten antes da biópsia pode normalizar a mucosa e prejudicar o diagnóstico definitivo. B: corticoide não é o tratamento da doença celíaca, que é dietético. C: exame parasitológico não investiga doença celíaca.', 'Em revisão', null, null, null),
  ('SIM2-009', 'simulado', '2', '9', 'Clínica Médica', 'Doença inflamatória intestinal (retocolite ulcerativa)', 'Difícil', null, null, 'Paciente de 28 anos apresenta diarreia sanguinolenta há 6 semanas, com até 8 evacuações diárias, dor abdominal em cólica e urgência evacuatória, associada a febre baixa intermitente. Colonoscopia mostra mucosa retal e de cólon esquerdo com friabilidade, úlceras superficiais e padrão contínuo de acometimento, poupando o restante do cólon.

A hipótese diagnóstica mais provável é', 'Retocolite ulcerativa', 'Síndrome do intestino irritável', 'Doença de Crohn', 'Colite isquêmica', 'A', 'Acometimento contínuo, iniciado no reto e limitado à mucosa/submucosa, com diarreia sanguinolenta, é característico de retocolite ulcerativa, diferente do padrão salteado e transmural da doença de Crohn.', 'B: síndrome do intestino irritável não causa sangramento nem alterações endoscópicas inflamatórias. C: doença de Crohn tipicamente tem acometimento salteado e transmural, podendo afetar qualquer segmento do trato digestivo. D: colite isquêmica tem apresentação aguda, geralmente em pacientes com fatores de risco vascular.', 'Em revisão', null, null, null),
  ('SIM2-010', 'simulado', '2', '10', 'Clínica Médica', 'Síndrome do intestino irritável', 'Fácil', null, null, 'Paciente de 35 anos relata dor abdominal recorrente há 8 meses, associada a alteração do hábito intestinal (alternância entre constipação e diarreia), que melhora após a evacuação. Nega sangramento, perda de peso, febre ou sintomas noturnos. Exames laboratoriais básicos e exame físico sem alterações.

A conduta mais adequada é', 'Encaminhar imediatamente para cirurgia, independente da investigação', 'Diagnóstico clínico de síndrome do intestino irritável, com orientação dietética e sintomáticos, reservando exames complementares para sinais de alarme', 'Iniciar corticoterapia sistêmica empírica', 'Solicitar colonoscopia obrigatória em todos os casos antes de qualquer conduta', 'B', 'Na ausência de sinais de alarme (sangramento, perda de peso, sintomas noturnos, início após os 50 anos), o diagnóstico de síndrome do intestino irritável pode ser feito clinicamente pelos critérios de Roma, com tratamento sintomático inicial.', 'A: não há indicação cirúrgica para síndrome do intestino irritável. C: corticoide não tem indicação nesse quadro funcional. D: colonoscopia não é obrigatória na ausência de sinais de alarme.', 'Em revisão', null, null, null),
  ('SIM2-011', 'simulado', '2', '11', 'Clínica Médica', 'Litíase renal / cólica nefrética', 'Médio', null, null, 'Paciente de 40 anos apresenta dor lombar súbita, intensa, em cólica, irradiando para a região inguinal, associada a náuseas e hematúria microscópica, há 3 horas. Está agitado, sem conseguir posição de conforto. Sinais vitais estáveis, afebril.

A conduta inicial mais adequada é', 'Cirurgia de urgência imediata, independente do tamanho do cálculo', 'Antibioticoterapia empírica de amplo espectro, sem necessidade de exame de imagem', 'Alta imediata sem analgesia, orientando retorno apenas se houver febre', 'Analgesia adequada (anti-inflamatório ou opioide), hidratação e exame de imagem (USG ou TC de vias urinárias) para confirmação e localização do cálculo', 'D', 'Cólica nefrética típica (dor lombar súbita irradiando para região inguinal, hematúria) tem conduta inicial de analgesia efetiva, hidratação e exame de imagem para confirmar e caracterizar o cálculo, orientando conduta subsequente.', 'A: a maioria dos cálculos pequenos elimina espontaneamente, cirurgia não é conduta inicial de rotina. B: antibiótico não é indicado sem sinais de infecção associada. C: dor intensa sem tratamento e sem investigação não é conduta adequada.', 'Em revisão', null, null, null),
  ('SIM2-012', 'simulado', '2', '12', 'Clínica Médica', 'Glomerulonefrite pós-estreptocócica', 'Médio', null, null, 'Criança de 7 anos apresenta edema periorbital e urina cor de ''coca-cola'' há 2 dias, cerca de 2 semanas após um quadro de faringite não tratada. Exame de urina mostra hematúria dismórfica e proteinúria não nefrótica. Sinais vitais e exames coletados na admissão:', 'Síndrome nefrótica idiopática; iniciar corticoterapia imediatamente', 'Púrpura de Henoch-Schönlein; apenas observação clínica', 'Infecção urinária; iniciar antibiótico oral ambulatorial', 'Glomerulonefrite difusa aguda pós-estreptocócica; controle da PA, restrição hidrossalina e monitorização da função renal', 'D', 'Hematúria macroscópica, edema, hipertensão e história de infecção estreptocócica prévia (período de latência de 1-3 semanas) são clássicos de glomerulonefrite pós-estreptocócica; a conduta inicial é controle da PA, restrição hidrossalina e monitorização renal.', 'A: síndrome nefrótica cursa tipicamente com proteinúria maciça e hipoalbuminemia, não hematúria macroscópica como achado principal. B: HSP cursa com púrpura palpável, ausente neste caso. C: o quadro sistêmico e a hematúria não são compatíveis apenas com ITU.', 'Em revisão', '[object Object]', null, null),
  ('SIM2-013', 'simulado', '2', '13', 'Clínica Médica', 'Síndrome de Guillain-Barré', 'Difícil', null, null, 'Paciente de 35 anos apresenta fraqueza progressiva e ascendente em membros inferiores há 3 dias, iniciada após quadro de gastroenterite há 2 semanas, agora associada a dificuldade para subir escadas e leve dificuldade respiratória. Reflexos profundos abolidos em membros inferiores. Sensibilidade preservada.

A hipótese diagnóstica mais provável e a conduta são', 'Síndrome de Guillain-Barré; internação para monitorização respiratória e considerar imunoglobulina IV ou plasmaférese', 'Miastenia gravis; iniciar piridostigmina ambulatorial', 'Hérnia de disco lombar; encaminhar para fisioterapia ambulatorial', 'Acidente vascular encefálico medular; solicitar apenas ressonância magnética ambulatorial', 'A', 'Fraqueza ascendente com arreflexia após infecção prévia (padrão pós-infeccioso) é característica de síndrome de Guillain-Barré; exige internação para monitorização respiratória (risco de insuficiência ventilatória) e tratamento com imunoglobulina IV ou plasmaférese.', 'B: miastenia gravis cursa com fraqueza flutuante e fatigabilidade, não com esse padrão ascendente pós-infeccioso. C e D: não explicam o padrão ascendente simétrico com arreflexia e o contexto pós-infeccioso.', 'Em revisão', null, null, null),
  ('SIM2-014', 'simulado', '2', '14', 'Clínica Médica', 'Miastenia gravis', 'Difícil', null, null, 'Paciente de 28 anos, sexo feminino, relata fraqueza muscular que piora ao longo do dia e com esforço repetitivo, melhorando com repouso, há 3 meses. Notou ptose palpebral bilateral vespertina e dificuldade para mastigar no final das refeições. Nega alteração sensitiva.

A hipótese diagnóstica mais provável e o exame confirmatório mais indicado são', 'Esclerose múltipla; ressonância magnética de crânio', 'Distrofia muscular; biópsia muscular', 'Síndrome de Guillain-Barré; punção lombar para análise do líquor', 'Miastenia gravis; dosagem de anticorpo anti-receptor de acetilcolina', 'D', 'Fraqueza muscular flutuante, que piora com esforço/ao longo do dia e melhora com repouso, associada a ptose e fadiga à mastigação, é característica de miastenia gravis; a dosagem de anticorpo anti-receptor de acetilcolina confirma o diagnóstico na maioria dos casos.', 'A: esclerose múltipla teria outros achados neurológicos associados, não esse padrão de fatigabilidade muscular pura. B: distrofia muscular tem curso progressivo, não flutuante. C: Guillain-Barré cursa com fraqueza ascendente progressiva e arreflexia, padrão diferente do flutuante descrito.', 'Em revisão', null, null, null),
  ('SIM2-015', 'simulado', '2', '15', 'Clínica Médica', 'Epilepsia - manejo da crise convulsiva', 'Médio', null, null, 'Paciente de 25 anos, com diagnóstico prévio de epilepsia em uso irregular de carbamazepina, é trazido ao PS em crise tônico-clônica generalizada contínua há 8 minutos, sem recuperação da consciência entre os movimentos.

A conduta inicial mais adequada é', 'Introduzir objeto na boca do paciente para evitar mordedura de língua', 'Garantir via aérea e administrar benzodiazepínico (ex: diazepam IV) para interromper a crise, com preparo para anticonvulsivante de segunda linha se persistir', 'Aguardar resolução espontânea da crise, pois costuma cessar em poucos minutos sem intervenção', 'Conter fisicamente o paciente com força para impedir os movimentos convulsivos', 'B', 'Crise convulsiva com duração superior a 5 minutos caracteriza estado de mal epiléptico; a conduta é garantir via aérea e administrar benzodiazepínico IV para interromper a crise, preparando escalonamento terapêutico se não houver resposta.', 'A: introduzir objetos na boca é contraindicado, pelo risco de lesão dentária/aspiração. C: crise prolongada (estado de mal) não deve ser apenas observada, pelo risco de lesão neurológica. D: conter fisicamente com força pode causar lesões musculoesqueléticas.', 'Em revisão', null, null, null),
  ('SIM2-016', 'simulado', '2', '16', 'Clínica Médica', 'Doença de Parkinson - diagnóstico inicial', 'Médio', null, null, 'Paciente de 68 anos apresenta lentidão de movimentos progressiva há 8 meses, associada a tremor de repouso em mão direita, que diminui com o movimento intencional, e rigidez em roda denteada ao exame do membro superior direito. Marcha com passos curtos e diminuição do balanço do braço direito.

A hipótese diagnóstica mais provável e a conduta inicial são', 'Hidrocefalia de pressão normal; encaminhar para derivação ventriculoperitoneal imediata', 'Doença de Parkinson; iniciar levodopa/carbidopa conforme impacto funcional dos sintomas', 'Tremor essencial; iniciar propranolol como primeira linha', 'Acidente vascular encefálico; solicitar tomografia de crânio de urgência', 'B', 'Tremor de repouso assimétrico, bradicinesia e rigidez em roda denteada são a tríade clássica da doença de Parkinson; o tratamento inicial com levodopa/carbidopa é indicado conforme o impacto funcional dos sintomas.', 'A: hidrocefalia de pressão normal cursa com tríade de marcha, incontinência e demência, diferente do quadro descrito. C: tremor essencial é tipicamente de ação/postural, não de repouso, e não cursa com bradicinesia ou rigidez. D: quadro é crônico e progressivo, não agudo como em AVC.', 'Em revisão', null, null, null),
  ('SIM2-017', 'simulado', '2', '17', 'Clínica Médica', 'Demência de Alzheimer', 'Médio', null, null, 'Paciente de 75 anos é trazida pela família com queixa de esquecimentos progressivos há 2 anos, inicialmente para fatos recentes, agora também repetindo perguntas e se perdendo em trajetos habituais. Mantém-se funcionalmente independente para atividades básicas, mas já não consegue administrar as próprias finanças sozinha.

A conduta mais adequada é', 'Tranquilizar a família, pois esquecimento é esperado e normal para a idade', 'Iniciar anticolinesterásico imediatamente, sem necessidade de investigação complementar', 'Encaminhar diretamente para instituição de longa permanência, sem investigação adicional', 'Investigação com avaliação cognitiva estruturada, exames laboratoriais para causas reversíveis e neuroimagem, antes de firmar o diagnóstico', 'D', 'Declínio cognitivo progressivo com impacto funcional exige investigação estruturada (avaliação cognitiva, exames para causas reversíveis como hipotireoidismo e deficiência de B12, neuroimagem) antes de firmar o diagnóstico de demência de Alzheimer.', 'A: o padrão descrito (progressivo, com impacto funcional) não é esquecimento benigno do envelhecimento. B: tratamento não deve ser iniciado sem investigação e diagnóstico adequados. C: institucionalização não é conduta inicial sem avaliação completa e discussão com a família.', 'Em revisão', null, null, null),
  ('SIM2-018', 'simulado', '2', '18', 'Clínica Médica', 'Delirium em idoso hospitalizado', 'Médio', null, null, 'Paciente de 82 anos, internado há 3 dias por pneumonia, apresenta flutuação do nível de consciência, desatenção e desorientação de início agudo nas últimas 24 horas, alternando períodos de agitação com sonolência. Não havia alteração cognitiva prévia relatada pela família.

A conduta mais adequada é', 'Investigar e tratar causas reversíveis (infecção, distúrbio metabólico, medicações, retenção urinária) e implementar medidas não farmacológicas de reorientação', 'Não é necessária nenhuma investigação, pois é esperado que idosos hospitalizados fiquem confusos', 'Iniciar antipsicótico em dose plena como primeira conduta, sem investigar causas subjacentes', 'Assumir diagnóstico de demência de início agudo e iniciar anticolinesterásico', 'A', 'Início agudo com flutuação do nível de consciência caracteriza delirium, sempre secundário a uma causa subjacente; a conduta é investigar e tratar a causa (infecção, metabólica, medicamentosa) associada a medidas não farmacológicas de reorientação.', 'B: delirium não deve ser normalizado; é uma condição tratável com causa identificável. C: antipsicótico não é primeira conduta e não trata a causa de base, sendo reservado para agitação grave refratária. D: demência tem início insidioso e crônico, diferente do quadro agudo e flutuante descrito.', 'Em revisão', null, null, null),
  ('SIM2-019', 'simulado', '2', '19', 'Clínica Médica', 'Osteoartrite', 'Fácil', null, null, 'Paciente de 62 anos relata dor em joelho direito há 1 ano, que piora com atividade física e melhora com repouso, associada a rigidez matinal de curta duração (menos de 30 minutos). Radiografia mostra redução do espaço articular medial e osteófitos marginais.

O diagnóstico mais provável e a primeira linha de tratamento são', 'Osteoartrite; analgésicos simples/anti-inflamatórios tópicos ou orais conforme necessidade, associados a exercício e controle de peso', 'Artrite reumatoide; iniciar metotrexato imediatamente', 'Gota; iniciar colchicina de forma contínua', 'Espondilite anquilosante; solicitar HLA-B27 e iniciar anti-TNF', 'A', 'Dor mecânica (piora com uso, melhora com repouso), rigidez matinal curta e achados radiográficos de redução de espaço articular com osteófitos são característicos de osteoartrite; o tratamento inicial é analgesia, exercício e controle de peso.', 'B: artrite reumatoide cursa com rigidez matinal prolongada (>1h) e padrão inflamatório poliarticular simétrico, diferente do quadro. C: gota cursa com crises agudas de monoartrite intensa, não dor crônica progressiva. D: espondilite anquilosante acomete predominantemente esqueleto axial em jovens.', 'Em revisão', null, null, null),
  ('SIM2-020', 'simulado', '2', '20', 'Clínica Médica', 'Gota - crise aguda', 'Médio', null, null, 'Paciente de 55 anos, obeso e hipertenso, apresenta dor súbita e intensa em primeiro pododáctilo direito, com início noturno há 12 horas, associada a eritema, calor e edema importantes na articulação, impossibilitando o uso de calçado. Refere ingestão de bebida alcoólica e carne vermelha em excesso na véspera.

A conduta mais adequada na fase aguda é', 'Anti-inflamatório não esteroide ou colchicina em dose adequada para a crise aguda, evitando iniciar hipouricemiante nesse momento', 'Iniciar alopurinol em dose plena imediatamente durante a crise aguda', 'Antibioticoterapia empírica de amplo espectro, por suspeita de artrite séptica isolada', 'Aspiração articular obrigatória antes de qualquer tratamento medicamentoso', 'A', 'A crise aguda de gota é tratada com anti-inflamatório ou colchicina; hipouricemiantes (como alopurinol) não devem ser iniciados durante a crise aguda, pois podem prolongá-la, sendo introduzidos após resolução do quadro agudo.', 'B: iniciar hipouricemiante na crise aguda pode prolongar e intensificar o quadro. C: o quadro é típico de gota, não há indicação de antibiótico empírico sem outros sinais de infecção. D: aspiração articular é útil para diagnóstico diferencial (cristais), mas não é obrigatória antes de iniciar tratamento em quadro típico.', 'Em revisão', null, null, null),
  ('SIM2-021', 'simulado', '2', '21', 'Clínica Médica', 'Artrite reumatoide', 'Médio', null, null, 'Mulher de 45 anos apresenta dor e edema em articulações metacarpofalangeanas e interfalangeanas proximais de ambas as mãos, além de punhos, há 4 meses, com rigidez matinal de mais de 1 hora. Fator reumatoide e anti-CCP positivos, com elevação de VHS e PCR.

O diagnóstico mais provável e a primeira linha de tratamento medicamentoso modificador de doença são', 'Lúpus eritematoso sistêmico; hidroxicloroquina isolada', 'Osteoartrite; anti-inflamatório tópico', 'Gota poliarticular; alopurinol', 'Artrite reumatoide; metotrexato', 'D', 'Poliartrite simétrica de pequenas articulações, com rigidez matinal prolongada e sorologia positiva (FR e anti-CCP) com marcadores inflamatórios elevados, é característica de artrite reumatoide; o metotrexato é o medicamento modificador de doença de primeira linha.', 'A: lúpus tem outros critérios diagnósticos e a hidroxicloroquina isolada não é a primeira linha para artrite reumatoide erosiva. B: osteoartrite não cursa com sorologia positiva nem inflamação sistêmica significativa. C: gota poliarticular tem apresentação clínica e laboratorial diferentes (hiperuricemia, cristais).', 'Em revisão', null, null, null),
  ('SIM2-022', 'simulado', '2', '22', 'Clínica Médica', 'Espondilite anquilosante', 'Médio', null, null, 'Paciente de 26 anos, sexo masculino, relata dor lombar crônica há 8 meses, de início insidioso, que piora com o repouso e melhora com a atividade física, associada a rigidez matinal de mais de 30 minutos. Radiografia de sacroilíacas mostra sacroiliíte bilateral. HLA-B27 positivo.

O diagnóstico mais provável é', 'Hérnia de disco lombar', 'Espondilite anquilosante', 'Osteoartrite de coluna lombar', 'Fibromialgia', 'B', 'Dor lombar inflamatória (piora com repouso, melhora com atividade), rigidez matinal prolongada, sacroiliíte radiográfica e HLA-B27 positivo em homem jovem são característicos de espondilite anquilosante.', 'A: hérnia de disco cursaria com dor radicular e não explicaria a sacroiliíte bilateral. C: osteoartrite cursa com dor mecânica (piora com atividade), padrão oposto ao descrito. D: fibromialgia não apresenta alterações radiográficas inflamatórias nem HLA-B27 associado.', 'Em revisão', null, null, null),
  ('SIM2-023', 'simulado', '2', '23', 'Clínica Médica', 'Lúpus eritematoso sistêmico', 'Difícil', null, null, 'Mulher de 28 anos apresenta artralgia em pequenas articulações, eritema malar fotossensível, úlceras orais indolores recorrentes e fadiga importante há 4 meses. Exames mostram FAN positivo em título alto, anti-DNA dupla hélice positivo e complemento (C3/C4) reduzido. Exame de urina com proteinúria significativa.

A conduta mais adequada é', 'Iniciar apenas anti-inflamatório não esteroide, sem necessidade de outra investigação', 'Investigar acometimento renal (biópsia renal se indicada) e iniciar tratamento imunossupressor conforme gravidade do quadro', 'Tranquilizar a paciente, pois FAN positivo isolado não tem significado clínico relevante', 'Aguardar sem tratamento até que surjam mais critérios diagnósticos', 'B', 'Quadro compatível com lúpus eritematoso sistêmico com sorologia específica positiva e proteinúria sugere possível nefrite lúpica; deve-se investigar o acometimento renal e iniciar tratamento imunossupressor conforme a gravidade.', 'A: AINE isolado não trata a doença de base nem previne dano de órgão-alvo. C: o conjunto de achados (clínicos + anti-DNA + complemento baixo) tem significado diagnóstico relevante, não é achado isolado sem importância. D: proteinúria significativa exige investigação e tratamento precoces, não pode aguardar.', 'Em revisão', null, null, null),
  ('SIM2-024', 'simulado', '2', '24', 'Clínica Médica', 'Esclerose sistêmica (esclerodermia)', 'Difícil', null, null, 'Mulher de 50 anos apresenta espessamento e endurecimento progressivo da pele dos dedos das mãos e antebraços há 1 ano, associado a episódios de mudança de coloração dos dedos (branco, depois azulado) ao frio, e dificuldade progressiva para deglutir alimentos sólidos.

A hipótese diagnóstica mais provável é', 'Lúpus eritematoso sistêmico', 'Esclerose sistêmica', 'Dermatomiosite', 'Síndrome de Sjögren', 'B', 'Espessamento cutâneo progressivo (esclerodactilia), fenômeno de Raynaud e disfagia por acometimento esofágico são característicos de esclerose sistêmica.', 'A: lúpus não costuma causar esclerodactilia nem disfagia por esse mecanismo. C: dermatomiosite cursa com fraqueza muscular proximal e lesões cutâneas características (heliotropo, pápulas de Gottron), não espessamento cutâneo progressivo. D: síndrome de Sjögren cursa predominantemente com xeroftalmia e xerostomia.', 'Em revisão', null, null, null),
  ('SIM2-025', 'simulado', '2', '25', 'Clínica Médica', 'HIV - infecção oportunista (toxoplasmose cerebral)', 'Difícil', null, null, 'Paciente de 38 anos, com diagnóstico de HIV há 5 anos sem tratamento regular, é trazido com cefaleia progressiva, febre e hemiparesia direita de início há 5 dias, associada a confusão mental. Contagem de CD4 recente: 45 células/mm³. Tomografia de crânio com contraste mostra lesão em anel, com edema perilesional, em núcleos da base.

A hipótese diagnóstica mais provável e a conduta são', 'Neurotoxoplasmose; iniciar tratamento empírico (sulfadiazina + pirimetamina) e reavaliar resposta clínica/radiológica', 'Acidente vascular encefálico isquêmico; iniciar trombólise imediata', 'Enxaqueca com aura; iniciar apenas analgesia sintomática', 'Meningite bacteriana; iniciar antibioticoterapia isolada, sem necessidade de outra investigação', 'A', 'Lesão em anel com edema perilesional em núcleos da base, em paciente com CD4 muito baixo, é altamente sugestiva de neurotoxoplasmose; a conduta padrão é tratamento empírico com reavaliação clínica/radiológica em 10-14 dias.', 'B: quadro tem início subagudo com achados de imagem específicos, incompatível com AVC isquêmico agudo típico. C: os achados de imagem e o contexto clínico excluem enxaqueca simples. D: o padrão radiológico e o contexto imunossuprimido sugerem toxoplasmose, não meningite bacteriana isolada.', 'Em revisão', null, null, null),
  ('SIM2-026', 'simulado', '2', '26', 'Clínica Médica', 'Sífilis terciária / neurossífilis', 'Difícil', null, null, 'Paciente de 55 anos, sem acompanhamento médico regular, apresenta alterações comportamentais progressivas, declínio cognitivo e marcha atáxica há 6 meses. Refere história de úlcera genital indolor há muitos anos, não tratada na época. VDRL sérico reagente em título alto, confirmado por teste treponêmico.

A conduta mais adequada é', 'Realizar punção lombar para análise do líquor e, confirmada neurossífilis, tratar com penicilina cristalina intravenosa por 10-14 dias', 'Iniciar apenas tratamento sintomático para os sintomas neurológicos, sem terapia antimicrobiana específica', 'Tratar com penicilina benzatina em dose única, esquema padrão para sífilis recente', 'Aguardar confirmação por biópsia cerebral antes de iniciar qualquer tratamento', 'A', 'Sintomas neurológicos crônicos com sorologia positiva em paciente com história compatível sugerem neurossífilis; deve-se confirmar por análise do líquor e tratar com penicilina cristalina intravenosa, esquema diferente da sífilis recente.', 'B: tratamento sintomático isolado não trata a infecção de base, que é curável. C: penicilina benzatina em dose única não penetra adequadamente o sistema nervoso central, sendo insuficiente para neurossífilis. D: biópsia cerebral não é necessária quando há sorologia positiva compatível; a investigação adequada é liquórica.', 'Em revisão', null, null, null),
  ('SIM2-027', 'simulado', '2', '27', 'Clínica Médica', 'Malária', 'Médio', null, null, 'Paciente de 30 anos, retornando de viagem à região amazônica há 10 dias, apresenta febre alta cíclica associada a calafrios intensos e sudorese, com padrão de melhora entre os episódios, há 3 dias. Nega outros sintomas associados. Ao exame: hepatoesplenomegalia discreta.

A conduta mais adequada é', 'Tranquilizar o paciente, pois febre cíclica após viagem é sempre de origem viral autolimitada', 'Iniciar antibioticoterapia empírica para infecção bacteriana, sem necessidade de exame parasitológico', 'Aguardar resolução espontânea da febre antes de qualquer investigação', 'Solicitar gota espessa (ou teste rápido) para malária e iniciar tratamento antimalárico específico conforme a espécie identificada', 'D', 'Febre cíclica com calafrios em paciente com história epidemiológica de exposição em área endêmica é altamente sugestiva de malária; a confirmação é feita por gota espessa/teste rápido, com tratamento específico conforme a espécie de Plasmodium identificada.', 'A: o padrão cíclico com história epidemiológica de viagem exige investigação específica para malária, não pode ser assumido como viral. B: antibiótico não trata malária, que é doença parasitária, não bacteriana. C: malária não tratada pode evoluir para formas graves, exigindo investigação e tratamento precoces.', 'Em revisão', null, null, null),
  ('SIM2-028', 'simulado', '2', '28', 'Clínica Médica', 'Insuficiência adrenal (Doença de Addison)', 'Difícil', null, null, 'Paciente de 40 anos apresenta fadiga progressiva, perda de peso, hipotensão postural e hiperpigmentação cutânea difusa (mais evidente em pregas palmares e mucosa oral) há 6 meses, com piora aguda nas últimas 24 horas: náuseas, vômitos, dor abdominal e hipotensão importante (PA 78x50mmHg) após um quadro infeccioso recente. Sódio sérico baixo, potássio elevado.

A hipótese diagnóstica mais provável e a conduta imediata são', 'Síndrome de Cushing; iniciar cetoconazol para reduzir o cortisol', 'Crise addisoniana (insuficiência adrenal aguda); hidrocortisona intravenosa em dose de estresse e reposição volêmica vigorosa imediatas', 'Choque séptico isolado; apenas antibioticoterapia de amplo espectro, sem necessidade de corticoide', 'Hipotireoidismo grave; iniciar levotiroxina intravenosa isoladamente', 'B', 'Hiperpigmentação, hipotensão, hiponatremia e hipercalemia crônicas, com descompensação aguda diante de estresse (infecção), são clássicas de crise addisoniana; o tratamento imediato é hidrocortisona IV em dose de estresse associada a reposição volêmica vigorosa, medida que salva vidas.', 'A: Cushing cursaria com quadro clínico oposto (hipertensão, hipopotassemia), não hipotensão com hipercalemia. C: o quadro crônico prévio (hiperpigmentação, hiponatremia, hipercalemia) aponta para insuficiência adrenal de base, não apenas sepse; corticoide é essencial no tratamento. D: o quadro não é predominantemente de hipotireoidismo; a hiperpigmentação e o padrão eletrolítico apontam para adrenal.', 'Em revisão', null, null, null),
  ('SIM2-029', 'simulado', '2', '29', 'Ginecologia e Obstetrícia', 'Trabalho de parto prematuro - tocólise', 'Difícil', null, null, 'Gestante de 30 semanas apresenta contrações uterinas regulares (4 em 10 minutos) e dor lombar há 3 horas. Ao toque: colo com 2cm de dilatação e 70% de esvaecimento. Membranas íntegras. Sem sinais de infecção ou sofrimento fetal. BCF 145bpm.

A conduta mais adequada é', 'Iniciar antibioticoterapia isolada, sem necessidade de tocólise ou corticoterapia', 'Corticoterapia para maturação pulmonar fetal, tocólise e sulfato de magnésio para neuroproteção fetal, conforme idade gestacional', 'Indicar parto imediato por via alta, independentemente da idade gestacional', 'Alta hospitalar com repouso domiciliar, sem necessidade de qualquer intervenção', 'B', 'Trabalho de parto prematuro confirmado (dilatação + contrações regulares) antes de 34 semanas tem indicação de corticoterapia para maturação pulmonar, tocólise para ganhar tempo até o efeito do corticoide, e sulfato de magnésio para neuroproteção antes de 32 semanas.', 'A: antibiótico isolado não trata a causa do trabalho de parto prematuro nem substitui as medidas de proteção fetal. C: interrupção imediata sem indicação materna/fetal aumenta a prematuridade desnecessariamente. D: quadro de trabalho de parto confirmado não deve ser apenas observado em casa.', 'Em revisão', null, null, null),
  ('SIM2-030', 'simulado', '2', '30', 'Ginecologia e Obstetrícia', 'Rotura uterina', 'Difícil', null, null, 'Gestante de 38 semanas, com cesárea prévia, em trabalho de parto induzido com ocitocina, apresenta dor abdominal súbita e intensa, seguida de cessação das contrações uterinas e sangramento vaginal moderado. BCF apresenta bradicardia súbita e sustentada (60bpm). Ao exame, perda da apresentação fetal previamente fixa.

A hipótese diagnóstica mais provável e a conduta são', 'Distócia funcional; aumentar a dose de ocitocina para acelerar o parto', 'Rotura uterina; laparotomia de urgência para cesárea imediata e reparo uterino', 'Rotura de vasa prévia; realizar apenas amniotomia', 'Descolamento prematuro de placenta; aguardar evolução do trabalho de parto vaginal', 'B', 'Dor abdominal súbita com cessação das contrações, sangramento e bradicardia fetal sustentada em paciente com cicatriz uterina prévia (cesárea) durante uso de ocitocina são clássicos de rotura uterina, emergência que exige laparotomia imediata.', 'A: aumentar ocitocina em suspeita de rotura uterina é contraindicado e perigoso. C: rotura de vasa prévia tem apresentação diferente, sem a perda da apresentação fetal descrita. D: DPP não costuma cursar com cessação abrupta das contrações e perda da apresentação fixa.', 'Em revisão', null, null, null),
  ('SIM2-031', 'simulado', '2', '31', 'Ginecologia e Obstetrícia', 'Gestação múltipla - complicações', 'Médio', null, null, 'Gestante de 28 semanas, com gestação gemelar dicoriônica diamniótica, comparece à consulta de pré-natal de rotina. USG mostra crescimento discordante entre os fetos (diferença de peso estimado de 22% entre eles), com dopplervelocimetria normal em ambos.

A conduta mais adequada é', 'Indicar parto imediato, independentemente da idade gestacional', 'Tranquilizar a paciente, pois discordância de crescimento é irrelevante em gestação gemelar', 'Intensificar a vigilância fetal (USG seriada, dopplervelocimetria, perfil biofísico) e monitorar a evolução da discordância de crescimento', 'Solicitar apenas repetição da USG em 8 semanas, sem outras medidas', 'C', 'Discordância de crescimento significativa em gestação gemelar exige vigilância intensificada, pois pode indicar insuficiência placentária em um dos fetos, com risco de complicações que precisam ser monitoradas de perto.', 'A: parto imediato sem outros sinais de gravidade e sem maturidade fetal adequada expõe a prematuridade desnecessária. B: discordância significativa de crescimento tem relevância clínica e não deve ser minimizada. D: o intervalo de reavaliação deve ser mais curto diante de discordância significativa.', 'Em revisão', null, null, null),
  ('SIM2-032', 'simulado', '2', '32', 'Ginecologia e Obstetrícia', 'Restrição de crescimento fetal', 'Difícil', null, null, 'Gestante de 32 semanas apresenta altura uterina menor que a esperada para a idade gestacional em duas consultas consecutivas. USG confirma peso fetal estimado abaixo do percentil 3 para a idade gestacional, com dopplervelocimetria de artéria umbilical mostrando diástole zero.

A conduta mais adequada é', 'Indicar cesariana eletiva apenas após 39 semanas, independente dos achados dopplervelocimétricos', 'Tranquilizar a paciente, pois restrição de crescimento isolada não representa risco fetal', 'Internação para vigilância intensiva (cardiotocografia e perfil biofísico seriados) e avaliação da necessidade de interrupção da gestação conforme a gravidade', 'Orientar repouso domiciliar e retorno em 4 semanas para nova avaliação', 'C', 'Restrição de crescimento grave (percentil <3) com diástole zero na artéria umbilical indica insuficiência placentária significativa e risco de deterioração fetal; exige internação para vigilância intensiva e avaliação de interrupção conforme gravidade, podendo ser antes de 39 semanas.', 'A: aguardar até 39 semanas sem considerar a gravidade doppler pode resultar em óbito fetal. B: a associação com doppler alterado indica risco real de sofrimento fetal. D: um retorno em 4 semanas é inadequado diante de achados de gravidade (diástole zero); a vigilância deve ser muito mais próxima.', 'Em revisão', null, null, null),
  ('SIM2-033', 'simulado', '2', '33', 'Ginecologia e Obstetrícia', 'Diabetes pré-gestacional - manejo periconcepcional', 'Médio', null, null, 'Mulher de 32 anos, diabética tipo 1 há 10 anos, com hemoglobina glicada de 9,8% (mal controlada), planeja engravidar nos próximos meses e procura orientação pré-concepcional na UBS.

A orientação mais adequada é', 'Contraindicar definitivamente a gestação em mulheres com diabetes tipo 1', 'Otimizar o controle glicêmico (meta de HbA1c próxima da normalidade) antes de tentar engravidar, além de suplementação de ácido fólico em dose adequada', 'Não há necessidade de ajuste no controle glicêmico antes da gestação, apenas durante o pré-natal', 'Orientar a engravidar imediatamente, independente do controle glicêmico atual', 'B', 'Diabetes mal controlado no período periconcepcional aumenta significativamente o risco de malformações congênitas; a orientação é otimizar o controle glicêmico antes da concepção, além de suplementação de ácido fólico para redução de defeitos do tubo neural.', 'A: diabetes tipo 1 não contraindica gestação, desde que bem controlado e acompanhado. C: o controle glicêmico periconcepcional é crucial para reduzir risco de malformações, que ocorrem principalmente na organogênese precoce. D: engravidar com controle inadequado aumenta significativamente riscos materno-fetais.', 'Em revisão', null, null, null),
  ('SIM2-034', 'simulado', '2', '34', 'Ginecologia e Obstetrícia', 'Isoimunização Rh', 'Difícil', null, null, 'Gestante de 28 anos, tipo sanguíneo O negativo, primigesta, com parceiro Rh positivo, está na 28ª semana de gestação, sem sangramentos ou procedimentos invasivos prévios. Coombs indireto realizado nesta consulta é negativo.

A conduta mais adequada é', 'Administrar imunoglobulina anti-Rh profilática nesta idade gestacional, e novamente após o parto se o RN for Rh positivo', 'Realizar transfusão sanguínea profilática para a gestante', 'Não é necessária nenhuma profilaxia, pois o Coombs indireto negativo já garante ausência de sensibilização futura', 'Aguardar o parto para decidir sobre a necessidade de imunoglobulina anti-Rh', 'A', 'Gestante Rh negativo não sensibilizada (Coombs indireto negativo) com parceiro Rh positivo deve receber imunoglobulina anti-Rh profilática por volta da 28ª semana, e nova dose após o parto se o recém-nascido for Rh positivo, para prevenir sensibilização.', 'B: transfusão sanguínea não é a conduta indicada; a profilaxia é feita com imunoglobulina específica. C: Coombs negativo não elimina a necessidade de profilaxia; ela é justamente para prevenir sensibilização futura. D: a profilaxia antenatal na 28ª semana é recomendada, não deve ser postergada apenas para o pós-parto.', 'Em revisão', null, null, null),
  ('SIM2-035', 'simulado', '2', '35', 'Ginecologia e Obstetrícia', 'Sífilis congênita - conduta na gestante', 'Difícil', null, null, 'Gestante de 24 semanas realiza teste rápido para sífilis de rotina no pré-natal, com resultado reagente, confirmado por VDRL com título 1:32. Refere não ter sido tratada previamente e desconhece a duração da infecção.

A conduta mais adequada é', 'Tratar apenas com azitromicina oral, evitando penicilina na gestação', 'Não tratar a gestante, tratando apenas o recém-nascido após o nascimento', 'Tratar com penicilina benzatina conforme o estágio presumido da sífilis, e realizar seguimento com VDRL mensal para avaliar resposta ao tratamento', 'Aguardar o parto para iniciar o tratamento, evitando qualquer medicação durante a gestação', 'C', 'Sífilis na gestação deve ser tratada com penicilina benzatina (único tratamento comprovadamente eficaz para prevenir sífilis congênita), com seguimento mensal do VDRL para monitorar a resposta terapêutica.', 'A: azitromicina não é eficaz para prevenir transmissão vertical da sífilis, penicilina é o tratamento indicado. B: tratar apenas o recém-nascido após a exposição intraútero não previne as complicações já estabelecidas. D: adiar o tratamento para o pós-parto expõe o feto a risco significativo de sífilis congênita.', 'Em revisão', null, null, null),
  ('SIM2-036', 'simulado', '2', '36', 'Ginecologia e Obstetrícia', 'Toxoplasmose na gestação', 'Difícil', null, null, 'Gestante de 16 semanas apresenta sorologia de rotina do pré-natal com IgM e IgG positivos para toxoplasmose, sugerindo infecção aguda no período gestacional. Está assintomática. USG obstétrica sem alterações até o momento.

A conduta mais adequada é', 'Não é necessário tratamento, pois a paciente está assintomática', 'Indicar interrupção da gestação, pois toxoplasmose aguda sempre causa malformação fetal grave', 'Iniciar espiramicina para reduzir o risco de transmissão vertical, com investigação adicional (teste de avidez de IgG, PCR de líquido amniótico) conforme protocolo', 'Iniciar sulfadiazina e pirimetamina imediatamente no primeiro trimestre, independente da idade gestacional', 'C', 'Infecção aguda por toxoplasmose na gestação, mesmo assintomática, tem indicação de espiramicina para reduzir a transmissão vertical, associada a investigação complementar para confirmar infecção fetal e definir conduta subsequente.', 'A: a ausência de sintomas maternos não elimina o risco de transmissão vertical e suas complicações. B: nem toda infecção fetal resulta em malformação grave; a conduta depende da investigação e não é interrupção automática. D: sulfadiazina e pirimetamina são teratogênicas no primeiro trimestre, sendo reservadas para confirmação de infecção fetal ou fases posteriores.', 'Em revisão', null, null, null),
  ('SIM2-037', 'simulado', '2', '37', 'Ginecologia e Obstetrícia', 'Aborto espontâneo - tipos e conduta', 'Médio', null, null, 'Gestante de 9 semanas apresenta sangramento vaginal moderado e cólicas abdominais há 1 dia. Ao exame especular, colo uterino aberto com saída de material ovular. USG mostra conteúdo uterino heterogêneo, sem saco gestacional íntegro identificável.

A classificação e a conduta mais adequadas são', 'Aborto retido; aguardar eliminação espontânea por tempo indeterminado sem qualquer conduta', 'Aborto incompleto; considerar esvaziamento uterino (AMIU ou curetagem) ou conduta expectante/medicamentosa conforme estabilidade clínica', 'Gravidez ectópica; indicar laparoscopia de urgência', 'Ameaça de aborto; orientar repouso relativo e reavaliação em 1 semana', 'B', 'Colo aberto com saída de material ovular e USG mostrando conteúdo uterino heterogêneo sem gestação íntegra caracterizam aborto incompleto; a conduta pode ser esvaziamento uterino ou, em casos estáveis, conduta expectante ou medicamentosa.', 'A: aborto retido cursa com colo fechado e ausência de sintomas de expulsão, diferente do quadro descrito. C: não há dados sugestivos de gestação extrauterina. D: ameaça de aborto cursa com colo fechado e gestação intrauterina viável, achados ausentes aqui.', 'Em revisão', null, null, null),
  ('SIM2-038', 'simulado', '2', '38', 'Ginecologia e Obstetrícia', 'Mola hidatiforme', 'Difícil', null, null, 'Gestante de 10 semanas por data da última menstruação apresenta sangramento vaginal intermitente e útero com altura uterina maior que o esperado para a idade gestacional, associados a náuseas intensas. Beta-hCG quantitativo muito elevado. USG mostra imagem intrauterina heterogênea, em ''flocos de neve'', sem embrião ou batimentos cardíacos identificáveis.

A hipótese diagnóstica mais provável e a conduta são', 'Gestação normal com crescimento uterino aumentado por gestação múltipla; apenas acompanhamento de rotina', 'Aborto retido; aguardar eliminação espontânea sem necessidade de seguimento adicional', 'Gravidez ectópica; indicar laparotomia de urgência', 'Mola hidatiforme; esvaziamento uterino por aspiração e seguimento com beta-hCG seriado para descartar doença trofoblástica persistente', 'D', 'Útero maior que o esperado, beta-hCG muito elevado e imagem característica em ''flocos de neve'' sem embrião são clássicos de mola hidatiforme; o tratamento é esvaziamento uterino com seguimento rigoroso do beta-hCG pelo risco de doença trofoblástica persistente.', 'A: a imagem descrita não é compatível com gestação normal ou múltipla viável. B: aborto retido não explica o padrão de imagem em flocos de neve nem o beta-hCG tão elevado. C: os achados de imagem são intrauterinos, não sugerindo gestação ectópica.', 'Em revisão', null, null, null),
  ('SIM2-039', 'simulado', '2', '39', 'Ginecologia e Obstetrícia', 'Câncer de mama - rastreamento', 'Médio', null, null, 'Mulher de 45 anos, assintomática, sem histórico familiar de câncer de mama, procura a UBS para orientação sobre rastreamento mamográfico. Exame clínico das mamas sem alterações.

Segundo as recomendações do Ministério da Saúde para a população de risco habitual, a conduta é', 'Iniciar rastreamento apenas aos 60 anos, independente de outros fatores', 'Iniciar mamografia anual a partir dos 40 anos para todas as mulheres, independente do risco', 'Não é necessário rastreamento mamográfico em nenhuma idade na ausência de sintomas', 'Iniciar rastreamento com mamografia bienal a partir dos 50 anos, mantendo exame clínico das mamas nas consultas de rotina', 'D', 'No Brasil, a recomendação do Ministério da Saúde para mulheres de risco habitual é rastreamento com mamografia bienal dos 50 aos 69 anos, sem indicação de início mais precoce na ausência de fatores de risco.', 'A: aos 60 anos já se está dentro, mas não no início, da faixa recomendada (50-69 anos). B: mamografia anual a partir dos 40 anos para toda a população não é a recomendação do Ministério da Saúde para risco habitual. C: existe recomendação de rastreamento estabelecida para a faixa etária de maior risco-benefício.', 'Em revisão', null, null, null),
  ('SIM2-040', 'simulado', '2', '40', 'Ginecologia e Obstetrícia', 'Câncer de endométrio', 'Médio', null, null, 'Mulher de 58 anos, obesa, com menopausa aos 52 anos, sem uso de terapia hormonal, apresenta sangramento vaginal há 1 semana, em pequena quantidade. USG transvaginal mostra espessamento endometrial de 14mm.

A conduta mais adequada é', 'Iniciar terapia hormonal combinada, sem necessidade de investigação prévia', 'Tranquilizar a paciente, pois sangramento após a menopausa é sempre fisiológico', 'Investigação histológica do endométrio (biópsia por histeroscopia ou aspiração endometrial) para descartar neoplasia', 'Indicar histerectomia diretamente, sem confirmação histológica', 'C', 'Sangramento pós-menopausa com espessamento endometrial significativo exige investigação histológica para descartar câncer de endométrio, diagnóstico mais preocupante nessa faixa etária e contexto.', 'A: terapia hormonal sem investigação prévia pode mascarar ou agravar uma neoplasia já presente. B: sangramento pós-menopausa nunca deve ser considerado fisiológico sem investigação, pelo risco de malignidade. D: procedimento cirúrgico definitivo não deve ser indicado sem confirmação histológica prévia.', 'Em revisão', null, null, null),
  ('SIM2-041', 'simulado', '2', '41', 'Ginecologia e Obstetrícia', 'Câncer de ovário - massa anexial', 'Difícil', null, null, 'Mulher de 62 anos, pós-menopausa, apresenta distensão abdominal progressiva e saciedade precoce há 2 meses. USG transvaginal identifica massa anexial complexa, de 8cm, com septações espessas, componente sólido e vascularização ao doppler. CA-125 muito elevado.

A conduta mais adequada é', 'Indicar apenas acompanhamento clínico ambulatorial sem investigação adicional', 'Encaminhar para avaliação oncológica ginecológica especializada para estadiamento e planejamento cirúrgico', 'Prescrever anticoncepcional hormonal para redução do tamanho da massa', 'Conduta expectante com reavaliação ultrassonográfica em 12 meses', 'B', 'Massa anexial complexa em mulher pós-menopausa, com características ultrassonográficas suspeitas e CA-125 muito elevado, tem alto risco de malignidade, exigindo encaminhamento a serviço especializado para estadiamento e conduta cirúrgica adequada.', 'A e D: massas com características tão suspeitas em pós-menopausa não devem ter conduta expectante prolongada, pelo risco de neoplasia. C: tratamento hormonal não é indicado para massa anexial suspeita de malignidade.', 'Em revisão', null, null, null),
  ('SIM2-042', 'simulado', '2', '42', 'Ginecologia e Obstetrícia', 'Prolapso genital', 'Médio', null, null, 'Mulher de 68 anos, multípara (5 partos vaginais), relata sensação de peso e abaulamento vaginal, que piora ao final do dia e com esforço físico, há 1 ano, associada a dificuldade miccional ocasional. Ao exame, identifica-se descida do colo uterino até o intróito vaginal ao esforço (prolapso grau III).

A conduta mais adequada é', 'Indicar histerectomia como única opção possível, sem considerar alternativas', 'Prescrever apenas fisioterapia do assoalho pélvico, sem outras opções em prolapso avançado', 'Discutir opções terapêuticas conforme sintomas e desejo da paciente, incluindo pessário vaginal ou correção cirúrgica', 'Conduta expectante obrigatória, sem qualquer intervenção, independente dos sintomas', 'C', 'Prolapso genital sintomático de grau avançado deve ter suas opções terapêuticas discutidas com a paciente, incluindo pessário vaginal (opção não cirúrgica) ou correção cirúrgica, conforme desejo e condições clínicas.', 'A: histerectomia não é a única opção; alternativas devem ser discutidas. B: fisioterapia isolada tem eficácia limitada em prolapsos avançados (grau III), sendo mais indicada para graus iniciais. D: prolapso sintomático e avançado justifica intervenção.', 'Em revisão', null, null, null),
  ('SIM2-043', 'simulado', '2', '43', 'Ginecologia e Obstetrícia', 'Incontinência urinária de esforço', 'Médio', null, null, 'Mulher de 50 anos, multípara, relata perda involuntária de urina ao tossir, espirrar ou praticar exercício físico, há 1 ano, sem urgência miccional associada. Exame físico sem sinais de prolapso significativo. Exame de urina sem alterações.

A conduta inicial mais adequada é', 'Iniciar antibioticoterapia empírica, por suspeita de infecção urinária', 'Indicar cirurgia de correção de incontinência como primeira conduta, sem tentativa de tratamento conservador', 'Prescrever anticolinérgico, medicamento de escolha para incontinência de esforço', 'Orientar exercícios de fortalecimento da musculatura do assoalho pélvico (exercícios de Kegel) como primeira linha de tratamento', 'D', 'Incontinência urinária de esforço (perda aos esforços, sem urgência) tem como primeira linha de tratamento os exercícios de fortalecimento do assoalho pélvico, antes de considerar opções cirúrgicas.', 'A: não há sinais clínicos ou laboratoriais de infecção urinária. B: cirurgia é reservada para casos refratários ao tratamento conservador. C: anticolinérgicos são usados para incontinência de urgência, não de esforço.', 'Em revisão', null, null, null),
  ('SIM2-044', 'simulado', '2', '44', 'Ginecologia e Obstetrícia', 'Vaginose bacteriana e tricomoníase', 'Fácil', null, null, 'Mulher relata corrimento vaginal acinzentado, com odor fétido descrito como ''de peixe'', que piora após a relação sexual, há 5 dias. Teste das aminas (whiff test) positivo. Exame a fresco mostra células-guia (clue cells), sem presença de protozoários móveis ou hifas.

O diagnóstico mais provável e o tratamento indicado são', 'Vaginose bacteriana; metronidazol por via oral ou em creme vaginal', 'Candidíase vulvovaginal; antifúngico tópico', 'Cervicite por clamídia; azitromicina em dose única', 'Tricomoníase; metronidazol com tratamento obrigatório do parceiro', 'A', 'Corrimento acinzentado com odor fétido, teste das aminas positivo e clue cells ao exame a fresco são característicos de vaginose bacteriana; tratamento com metronidazol oral ou vaginal.', 'B: candidíase cursaria com hifas ao exame, ausentes, e corrimento diferente. C: clamídia não explica o teste das aminas positivo nem as clue cells. D: tricomoníase cursaria com protozoários móveis ao exame a fresco, ausentes aqui, além de corrimento tipicamente amarelo-esverdeado espumoso.', 'Em revisão', null, null, null),
  ('SIM2-045', 'simulado', '2', '45', 'Ginecologia e Obstetrícia', 'HPV / condiloma', 'Médio', null, null, 'Mulher de 26 anos apresenta lesões verrucosas, indolores, em região vulvar e perianal, de crescimento lento há 3 meses. Nega prurido intenso ou sangramento. Citologia oncótica recente sem alterações.

A conduta mais adequada é', 'Tratamento das lesões (métodos destrutivos ou químicos, conforme disponibilidade) e orientação sobre transmissão sexual e rastreamento de câncer de colo uterino', 'Iniciar antibioticoterapia sistêmica, pois se trata de infecção bacteriana', 'Não é necessário tratamento, pois lesões por HPV sempre regridem espontaneamente sem intervenção', 'Indicar biópsia obrigatória de todas as lesões antes de qualquer tratamento', 'A', 'Condilomas acuminados (verrugas genitais por HPV) têm indicação de tratamento destrutivo/químico conforme o caso, associado a orientação sobre transmissão sexual e reforço da importância do rastreamento cervical, dado o potencial oncogênico de alguns subtipos.', 'B: HPV é vírus, não bactéria; antibiótico não tem indicação nesse contexto. C: nem todas as lesões regridem espontaneamente; muitas necessitam de tratamento ativo. D: biópsia não é obrigatória em lesões típicas, sendo reservada para casos atípicos ou refratários.', 'Em revisão', null, null, null),
  ('SIM2-046', 'simulado', '2', '46', 'Ginecologia e Obstetrícia', 'Puerpério - infecção puerperal (endometrite)', 'Médio', null, null, 'Puérpera de 5 dias pós-parto vaginal apresenta febre (38,6°C), dor abdominal em hipogástrio e lóquios com odor fétido. Ao exame: útero doloroso à palpação, subinvoluído para o tempo de puerpério, sem sinais de infecção de ferida perineal.

A hipótese diagnóstica mais provável e a conduta são', 'Endometrite puerperal; iniciar antibioticoterapia de amplo espectro (cobertura para polimicrobiano) por via intravenosa', 'Infecção do trato urinário; iniciar antibiótico oral ambulatorial', 'Involução uterina normal; tranquilizar a puérpera sem necessidade de tratamento', 'Mastite puerperal; orientar manter amamentação e iniciar antibiótico oral', 'A', 'Febre, dor uterina e lóquios fétidos no puerpério são característicos de endometrite puerperal; o tratamento é antibioticoterapia intravenosa de amplo espectro cobrindo flora polimicrobiana (aeróbios e anaeróbios).', 'B: o quadro descrito (dor uterina, lóquios fétidos) não é compatível com ITU isolada. C: os achados descritos (febre, dor, subinvolução, lóquios fétidos) não são normais para o puerpério. D: mastite cursaria com sinais inflamatórios na mama, não descritos aqui.', 'Em revisão', null, null, null),
  ('SIM2-047', 'simulado', '2', '47', 'Ginecologia e Obstetrícia', 'Mastite puerperal', 'Fácil', null, null, 'Puérpera no 15º dia pós-parto, lactante, apresenta dor, hiperemia e calor em quadrante superior externo da mama esquerda há 2 dias, associados a febre (38,3°C) e mal-estar. Nega ponto de flutuação à palpação.

A conduta mais adequada é', 'Apenas compressas frias, sem necessidade de antibioticoterapia', 'Antibioticoterapia oral, manutenção do aleitamento materno (inclusive pela mama afetada), analgesia e esvaziamento adequado da mama', 'Suspensão imediata e definitiva da amamentação em ambas as mamas', 'Drenagem cirúrgica imediata, independente da ausência de sinais de abscesso', 'B', 'Mastite puerperal sem sinais de abscesso é tratada com antibioticoterapia oral, mantendo a amamentação (inclusive pela mama afetada, o que favorece a resolução), analgesia e esvaziamento adequado da mama.', 'A: quadro com febre e sinais inflamatórios importantes tem indicação de antibioticoterapia, não apenas medidas físicas. C: a manutenção do aleitamento, inclusive pela mama afetada, é recomendada e favorece a resolução do quadro. D: drenagem cirúrgica é reservada para abscesso confirmado (ponto de flutuação), ausente neste caso.', 'Em revisão', null, null, null),
  ('SIM2-048', 'simulado', '2', '48', 'Ginecologia e Obstetrícia', 'Contracepção de emergência', 'Fácil', null, null, 'Mulher de 24 anos procura a UBS relatando relação sexual desprotegida há 30 horas, sem uso de nenhum método contraceptivo. Deseja orientação sobre contracepção de emergência.

A conduta mais adequada é', 'Informar que já passou o prazo para uso de contracepção de emergência, pois só é eficaz em até 24 horas', 'Indicar inserção de DIU de cobre como única opção, recusando a via hormonal', 'Orientar apenas observação e teste de gravidez em 30 dias, sem oferecer contracepção de emergência', 'Prescrever levonorgestrel em dose única (ou esquema de duas doses, conforme apresentação disponível), o quanto antes', 'D', 'A contracepção de emergência com levonorgestrel é eficaz e indicada até 72-120 horas após a relação desprotegida, sendo mais eficaz quanto mais precoce o uso; 30 horas está dentro da janela de maior eficácia.', 'A: a contracepção de emergência hormonal continua indicada além de 24 horas, com eficácia até 72-120h conforme o método. B: o DIU de cobre é uma opção eficaz, mas não é a única disponível; a via hormonal também é válida e mais acessível. C: negar a contracepção de emergência disponível não é conduta adequada diante de janela terapêutica ainda válida.', 'Em revisão', null, null, null),
  ('SIM2-049', 'simulado', '2', '49', 'Ginecologia e Obstetrícia', 'Climatério - osteoporose pós-menopausa', 'Médio', null, null, 'Mulher de 63 anos, menopausa aos 50 anos, sem reposição hormonal, procura a UBS para avaliação de risco de fraturas. Densitometria óssea mostra T-score de -2,7 em coluna lombar. Nega fraturas prévias.

A conduta mais adequada é', 'Iniciar bisfosfonato oral, associado a suplementação de cálcio e vitamina D e orientação de exercícios físicos regulares', 'Não é necessária nenhuma conduta, pois T-score abaixo de -2,5 é considerado normal para a idade', 'Iniciar apenas suplementação isolada de cálcio, sem necessidade de outros tratamentos', 'Indicar terapia hormonal com estrogênio como primeira linha para tratamento da osteoporose estabelecida', 'A', 'T-score ≤-2,5 confirma osteoporose; o tratamento de primeira linha inclui bisfosfonato oral, associado a suplementação de cálcio e vitamina D e orientação de atividade física para redução do risco de fraturas.', 'B: T-score de -2,7 confirma diagnóstico de osteoporose, não é um achado normal. C: suplementação isolada de cálcio é insuficiente para tratar osteoporose já estabelecida. D: terapia hormonal não é primeira linha para tratamento da osteoporose estabelecida, tendo outras indicações e riscos associados.', 'Em revisão', null, null, null),
  ('SIM2-050', 'simulado', '2', '50', 'Cirurgia', 'Trauma torácico - pneumotórax hipertensivo', 'Difícil', null, null, 'Paciente de 26 anos, vítima de acidente motociclístico, chega ao PS com dispneia grave, dor torácica à esquerda e agitação. Ao exame: desvio de traqueia para a direita, ausência de murmúrio vesicular à esquerda, timpanismo à percussão, turgência jugular, PA 88x54mmHg, saturação 84% em ar ambiente.

A conduta imediata mais adequada é', 'Realizar toracocentese diagnóstica com agulha fina, sem caráter terapêutico', 'Solicitar radiografia de tórax antes de qualquer intervenção', 'Administrar apenas oxigênio suplementar e reavaliar em 30 minutos', 'Descompressão torácica com agulha no segundo espaço intercostal, linha hemiclavicular, seguida de drenagem torácica definitiva', 'D', 'Desvio de traqueia, ausência de murmúrio vesicular, timpanismo, turgência jugular e instabilidade hemodinâmica são clássicos de pneumotórax hipertensivo, emergência que exige descompressão imediata com agulha, seguida de drenagem definitiva, sem aguardar exame de imagem.', 'A: toracocentese diagnóstica não é a conduta terapêutica adequada para essa emergência. B: pneumotórax hipertensivo é diagnóstico clínico; aguardar radiografia atrasa tratamento potencialmente fatal. C: o quadro exige intervenção imediata, não apenas oxigênio e reavaliação tardia.', 'Em revisão', null, null, null),
  ('SIM2-051', 'simulado', '2', '51', 'Cirurgia', 'Trauma torácico - tamponamento cardíaco', 'Difícil', null, null, 'Paciente de 24 anos, vítima de ferimento por arma branca em região precordial, chega ao PS hipotenso (PA 78x50mmHg), com turgência jugular e bulhas cardíacas hipofonéticas (tríade de Beck). FAST à beira-leito mostra líquido livre no saco pericárdico.

A conduta mais adequada é', 'Pericardiocentese de urgência ou toracotomia, conforme disponibilidade e gravidade, com preparo para cirurgia definitiva', 'Aguardar ecocardiograma eletivo para confirmação diagnóstica antes de qualquer intervenção', 'Reposição volêmica isolada, sem necessidade de drenagem do pericárdio', 'Administrar apenas diurético para reduzir a sobrecarga de volume', 'A', 'A tríade de Beck (hipotensão, turgência jugular, bulhas hipofonéticas) associada a líquido pericárdico no FAST confirma tamponamento cardíaco traumático; a conduta é drenagem urgente (pericardiocentese ou toracotomia) com preparo cirúrgico definitivo.', 'B: aguardar exame eletivo atrasa tratamento de uma condição rapidamente fatal. C: reposição volêmica isolada não resolve a compressão cardíaca, sendo apenas medida temporizadora. D: diurético é contraindicado, pois reduziria ainda mais o retorno venoso em paciente já comprometido hemodinamicamente.', 'Em revisão', null, null, null),
  ('SIM2-052', 'simulado', '2', '52', 'Cirurgia', 'Trauma cranioencefálico - hematoma epidural', 'Difícil', null, null, 'Paciente de 20 anos sofre queda de bicicleta com trauma craniano, mantendo-se consciente inicialmente (intervalo lúcido), mas evolui em 2 horas com cefaleia intensa, vômitos e rebaixamento progressivo do nível de consciência, associado a midríase à direita. Tomografia de crânio mostra coleção biconvexa hiperdensa em região temporal direita.

A conduta mais adequada é', 'Cirurgia de urgência para drenagem do hematoma epidural, dado o risco de herniação cerebral iminente', 'Conduta expectante com observação clínica seriada, sem indicação cirúrgica', 'Hidantalização isolada, aguardando melhora clínica espontânea', 'Alta hospitalar com orientações de retorno se piora dos sintomas', 'A', 'Intervalo lúcido seguido de deterioração neurológica rápida com midríase unilateral e imagem de coleção biconvexa hiperdensa são clássicos de hematoma epidural, emergência neurocirúrgica que exige drenagem imediata pelo risco de herniação.', 'B: quadro com deterioração neurológica rápida e sinais de herniação iminente não deve ser apenas observado. C: hidantalização isolada não trata a causa compressiva do hematoma. D: gravidade do quadro contraindica alta hospitalar.', 'Em revisão', null, null, null),
  ('SIM2-053', 'simulado', '2', '53', 'Cirurgia', 'Trauma cranioencefálico - hematoma subdural', 'Difícil', null, null, 'Paciente de 75 anos, em uso de anticoagulante oral para fibrilação atrial, sofre queda da própria altura há 3 dias, com trauma craniano leve na ocasião. Nos últimos dias, familiares notam confusão progressiva, lentificação e um episódio de hemiparesia leve transitória. Tomografia de crânio mostra coleção em crescente, hipodensa, ao longo da convexidade cerebral.

A hipótese diagnóstica mais provável e a conduta são', 'Meningite; iniciar antibioticoterapia empírica isolada', 'Hematoma subdural (provavelmente crônico); avaliação neurocirúrgica para definir necessidade de drenagem e correção da anticoagulação', 'Acidente vascular encefálico isquêmico; iniciar trombólise imediata', 'Demência de início agudo; iniciar investigação ambulatorial sem urgência', 'B', 'Trauma craniano em paciente anticoagulado, com deterioração neurológica progressiva dias depois e imagem de coleção em crescente ao longo da convexidade, é característico de hematoma subdural; exige avaliação neurocirúrgica e correção da anticoagulação.', 'A: a imagem descrita não é compatível com meningite. C: o contexto de trauma recente e a imagem descrita não são compatíveis com AVC isquêmico, e trombólise seria contraindicada em paciente já anticoagulado com sangramento. D: o quadro tem causa identificável (hematoma) e não deve ser tratado como investigação ambulatorial sem urgência.', 'Em revisão', null, null, null),
  ('SIM2-054', 'simulado', '2', '54', 'Cirurgia', 'Aneurisma de aorta abdominal roto', 'Difícil', null, null, 'Paciente de 70 anos, tabagista e hipertenso, apresenta dor abdominal e lombar súbita e intensa, associada a massa pulsátil palpável em abdome e sinais de choque hipovolêmico. Sinais vitais na admissão:', 'Tratamento conservador com analgesia e observação clínica', 'Estabilização hemodinâmica inicial e encaminhamento imediato para correção cirúrgica de urgência (aberta ou endovascular), sem atrasar por exames demorados', 'Solicitar tomografia de abdome com contraste antes de qualquer decisão terapêutica, independentemente da estabilidade hemodinâmica', 'Alta hospitalar com anti-hipertensivo oral e retorno ambulatorial em 1 semana', 'B', 'Dor abdominal súbita, massa pulsátil e choque hipovolêmico em paciente idoso com fatores de risco vascular sugerem ruptura de aneurisma de aorta abdominal, emergência com altíssima mortalidade que exige correção cirúrgica imediata sem atrasos desnecessários.', 'A: tratamento conservador não é opção para ruptura confirmada ou fortemente suspeita de aneurisma. C: em paciente instável com quadro típico, aguardar exame de imagem demorado pode ser fatal; a decisão cirúrgica não deve ser atrasada. D: a gravidade do quadro contraindica alta hospitalar.', 'Em revisão', '[object Object]', null, null),
  ('SIM2-055', 'simulado', '2', '55', 'Cirurgia', 'Câncer gástrico', 'Médio', null, null, 'Paciente de 62 anos relata dor epigástrica vaga, saciedade precoce e perda de peso de 8kg em 3 meses, associados a episódios de melena intermitente. Endoscopia digestiva alta revela lesão ulcerada de bordas irregulares e elevadas em corpo gástrico, com biópsia confirmando adenocarcinoma.

A conduta mais adequada é', 'Iniciar apenas tratamento sintomático, sem investigação de estadiamento', 'Indicar cirurgia imediata sem qualquer estadiamento prévio', 'Encaminhar para estadiamento oncológico completo (tomografia de tórax/abdome/pelve) e avaliação de equipe multidisciplinar para definição terapêutica', 'Prescrever inibidor de bomba de prótons isolado, como tratamento definitivo', 'C', 'Confirmado o diagnóstico histológico de câncer gástrico, o próximo passo é o estadiamento completo para definir a extensão da doença e planejar o tratamento (cirúrgico, quimioterápico ou combinado) com equipe multidisciplinar.', 'A: tratamento sintomático isolado não trata a neoplasia diagnosticada. B: cirurgia sem estadiamento prévio pode ser inadequada, dependendo da extensão da doença. D: IBP não trata a neoplasia maligna já confirmada por biópsia.', 'Em revisão', null, null, null),
  ('SIM2-056', 'simulado', '2', '56', 'Cirurgia', 'Câncer de esôfago', 'Difícil', null, null, 'Paciente de 65 anos, tabagista e etilista importante, apresenta disfagia progressiva primeiro para sólidos e depois também para líquidos, associada a perda de peso significativa (12kg em 4 meses), há 5 meses. Endoscopia digestiva alta revela lesão vegetante e estenosante no terço médio do esôfago, biópsia confirmando carcinoma epidermoide.

A conduta mais adequada é', 'Prescrever apenas inibidor de bomba de prótons, sem necessidade de investigação adicional', 'Encaminhar para estadiamento completo (tomografia, ecoendoscopia) e avaliação multidisciplinar para definição do tratamento', 'Iniciar dilatação endoscópica isolada como tratamento definitivo, sem necessidade de outras condutas', 'Indicar apenas suporte nutricional, sem qualquer investigação oncológica', 'B', 'Diagnóstico histológico confirmado de câncer de esôfago exige estadiamento completo para avaliar extensão da doença e definir a estratégia terapêutica adequada (cirúrgica, quimioterápica, radioterápica ou combinada) com equipe multidisciplinar.', 'A: IBP não trata a neoplasia maligna já confirmada. C: dilatação endoscópica é medida paliativa para disfagia, não tratamento definitivo do câncer. D: suporte nutricional é importante, mas não substitui a investigação e tratamento oncológico da causa de base.', 'Em revisão', null, null, null),
  ('SIM2-057', 'simulado', '2', '57', 'Cirurgia', 'Estenose hipertrófica do piloro', 'Médio', null, null, 'Lactente de 5 semanas apresenta vômitos em jato, não biliosos, progressivamente mais frequentes após as mamadas, com fome logo após vomitar, há 1 semana. Notado emagrecimento e diminuição do número de fraldas molhadas. Ao exame: oliva pilórica palpável em quadrante superior direito do abdome, ondas peristálticas visíveis.

A hipótese diagnóstica mais provável e a conduta são', 'Refluxo gastroesofágico fisiológico; apenas orientações posturais, sem necessidade de exames', 'Invaginação intestinal; realizar redução por enema com contraste de urgência', 'Alergia à proteína do leite de vaca; substituir por fórmula extensamente hidrolisada', 'Estenose hipertrófica do piloro; correção hidroeletrolítica prévia seguida de piloromiotomia cirúrgica', 'D', 'Vômitos em jato não biliosos, com fome após o episódio, oliva palpável e ondas peristálticas visíveis são clássicos de estenose hipertrófica do piloro; a conduta é correção hidroeletrolítica (alcalose hipoclorêmica é comum) seguida de piloromiotomia.', 'A: vômitos em jato progressivos com massa palpável e emagrecimento não são compatíveis com refluxo fisiológico simples. B: invaginação cursa com dor em cólica e fezes em geleia de framboesa, quadro diferente. C: o quadro descrito com oliva pilórica palpável é mais específico de estenose pilórica.', 'Em revisão', null, null, null),
  ('SIM2-058', 'simulado', '2', '58', 'Cirurgia', 'Invaginação intestinal', 'Difícil', null, null, 'Lactente de 8 meses, previamente hígido, apresenta episódios de choro intenso e irritabilidade intercalados com períodos de letargia, associados a vômitos e uma evacuação com muco e sangue (''geleia de framboesa''), há algumas horas. Ao exame: massa palpável em quadrante superior direito do abdome, discretamente dolorosa.

A hipótese diagnóstica mais provável e a conduta são', 'Invaginação intestinal; redução por enema (hidrostático ou pneumático) guiado por imagem, com cirurgia se falha ou sinais de perfuração', 'Apendicite aguda; indicar apendicectomia de urgência sem outra investigação', 'Constipação intestinal funcional; orientar dieta rica em fibras', 'Gastroenterite aguda; apenas hidratação oral e observação domiciliar', 'A', 'Dor em cólica intermitente com períodos de letargia, vômitos, fezes em ''geleia de framboesa'' e massa palpável são clássicos de invaginação intestinal; a conduta inicial é redução por enema guiado por imagem, reservando cirurgia para falha ou complicações.', 'B: apendicectomia não é a conduta para invaginação; o quadro clínico e a idade também não são típicos de apendicite. C: constipação não explica o sangramento nem a massa palpável. D: o padrão de dor intermitente com letargia e sangue nas fezes não é típico de gastroenterite simples.', 'Em revisão', null, null, null),
  ('SIM2-059', 'simulado', '2', '59', 'Cirurgia', 'Varizes de membros inferiores', 'Fácil', null, null, 'Paciente de 48 anos, que trabalha em pé por longos períodos, relata dor e sensação de peso em membros inferiores ao final do dia, com veias dilatadas e tortuosas visíveis em face medial da perna, que melhoram com elevação dos membros. Nega úlceras ou alterações de pele.

A conduta inicial mais adequada é', 'Orientar medidas conservadoras (meias de compressão, elevação dos membros, exercício físico) e avaliar necessidade de tratamento especializado conforme evolução', 'Indicar cirurgia de safenectomia imediata, independentemente dos sintomas', 'Prescrever anticoagulante oral, pois se trata de trombose venosa', 'Não é necessária nenhuma orientação, pois varizes não trazem nenhum risco à saúde', 'A', 'Varizes sintomáticas sem complicações (úlcera, tromboflebite) têm indicação inicial de medidas conservadoras, reservando tratamento cirúrgico/especializado para casos refratários ou com complicações.', 'B: cirurgia não é a primeira conduta para varizes não complicadas. C: não há dados sugestivos de trombose venosa aguda no quadro descrito. D: varizes podem evoluir com complicações (úlceras, tromboflebite) se não orientadas adequadamente.', 'Em revisão', null, null, null),
  ('SIM2-060', 'simulado', '2', '60', 'Cirurgia', 'Doença arterial periférica', 'Médio', null, null, 'Paciente de 65 anos, tabagista e diabético, relata dor em panturrilha ao caminhar determinada distância, que melhora com o repouso (claudicação intermitente), há 6 meses, com piora progressiva da distância percorrida. Pulsos pediosos diminuídos bilateralmente. Índice tornozelo-braquial de 0,65.

A conduta mais adequada é', 'Iniciar anticoagulação plena como primeira conduta, sem outras medidas', 'Controle rigoroso dos fatores de risco cardiovascular, cessação do tabagismo, programa de exercício supervisionado e antiagregante plaquetário', 'Tranquilizar o paciente, pois claudicação intermitente não representa risco cardiovascular', 'Indicar amputação preventiva, independentemente da gravidade dos sintomas', 'B', 'Claudicação intermitente com ITB reduzido confirma doença arterial periférica; o manejo inicial inclui controle de fatores de risco, cessação do tabagismo, exercício supervisionado e antiagregante plaquetário, reservando revascularização para casos refratários ou críticos.', 'A: anticoagulação plena não é o tratamento de primeira linha para doença arterial periférica sintomática. C: doença arterial periférica é marcador importante de risco cardiovascular sistêmico, não deve ser minimizada. D: amputação é medida extrema, reservada para isquemia crítica com inviabilidade de membro, não para claudicação intermitente inicial.', 'Em revisão', null, null, null),
  ('SIM2-061', 'simulado', '2', '61', 'Cirurgia', 'Trombose venosa profunda', 'Médio', null, null, 'Paciente de 55 anos, em pós-operatório de cirurgia ortopédica há 4 dias, apresenta edema, dor e aumento da temperatura local em panturrilha esquerda, com sinal de Homans positivo. Nega dispneia ou dor torácica.

A conduta mais adequada é', 'Iniciar apenas repouso absoluto com o membro elevado, sem necessidade de anticoagulação', 'Aguardar resolução espontânea do quadro, sem qualquer investigação', 'Realizar massagem local vigorosa para melhorar a circulação', 'Confirmar o diagnóstico com ultrassonografia com doppler e iniciar anticoagulação conforme protocolo', 'D', 'Quadro sugestivo de trombose venosa profunda em paciente com fator de risco (pós-operatório recente) deve ser confirmado por USG com doppler, com anticoagulação iniciada conforme protocolo para prevenir progressão e embolia pulmonar.', 'A: TVP confirmada ou fortemente suspeita exige anticoagulação, não apenas repouso. B: TVP não tratada tem risco significativo de embolia pulmonar, não deve ser deixada sem investigação. C: massagem local é contraindicada em suspeita de TVP, pelo risco de deslocamento do trombo.', 'Em revisão', null, null, null),
  ('SIM2-062', 'simulado', '2', '62', 'Cirurgia', 'Abscesso hepático', 'Difícil', null, null, 'Paciente de 45 anos apresenta febre alta, calafrios e dor em hipocôndrio direito há 5 dias, associados a hepatomegalia dolorosa. Tomografia de abdome mostra coleção hipodensa arredondada de 6cm no lobo hepático direito, com realce periférico ao contraste.

A conduta mais adequada é', 'Conduta expectante sem qualquer intervenção, aguardando resolução espontânea', 'Cirurgia aberta de urgência como única opção terapêutica, sem tentativa de drenagem percutânea', 'Apenas antibioticoterapia oral ambulatorial, sem necessidade de drenagem', 'Antibioticoterapia de amplo espectro associada a drenagem percutânea guiada por imagem da coleção', 'D', 'Abscesso hepático com coleção significativa (>5cm) tem indicação de drenagem percutânea guiada por imagem associada a antibioticoterapia de amplo espectro, sendo essa a conduta padrão para a maioria dos casos.', 'A: abscesso não tratado tem risco de sepse e ruptura, não deve ser conduzido apenas expectante. B: drenagem percutânea é a primeira opção na maioria dos casos, reservando cirurgia aberta para falha do tratamento percutâneo. C: antibiótico oral isolado é insuficiente para coleção significativa, que necessita de drenagem.', 'Em revisão', null, null, null),
  ('SIM2-063', 'simulado', '2', '63', 'Cirurgia', 'Colangite aguda', 'Difícil', null, null, 'Paciente de 68 anos apresenta febre alta, icterícia e dor em hipocôndrio direito (tríade de Charcot) há 2 dias, evoluindo nas últimas horas com confusão mental e hipotensão (pêntade de Reynolds). USG mostra dilatação de vias biliares com cálculo no colédoco.

A conduta mais adequada é', 'Colecistectomia videolaparoscópica eletiva em 6 meses, sem necessidade de conduta imediata', 'Conduta expectante, aguardando resolução espontânea da obstrução biliar', 'Estabilização hemodinâmica, antibioticoterapia de amplo espectro e descompressão biliar de urgência (CPRE ou drenagem percutânea)', 'Apenas antibioticoterapia oral ambulatorial, sem necessidade de descompressão biliar', 'C', 'A pêntade de Reynolds (tríade de Charcot + confusão mental + hipotensão) indica colangite aguda grave, exigindo estabilização, antibioticoterapia de amplo espectro e descompressão biliar de urgência, pelo alto risco de sepse e óbito.', 'A: a gravidade do quadro exige descompressão biliar imediata, não pode aguardar meses. B: colangite aguda grave não tratada tem alta mortalidade, exigindo intervenção urgente. D: quadro grave com instabilidade hemodinâmica e confusão mental exige internação e tratamento intensivo, não conduta ambulatorial.', 'Em revisão', null, null, null),
  ('SIM2-064', 'simulado', '2', '64', 'Cirurgia', 'Fístula anal', 'Médio', null, null, 'Paciente de 38 anos relata episódios recorrentes de drenagem de secreção purulenta por orifício próximo ao ânus, associados a desconforto local, há 6 meses, com história de abscesso perianal drenado cirurgicamente há 8 meses. Exame proctológico identifica orifício externo com trajeto fistuloso palpável.

A conduta mais adequada é', 'Conduta expectante, pois fístulas anais resolvem espontaneamente na maioria dos casos', 'Indicar apenas banho de assento, sem necessidade de avaliação especializada', 'Apenas antibioticoterapia oral prolongada, sem necessidade de tratamento cirúrgico', 'Encaminhar para avaliação cirúrgica especializada para tratamento definitivo da fístula (fistulotomia ou outras técnicas conforme complexidade)', 'D', 'Fístula anal estabelecida, com trajeto fistuloso identificável e história de abscesso prévio, tem indicação de tratamento cirúrgico definitivo, sendo necessária avaliação especializada para definir a melhor técnica conforme a complexidade do trajeto.', 'A: fístulas anais estabelecidas raramente resolvem espontaneamente, geralmente persistindo até tratamento definitivo. B: banho de assento pode ser medida coadjuvante, mas não trata definitivamente a fístula. C: antibiótico isolado não resolve o trajeto fistuloso já formado, que requer tratamento cirúrgico.', 'Em revisão', null, null, null),
  ('SIM2-065', 'simulado', '2', '65', 'Cirurgia', 'Cisto pilonidal', 'Fácil', null, null, 'Paciente de 24 anos, sexo masculino, apresenta dor e tumoração dolorosa na região sacrococcígea há 4 dias, com saída de secreção purulenta ao exame, associada a hiperemia local. Refere episódios semelhantes anteriores que resolveram espontaneamente.

A conduta mais adequada na fase aguda é', 'Conduta expectante, aguardando drenagem espontânea sem qualquer intervenção', 'Indicar excisão ampla de urgência da região sacrococcígea, mesmo na fase aguda infectada', 'Drenagem cirúrgica do abscesso pilonidal agudo, com tratamento definitivo eletivo posterior conforme recorrência', 'Apenas antibioticoterapia oral isolada, sem necessidade de drenagem', 'C', 'Abscesso pilonidal agudo tem indicação de drenagem cirúrgica na fase aguda, com tratamento definitivo (excisão) considerado posteriormente de forma eletiva, especialmente diante de recorrência.', 'A: abscessos geralmente não resolvem sem drenagem, podendo progredir com risco de complicações. B: excisão ampla na fase aguda infectada não é a conduta padrão, sendo preferível drenar primeiro e operar definitivamente depois, a frio. D: antibiótico isolado é insuficiente quando há coleção purulenta que necessita drenagem.', 'Em revisão', null, null, null),
  ('SIM2-066', 'simulado', '2', '66', 'Cirurgia', 'Queimadura elétrica', 'Difícil', null, null, 'Paciente de 35 anos sofre queimadura elétrica por contato com fiação de alta voltagem, com pontos de entrada e saída identificáveis nas mãos e pés. Apresenta arritmia cardíaca ao monitor e urina de coloração escura (mioglobinúria suspeita).

A conduta mais adequada é', 'Restringir líquidos pelo risco de sobrecarga hídrica', 'Alta hospitalar após curativo local, sem necessidade de internação', 'Monitorização cardíaca contínua, hidratação venosa vigorosa visando diurese adequada para prevenir lesão renal por mioglobina, e avaliação de lesões profundas', 'Tratar apenas as lesões cutâneas visíveis, sem necessidade de monitorização cardíaca', 'C', 'Queimadura elétrica de alta voltagem pode causar lesão profunda desproporcional às lesões cutâneas visíveis, arritmias cardíacas e rabdomiólise com mioglobinúria; a conduta inclui monitorização cardíaca contínua e hidratação vigorosa para proteção renal.', 'A: hidratação vigorosa é necessária para prevenir lesão renal por mioglobina, ao contrário da restrição. B: o risco de arritmias e lesão renal contraindica alta sem observação e monitorização adequadas. D: a lesão elétrica frequentemente causa dano interno significativo, não visível externamente, exigindo avaliação sistêmica completa.', 'Em revisão', null, null, null),
  ('SIM2-067', 'simulado', '2', '67', 'Cirurgia', 'Amputação traumática - manejo pré-hospitalar', 'Médio', null, null, 'Paciente de 30 anos sofre amputação traumática parcial de antebraço direito em acidente de trabalho com máquina industrial, com sangramento ativo importante no coto. A equipe de resgate consegue recuperar o segmento amputado no local.

A conduta mais adequada em relação ao segmento amputado e ao controle da hemorragia é', 'Descartar o segmento amputado, pois reimplante não é mais realizado atualmente', 'Envolver o segmento amputado em gaze umedecida com soro fisiológico, acondicioná-lo em saco plástico e depois em recipiente com gelo, e controlar a hemorragia do coto com compressão direta ou torniquete se necessário', 'Aplicar torniquete no segmento amputado antes de transportá-lo, junto ao paciente', 'Congelar diretamente o segmento amputado em contato com o gelo, sem proteção', 'B', 'O segmento amputado deve ser envolvido em gaze umedecida com soro fisiológico, protegido em saco plástico e resfriado indiretamente (sem contato direto com gelo) para preservar viabilidade para eventual reimplante; a hemorragia do coto é controlada com compressão direta, reservando torniquete para hemorragia não controlável.', 'A: reimplante ainda é uma opção terapêutica válida em centros especializados, dependendo do caso. C: torniquete é aplicado no paciente para controlar hemorragia, não faz sentido no segmento já amputado. D: contato direto do tecido com gelo pode causar lesão por congelamento, prejudicando a viabilidade para reimplante.', 'Em revisão', null, null, null),
  ('SIM2-068', 'simulado', '2', '68', 'Cirurgia', 'Peritonite secundária pós-operatória', 'Difícil', null, null, 'Paciente no 5º dia de pós-operatório de colectomia por câncer, evolui com febre, dor abdominal difusa em piora, distensão e taquicardia. Ao exame: abdome com defesa generalizada e descompressão brusca dolorosa difusa. Tomografia de abdome sugere deiscência de anastomose com extravasamento de conteúdo intestinal.

A conduta mais adequada é', 'Reoperação de urgência para controle do foco (revisão da anastomose, lavagem da cavidade) associada a antibioticoterapia de amplo espectro', 'Alta hospitalar com antibiótico oral e retorno ambulatorial em 1 semana', 'Tratamento clínico exclusivo com antibioticoterapia, sem necessidade de reoperação', 'Conduta expectante, aguardando fechamento espontâneo da deiscência', 'A', 'Peritonite secundária por deiscência de anastomose com extravasamento de conteúdo intestinal é emergência cirúrgica; a conduta é reoperação de urgência para controle do foco infeccioso, associada a antibioticoterapia de amplo espectro.', 'B: a gravidade do quadro contraindica alta hospitalar. C: peritonite estabelecida com extravasamento confirmado não é tratada apenas clinicamente, exige controle cirúrgico do foco. D: deiscências com peritonite generalizada raramente fecham espontaneamente sem risco de deterioração clínica grave.', 'Em revisão', null, null, null),
  ('SIM2-069', 'simulado', '2', '69', 'Pediatria', 'Sepse neonatal tardia', 'Difícil', null, null, 'Recém-nascido de 20 dias de vida, prematuro (32 semanas ao nascer), ainda internado em UTI neonatal com cateter venoso central, apresenta instabilidade térmica, letargia e distensão abdominal nas últimas 12 horas, associadas a episódios de apneia. Exames coletados mostram leucocitose com desvio à esquerda e PCR elevada.

A conduta mais adequada é', 'Alta da UTI neonatal para acompanhamento ambulatorial, pois o quadro é leve', 'Tratar apenas a distensão abdominal com sonda orogástrica, sem necessidade de antibiótico', 'Observação clínica isolada, aguardando resultado da hemocultura antes de qualquer tratamento', 'Coletar hemocultura (e de outros sítios pertinentes) e iniciar antibioticoterapia empírica de amplo espectro, considerando germes hospitalares', 'D', 'Sepse neonatal tardia (após 72h de vida) em prematuro com cateter central e sinais clínicos/laboratoriais sugestivos exige coleta de culturas e início imediato de antibioticoterapia empírica cobrindo germes hospitalares, sem aguardar resultado.', 'A: a gravidade e instabilidade do quadro contraindicam alta da UTI. B: distensão abdominal pode ser manifestação de sepse, tratamento isolado da distensão não trata a infecção sistêmica. C: aguardar hemocultura atrasa tratamento essencial em quadro de alto risco.', 'Em revisão', null, null, null),
  ('SIM2-070', 'simulado', '2', '70', 'Pediatria', 'Displasia do desenvolvimento do quadril', 'Médio', null, null, 'Recém-nascida do sexo feminino, primeira filha, nascida de parto pélvico, é avaliada na consulta de puericultura. Ao exame físico, observa-se assimetria de pregas cutâneas em membros inferiores e manobra de Ortolani positiva à esquerda (sensação de ressalto ao abduzir o quadril).

A conduta mais adequada é', 'Indicar radiografia de quadril imediatamente, sem necessidade de avaliação ultrassonográfica em recém-nascidos', 'Encaminhar para ultrassonografia de quadril e avaliação ortopédica pediátrica para confirmação e tratamento precoce', 'Aguardar até 1 ano de idade para realizar qualquer investigação de quadril', 'Tranquilizar os pais, pois assimetria de pregas é sempre variação da normalidade sem necessidade de investigação', 'B', 'Manobra de Ortolani positiva em recém-nascida com fatores de risco (sexo feminino, parto pélvico) é sugestiva de displasia do desenvolvimento do quadril; a investigação por USG (método de escolha em lactentes jovens) e avaliação ortopédica precoces são essenciais para melhor prognóstico.', 'A: radiografia tem menor acurácia em recém-nascidos devido à cartilagem não ossificada; USG é o exame de escolha nessa idade. C: o diagnóstico e tratamento precoces melhoram significativamente o prognóstico; atrasar a investigação piora o desfecho. D: assimetria de pregas associada a Ortolani positivo tem significado clínico e requer investigação.', 'Em revisão', null, null, null),
  ('SIM2-071', 'simulado', '2', '71', 'Pediatria', 'Criptorquidia', 'Fácil', null, null, 'Menino de 8 meses é levado à consulta de puericultura. Ao exame físico, testículo direito não é palpável na bolsa escrotal nem no trajeto inguinal, estando ausente desde o nascimento. Testículo esquerdo tópico e de volume normal.

A conduta mais adequada é', 'Tranquilizar os pais, pois criptorquidia unilateral não traz nenhum risco à saúde reprodutiva futura', 'Aguardar até os 5 anos de idade, pois a maioria dos casos resolve espontaneamente até essa idade', 'Encaminhar para avaliação cirúrgica pediátrica, pois a orquidopexia é recomendada idealmente entre 6 e 18 meses de idade', 'Iniciar tratamento hormonal isolado com gonadotrofina coriônica como primeira linha, sem necessidade de avaliação cirúrgica', 'C', 'Criptorquidia persistente após os 6 meses de idade tem indicação de correção cirúrgica (orquidopexia), idealmente entre 6 e 18 meses, para reduzir riscos futuros de infertilidade e neoplasia testicular.', 'A: criptorquidia não corrigida está associada a maior risco de infertilidade e neoplasia testicular. B: a maioria da descida espontânea ocorre nos primeiros meses de vida; após os 6 meses, a chance de descida espontânea é baixa, não devendo se aguardar até os 5 anos. D: tratamento hormonal isolado tem eficácia limitada e não é a primeira linha atualmente.', 'Em revisão', null, null, null),
  ('SIM2-072', 'simulado', '2', '72', 'Pediatria', 'Hipotireoidismo congênito - triagem neonatal', 'Médio', null, null, 'Recém-nascido realiza teste do pezinho no 5º dia de vida, com resultado de TSH elevado, confirmado em segunda coleta. Exame físico com hipotonia leve e icterícia prolongada, sem outras alterações significativas.

A conduta mais adequada é', 'Iniciar apenas acompanhamento nutricional, sem necessidade de reposição hormonal', 'Aguardar até 6 meses de vida para confirmar o diagnóstico antes de iniciar tratamento', 'Iniciar reposição com levotiroxina o mais precocemente possível, idealmente antes das duas semanas de vida, para prevenir dano neurológico', 'Não é necessário tratamento se a criança não apresentar sintomas evidentes ao exame físico', 'C', 'O hipotireoidismo congênito, identificado pela triagem neonatal, exige início precocíssimo de levotiroxina (idealmente antes de 2 semanas de vida) para prevenir o dano neurológico irreversível associado ao atraso no tratamento.', 'A: o tratamento específico é a reposição hormonal, não apenas suporte nutricional. B: o atraso no tratamento é a principal causa de dano neurológico permanente; não se deve aguardar. D: muitos casos são oligossintomáticos ao nascimento, e a ausência de sintomas não descarta a necessidade de tratamento diante de triagem positiva confirmada.', 'Em revisão', null, null, null),
  ('SIM2-073', 'simulado', '2', '73', 'Pediatria', 'Fibrose cística', 'Difícil', null, null, 'Lactente de 6 meses apresenta infecções respiratórias de repetição, tosse produtiva crônica e déficit de crescimento, associados a fezes volumosas, gordurosas e de odor fétido desde os primeiros meses de vida. Teste do suor realizado em duas dosagens:', 'Refluxo gastroesofágico fisiológico; apenas medidas posturais', 'Alergia à proteína do leite de vaca; substituir por fórmula hidrolisada, sem necessidade de outras condutas', 'Doença celíaca; iniciar dieta isenta de glúten como tratamento único', 'Fibrose cística; encaminhar para centro de referência para manejo multidisciplinar (fisioterapia respiratória, reposição enzimática, suporte nutricional)', 'D', 'Infecções respiratórias de repetição, esteatorreia e teste do suor positivo (cloreto elevado) são diagnósticos de fibrose cística; o manejo é multidisciplinar, com fisioterapia respiratória, reposição enzimática pancreática e suporte nutricional intensivo em centro especializado.', 'A: refluxo fisiológico não causa esteatorreia nem infecções respiratórias recorrentes. B: APLV não explica o teste do suor positivo nem o padrão respiratório e digestivo combinado descrito. C: doença celíaca não explica infecções respiratórias de repetição nem o teste do suor alterado.', 'Em revisão', '[object Object]', null, null),
  ('SIM2-074', 'simulado', '2', '74', 'Pediatria', 'Doença do refluxo gastroesofágico patológico', 'Médio', null, null, 'Lactente de 5 meses apresenta recusa alimentar progressiva, irritabilidade durante e após as mamadas, arqueamento do corpo e ganho de peso insuficiente nos últimos 2 meses, além de episódios recorrentes de tosse. Diferente do refluxo fisiológico simples.

A conduta mais adequada é', 'Investigação adicional (pHmetria ou endoscopia conforme indicação) e considerar tratamento farmacológico (inibidor de bomba de prótons) diante de sinais de doença do refluxo', 'Iniciar antibioticoterapia empírica para os episódios de tosse, sem investigar a causa de base', 'Suspender definitivamente o aleitamento materno como primeira conduta', 'Apenas orientações posturais, sem necessidade de investigação adicional, pois todo refluxo em lactente é fisiológico', 'A', 'A presença de sinais de alarme (recusa alimentar, déficit de ganho ponderal, irritabilidade importante, sintomas respiratórios) diferencia doença do refluxo gastroesofágico patológico do refluxo fisiológico simples, justificando investigação adicional e considerar tratamento farmacológico.', 'B: a tosse aqui é provavelmente secundária ao refluxo, não uma infecção primária a ser tratada com antibiótico. C: suspensão do aleitamento materno não é a primeira conduta; pode-se considerar ajustes na dieta materna se em amamentação. D: os sinais de alarme presentes (déficit de peso, recusa alimentar) diferenciam de refluxo fisiológico simples, exigindo investigação.', 'Em revisão', null, null, null),
  ('SIM2-075', 'simulado', '2', '75', 'Pediatria', 'Alergia à proteína do leite de vaca', 'Médio', null, null, 'Lactente de 3 meses, em uso de fórmula infantil desde o nascimento, apresenta regurgitações frequentes, cólicas importantes, fezes com raias de sangue e eczema cutâneo persistente, com piora progressiva nas últimas semanas.

A conduta mais adequada é', 'Suspender a fórmula com proteína do leite de vaca e substituir por fórmula extensamente hidrolisada (ou aminoácidos, se necessário)', 'Iniciar corticoide sistêmico como primeira conduta, sem alterar a alimentação', 'Iniciar antibioticoterapia empírica para tratar o sangramento nas fezes', 'Aumentar o volume da fórmula atual, pois os sintomas indicam apenas fome insatisfeita', 'A', 'Sintomas gastrointestinais (sangue nas fezes, cólicas) associados a manifestação cutânea (eczema) em lactente com fórmula à base de leite de vaca sugerem alergia à proteína do leite de vaca; a conduta é substituição por fórmula extensamente hidrolisada.', 'B: a primeira conduta é a exclusão do alérgeno alimentar, não o tratamento medicamentoso sistêmico. C: o sangramento é de origem alérgica/inflamatória, não infecciosa, não havendo indicação de antibiótico. D: aumentar o volume da mesma fórmula agravaria os sintomas alérgicos.', 'Em revisão', null, null, null),
  ('SIM2-076', 'simulado', '2', '76', 'Pediatria', 'Síndrome nefrótica idiopática na infância', 'Médio', null, null, 'Criança de 3 anos apresenta edema periorbital que piora pela manhã, evoluindo para edema generalizado (anasarca) em 1 semana, associado a urina espumosa. Exames mostram proteinúria maciça, hipoalbuminemia importante (albumina 1,6g/dL) e hipercolesterolemia, sem hematúria significativa.

A conduta mais adequada é', 'Apenas restrição hídrica isolada, sem necessidade de tratamento medicamentoso', 'Iniciar imunossupressor de segunda linha diretamente, sem tentativa prévia de corticoterapia', 'Iniciar corticoterapia (prednisona) em dose padrão, considerando o alto índice de resposta em crianças com essa apresentação típica', 'Indicar biópsia renal antes de iniciar qualquer tratamento em todos os casos', 'C', 'Síndrome nefrótica com apresentação típica em criança pequena (a causa mais comum é a doença de lesões mínimas) tem alta taxa de resposta à corticoterapia, sendo esta a conduta inicial padrão, sem necessidade de biópsia renal de rotina nesses casos típicos.', 'A: a proteinúria maciça e hipoalbuminemia exigem tratamento específico, não apenas restrição hídrica. B: corticoterapia é a primeira linha; imunossupressores de segunda linha são reservados para casos corticorresistentes ou corticodependentes. D: biópsia renal não é rotina em apresentação típica em criança pequena, sendo reservada para casos atípicos.', 'Em revisão', null, null, null),
  ('SIM2-077', 'simulado', '2', '77', 'Pediatria', 'Infecção do trato urinário na infância', 'Médio', null, null, 'Lactente de 8 meses apresenta febre alta sem foco aparente há 2 dias, irritabilidade e recusa alimentar. Exame de urina coletado por saco coletor mostra piúria e nitrito positivo. Urocultura foi solicitada por técnica adequada.

A conduta mais adequada é', 'Iniciar antibioticoterapia apenas se a criança apresentar sintomas urinários específicos, como disúria', 'Aguardar o resultado da urocultura antes de iniciar qualquer tratamento antibiótico', 'Iniciar antibioticoterapia empírica enquanto aguarda o resultado da urocultura, com posterior investigação por USG de vias urinárias', 'Tratar apenas a febre com antitérmico, sem necessidade de investigação ou antibiótico', 'C', 'Febre sem foco em lactente com achados sugestivos de ITU (piúria, nitrito positivo) justifica início de antibioticoterapia empírica sem aguardar a urocultura, dado o risco de pielonefrite e sequelas renais em lactentes, com investigação de imagem subsequente.', 'A: lactentes frequentemente não apresentam sintomas urinários específicos, manifestando-se apenas com febre e irritabilidade. B: aguardar a urocultura atrasa um tratamento necessário em lactente com febre e achados sugestivos de ITU. D: febre sem foco com achados urinários alterados não deve ser tratada apenas sintomaticamente.', 'Em revisão', null, null, null),
  ('SIM2-078', 'simulado', '2', '78', 'Pediatria', 'Meningite bacteriana na infância', 'Difícil', null, null, 'Criança de 18 meses apresenta febre alta, irritabilidade importante, recusa alimentar e abaulamento de fontanela (ainda não fechada), associados a um episódio de vômito, há 8 horas. Ao exame: letárgica, com choro agudo característico ao manuseio.

A conduta mais adequada é', 'Iniciar antibioticoterapia empírica imediatamente e realizar punção lombar assim que possível, sem atrasar o tratamento', 'Tratar apenas como quadro viral autolimitado, sem necessidade de investigação adicional', 'Aguardar resultado de exames de imagem antes de qualquer conduta terapêutica', 'Iniciar apenas antitérmico e observação domiciliar', 'A', 'Fontanela abaulada, letargia e choro agudo em lactente febril são sinais de alarme para meningite bacteriana; a antibioticoterapia empírica deve ser iniciada imediatamente, com punção lombar realizada assim que possível, sem atrasar o tratamento.', 'B: os sinais de alarme presentes não são compatíveis com quadro viral simples autolimitado. C: aguardar exames de imagem atrasa tratamento essencial em suspeita de meningite bacteriana. D: a gravidade do quadro contraindica conduta apenas domiciliar.', 'Em revisão', null, null, null),
  ('SIM2-079', 'simulado', '2', '79', 'Pediatria', 'Varicela', 'Fácil', null, null, 'Criança de 4 anos apresenta lesões cutâneas pruriginosas em diferentes estágios evolutivos (máculas, pápulas, vesículas e crostas) simultaneamente, distribuídas pelo tronco, face e couro cabeludo, associadas a febre baixa, há 2 dias. Não frequenta a escola há 3 dias por contato com colega com quadro semelhante.

A conduta mais adequada é', 'Iniciar aciclovir oral de rotina para todas as crianças saudáveis com varicela não complicada', 'Indicar internação hospitalar obrigatória para todos os casos de varicela na infância', 'Tratamento sintomático (antitérmico, anti-histamínico se necessário) e orientação de isolamento até que todas as lesões estejam em fase de crosta', 'Iniciar antibioticoterapia sistêmica de rotina para todos os casos, independentemente de sinais de infecção secundária', 'C', 'Lesões em diferentes estágios evolutivos (polimorfismo característico) em criança saudável com quadro típico de varicela têm tratamento sintomático, com orientação de isolamento até a fase de crosta de todas as lesões, quando cessa a transmissibilidade.', 'A: aciclovir não é rotina para crianças saudáveis com varicela não complicada, sendo reservado para casos de maior risco. B: internação não é rotina para varicela não complicada em criança saudável. D: antibiótico não é indicado rotineiramente na varicela não complicada, sendo etiologia viral.', 'Em revisão', null, null, null),
  ('SIM2-080', 'simulado', '2', '80', 'Pediatria', 'Sarampo', 'Médio', null, null, 'Criança de 3 anos, sem histórico vacinal (pais recusam vacinação), apresenta febre alta, tosse, coriza e conjuntivite há 3 dias, com surgimento de exantema maculopapular iniciado na face e progredindo para o tronco no dia atual. Presença de manchas esbranquiçadas em mucosa oral.

A hipótese diagnóstica mais provável e a conduta são', 'Escarlatina; iniciar penicilina oral, sem necessidade de notificação compulsória', 'Exantema súbito (roséola); apenas orientar retorno se houver piora, sem necessidade de notificação', 'Sarampo; notificação compulsória imediata, isolamento respiratório e suporte clínico, com vitamina A conforme protocolo', 'Rubéola; apenas acompanhamento clínico ambulatorial de rotina', 'C', 'Febre, tosse, coriza, conjuntivite, manchas de Koplik (manchas esbranquiçadas em mucosa oral) e exantema com progressão craniocaudal são clássicos de sarampo em criança não vacinada; é doença de notificação compulsória imediata, com isolamento e suporte clínico.', 'A: escarlatina cursa com exantema micropapular áspero e outros achados, sem manchas de Koplik. B: roséola tem outro padrão de exantema (surge após a queda da febre) e não apresenta manchas de Koplik. D: rubéola geralmente tem quadro mais brando, sem manchas de Koplik características.', 'Em revisão', null, null, null),
  ('SIM2-081', 'simulado', '2', '81', 'Pediatria', 'Dengue na infância', 'Médio', null, null, 'Criança de 6 anos apresenta febre alta, dor retro-orbitária (referida como dor nos olhos), mialgia e exantema há 3 dias, em área endêmica para dengue. Nos últimos exames, hematócrito discretamente elevado em relação ao basal e plaquetas em queda, sem sinais de alarme no momento.

A conduta mais adequada é', 'Internação hospitalar obrigatória para todos os casos de dengue na infância, independente da gravidade', 'Prescrever ácido acetilsalicílico para controle da febre e dos sintomas', 'Iniciar antibioticoterapia empírica, por suspeita de infecção bacteriana associada', 'Manejo ambulatorial com hidratação oral vigorosa, antitérmico (evitando AAS e anti-inflamatórios), e orientação de sinais de alarme para retorno imediato', 'D', 'Dengue sem sinais de alarme pode ser manejada ambulatorialmente com hidratação oral vigorosa e antitérmico seguro (evitando AAS e AINEs pelo risco de sangramento), com orientação clara sobre sinais de alarme para retorno imediato.', 'A: nem todo caso de dengue sem sinais de alarme necessita internação; a maioria pode ser acompanhada ambulatorialmente com orientação adequada. B: AAS é contraindicado na dengue pelo risco aumentado de sangramento. C: dengue é doença viral, antibiótico não tem indicação sem evidência de infecção bacteriana concomitante.', 'Em revisão', null, null, null),
  ('SIM2-082', 'simulado', '2', '82', 'Pediatria', 'Autismo - triagem e diagnóstico', 'Médio', null, null, 'Criança de 20 meses é levada à consulta de puericultura. Os pais relatam que a criança não aponta para objetos de interesse, não estabelece contato visual sustentado, prefere brincar sozinha e ainda não fala nenhuma palavra com significado. Apresenta movimentos repetitivos com as mãos.

A conduta mais adequada é', 'Aguardar até os 4 anos de idade para iniciar qualquer investigação de desenvolvimento', 'Encaminhar diretamente para tratamento medicamentoso, sem necessidade de avaliação diagnóstica prévia', 'Tranquilizar os pais, pois esses comportamentos são absolutamente normais para a idade e não requerem investigação', 'Aplicar instrumento de triagem para transtorno do espectro autista (ex: M-CHAT) e, se positivo, encaminhar para avaliação multidisciplinar especializada', 'D', 'Sinais de alerta para transtorno do espectro autista (ausência de contato visual, não apontar, ausência de linguagem, comportamentos repetitivos) justificam aplicação de instrumento de triagem validado e encaminhamento precoce para avaliação multidisciplinar, dado o benefício da intervenção precoce.', 'A: a intervenção precoce melhora significativamente o prognóstico; atrasar a investigação até os 4 anos é prejudicial. B: não há tratamento medicamentoso específico para TEA sem diagnóstico e plano terapêutico individualizado prévio. C: os sinais descritos são reconhecidos sinais de alerta para TEA e merecem investigação, não devendo ser normalizados sem avaliação.', 'Em revisão', null, null, null),
  ('SIM2-083', 'simulado', '2', '83', 'Pediatria', 'Maus-tratos infantis / síndrome do bebê sacudido', 'Difícil', null, null, 'Lactente de 4 meses é trazido ao PS com letargia, vômitos e um episódio de convulsão, sem história de trauma relatada pelos cuidadores. Fundoscopia revela hemorragias retinianas bilaterais. Tomografia de crânio mostra hematoma subdural bilateral, sem fratura de crânio associada.

A conduta mais adequada é', 'Aceitar a ausência de história de trauma relatada pelos cuidadores como suficiente para descartar maus-tratos', 'Suspeitar de síndrome do bebê sacudido (trauma infligido), notificar o Conselho Tutelar e realizar investigação multidisciplinar completa', 'Encaminhar para alta hospitalar assim que houver estabilização clínica, sem investigação adicional', 'Tratar apenas as manifestações clínicas agudas, sem necessidade de notificação', 'B', 'Hemorragias retinianas associadas a hematoma subdural sem fratura ou trauma relatado, em lactente, são um padrão clássico e altamente sugestivo de síndrome do bebê sacudido; a suspeita exige notificação obrigatória ao Conselho Tutelar e investigação multidisciplinar.', 'A: a ausência de história de trauma relatada, associada a esse padrão de lesões, reforça a suspeita de trauma não acidental, não a descarta. C: alta sem investigação e sem proteção adequada expõe a criança a risco de nova agressão. D: a notificação é obrigatória em suspeita de maus-tratos, independentemente do tratamento clínico agudo.', 'Em revisão', null, null, null),
  ('SIM2-084', 'simulado', '2', '84', 'Pediatria', 'Anemia falciforme - triagem neonatal', 'Médio', null, null, 'Recém-nascido tem resultado do teste do pezinho compatível com traço falciforme heterozigoto (padrão FAS), confirmado em eletroforese de hemoglobina de segunda amostra. Está assintomático, com desenvolvimento normal.

A orientação mais adequada aos pais é', 'Não é necessária nenhuma orientação, pois traço falciforme não tem nenhuma relevância clínica ou genética', 'Informar que a criança tem doença falciforme grave e necessitará de transfusões sanguíneas regulares', 'Iniciar profilaxia com penicilina e ácido fólico de rotina, como se fosse doença falciforme homozigota', 'Explicar que se trata de traço falciforme (heterozigoto), geralmente sem manifestações clínicas significativas, mas com importância para aconselhamento genético familiar', 'D', 'O padrão FAS na triagem neonatal indica traço falciforme (heterozigoto), condição geralmente assintomática que não configura doença falciforme; é importante orientar os pais sobre a relevância para aconselhamento genético familiar (risco em futuras gestações).', 'A: o traço falciforme tem relevância para aconselhamento genético, mesmo sendo geralmente assintomático clinicamente. B: traço falciforme não é doença falciforme grave; a maioria dos portadores é assintomática. C: profilaxia com penicilina é indicada para doença falciforme (padrão FS ou similares), não para o traço isolado.', 'Em revisão', null, null, null),
  ('SIM2-085', 'simulado', '2', '85', 'Pediatria', 'Puberdade precoce', 'Difícil', null, null, 'Menina de 7 anos apresenta desenvolvimento de broto mamário bilateral e pelos pubianos iniciados há 4 meses, com aceleração da velocidade de crescimento. Idade óssea compatível com 9 anos. Nega cefaleia ou alterações visuais.

A conduta mais adequada é', 'Iniciar bloqueio puberal medicamentoso imediatamente na UBS, sem investigação especializada prévia', 'Tranquilizar a família, pois desenvolvimento puberal aos 7 anos está sempre dentro da normalidade', 'Encaminhar para avaliação endocrinológica pediátrica especializada para investigação da causa e definição da necessidade de tratamento', 'Aguardar até os 10 anos para reavaliar, sem necessidade de investigação nesse momento', 'C', 'Desenvolvimento de caracteres sexuais secundários antes dos 8 anos em meninas caracteriza puberdade precoce, exigindo investigação especializada para identificar a causa (central, periférica) e definir necessidade e tipo de tratamento.', 'A: o tratamento deve ser definido após investigação especializada da causa, não iniciado empiricamente na atenção primária. B: o quadro descrito está fora do limite considerado normal (8 anos em meninas), configurando puberdade precoce. D: atrasar a investigação pode comprometer o prognóstico de estatura final e adiar o diagnóstico de causas potencialmente graves.', 'Em revisão', null, null, null),
  ('SIM2-086', 'simulado', '2', '86', 'Pediatria', 'Diabetes mellitus tipo 1 na infância - debut', 'Difícil', null, null, 'Criança de 8 anos é trazida ao PS com poliúria, polidipsia e emagrecimento importante nas últimas 3 semanas, associados a dor abdominal e vômitos nas últimas horas, hálito cetônico e respiração de Kussmaul. Exames coletados na admissão:', 'Restringir totalmente a hidratação, pelo risco de sobrecarga volêmica no quadro', 'Iniciar apenas insulina subcutânea ambulatorial, sem necessidade de internação', 'Internação para tratamento de cetoacidose diabética, com hidratação venosa cuidadosa e insulinoterapia conforme protocolo pediátrico, monitorando o risco de edema cerebral', 'Tratar apenas a dor abdominal e os vômitos, sem investigar a causa metabólica de base', 'C', 'Poliúria, polidipsia, emagrecimento e cetoacidose confirmada caracterizam debut de diabetes mellitus tipo 1 com cetoacidose diabética; o tratamento exige internação, hidratação venosa cuidadosa (risco de edema cerebral em crianças é maior que em adultos) e insulinoterapia conforme protocolo específico.', 'A: a hidratação venosa é essencial no tratamento, devendo ser cuidadosamente calculada, não restringida totalmente, pelo risco de choque. B: cetoacidose diabética exige tratamento hospitalar intensivo, não manejo ambulatorial inicial. D: os sintomas gastrointestinais são secundários à cetoacidose, que precisa ser tratada na sua causa.', 'Em revisão', '[object Object]', null, null),
  ('SIM2-087', 'simulado', '2', '87', 'Pediatria', 'Alergia à proteína do leite de vaca vs intolerância à lactose', 'Médio', null, null, 'Lactente de 2 meses, em aleitamento misto (materno e fórmula), apresenta distensão abdominal, flatulência excessiva e fezes explosivas e ácidas após a introdução da fórmula, sem sangue nas fezes ou manifestações cutâneas associadas.

A hipótese mais provável e a conduta são', 'Doença celíaca; iniciar dieta isenta de glúten como conduta imediata', 'Quadro normal para a idade, sem necessidade de qualquer investigação ou ajuste', 'Possível intolerância transitória à lactose ou sensibilidade à fórmula; considerar fórmula com baixo teor de lactose e reavaliação, diferenciando de alergia verdadeira pela ausência de sinais imunomediados', 'Alergia à proteína do leite de vaca grave; iniciar imediatamente fórmula de aminoácidos, sem considerar outras hipóteses', 'C', 'Sintomas predominantemente digestivos (distensão, flatulência, fezes ácidas) sem sinais imunomediados (sangue nas fezes, eczema, urticária) sugerem mais intolerância/sensibilidade do que alergia verdadeira à proteína do leite de vaca, orientando conduta escalonada.', 'A: doença celíaca não se manifesta antes da introdução de glúten na dieta, ainda não ocorrida nessa idade. B: os sintomas descritos, embora possam ser leves, merecem avaliação e ajuste conforme evolução. D: a ausência de sinais imunomediados torna a hipótese de alergia grave menos provável como primeira conduta, sendo mais adequado uma abordagem escalonada.', 'Em revisão', null, null, null),
  ('SIM2-088', 'simulado', '2', '88', 'Medicina Preventiva e Social', 'Rastreamento de câncer de mama - mamografia', 'Médio', null, null, 'Mulher de 42 anos, cuja mãe teve câncer de mama diagnosticado aos 38 anos, procura a UBS para orientação sobre início de rastreamento mamográfico, preocupada com o histórico familiar.

A conduta mais adequada, considerando o risco elevado pelo histórico familiar, é', 'Encaminhar para avaliação de risco especializada, considerando início de rastreamento mais precoce do que o recomendado para a população geral', 'Orientar que deve seguir exatamente a mesma recomendação da população de risco habitual (início aos 50 anos), sem qualquer diferenciação', 'Iniciar mamografia apenas aos 50 anos, independentemente do histórico familiar relatado', 'Não é necessário nenhum rastreamento, pois câncer de mama na mãe não influencia o risco da filha', 'A', 'Histórico familiar de câncer de mama em parente de primeiro grau diagnosticado antes dos 50 anos é fator de risco relevante, justificando avaliação especializada de risco e consideração de rastreamento mais precoce do que o preconizado para a população geral.', 'B: o histórico familiar significativo modifica a estratégia de rastreamento recomendada, não devendo seguir exatamente o protocolo de risco habitual. C: aguardar até os 50 anos ignora o fator de risco familiar relevante. D: histórico familiar de câncer de mama, especialmente em idade jovem, é fator de risco genético reconhecido.', 'Em revisão', null, null, null),
  ('SIM2-089', 'simulado', '2', '89', 'Medicina Preventiva e Social', 'Rastreamento de câncer de próstata', 'Difícil', null, null, 'Homem de 55 anos, assintomático, sem histórico familiar de câncer de próstata, procura a UBS solicitando dosagem de PSA para rastreamento, após ler sobre o exame na internet.

A conduta mais adequada, segundo as recomendações baseadas em evidências para a população de risco habitual, é', 'Recusar a solicitação do exame, informando que rastreamento de câncer de próstata nunca deve ser realizado', 'Solicitar o PSA imediatamente, sem qualquer discussão prévia, pois é sempre indicado a partir dos 50 anos', 'Solicitar apenas toque retal, sem necessidade de qualquer conversa sobre o PSA', 'Discutir com o paciente os riscos e benefícios do rastreamento (incluindo possibilidade de sobrediagnóstico e sobretratamento), respeitando a decisão compartilhada', 'D', 'O rastreamento de câncer de próstata com PSA é controverso, com risco de sobrediagnóstico e sobretratamento; a conduta recomendada é a decisão compartilhada, discutindo riscos e benefícios individualizados com o paciente, respeitando sua autonomia.', 'A: recusar categoricamente também não respeita a autonomia do paciente informado sobre os riscos e benefícios. B: solicitar sem discussão prévia ignora a natureza controversa do rastreamento e a necessidade de decisão compartilhada. C: toque retal isolado sem discussão sobre o PSA não atende adequadamente à solicitação do paciente nem ao processo de decisão compartilhada.', 'Em revisão', null, null, null),
  ('SIM2-090', 'simulado', '2', '90', 'Medicina Preventiva e Social', 'Coeficiente de mortalidade materna', 'Médio', null, null, 'Em um estado brasileiro, ocorreram 45 óbitos maternos (por causas relacionadas à gestação, parto ou puerpério) em um ano, sobre um total de 90.000 nascidos vivos no mesmo período e local.

O coeficiente de mortalidade materna desse estado, e sua principal utilidade, são', '0,5 por 1.000 nascidos vivos; reflete exclusivamente causas genéticas fetais', '45 por 100.000 nascidos vivos; indicador exclusivo de mortalidade neonatal', '5 por 100.000 nascidos vivos; reflete apenas mortalidade por causas violentas', '50 por 100.000 nascidos vivos; reflete a qualidade da assistência obstétrica e as condições de saúde da mulher', 'D', 'Coeficiente de mortalidade materna = (óbitos maternos / nascidos vivos) x 100.000 = (45/90.000)x100.000 = 50 por 100.000 nascidos vivos. É indicador sensível à qualidade da assistência obstétrica e às condições socioeconômicas.', 'A: cálculo e unidade incorretos; o indicador não reflete causas genéticas fetais, mas óbitos maternos. B: 45 é o número absoluto de óbitos, não o coeficiente calculado; o indicador não é de mortalidade neonatal. C: cálculo incorreto e definição equivocada do que o indicador mede.', 'Em revisão', '[object Object]', null, null),
  ('SIM2-091', 'simulado', '2', '91', 'Medicina Preventiva e Social', 'Estudo de coorte vs caso-controle (desenho de pesquisa)', 'Difícil', null, null, 'Pesquisadores desejam investigar a associação entre exposição ocupacional a determinado solvente químico e o desenvolvimento de uma doença rara (incidência muito baixa na população geral), com recursos e tempo limitados para a pesquisa.

O desenho de estudo mais adequado para essa situação é', 'Estudo de coorte prospectivo, por ser sempre superior para qualquer tipo de associação exposição-doença', 'Estudo transversal, por ser o mais rápido e permitir avaliar causalidade de forma direta', 'Estudo de caso-controle, por ser mais eficiente para doenças raras, partindo dos casos já existentes e comparando com controles quanto à exposição prévia', 'Ensaio clínico randomizado, por ser o padrão-ouro para investigar qualquer associação causal', 'C', 'Para doenças raras, o estudo de caso-controle é mais eficiente, pois parte dos casos já existentes (identificados) e investiga retrospectivamente a exposição, sendo mais rápido e barato do que aguardar o desenvolvimento da doença em uma coorte.', 'A: coorte prospectiva para doença rara exigiria amostra enorme e acompanhamento muito longo, sendo ineficiente com recursos limitados. B: estudo transversal avalia exposição e desfecho simultaneamente, não permitindo estabelecer relação temporal/causal adequada. D: ensaio clínico não seria ético nem viável para investigar exposição ocupacional a um agente potencialmente nocivo.', 'Em revisão', null, null, null),
  ('SIM2-092', 'simulado', '2', '92', 'Medicina Preventiva e Social', 'Viés de confusão em pesquisa epidemiológica', 'Difícil', null, null, 'Um estudo observacional encontra associação entre o consumo de café e maior incidência de câncer de pulmão. Ao analisar os dados mais detalhadamente, os pesquisadores notam que consumidores de café também apresentam maior prevalência de tabagismo em comparação aos não consumidores.

Esse cenário exemplifica principalmente qual conceito metodológico?', 'Viés de confusão, pois o tabagismo pode ser a verdadeira causa do câncer de pulmão, distorcendo a associação aparente com o café', 'Causalidade reversa, indicando que o câncer de pulmão causa maior consumo de café', 'Viés de seleção, relacionado à forma como os participantes foram recrutados para o estudo', 'Viés de aferição, relacionado a erro sistemático na medição do consumo de café', 'A', 'Quando uma terceira variável (tabagismo) está associada tanto à exposição estudada (café) quanto ao desfecho (câncer de pulmão), e não está no caminho causal entre eles, configura-se viés de confusão, que pode distorcer ou até criar uma associação espúria.', 'B: não há indicação no cenário de que a doença precede ou causa o comportamento de consumo. C: viés de seleção se refere a distorções na forma de seleção dos participantes, não é o problema central aqui. D: viés de aferição se refere a erros na medição das variáveis, não descrito no cenário.', 'Em revisão', null, null, null),
  ('SIM2-093', 'simulado', '2', '93', 'Medicina Preventiva e Social', 'Calendário vacinal do idoso', 'Fácil', null, null, 'Idoso de 68 anos, sem comorbidades relevantes, procura a UBS para atualizar seu calendário vacinal, sem registro de vacinação nos últimos anos.

Segundo o calendário nacional de vacinação para idosos, as vacinas recomendadas incluem', 'Influenza anual, dupla adulto (dT) a cada 10 anos, pneumocócica conforme esquema vigente, e outras conforme indicação individual (herpes-zóster, hepatite B, se não vacinado)', 'BCG de reforço obrigatório para todos os idosos, independente do histórico vacinal prévio', 'Nenhuma vacina é recomendada rotineiramente para a população idosa saudável', 'Apenas vacina contra influenza, sendo as demais desnecessárias após os 60 anos', 'A', 'O calendário nacional do idoso inclui vacina contra influenza anual, reforço de dupla adulto a cada 10 anos, pneumocócica conforme esquema vigente, além de outras conforme indicação individual, sendo um grupo prioritário para diversas imunizações.', 'B: BCG não é indicada como reforço de rotina para idosos. C: idosos são grupo prioritário para diversas vacinações, dada a maior vulnerabilidade a complicações de doenças imunopreveníveis. D: outras vacinas além da influenza são recomendadas e importantes para essa faixa etária.', 'Em revisão', null, null, null),
  ('SIM2-094', 'simulado', '2', '94', 'Medicina Preventiva e Social', 'Notificação de violência doméstica', 'Médio', null, null, 'Mulher de 30 anos comparece à consulta na UBS com equimoses em diferentes estágios de evolução em braços e face, relatando inicialmente que ''caiu de escada''. Durante a consulta, acaba relatando espontaneamente que o companheiro tem sido agressivo fisicamente há meses.

A conduta mais adequada é', 'Contatar imediatamente o agressor para confrontá-lo sobre a situação relatada', 'Orientar a paciente a resolver a situação sozinha, sem envolvimento de outros serviços', 'Acolher a paciente, registrar os achados no prontuário, notificar o caso conforme protocolo de violência doméstica e oferecer encaminhamento à rede de proteção, respeitando a autonomia da paciente quanto às decisões subsequentes', 'Não notificar, pois a notificação depende exclusivamente da autorização da vítima', 'C', 'Diante de relato de violência doméstica, a conduta é acolher, registrar adequadamente, notificar conforme protocolo (a notificação de violência é compulsória e não depende de autorização da vítima) e oferecer encaminhamento à rede de proteção, respeitando a autonomia da paciente nas decisões subsequentes.', 'A: confrontar o agressor diretamente pode colocar a vítima em risco maior, não sendo conduta apropriada do profissional de saúde. B: a paciente não deve ser deixada sem suporte da rede de proteção disponível. D: a notificação de violência é compulsória no Brasil, não dependendo de autorização da vítima para ser realizada.', 'Em revisão', null, null, null),
  ('SIM2-095', 'simulado', '2', '95', 'Medicina Preventiva e Social', 'Saúde indígena / equidade', 'Médio', null, null, 'Uma equipe de saúde que atende população indígena em aldeia remota nota alta prevalência de desnutrição infantil e doenças infecciosas, associada a dificuldades de acesso a saneamento básico e serviços de saúde regulares.

A abordagem mais adequada para reduzir essas iniquidades em saúde é', 'Aguardar que a própria comunidade resolva os problemas de saúde sem intervenção externa', 'Aplicar exatamente os mesmos protocolos padronizados usados em grandes centros urbanos, sem qualquer adaptação', 'Articulação intersetorial (saúde, saneamento, educação) e fortalecimento da atenção primária com respeito às especificidades culturais da comunidade indígena', 'Focar exclusivamente em campanhas de vacinação, sem considerar outros determinantes de saúde', 'C', 'A redução de iniquidades em saúde de populações vulneráveis, como comunidades indígenas, exige articulação intersetorial (abordando determinantes sociais como saneamento) e fortalecimento da atenção primária, respeitando as especificidades culturais locais.', 'A: a ausência de intervenção do sistema de saúde não é compatível com o princípio de equidade do SUS. B: protocolos padronizados sem adaptação cultural e territorial tendem a ser menos efetivos nessas populações. D: focar apenas em vacinação ignora outros determinantes relevantes, como saneamento e nutrição, evidenciados no caso.', 'Em revisão', null, null, null),
  ('SIM2-096', 'simulado', '2', '96', 'Medicina Preventiva e Social', 'Humanização do parto (PHPN)', 'Médio', null, null, 'Uma maternidade pública revisa seus protocolos assistenciais para alinhar-se aos princípios do Programa de Humanização no Pré-natal e Nascimento, com foco em reduzir intervenções desnecessárias e respeitar a autonomia das gestantes durante o trabalho de parto.

Uma medida alinhada a esses princípios é', 'Permitir a presença de acompanhante de escolha da mulher durante todo o trabalho de parto, parto e pós-parto imediato', 'Realizar cesariana eletiva de rotina para todas as gestantes, independentemente de indicação clínica', 'Restringir a movimentação da parturiente durante todo o trabalho de parto, mantendo-a sempre deitada', 'Realizar episiotomia de rotina em todos os partos vaginais, independentemente da avaliação individual', 'A', 'A garantia de acompanhante de livre escolha da mulher durante o trabalho de parto, parto e pós-parto é um direito legalmente assegurado e um dos pilares da humanização da assistência obstétrica.', 'B: cesariana eletiva de rotina sem indicação clínica não está alinhada aos princípios de humanização e uso racional de intervenções. C: restringir a movimentação vai contra as práticas humanizadas, que incentivam a liberdade de posição durante o trabalho de parto. D: episiotomia de rotina não é recomendada atualmente, devendo ser seletiva e não sistemática, indo contra a humanização baseada em evidências.', 'Em revisão', null, null, null),
  ('SIM2-097', 'simulado', '2', '97', 'Medicina Preventiva e Social', 'Programa Saúde da Família - histórico e princípios', 'Fácil', null, null, 'Durante uma capacitação de novos profissionais para atuação em Estratégia Saúde da Família, o instrutor explica os princípios organizativos que fundamentaram a criação do modelo no Brasil, a partir da década de 1990.

Um dos princípios centrais da Estratégia Saúde da Família é', 'Foco exclusivo em ações curativas individuais, sem articulação com ações coletivas de saúde', 'Substituição do modelo de atenção tradicional centrado na doença por um modelo centrado na família e no território, com ações de promoção e prevenção prioritárias', 'Priorização exclusiva de atendimentos hospitalares de alta complexidade dentro do território adscrito', 'Atendimento por livre demanda, sem vínculo territorial ou adscrição de população definida', 'B', 'A Estratégia Saúde da Família foi concebida para reorganizar a atenção básica, substituindo o modelo centrado na doença e no atendimento hospitalar por um modelo centrado na família, no território e nas ações de promoção e prevenção.', 'A: a ESF articula ações individuais e coletivas, com forte ênfase em promoção e prevenção, não apenas ações curativas. C: a ESF é voltada para a atenção primária, não para atendimentos hospitalares de alta complexidade. D: a adscrição de território e população é um princípio central da ESF, não a livre demanda sem vínculo.', 'Em revisão', null, null, null),
  ('SIM2-098', 'simulado', '2', '98', 'Medicina Preventiva e Social', 'Matriciamento em saúde mental na Atenção Básica', 'Médio', null, null, 'Uma equipe de Estratégia Saúde da Família identifica dificuldade em manejar casos complexos de saúde mental em seu território, com longa fila de espera para encaminhamento ao serviço especializado.

A estratégia mais adequada, segundo os Cadernos de Atenção Básica, para qualificar o cuidado nesses casos é', 'Encaminhar automaticamente todos os casos de saúde mental para o hospital psiquiátrico, sem tentativa de manejo na atenção básica', 'Implementar apoio matricial com equipe de saúde mental especializada, realizando discussão de casos conjunta e capacitação da equipe de referência', 'Prescrever psicotrópicos para todos os casos identificados, sem avaliação especializada', 'Não realizar nenhum acompanhamento de saúde mental na atenção básica, aguardando exclusivamente vaga no CAPS', 'B', 'O apoio matricial em saúde mental, com discussão compartilhada de casos entre a equipe de referência (ESF) e especialistas, qualifica o cuidado na atenção básica, ampliando a capacidade resolutiva sem necessidade de encaminhamento para todos os casos.', 'A: encaminhamento automático para hospital psiquiátrico não é a estratégia preconizada, indo contra o modelo de cuidado em rede e desospitalização. C: prescrição sem avaliação adequada não é conduta segura nem alinhada às diretrizes de cuidado em saúde mental. D: a atenção básica tem papel importante no cuidado em saúde mental, não devendo se eximir dessa responsabilidade.', 'Em revisão', null, null, null),
  ('SIM2-099', 'simulado', '2', '99', 'Medicina Preventiva e Social', 'Ética médica - sigilo profissional', 'Médio', null, null, 'Durante consulta, um paciente de 16 anos revela ao médico que iniciou atividade sexual e solicita orientação sobre contracepção, pedindo explicitamente que a informação não seja compartilhada com os pais.

Considerando os princípios éticos aplicáveis, a conduta mais adequada é', 'Informar obrigatoriamente os pais sobre tudo o que foi relatado na consulta, independente da vontade do adolescente', 'Registrar a informação no prontuário de forma acessível a qualquer pessoa que solicite, sem restrição de sigilo', 'Respeitar o sigilo profissional e fornecer a orientação solicitada, avaliando a capacidade de compreensão do adolescente sobre a informação (autonomia progressiva)', 'Recusar-se a atender a solicitação do adolescente até que os pais estejam presentes', 'C', 'O sigilo médico se aplica a adolescentes com capacidade de compreensão sobre sua própria saúde (autonomia progressiva), sendo ético fornecer orientação sobre contracepção e saúde sexual reprodutiva respeitando essa confidencialidade, salvo situações de risco grave que exijam quebra de sigilo.', 'A: quebrar o sigilo sem justificativa ética/legal específica fere a confidencialidade e pode afastar o adolescente do serviço de saúde. B: o prontuário deve manter sigilo, não sendo acessível livremente sem justificativa legal. D: recusar o atendimento nega o direito do adolescente à informação e ao cuidado em saúde.', 'Em revisão', null, null, null),
  ('SIM2-100', 'simulado', '2', '100', 'Medicina Preventiva e Social', 'Bioética - princípios fundamentais', 'Médio', null, null, 'Um paciente idoso, lúcido e orientado, com doença terminal em estágio avançado, recusa um procedimento invasivo de suporte de vida oferecido pela equipe médica, mesmo após receber informações completas sobre riscos e benefícios do procedimento.

O princípio bioético que deve prevalecer nessa decisão é', 'Autonomia, respeitando a decisão informada e consciente do paciente sobre seu próprio corpo e tratamento', 'Justiça, priorizando a decisão da equipe médica sobre a alocação de recursos hospitalares', 'Não maleficência isolada, justificando a realização forçada do procedimento para evitar dano futuro', 'Beneficência exclusivamente, impondo o tratamento por ser considerado o melhor para o paciente, independente de sua vontade', 'A', 'O princípio da autonomia garante ao paciente capaz e devidamente informado o direito de aceitar ou recusar tratamentos propostos, mesmo que a equipe médica considere o procedimento benéfico; a decisão informada do paciente deve ser respeitada.', 'B: a questão não envolve alocação de recursos entre pacientes, mas a decisão individual do próprio paciente sobre seu tratamento. C: não maleficência não justifica impor tratamento contra a vontade de paciente capaz, o que constituiria violação da autonomia. D: impor tratamento contra a vontade de paciente capaz e informado fere o princípio da autonomia, não devendo prevalecer isoladamente sobre a decisão do paciente.', 'Em revisão', null, null, null),
  ('SIM3-001', 'simulado', '3', '1', 'Clínica Médica', 'Estenose mitral', 'Difícil', null, null, 'Paciente de 45 anos, com histórico de febre reumática na infância, relata dispneia progressiva aos esforços e episódios de palpitação há 6 meses, com piora recente. Ao exame: ausculta cardíaca com ruflar diastólico em ápice, hiperfonese de primeira bulha, estalido de abertura. ECG mostra fibrilação atrial de início recente.

A hipótese diagnóstica mais provável e a conduta são', 'Insuficiência aórtica; iniciar apenas diurético, sem necessidade de anticoagulação', 'Estenose mitral reumática; anticoagulação pela fibrilação atrial associada, controle de frequência e avaliação de intervenção valvar conforme gravidade', 'Pericardite constritiva; indicar pericardiectomia de urgência', 'Prolapso de valva mitral; tranquilizar a paciente, sem necessidade de investigação adicional', 'B', 'Ruflar diastólico, hiperfonese de B1 e estalido de abertura em paciente com febre reumática prévia são clássicos de estenose mitral; a fibrilação atrial associada exige anticoagulação pelo alto risco tromboembólico, além de avaliação de intervenção valvar conforme a gravidade.', 'A: os achados auscultatórios descritos (ruflar diastólico, estalido de abertura) não são de insuficiência aórtica. C: pericardite constritiva tem outros achados clínicos, sem relação direta com o quadro valvar descrito. D: prolapso mitral tem achado auscultatório diferente (clique mesossistólico) e não costuma cursar com esse quadro.', 'Em revisão', null, null, null),
  ('SIM3-002', 'simulado', '3', '2', 'Clínica Médica', 'Endocardite infecciosa', 'Difícil', null, null, 'Paciente de 55 anos, usuário de drogas injetáveis, apresenta febre persistente há 2 semanas, associada a mal-estar e perda de peso. Ao exame: sopro sistólico novo em foco tricúspide, petéquias em conjuntiva, nódulos dolorosos em polpas digitais (nódulos de Osler). Hemoculturas seriadas positivas para Staphylococcus aureus.

A conduta mais adequada é', 'Aguardar resultado de biópsia dos nódulos antes de iniciar qualquer tratamento', 'Iniciar antibioticoterapia oral de curta duração, sem necessidade de exame de imagem cardíaco', 'Tratar apenas a febre com antitérmico, sem necessidade de antibioticoterapia específica', 'Iniciar antibioticoterapia intravenosa prolongada dirigida ao agente identificado, com avaliação ecocardiográfica para complicações', 'D', 'Febre persistente, sopro novo, fenômenos vasculares/imunológicos (petéquias, nódulos de Osler) e hemoculturas positivas em usuário de drogas injetáveis confirmam endocardite infecciosa; o tratamento é antibioticoterapia IV prolongada dirigida, com ecocardiograma para avaliar complicações valvares.', 'A: o diagnóstico já está estabelecido pelas hemoculturas e quadro clínico, não sendo necessário aguardar biópsia. B: endocardite infecciosa exige antibioticoterapia intravenosa prolongada (semanas), não tratamento oral de curta duração. C: a gravidade da infecção exige tratamento antimicrobiano específico, não apenas sintomático.', 'Em revisão', null, null, null),
  ('SIM3-003', 'simulado', '3', '3', 'Clínica Médica', 'Pericardite aguda', 'Médio', null, null, 'Paciente de 30 anos, com quadro viral respiratório recente, apresenta dor torácica pleurítica que piora ao deitar e melhora ao inclinar-se para frente, há 2 dias. ECG mostra supradesnivelamento difuso do segmento ST com concavidade para cima, sem imagem em espelho.

A hipótese diagnóstica mais provável e a conduta são', 'Pericardite aguda; anti-inflamatório não esteroide em dose plena, associado a colchicina para reduzir recorrência', 'Dissecção de aorta; solicitar angiotomografia de tórax de urgência antes de qualquer tratamento', 'Embolia pulmonar; iniciar anticoagulação plena imediatamente', 'Infarto agudo do miocárdio; encaminhar para angioplastia primária de urgência', 'A', 'Dor pleurítica posicional (piora deitado, melhora inclinando-se para frente) associada a supradesnivelamento difuso e côncavo do ST, sem imagem em espelho, é característica de pericardite aguda; o tratamento inicial é AINE associado a colchicina.', 'B: a dissecção de aorta tem apresentação clínica diferente, geralmente com dor lancinante e irradiação características. C: a dor posicional típica e o ECG descrito não são compatíveis com embolia pulmonar. D: o padrão eletrocardiográfico difuso e côncavo, sem imagem em espelho, e a característica posicional da dor não são típicos de IAM.', 'Em revisão', null, null, null),
  ('SIM3-004', 'simulado', '3', '4', 'Clínica Médica', 'Crise tireotóxica', 'Difícil', null, null, 'Paciente de 35 anos, com hipertireoidismo conhecido sem tratamento regular, é trazida ao PS após procedimento cirúrgico de urgência, com febre alta (39,8°C), taquicardia importante (FC 150bpm), agitação intensa e confusão mental.

A hipótese diagnóstica mais provável e a conduta são', 'Crise tireotóxica (tempestade tireoidiana); tratamento intensivo com tionamida, iodo, betabloqueador e corticoide, em ambiente de terapia intensiva', 'Infecção pós-operatória isolada; apenas antibioticoterapia, sem necessidade de tratamento específico para a tireoide', 'Síndrome neuroléptica maligna; suspender qualquer medicação tireoidiana', 'Delirium pós-operatório simples; apenas sedação leve e observação', 'A', 'Febre alta, taquicardia importante e alteração do estado mental em paciente com hipertireoidismo não controlado, precipitados por estresse cirúrgico, são característicos de tempestade tireoidiana, emergência endócrina que exige tratamento intensivo multimodal.', 'B: o quadro sistêmico grave com esses achados específicos aponta para descompensação tireoidiana, não apenas infecção isolada, embora a infecção possa ser o gatilho. C: o contexto de hipertireoidismo não tratado e o padrão clínico não são de síndrome neuroléptica maligna. D: a gravidade do quadro (febre alta, taquicardia extrema) não é compatível com delirium simples sem causa endócrina tratável.', 'Em revisão', null, null, null),
  ('SIM3-005', 'simulado', '3', '5', 'Clínica Médica', 'Feocromocitoma', 'Difícil', null, null, 'Paciente de 42 anos apresenta episódios paroxísticos de cefaleia intensa, palpitações e sudorese profusa, associados a picos de pressão arterial (até 210x120mmHg) durante as crises, com normalização entre os episódios, há 4 meses. Nega uso de substâncias ilícitas.

A conduta mais adequada para investigação é', 'Dosagem de metanefrinas plasmáticas ou urinárias fracionadas, seguida de exame de imagem abdominal se confirmada a suspeita bioquímica', 'Solicitar apenas ecocardiograma, sem necessidade de exames hormonais', 'Iniciar anti-hipertensivo de rotina sem investigação adicional, tratando como hipertensão essencial', 'Tranquilizar o paciente, pois episódios paroxísticos de hipertensão são sempre de origem psicogênica', 'A', 'Episódios paroxísticos de cefaleia, palpitação, sudorese e hipertensão intensa sugerem feocromocitoma; a investigação inicial é a dosagem de metanefrinas fracionadas, com exame de imagem abdominal subsequente se a suspeita bioquímica for confirmada.', 'B: ecocardiograma não investiga a causa hormonal suspeitada. C: tratar como hipertensão essencial sem investigar a causa secundária pode postergar diagnóstico de condição potencialmente grave e tratável. D: o padrão paroxístico característico não deve ser assumido como psicogênico sem investigação adequada.', 'Em revisão', null, null, null),
  ('SIM3-006', 'simulado', '3', '6', 'Clínica Médica', 'Doença de Cushing / síndrome de Cushing', 'Difícil', null, null, 'Paciente de 38 anos apresenta ganho de peso centrípeto, face em ''lua cheia'', estrias violáceas em abdome, fraqueza muscular proximal e hipertensão de início recente, ao longo dos últimos 8 meses. Cortisol salivar noturno elevado em duas dosagens.

A conduta mais adequada para prosseguir a investigação é', 'Indicar adrenalectomia bilateral de urgência, sem confirmação diagnóstica adicional', 'Tranquilizar o paciente, pois os achados descritos são inespecíficos e não sugerem doença endócrina', 'Realizar teste de supressão com dexametasona e dosagem de ACTH para diferenciar a causa (dependente ou independente de ACTH) do hipercortisolismo', 'Iniciar tratamento com cetoconazol imediatamente, sem necessidade de investigação da causa', 'C', 'Achados clínicos característicos de síndrome de Cushing associados a cortisol elevado confirmado exigem investigação da causa (teste de supressão com dexametasona e dosagem de ACTH) antes de definir o tratamento específico.', 'A: cirurgia definitiva não deve ser indicada sem identificação precisa da causa do hipercortisolismo. B: o conjunto de achados (fácies, estrias violáceas, fraqueza proximal, hipertensão) associado a cortisol elevado é bastante específico para síndrome de Cushing. D: tratamento medicamentoso deve ser guiado pela causa identificada, não iniciado empiricamente sem investigação etiológica.', 'Em revisão', null, null, null),
  ('SIM3-007', 'simulado', '3', '7', 'Clínica Médica', 'Hiperparatireoidismo primário', 'Médio', null, null, 'Paciente de 58 anos, assintomática, tem hipercalcemia identificada em exame de rotina (cálcio sérico 11,8mg/dL), confirmada em segunda dosagem. PTH sérico está elevado, inadequadamente normal-alto para o nível de cálcio.

A hipótese diagnóstica mais provável e a conduta são', 'Intoxicação por vitamina D; suspender suplementação, mesmo sem uso relatado', 'Hiperparatireoidismo primário; investigação adicional (densitometria óssea, função renal) e avaliação de indicação cirúrgica (paratireoidectomia)', 'Hipoparatireoidismo; iniciar reposição de cálcio e vitamina D imediatamente', 'Hipercalcemia maligna; iniciar quimioterapia empírica sem investigação adicional', 'B', 'Hipercalcemia com PTH elevado ou inadequadamente normal é característica de hiperparatireoidismo primário; a conduta inclui investigação de repercussões (óssea, renal) e avaliação da indicação cirúrgica conforme critérios estabelecidos.', 'A: não há relato de uso de suplementação de vitamina D no caso. C: hipoparatireoidismo cursaria com hipocalcemia e PTH baixo, quadro oposto ao descrito. D: hipercalcemia maligna geralmente cursa com PTH suprimido, diferente do achado descrito; além disso, não há evidência de neoplasia no caso.', 'Em revisão', null, null, null),
  ('SIM3-008', 'simulado', '3', '8', 'Clínica Médica', 'Doença renal policística', 'Médio', null, null, 'Paciente de 40 anos, com histórico familiar de doença renal em ambos os pais, apresenta hipertensão arterial de difícil controle e episódios recorrentes de dor lombar surda. USG de abdome mostra rins aumentados de tamanho bilateralmente, com múltiplos cistos de diferentes tamanhos.

A hipótese diagnóstica mais provável e a conduta são', 'Doença renal policística autossômica dominante; controle rigoroso da pressão arterial, monitorização da função renal e rastreamento de complicações associadas (aneurismas cerebrais em casos selecionados)', 'Nefrolitíase bilateral; indicar cirurgia de urgência para remoção dos cálculos', 'Pielonefrite crônica; iniciar antibioticoterapia prolongada isolada', 'Rim em ferradura; nenhuma conduta específica é necessária, achado sem relevância clínica', 'A', 'Rins aumentados com múltiplos cistos, histórico familiar positivo e hipertensão são característicos de doença renal policística autossômica dominante; a conduta envolve controle rigoroso da PA, monitorização renal e avaliação de complicações associadas.', 'B: os achados descritos são cistos, não cálculos, não havendo indicação cirúrgica de urgência para remoção de cálculos. C: o padrão de imagem descrito (múltiplos cistos bilaterais) não é característico de pielonefrite crônica isolada. D: rim em ferradura é anomalia anatômica diferente, sem o padrão cístico múltiplo bilateral descrito.', 'Em revisão', null, null, null),
  ('SIM3-009', 'simulado', '3', '9', 'Clínica Médica', 'Síndrome hepatorrenal', 'Difícil', null, null, 'Paciente com cirrose hepática avançada e ascite refratária evolui com piora da função renal (creatinina de 0,9 para 2,4mg/dL em 5 dias), sem outra causa identificável (sedimento urinário sem alterações, sem uso de nefrotóxicos, sem resposta à expansão volêmica com albumina).

A hipótese diagnóstica mais provável e a conduta são', 'Necrose tubular aguda por nefrotoxicidade; suspender qualquer medicação em uso', 'Síndrome hepatorrenal; considerar uso de vasoconstritores associados à albumina e avaliação para transplante hepático', 'Desidratação simples; apenas hidratação oral domiciliar', 'Glomerulonefrite aguda; iniciar corticoterapia imediatamente', 'B', 'Piora progressiva da função renal em cirrótico com ascite, sem outra causa identificável e sem resposta à expansão volêmica com albumina, é característica de síndrome hepatorrenal; o tratamento inclui vasoconstritores associados a albumina, com transplante hepático como tratamento definitivo.', 'A: a ausência de nefrotóxicos identificados e o sedimento urinário normal tornam necrose tubular aguda menos provável como diagnóstico principal. C: o quadro já foi testado com expansão volêmica sem resposta, descartando desidratação simples como causa isolada. D: não há achados sugestivos de glomerulonefrite (sedimento normal).', 'Em revisão', null, null, null),
  ('SIM3-010', 'simulado', '3', '10', 'Clínica Médica', 'Hipertensão portal / varizes esofágicas', 'Difícil', null, null, 'Paciente com cirrose hepática conhecida apresenta hematêmese volumosa súbita, com instabilidade hemodinâmica (PA 84x52mmHg, FC 124bpm). Endoscopia digestiva alta de urgência confirma sangramento ativo de varizes esofágicas.

Além da estabilização hemodinâmica, a conduta mais adequada inclui', 'Apenas reposição volêmica isolada, sem necessidade de terapia endoscópica ou medicamentosa específica', 'Cirurgia de urgência como primeira conduta, sem tentativa de terapia endoscópica', 'Terapia endoscópica (ligadura elástica) associada a droga vasoativa (terlipressina ou octreotide) e antibioticoterapia profilática', 'Aguardar resolução espontânea do sangramento, sem qualquer intervenção adicional', 'C', 'Hemorragia digestiva alta varicosa em cirrótico exige terapia endoscópica (ligadura elástica) associada a droga vasoativa para reduzir a pressão portal, além de antibioticoterapia profilática, que reduz mortalidade nesse contexto.', 'A: sangramento varicoso ativo exige intervenção específica (endoscópica e medicamentosa), não apenas reposição volêmica. B: terapia endoscópica é a primeira linha antes de considerar intervenções cirúrgicas ou de resgate. D: sangramento varicoso ativo tem alta mortalidade sem tratamento, não devendo ser deixado sem intervenção.', 'Em revisão', null, null, null),
  ('SIM3-011', 'simulado', '3', '11', 'Clínica Médica', 'Encefalopatia hepática', 'Médio', null, null, 'Paciente cirrótico apresenta confusão mental progressiva, flapping (asterix) e inversão do ciclo sono-vigília há 2 dias, após episódio de constipação intestinal importante. Nega uso de sedativos ou sangramento digestivo.

A conduta mais adequada é', 'Restringir totalmente a proteína da dieta por tempo indeterminado', 'Iniciar sedativo para controlar a agitação, sem investigar fatores precipitantes', 'Indicar transplante hepático de urgência como única conduta possível nesse momento', 'Identificar e tratar o fator precipitante (constipação) e iniciar lactulose para redução da absorção de amônia', 'D', 'Encefalopatia hepática frequentemente é precipitada por fatores identificáveis (constipação, infecção, sangramento, uso de sedativos); a conduta é identificar e tratar o precipitante, associada a lactulose para reduzir a produção/absorção de amônia intestinal.', 'A: restrição proteica prolongada não é mais recomendada rotineiramente, podendo prejudicar o estado nutricional. B: sedativos podem piorar a encefalopatia hepática e não tratam a causa de base. C: transplante não é conduta imediata para um episódio agudo tratável de encefalopatia hepática precipitada por fator identificável.', 'Em revisão', null, null, null),
  ('SIM3-012', 'simulado', '3', '12', 'Clínica Médica', 'Trombocitopenia induzida por heparina', 'Difícil', null, null, 'Paciente em uso de heparina não fracionada há 6 dias para tratamento de trombose venosa profunda apresenta queda significativa na contagem de plaquetas (de 220.000 para 85.000/mm³), associada a novo episódio de trombose em outro sítio.

A conduta mais adequada é', 'Suspender imediatamente a heparina e iniciar anticoagulante alternativo não heparínico', 'Manter a heparina na mesma dose, pois trombocitopenia leve é esperada e não requer conduta', 'Aumentar a dose de heparina para compensar a queda de plaquetas', 'Iniciar transfusão de plaquetas isolada, sem alterar a anticoagulação em uso', 'A', 'Queda significativa de plaquetas associada a novo evento trombótico durante uso de heparina sugere trombocitopenia induzida por heparina; a conduta é suspender imediatamente a heparina e iniciar anticoagulante alternativo não heparínico, pelo estado paradoxalmente pró-trombótico da condição.', 'B: a queda significativa associada a trombose não deve ser ignorada, sendo um quadro grave que exige ação imediata. C: aumentar a dose de heparina agravaria o quadro, já que ela é a causa da trombocitopenia. D: transfusão de plaquetas é geralmente contraindicada nesse contexto, pelo risco de agravar a trombose.', 'Em revisão', null, null, null),
  ('SIM3-013', 'simulado', '3', '13', 'Clínica Médica', 'Doença de von Willebrand', 'Médio', null, null, 'Paciente de 20 anos relata sangramento gengival frequente, epistaxes recorrentes desde a infância e menorragia importante desde a menarca. Histórico familiar de sangramentos similares na mãe. Tempo de sangramento prolongado, com contagem de plaquetas e coagulograma convencional normais.

A hipótese diagnóstica mais provável é', 'Púrpura trombocitopênica idiopática', 'Hemofilia A', 'Deficiência de vitamina K', 'Doença de von Willebrand', 'D', 'Sangramentos mucocutâneos recorrentes (gengival, epistaxe, menorragia) com histórico familiar e tempo de sangramento prolongado, apesar de plaquetas e coagulograma convencional normais, são característicos de doença de von Willebrand, distúrbio da hemostasia primária mais comum.', 'A: PTI cursaria com plaquetopenia, ausente neste caso. B: hemofilia A é ligada ao X (mais comum em homens) e cursa com sangramentos articulares/musculares profundos, além de TTPa alargado, diferente do quadro. C: deficiência de vitamina K alteraria o coagulograma convencional (TP/RNI), que está normal no caso.', 'Em revisão', null, null, null),
  ('SIM3-014', 'simulado', '3', '14', 'Clínica Médica', 'Linfoma de Hodgkin', 'Médio', null, null, 'Paciente de 28 anos apresenta linfonodomegalia cervical indolor, de crescimento progressivo há 2 meses, associada a febre intermitente, sudorese noturna profusa e perda de peso de 6kg no período (sintomas B). Biópsia do linfonodo mostra células de Reed-Sternberg.

A conduta mais adequada é', 'Indicar apenas observação clínica por 6 meses antes de qualquer investigação adicional', 'Iniciar antibioticoterapia empírica isolada, sem investigação adicional', 'Tranquilizar o paciente, pois linfonodomegalia cervical é sempre de causa infecciosa benigna', 'Encaminhar para estadiamento completo (tomografia, biópsia de medula óssea se indicada) e avaliação hematológica para definição terapêutica', 'D', 'Confirmado o diagnóstico histológico de linfoma de Hodgkin (células de Reed-Sternberg) com sintomas B presentes, o próximo passo é o estadiamento completo para definir a extensão da doença e planejar o tratamento adequado com a equipe de hematologia/oncologia.', 'A: retardar a investigação de estadiamento e tratamento de uma neoplasia confirmada pode piorar o prognóstico. B: antibiótico não trata neoplasia hematológica já confirmada histologicamente. C: a biópsia já confirmou o diagnóstico de linfoma, afastando causa infecciosa benigna isolada.', 'Em revisão', null, null, null),
  ('SIM3-015', 'simulado', '3', '15', 'Clínica Médica', 'Leucemia mieloide crônica', 'Médio', null, null, 'Paciente de 50 anos, assintomático, apresenta leucocitose importante (leucócitos 180.000/mm³) identificada em exame de rotina, com predomínio de neutrófilos em diferentes estágios de maturação e basofilia associada. Esplenomegalia palpável ao exame físico. Pesquisa do cromossomo Filadélfia (BCR-ABL) positiva.

A hipótese diagnóstica mais provável e a conduta são', 'Leucemia mieloide crônica; iniciar inibidor de tirosina quinase (ex: imatinibe) como tratamento de primeira linha', 'Leucemia linfoide aguda; iniciar quimioterapia intensiva de indução imediatamente', 'Reação leucemoide por infecção; apenas tratar o foco infeccioso, sem necessidade de outra conduta', 'Policitemia vera; iniciar flebotomias terapêuticas seriadas', 'A', 'Leucocitose importante com predomínio de neutrófilos em diferentes estágios de maturação, basofilia, esplenomegalia e cromossomo Filadélfia positivo confirmam leucemia mieloide crônica; o tratamento de primeira linha são os inibidores de tirosina quinase.', 'B: LLA teria predomínio de linfoblastos, não o espectro de maturação mieloide descrito, e o BCR-ABL positivo aponta para LMC. C: a presença do cromossomo Filadélfia confirma neoplasia, não sendo compatível com reação leucemoide reativa simples. D: policitemia vera cursa com aumento de hemácias, não é o achado principal descrito no caso.', 'Em revisão', null, null, null),
  ('SIM3-016', 'simulado', '3', '16', 'Clínica Médica', 'Mieloma múltiplo', 'Difícil', null, null, 'Paciente de 68 anos apresenta dor óssea lombar persistente, fadiga e episódios de infecção recorrente, associados a anemia normocítica e função renal em declínio progressivo. Eletroforese de proteínas séricas mostra pico monoclonal (componente M). Radiografia de crânio mostra lesões líticas múltiplas (''em saca-bocado'').

A hipótese diagnóstica mais provável e a conduta são', 'Metástase óssea de origem indeterminada; iniciar quimioterapia empírica imediata sem outra investigação', 'Mieloma múltiplo; encaminhar para avaliação hematológica especializada para confirmação (mielograma, cadeias leves) e definição terapêutica', 'Infecção óssea crônica; iniciar antibioticoterapia prolongada isolada', 'Osteoporose senil isolada; iniciar apenas suplementação de cálcio e vitamina D', 'B', 'Dor óssea, anemia, insuficiência renal, pico monoclonal e lesões líticas (''em saca-bocado'') compõem o quadro clássico de mieloma múltiplo; a conduta é encaminhar para avaliação hematológica especializada para confirmação diagnóstica completa e definição terapêutica.', 'A: o padrão de achados (pico monoclonal, lesões líticas múltiplas) é mais específico de mieloma múltiplo do que de metástase de origem indeterminada, merecendo investigação hematológica dirigida. C: o padrão de lesões e achados sistêmicos não é compatível com infecção óssea isolada. D: osteoporose isolada não explica o pico monoclonal, a insuficiência renal nem as lesões líticas múltiplas específicas.', 'Em revisão', null, null, null),
  ('SIM3-017', 'simulado', '3', '17', 'Clínica Médica', 'Síndrome de lise tumoral', 'Difícil', null, null, 'Paciente com diagnóstico recente de linfoma de alto grau inicia quimioterapia de indução e, 24 horas depois, evolui com náuseas, letargia e arritmia cardíaca. Exames mostram hipercalemia, hiperfosfatemia, hiperuricemia e hipocalcemia, associadas a piora da função renal.

A hipótese diagnóstica mais provável e a conduta são', 'Síndrome da veia cava superior; iniciar radioterapia de urgência isolada', 'Reação alérgica à quimioterapia; suspender definitivamente o tratamento oncológico', 'Síndrome de lise tumoral; hidratação vigorosa, correção dos distúrbios eletrolíticos e uso de agente hipouricemiante (rasburicase ou alopurinol)', 'Insuficiência renal aguda por nefrotoxicidade isolada; suspender apenas a hidratação venosa', 'C', 'O conjunto de distúrbios eletrolíticos (hipercalemia, hiperfosfatemia, hiperuricemia, hipocalcemia) após início de quimioterapia em neoplasia de alto grau e alta carga tumoral é característico de síndrome de lise tumoral; o tratamento envolve hidratação vigorosa, correção eletrolítica e agente hipouricemiante.', 'A: o quadro descrito não é compatível com síndrome da veia cava superior. B: os achados laboratoriais específicos apontam para lise tumoral, não para reação alérgica. D: a hidratação venosa é parte essencial do tratamento, não devendo ser suspensa; a insuficiência renal aqui é decorrente da lise tumoral, não de nefrotoxicidade isolada.', 'Em revisão', null, null, null),
  ('SIM3-018', 'simulado', '3', '18', 'Clínica Médica', 'Doença de Wilson', 'Difícil', null, null, 'Paciente de 22 anos apresenta alterações de comportamento, tremor e disartria progressivos há 8 meses, associados a elevação de transaminases identificada em exame de rotina. Exame oftalmológico com lâmpada de fenda revela anel de Kayser-Fleischer. Ceruloplasmina sérica reduzida.

A hipótese diagnóstica mais provável e a conduta são', 'Hepatite autoimune isolada; iniciar corticoterapia sem necessidade de outra investigação', 'Esclerose múltipla; iniciar imunomodulador específico para a doença', 'Doença de Parkinson; iniciar levodopa/carbidopa como primeira linha', 'Doença de Wilson; iniciar quelante de cobre (ex: D-penicilamina ou trientina) e restrição dietética de alimentos ricos em cobre', 'D', 'Sintomas neurológicos (tremor, disartria) associados a alteração hepática, anel de Kayser-Fleischer e ceruloplasmina baixa em paciente jovem confirmam doença de Wilson; o tratamento é quelante de cobre associado a restrição dietética.', 'A: hepatite autoimune não explica os achados neurológicos nem o anel característico. B: esclerose múltipla não explica o comprometimento hepático nem os achados oftalmológicos descritos. C: Parkinson não explica a alteração hepática associada nem o anel de Kayser-Fleischer.', 'Em revisão', null, null, null),
  ('SIM3-019', 'simulado', '3', '19', 'Clínica Médica', 'Hipertensão pulmonar', 'Difícil', null, null, 'Paciente de 45 anos, com diagnóstico prévio de esclerose sistêmica, apresenta dispneia progressiva aos esforços há 6 meses, sem outra causa aparente. Ecocardiograma mostra sinais indiretos de hipertensão pulmonar, com função ventricular esquerda preservada. Cateterismo cardíaco direito confirma pressão de artéria pulmonar elevada.

A conduta mais adequada é', 'Indicar transplante pulmonar imediato como única conduta possível nesse momento', 'Tratar apenas com diurético isolado, sem necessidade de terapia específica para hipertensão pulmonar', 'Encaminhar para centro especializado em hipertensão pulmonar para tratamento específico (vasodilatadores pulmonares) e acompanhamento multidisciplinar', 'Tranquilizar o paciente, pois dispneia em esclerose sistêmica é sempre de causa musculoesquelética benigna', 'C', 'Hipertensão pulmonar associada à esclerose sistêmica, confirmada por cateterismo, exige encaminhamento a centro especializado para tratamento específico com vasodilatadores pulmonares e acompanhamento multidisciplinar, dada a gravidade e complexidade da condição.', 'A: transplante é considerado em casos refratários avançados, não como conduta inicial imediata. B: diurético isolado não trata especificamente a hipertensão pulmonar, sendo apenas medida coadjuvante para congestão. D: a confirmação por cateterismo estabelece causa cardiopulmonar específica, não devendo ser minimizada como causa musculoesquelética.', 'Em revisão', null, null, null),
  ('SIM3-020', 'simulado', '3', '20', 'Clínica Médica', 'Síndrome de Cushing induzida por corticoide exógeno', 'Médio', null, null, 'Paciente de 50 anos, em uso crônico de prednisona (20mg/dia há 8 meses) para doença reumatológica, apresenta ganho de peso centrípeto, face em lua cheia e fraqueza muscular proximal progressivos.

A conduta mais adequada é', 'Aumentar a dose de corticoide, pois os sintomas indicam controle inadequado da doença de base', 'Avaliar a possibilidade de redução gradual da dose de corticoide (nunca suspensão abrupta) em conjunto com o especialista responsável pela doença de base, e monitorar complicações', 'Iniciar cetoconazol para bloquear a produção endógena de cortisol, já suprimida pelo uso exógeno', 'Suspender o corticoide abruptamente, sem necessidade de desmame gradual', 'B', 'Síndrome de Cushing por uso crônico de corticoide exógeno deve ser manejada com redução gradual da dose, nunca suspensão abrupta (risco de insuficiência adrenal por supressão do eixo hipotálamo-hipófise-adrenal), em conjunto com a especialidade responsável pela doença de base.', 'A: os sintomas descritos são efeitos colaterais do próprio corticoide, não sinais de controle inadequado da doença de base. C: cetoconazol bloqueia produção endógena de cortisol, que já está suprimida pelo uso exógeno; essa não é a conduta indicada nesse contexto. D: suspensão abrupta de corticoide após uso prolongado pode causar insuficiência adrenal aguda grave.', 'Em revisão', null, null, null),
  ('SIM3-021', 'simulado', '3', '21', 'Clínica Médica', 'Anemia de doença crônica', 'Médio', null, null, 'Paciente de 60 anos, com artrite reumatoide ativa há vários anos, apresenta anemia leve a moderada persistente. Exames mostram ferro sérico baixo, ferritina normal-alta, capacidade total de ligação do ferro reduzida, e VCM normal ou discretamente reduzido.

O diagnóstico mais provável e a conduta são', 'Anemia megaloblástica; iniciar reposição de vitamina B12 parenteral', 'Anemia de doença crônica; tratar a doença de base (artrite reumatoide) e reavaliar a anemia, sem necessidade de suplementação de ferro na maioria dos casos', 'Talassemia menor; iniciar transfusão sanguínea de rotina', 'Anemia ferropriva; iniciar suplementação de ferro oral em altas doses imediatamente', 'B', 'Ferro baixo com ferritina normal-alta (diferente da ferropenia clássica, onde a ferritina estaria baixa) e capacidade de ligação do ferro reduzida são característicos de anemia de doença crônica, associada a doenças inflamatórias como artrite reumatoide; a conduta é tratar a doença de base.', 'A: não há dados sugestivos de macrocitose ou deficiência de B12 no caso. C: o quadro não é sugestivo de talassemia, que teria outras características laboratoriais e história familiar. D: na anemia ferropriva verdadeira a ferritina estaria baixa, diferente do padrão descrito (ferritina normal-alta); suplementação de ferro tem benefício limitado na anemia de doença crônica pura.', 'Em revisão', null, null, null),
  ('SIM3-022', 'simulado', '3', '22', 'Clínica Médica', 'Pneumonia atípica (Mycoplasma)', 'Médio', null, null, 'Paciente de 25 anos, previamente hígido, apresenta tosse seca persistente, febre baixa e mal-estar há 10 dias, de evolução arrastada, sem melhora com medidas sintomáticas. Ausculta pulmonar discreta, desproporcional aos achados radiográficos, que mostram infiltrado intersticial difuso bilateral.

A hipótese diagnóstica mais provável e a conduta são', 'Pneumonia bacteriana típica por pneumococo; iniciar amoxicilina em dose padrão', 'Pneumonia atípica por Mycoplasma pneumoniae; iniciar macrolídeo como tratamento de escolha', 'Embolia pulmonar; iniciar anticoagulação plena empírica', 'Tuberculose pulmonar; iniciar esquema RIPE imediatamente, sem confirmação bacteriológica', 'B', 'Quadro arrastado, com tosse seca persistente e achados radiográficos desproporcionais ao exame físico (dissociação clínico-radiológica), em paciente jovem, é sugestivo de pneumonia atípica por Mycoplasma; o tratamento de escolha são os macrolídeos.', 'A: pneumonia pneumocócica típica costuma ter apresentação mais aguda e exame físico mais exuberante, correlacionado com a radiografia. C: não há dados clínicos sugestivos de embolia pulmonar (fatores de risco, dor pleurítica súbita) no caso. D: o quadro não tem os elementos típicos de apresentação de tuberculose (evolução mais prolongada, sintomas constitucionais mais marcantes) para justificar tratamento empírico sem confirmação.', 'Em revisão', null, null, null),
  ('SIM3-023', 'simulado', '3', '23', 'Clínica Médica', 'Derrame pleural - abordagem diagnóstica', 'Médio', null, null, 'Paciente de 55 anos apresenta dispneia progressiva e dor torácica ventilatório-dependente há 1 semana. Radiografia de tórax mostra derrame pleural volumoso à direita. É realizada toracocentese diagnóstica.

A conduta mais adequada para caracterizar o derrame é', 'Iniciar antibioticoterapia empírica sem qualquer análise do líquido pleural', 'Indicar drenagem torácica em selo d''água para todos os casos de derrame pleural, independente da causa', 'Analisar o líquido pleural aplicando os critérios de Light (proteínas e LDH pleural/sérico) para diferenciar transudato de exsudato', 'Aguardar resolução espontânea do derrame, sem necessidade de qualquer investigação', 'C', 'A avaliação inicial de um derrame pleural de causa indeterminada é a toracocentese diagnóstica com aplicação dos critérios de Light, que diferenciam transudato de exsudato e orientam a investigação etiológica subsequente.', 'A: antibiótico empírico sem caracterizar a causa do derrame (que pode não ser infecciosa) não é conduta adequada. B: drenagem em selo d''água é reservada para casos específicos (empiema, derrame volumoso sintomático), não para todos os casos indiscriminadamente. D: um derrame pleural volumoso sintomático de causa indeterminada não deve ser deixado sem investigação.', 'Em revisão', null, null, null),
  ('SIM3-024', 'simulado', '3', '24', 'Clínica Médica', 'Tromboembolismo venoso - profilaxia hospitalar', 'Médio', null, null, 'Paciente de 68 anos é internado para tratamento clínico de pneumonia grave, com mobilidade reduzida esperada por vários dias, sem contraindicações identificadas para anticoagulação.

A conduta mais adequada em relação à profilaxia de tromboembolismo venoso é', 'Utilizar apenas meias de compressão, sem necessidade de avaliação de risco individualizada', 'Iniciar anticoagulação plena terapêutica de rotina em todos os pacientes internados', 'Não é necessária nenhuma profilaxia em pacientes clínicos internados, apenas em pós-operatórios', 'Avaliar o risco individual (ex: escore de Padua) e, se indicado, iniciar profilaxia farmacológica com heparina de baixo peso molecular ou não fracionada', 'D', 'Pacientes clínicos hospitalizados com mobilidade reduzida têm risco aumentado de tromboembolismo venoso; a conduta padrão é avaliar o risco individual por escore validado e, se indicado, iniciar profilaxia farmacológica apropriada.', 'A: meias de compressão são medida mecânica coadjuvante, mas a decisão deve ser individualizada conforme o risco, podendo necessitar de profilaxia farmacológica associada. B: anticoagulação plena terapêutica não é profilaxia de rotina, sendo reservada para tratamento de evento trombótico já estabelecido. C: pacientes clínicos internados também têm risco significativo de TEV e podem se beneficiar de profilaxia, não apenas pacientes cirúrgicos.', 'Em revisão', null, null, null),
  ('SIM3-025', 'simulado', '3', '25', 'Clínica Médica', 'Insuficiência respiratória aguda - ventilação mecânica', 'Difícil', null, null, 'Paciente de 60 anos, internado por pneumonia grave, evolui com piora progressiva da insuficiência respiratória, apesar de oxigenoterapia suplementar em alto fluxo, apresentando taquipneia importante, uso de musculatura acessória e rebaixamento do nível de consciência.

A conduta mais adequada é', 'Indicar intubação orotraqueal e ventilação mecânica invasiva, diante da falência respiratória progressiva e rebaixamento de consciência', 'Manter apenas oxigenoterapia em alto fluxo, aguardando melhora espontânea', 'Aguardar piora ainda maior antes de considerar qualquer suporte ventilatório avançado', 'Iniciar ventilação não invasiva como única conduta, mesmo diante de rebaixamento do nível de consciência', 'A', 'Falência respiratória progressiva com sinais de exaustão (uso de musculatura acessória) e rebaixamento do nível de consciência são indicações de intubação orotraqueal e ventilação mecânica invasiva, já que a via não invasiva é contraindicada nesse contexto de risco de broncoaspiração e falha respiratória iminente.', 'B: manter apenas a mesma oxigenoterapia sem escalonamento diante de sinais de falência respiratória progressiva expõe o paciente a risco de parada respiratória. C: aguardar piora ainda maior atrasa uma intervenção necessária e aumenta o risco de desfecho grave. D: ventilação não invasiva é contraindicada em pacientes com rebaixamento importante do nível de consciência, pelo risco de broncoaspiração.', 'Em revisão', null, null, null),
  ('SIM3-026', 'simulado', '3', '26', 'Clínica Médica', 'Doença de Behçet', 'Difícil', null, null, 'Paciente de 30 anos apresenta úlceras orais recorrentes e dolorosas, associadas a úlceras genitais recorrentes e episódios de uveíte, há 1 ano. Refere também lesões cutâneas semelhantes a eritema nodoso em pernas.

A hipótese diagnóstica mais provável é', 'Pênfigo vulgar', 'Síndrome de Sjögren', 'Herpes simples recorrente isolado', 'Doença de Behçet', 'D', 'A combinação de úlceras orais recorrentes, úlceras genitais recorrentes, uveíte e lesões cutâneas tipo eritema nodoso é característica da doença de Behçet, vasculite sistêmica de causa multifatorial.', 'A: pênfigo vulgar cursa com bolhas cutâneas e mucosas, não com o padrão específico descrito de úlceras orais/genitais recorrentes associadas a uveíte. B: síndrome de Sjögren cursa predominantemente com xeroftalmia/xerostomia, não com esse padrão de úlceras recorrentes e uveíte. C: herpes simples isolado não explicaria o conjunto de manifestações sistêmicas (uveíte, lesões cutâneas) descritas.', 'Em revisão', null, null, null),
  ('SIM3-027', 'simulado', '3', '27', 'Clínica Médica', 'Rabdomiólise', 'Médio', null, null, 'Paciente de 40 anos é trazido ao PS após ficar preso sob escombros por várias horas, com lesão por esmagamento em membro inferior. Ao exame, urina de coloração escura (avermelhada/marrom). Exames mostram CPK muito elevada e função renal em declínio.

A conduta mais adequada é', 'Restringir líquidos para evitar sobrecarga volêmica no contexto de lesão renal', 'Hidratação venosa vigorosa para manter diurese adequada, com monitorização da função renal e correção de distúrbios eletrolíticos associados', 'Iniciar diálise imediata em todos os casos, independente da função renal atual', 'Tratar apenas as lesões musculoesqueléticas visíveis, sem necessidade de outras medidas', 'B', 'Rabdomiólise por lesão por esmagamento, com CPK elevada e urina escura (mioglobinúria), exige hidratação venosa vigorosa para manter diurese adequada e prevenir/limitar a lesão renal aguda, com monitorização de eletrólitos (risco de hipercalemia).', 'A: a hidratação vigorosa (não a restrição) é a conduta correta para proteger a função renal na rabdomiólise. C: diálise não é indicada rotineiramente para todos os casos, sendo reservada para complicações graves (hipercalemia refratária, insuficiência renal estabelecida). D: o risco sistêmico de lesão renal e distúrbios eletrolíticos exige monitorização e tratamento além das lesões musculoesqueléticas locais.', 'Em revisão', null, null, null),
  ('SIM3-028', 'simulado', '3', '28', 'Clínica Médica', 'Intoxicação exógena - manejo geral', 'Médio', null, null, 'Paciente de 22 anos é trazido ao PS por familiares após ingestão de quantidade desconhecida de medicamento em tentativa de autoextermínio, há 1 hora, consciente e estável hemodinamicamente no momento da avaliação.

A conduta inicial mais adequada é', 'Avaliação clínica completa, identificação da substância ingerida quando possível, contato com centro de informação toxicológica e medidas de descontaminação/suporte conforme indicado, além de avaliação psiquiátrica', 'Induzir vômito rotineiramente em todos os casos de intoxicação exógena, independente da substância', 'Aguardar o desenvolvimento de sintomas graves antes de qualquer intervenção', 'Tratar apenas os sintomas visíveis no momento, sem necessidade de avaliação psiquiátrica', 'A', 'O manejo de intoxicação exógena por tentativa de autoextermínio inclui avaliação clínica completa, identificação da substância, contato com centro de toxicologia para orientação específica, medidas de suporte/descontaminação conforme indicado e avaliação psiquiátrica obrigatória.', 'B: indução de vômito não é rotineiramente recomendada e pode ser contraindicada dependendo da substância ingerida (ex: corrosivos, risco de aspiração). C: aguardar sintomas graves atrasa intervenções que poderiam ser preventivas. D: avaliação psiquiátrica é essencial em toda tentativa de autoextermínio, não apenas o tratamento dos sintomas físicos.', 'Em revisão', null, null, null),
  ('SIM3-029', 'simulado', '3', '29', 'Ginecologia e Obstetrícia', 'Assistência ao recém-nascido em sala de parto', 'Médio', null, null, 'Recém-nascido a termo nasce de parto vaginal, com líquido amniótico claro, chorando vigorosamente e com boa tônus muscular ao nascer.

A conduta mais adequada nos primeiros minutos de vida é', 'Realizar clampeamento imediato do cordão umbilical em todos os casos, independente da vitalidade', 'Levar o recém-nascido imediatamente para mesa de reanimação, separando-o da mãe por rotina', 'Manter o recém-nascido junto à mãe, realizando os cuidados de rotina (secar, aquecer, clampeamento oportuno do cordão) sem necessidade de manobras de reanimação', 'Realizar aspiração de vias aéreas de rotina em todos os recém-nascidos, independentemente do estado clínico ao nascer', 'C', 'Recém-nascido a termo, com boa vitalidade ao nascer (chorando, bom tônus), não necessita de manobras de reanimação; a conduta é contato pele a pele com a mãe, secagem, aquecimento e clampeamento oportuno do cordão (após 1-3 minutos, se possível).', 'A: clampeamento oportuno (tardio) é recomendado para recém-nascidos vigorosos, trazendo benefícios hematológicos. B: recém-nascidos vigorosos devem ser mantidos com a mãe, não sendo necessária mesa de reanimação de rotina. D: aspiração de vias aéreas de rotina não é recomendada em recém-nascidos vigorosos, podendo causar reflexo vagal e bradicardia.', 'Em revisão', null, null, null),
  ('SIM3-030', 'simulado', '3', '30', 'Ginecologia e Obstetrícia', 'Assistência ao parto normal - episiotomia seletiva', 'Médio', null, null, 'Durante o segundo estágio do trabalho de parto de uma primigesta, a equipe obstétrica discute a necessidade de episiotomia, observando boa progressão do períneo e ausência de sinais de sofrimento fetal.

Segundo as evidências atuais e as recomendações da OMS, a conduta mais adequada é', 'Episiotomia de rotina em todas as primigestas, independentemente da progressão do parto', 'Proibição absoluta de episiotomia em qualquer circunstância do trabalho de parto', 'Episiotomia seletiva, realizada apenas quando houver indicação específica (ex: sofrimento fetal iminente, necessidade de abreviar o parto), não de rotina', 'Episiotomia de rotina em todos os partos vaginais, para prevenção de lacerações', 'C', 'As evidências atuais e as diretrizes da OMS recomendam episiotomia seletiva, reservada para situações com indicação específica, e não de rotina, pois a episiotomia rotineira não reduz complicações e pode aumentar a morbidade perineal.', 'A e D: episiotomia de rotina não é recomendada pelas evidências atuais, independente da paridade. B: episiotomia seletiva permanece indicada em situações específicas, não sendo proibida de forma absoluta.', 'Em revisão', null, null, null),
  ('SIM3-031', 'simulado', '3', '31', 'Ginecologia e Obstetrícia', 'Índice de Apgar - avaliação neonatal', 'Fácil', null, null, 'Recém-nascido, no primeiro minuto de vida, apresenta frequência cardíaca de 110bpm, choro fraco, alguma flexão de membros, careta à estimulação e cianose de extremidades com corpo rosado.

O índice de Apgar mais adequado para esse recém-nascido no primeiro minuto é', '7', '10', '3', '5', 'A', 'Considerando os critérios do Apgar: FC >100 (2 pontos), choro fraco/irregular (1 ponto), alguma flexão (1 ponto), careta à estimulação (1 ponto), cianose de extremidades com corpo rosado - acrocianose (1 ponto), totalizando 6-7 pontos, compatível com a alternativa correta.', 'B: 10 pontos exigiria todos os critérios em seu grau máximo (ex: choro forte, cor totalmente rosada), ausente aqui pela acrocianose e choro fraco. C: 3 pontos seria compatível com depressão neonatal significativa, incompatível com os achados relativamente favoráveis descritos (FC boa, algum tônus e reflexo presentes). D: o cálculo detalhado dos critérios não resulta em 5 pontos, dado o conjunto de achados descritos.', 'Em revisão', null, null, null),
  ('SIM3-032', 'simulado', '3', '32', 'Ginecologia e Obstetrícia', 'Vacinação na gestação', 'Fácil', null, null, 'Gestante de 24 semanas, sem contraindicações, comparece à UBS para atualização vacinal, sem registro de vacinas administradas durante a gestação atual.

Segundo o calendário vacinal da gestante, deve receber', 'Vacina dTpa (dupla adulto acelular, contra difteria, tétano e coqueluche) a partir da 20ª semana, e vacina contra influenza, conforme sazonalidade', 'Apenas vacina contra febre amarela, independente de outras recomendações', 'Apenas vacinas de vírus vivo atenuado, como tríplice viral, são recomendadas na gestação', 'Nenhuma vacina deve ser administrada durante a gestação, por risco ao feto', 'A', 'O calendário vacinal da gestante inclui dTpa a partir da 20ª semana (proteção contra coqueluche para o recém-nascido) e vacina contra influenza, sendo vacinas inativadas seguras na gestação.', 'B: febre amarela na gestação tem indicação restrita a situações de risco epidemiológico específico, não sendo a única vacina recomendada rotineiramente. C: vacinas de vírus vivo atenuado, como tríplice viral, são contraindicadas na gestação, ao contrário do afirmado. D: diversas vacinas inativadas são seguras e recomendadas na gestação.', 'Em revisão', null, null, null),
  ('SIM3-033', 'simulado', '3', '33', 'Ginecologia e Obstetrícia', 'Amenorreia primária', 'Difícil', null, null, 'Adolescente de 16 anos nunca menstruou. Apresenta desenvolvimento mamário normal (Tanner 4), mas ausência de pelos pubianos e axilares. Exame físico com genitália externa feminina normal. USG pélvica não identifica útero.

A hipótese diagnóstica mais provável é', 'Síndrome de insensibilidade androgênica completa', 'Síndrome de Turner', 'Himen imperfurado', 'Hipogonadismo hipogonadotrófico isolado', 'A', 'Desenvolvimento mamário normal (por aromatização periférica de testosterona), ausência de pelos pubianos/axilares (dependentes de androgênios) e ausência de útero (por ação do hormônio antimülleriano em indivíduo com cariótipo 46,XY) são característicos de síndrome de insensibilidade androgênica completa.', 'B: síndrome de Turner cursa com baixa estatura e desenvolvimento mamário ausente ou incompleto (disgenesia gonadal), diferente do quadro com mamas normais. C: himen imperfurado cursaria com útero presente e sintomas de retenção menstrual (dor cíclica), não ausência uterina à USG. D: hipogonadismo hipogonadotrófico não explicaria a ausência de útero.', 'Em revisão', null, null, null),
  ('SIM3-034', 'simulado', '3', '34', 'Ginecologia e Obstetrícia', 'Dismenorreia', 'Fácil', null, null, 'Adolescente de 15 anos relata dor pélvica em cólica, iniciada 1-2 dias antes da menstruação e persistindo nos primeiros dias do fluxo, há cerca de 1 ano desde a menarca. Exame ginecológico sem alterações. Nega outros sintomas associados.

A conduta mais adequada é', 'Tranquilizar a paciente sem qualquer orientação, pois dismenorreia nunca deve ser tratada', 'Indicar histerectomia como tratamento definitivo', 'Solicitar laparoscopia diagnóstica obrigatória antes de qualquer tratamento', 'Diagnóstico de dismenorreia primária; orientar anti-inflamatório não esteroide e considerar anticoncepcional hormonal se necessário', 'D', 'Dismenorreia associada ao ciclo menstrual, sem outros achados sugestivos de causa secundária, em adolescente com exame normal, é compatível com dismenorreia primária; o tratamento inicial é AINE, com anticoncepcional hormonal como opção adicional.', 'A: dismenorreia sintomática tem tratamento eficaz disponível e deve ser oferecido. B: histerectomia é conduta desproporcional para dismenorreia em adolescente. C: laparoscopia não é exame de primeira linha para dismenorreia primária típica, sendo reservada para suspeita de causas secundárias refratárias ao tratamento inicial.', 'Em revisão', null, null, null),
  ('SIM3-035', 'simulado', '3', '35', 'Ginecologia e Obstetrícia', 'Síndrome pré-menstrual', 'Fácil', null, null, 'Mulher de 28 anos relata irritabilidade, inchaço, mastalgia e alterações de humor recorrentes na semana que antecede a menstruação, com melhora completa após o início do fluxo menstrual, há vários ciclos, afetando moderadamente sua qualidade de vida.

A conduta mais adequada é', 'Orientar mudanças no estilo de vida (exercício, dieta) e considerar tratamento medicamentoso (ex: ISRS ou anticoncepcional hormonal) conforme intensidade dos sintomas', 'Iniciar antipsicótico em dose plena como primeira linha de tratamento', 'Tranquilizar a paciente, pois síndrome pré-menstrual nunca deve ser tratada', 'Indicar histerectomia com ooforectomia bilateral como primeira conduta', 'A', 'Sintomas cíclicos relacionados à fase lútea, com melhora após a menstruação, são característicos de síndrome pré-menstrual; o tratamento inicial inclui mudanças de estilo de vida e, conforme intensidade, tratamento medicamentoso (ISRS, anticoncepcional hormonal).', 'B: antipsicóticos não são primeira linha para síndrome pré-menstrual. C: sintomas com impacto na qualidade de vida têm tratamentos eficazes disponíveis e devem ser oferecidos. D: cirurgia radical é conduta desproporcional para síndrome pré-menstrual, reservada para casos extremamente refratários e específicos.', 'Em revisão', null, null, null),
  ('SIM3-036', 'simulado', '3', '36', 'Ginecologia e Obstetrícia', 'Câncer de vulva', 'Difícil', null, null, 'Mulher de 68 anos apresenta lesão ulcerada, de bordas irregulares, em grande lábio direito, com prurido vulvar crônico prévio há vários anos, não investigado. Biópsia da lesão confirma carcinoma epidermoide de vulva.

A conduta mais adequada é', 'Encaminhar para avaliação oncológica ginecológica especializada para estadiamento e planejamento cirúrgico', 'Prescrever antifúngico tópico, assumindo causa infecciosa isolada', 'Indicar apenas acompanhamento clínico, sem necessidade de intervenção', 'Iniciar apenas corticoide tópico para o prurido, sem necessidade de tratamento oncológico', 'A', 'Confirmado o diagnóstico histológico de carcinoma epidermoide de vulva, a conduta é encaminhamento para avaliação oncológica especializada, visando estadiamento adequado e planejamento do tratamento cirúrgico e/ou complementar.', 'B: a biópsia já confirmou etiologia maligna, não infecciosa, não sendo apropriado tratar como causa fúngica. C: câncer confirmado não deve ser conduzido apenas com observação, exigindo tratamento ativo. D: corticoide tópico não trata a neoplasia maligna já confirmada por biópsia.', 'Em revisão', null, null, null),
  ('SIM3-037', 'simulado', '3', '37', 'Ginecologia e Obstetrícia', 'Câncer de colo uterino - estadiamento avançado', 'Difícil', null, null, 'Mulher de 50 anos apresenta sangramento vaginal pós-coital recorrente e corrimento fétido há 4 meses. Exame especular mostra lesão vegetante e friável em colo uterino, medindo aproximadamente 5cm, com biópsia confirmando carcinoma epidermoide invasor. Exame de imagem sugere invasão de paramétrios.

A conduta mais adequada é', 'Iniciar apenas antibioticoterapia para o corrimento, sem investigação oncológica adicional', 'Realizar apenas conização do colo uterino como tratamento definitivo', 'Indicar histerectomia simples isolada, sem necessidade de outros tratamentos', 'Encaminhar para centro oncológico especializado para estadiamento completo e definição do tratamento (radioterapia associada a quimioterapia, conforme estadiamento)', 'D', 'Câncer de colo uterino com invasão de paramétrios já confirmada representa estádio localmente avançado, cujo tratamento padrão envolve radioterapia associada a quimioterapia (não cirurgia isolada), definido em centro especializado após estadiamento completo.', 'A: o corrimento é secundário à lesão neoplásica; tratar apenas com antibiótico ignora a doença de base grave. B: conização é procedimento para lesões pré-invasoras ou microinvasoras iniciais, inadequado para doença invasora avançada. C: histerectomia simples isolada não é adequada para doença localmente avançada com invasão parametrial, que tem tratamento não cirúrgico como padrão nesse estádio.', 'Em revisão', null, null, null),
  ('SIM3-038', 'simulado', '3', '38', 'Ginecologia e Obstetrícia', 'Infertilidade conjugal - investigação inicial', 'Médio', null, null, 'Casal procura atendimento por infertilidade após 14 meses de tentativas regulares sem uso de contracepção, sem gestação. A mulher tem 29 anos, ciclos menstruais regulares; o homem, 31 anos, sem comorbidades conhecidas.

A conduta inicial mais adequada para investigação é', 'Indicar fertilização in vitro diretamente, sem investigação prévia do casal', 'Aguardar mais 2 anos de tentativas antes de iniciar qualquer investigação', 'Investigar apenas a mulher, pois infertilidade é predominantemente um problema feminino', 'Iniciar investigação básica de ambos os parceiros simultaneamente (espermograma para o homem, avaliação hormonal/ovulatória e de permeabilidade tubária para a mulher)', 'D', 'Infertilidade após 12 meses de tentativas regulares (tempo padrão para investigação, considerando a idade da mulher) justifica investigação simultânea de ambos os parceiros, já que fatores masculinos e femininos contribuem de forma semelhante para a infertilidade conjugal.', 'A: tratamentos de reprodução assistida mais complexos devem ser considerados após investigação e tentativas de tratamentos mais simples, conforme a causa identificada. B: o tempo de tentativas já ultrapassa o critério padrão para início da investigação (12 meses, ou antes se fatores de risco). C: fatores masculinos contribuem para cerca de metade dos casos de infertilidade conjugal, devendo ser investigados desde o início.', 'Em revisão', null, null, null),
  ('SIM3-039', 'simulado', '3', '39', 'Ginecologia e Obstetrícia', 'Assistência ao puerpério imediato', 'Fácil', null, null, 'Puérpera, 2 horas após parto vaginal sem intercorrências, está em observação na sala de recuperação pós-parto.

A conduta de vigilância mais adequada nesse período inclui', 'Monitorização exclusiva da temperatura corporal, sem necessidade de avaliar outros parâmetros', 'Monitorização de sinais vitais, avaliação do tônus uterino (globo de segurança de Pinard) e do sangramento vaginal em intervalos regulares', 'Alta hospitalar imediata, sem necessidade de qualquer período de observação', 'Sedação de rotina para todas as puérperas nesse período, independente de sintomas', 'B', 'O período de 2 horas após o parto (quarto período do parto/Greenberg) é crítico para hemorragia pós-parto; a vigilância inclui sinais vitais, avaliação do tônus uterino e sangramento vaginal em intervalos regulares.', 'A: monitorização restrita à temperatura não identifica adequadamente sinais de hemorragia ou atonia uterina. C: alta imediata sem período de observação expõe a puérpera a risco não identificado de hemorragia pós-parto tardia nesse período crítico. D: sedação de rotina não é indicada nem necessária para todas as puérperas nesse período.', 'Em revisão', null, null, null),
  ('SIM3-040', 'simulado', '3', '40', 'Ginecologia e Obstetrícia', 'Gravidez na adolescência - abordagem', 'Médio', null, null, 'Adolescente de 15 anos, acompanhada da mãe, comparece à UBS com resultado de teste de gravidez positivo, confirmando gestação de 8 semanas. Relata namoro com adolescente de 16 anos.

A conduta mais adequada é', 'Recusar o acompanhamento pré-natal até que a situação seja esclarecida por autoridade competente', 'Acolher a adolescente, iniciar o pré-natal, avaliar a rede de apoio familiar/social e investigar sinais de vulnerabilidade, sem necessidade de comunicação obrigatória às autoridades nesse contexto de relação entre adolescentes de idade próxima', 'Notificar obrigatoriamente à polícia como caso de estupro de vulnerável, independentemente do contexto relatado', 'Orientar interrupção da gestação como única conduta possível na adolescência', 'B', 'Gestação em adolescente com parceiro de idade próxima, em relação consentida, deve ser acolhida com início do pré-natal e avaliação da rede de apoio; a comunicação a autoridades depende da avaliação individualizada de sinais de vulnerabilidade e do contexto específico, não sendo automática apenas pela idade.', 'A: recusar o acompanhamento pré-natal prejudica a saúde da gestante adolescente e do feto. C: a comunicação automática e indiscriminada como estupro de vulnerável, sem avaliação do contexto individual, não é a conduta recomendada em situações de relação consentida entre adolescentes de idade próxima. D: a decisão sobre a gestação cabe à gestante, dentro dos limites legais, não sendo imposta pelo profissional de saúde.', 'Em revisão', null, null, null),
  ('SIM3-041', 'simulado', '3', '41', 'Ginecologia e Obstetrícia', 'Câncer de mama - estadiamento inicial', 'Médio', null, null, 'Mulher de 52 anos identifica nódulo mamário palpável, e a investigação com mamografia e biópsia confirma carcinoma ductal invasivo, medindo 2,5cm, sem linfonodos palpáveis na axila.

A conduta mais adequada após a confirmação diagnóstica é', 'Indicar apenas acompanhamento clínico semestral, sem tratamento ativo', 'Realizar mastectomia bilateral de urgência, sem avaliação multidisciplinar prévia', 'Encaminhar para avaliação oncológica multidisciplinar para estadiamento completo e planejamento terapêutico (cirúrgico, sistêmico e/ou radioterápico)', 'Iniciar quimioterapia isolada, sem avaliação cirúrgica ou estadiamento adicional', 'C', 'Confirmado o câncer de mama, a conduta padrão é encaminhamento para avaliação oncológica multidisciplinar, que define o estadiamento completo e planeja a estratégia terapêutica mais adequada (cirurgia, quimioterapia, radioterapia, terapia-alvo, conforme o caso).', 'A: câncer confirmado exige tratamento ativo, não apenas observação. B: mastectomia bilateral não é conduta padrão sem avaliação multidisciplinar completa e discussão de alternativas com a paciente. D: a decisão terapêutica deve ser multidisciplinar e considerar todas as modalidades, não isolada em quimioterapia sem avaliação cirúrgica.', 'Em revisão', null, null, null),
  ('SIM3-042', 'simulado', '3', '42', 'Ginecologia e Obstetrícia', 'Assistência ao parto - distócia de ombro', 'Difícil', null, null, 'Durante parto vaginal de recém-nascido macrossômico, após o desprendimento cefálico, observa-se retração da cabeça fetal contra o períneo (''sinal da tartaruga''), com dificuldade na liberação dos ombros.

A conduta mais adequada é', 'Realizar cesariana de urgência, mesmo com a cabeça fetal já exteriorizada', 'Aguardar passivamente a resolução espontânea, sem qualquer manobra específica', 'Reconhecer a distócia de ombro e realizar manobras específicas (ex: McRoberts, pressão suprapúbica), evitando tração excessiva da cabeça fetal', 'Aplicar tração forte e imediata na cabeça fetal para liberar os ombros rapidamente', 'C', 'O sinal da tartaruga indica distócia de ombro, emergência obstétrica; a conduta é reconhecer rapidamente a situação e aplicar manobras específicas (McRoberts, pressão suprapúbica, entre outras), evitando tração excessiva da cabeça fetal, que pode causar lesão de plexo braquial.', 'A: cesariana não é possível com a cabeça fetal já exteriorizada; a resolução deve ser por manobras obstétricas específicas. B: distócia de ombro é emergência com risco de hipóxia fetal e lesões, não devendo ser conduzida passivamente. D: tração excessiva da cabeça fetal na distócia de ombro está associada a lesões graves, como paralisia de plexo braquial.', 'Em revisão', null, null, null),
  ('SIM3-043', 'simulado', '3', '43', 'Ginecologia e Obstetrícia', 'Assistência pré-natal - vitalidade fetal no termo', 'Médio', null, null, 'Gestante de 41 semanas, pré-natal de baixo risco, comparece à consulta de rotina. Exame físico e cardiotocografia dentro da normalidade, movimentos fetais presentes.

A conduta mais adequada nesse momento é', 'Intensificar a vigilância da vitalidade fetal (cardiotocografia e perfil biofísico seriados) e programar indução do parto até 42 semanas, se o parto não ocorrer espontaneamente antes', 'Não é necessária nenhuma vigilância adicional além da consulta de rotina padrão', 'Aguardar até 44 semanas sem qualquer conduta adicional, mesmo sem sinais de trabalho de parto', 'Indicar cesariana eletiva imediata, apenas pelo fato de ter ultrapassado a data provável do parto', 'A', 'Gestação que se aproxima ou ultrapassa 41 semanas exige vigilância intensificada da vitalidade fetal, com programação de indução do parto até 42 semanas (limite recomendado), pelo aumento do risco de complicações associadas à gestação pós-termo.', 'B: gestação além de 41 semanas exige vigilância intensificada, diferente da rotina padrão anterior a esse ponto. C: aguardar até 44 semanas sem conduta adicional expõe a gestante e o feto a riscos aumentados associados à pós-maturidade, além de ultrapassar os limites recomendados pelas diretrizes. D: cesariana eletiva não é indicada apenas pela idade gestacional avançada, na ausência de outras indicações obstétricas.', 'Em revisão', null, null, null),
  ('SIM3-044', 'simulado', '3', '44', 'Ginecologia e Obstetrícia', 'Anticoncepção hormonal - critérios de elegibilidade', 'Difícil', null, null, 'Mulher de 35 anos, tabagista (20 cigarros/dia), procura orientação contraceptiva. Nega outras comorbidades.

Considerando os critérios de elegibilidade da OMS, a conduta mais adequada é', 'Liberar o uso de anticoncepcional oral combinado sem qualquer restrição, independente do tabagismo', 'Contraindicar o uso de anticoncepcional oral combinado, pela associação entre tabagismo em mulher acima de 35 anos e risco cardiovascular/trombótico aumentado, oferecendo métodos apenas de progestagênio ou não hormonais', 'Indicar apenas laqueadura tubária como única opção contraceptiva disponível', 'Contraindicar todos os métodos contraceptivos hormonais, incluindo os de progestagênio isolado', 'B', 'Segundo os critérios de elegibilidade da OMS, tabagismo em mulher com 35 anos ou mais é contraindicação para uso de anticoncepcional oral combinado (risco cardiovascular/trombótico), sendo mais adequados métodos apenas de progestagênio ou não hormonais.', 'A: a combinação de idade ≥35 anos e tabagismo é contraindicação reconhecida para uso de estrogênio em contracepção. C: laqueadura é método definitivo, não sendo a única opção reversível disponível para essa paciente. D: métodos apenas de progestagênio não têm a mesma contraindicação relacionada ao tabagismo associado a estrogênio.', 'Em revisão', null, null, null),
  ('SIM3-045', 'simulado', '3', '45', 'Ginecologia e Obstetrícia', 'Doença trofoblástica gestacional - seguimento pós-molar', 'Difícil', null, null, 'Paciente realizou esvaziamento uterino por mola hidatiforme há 8 semanas, mantendo seguimento com beta-hCG semanal. Na última dosagem, houve aumento inesperado do beta-hCG após duas semanas consecutivas de queda.

A conduta mais adequada é', 'Suspender o seguimento com beta-hCG, considerando o caso resolvido', 'Repetir o esvaziamento uterino imediatamente, sem outra investigação', 'Investigar doença trofoblástica gestacional persistente/maligna, com avaliação de imagem e encaminhamento para tratamento quimioterápico se confirmada', 'Tranquilizar a paciente, pois pequenas variações do beta-hCG durante o seguimento são sempre irrelevantes', 'C', 'Aumento do beta-hCG durante o seguimento pós-molar, após período de queda, é sinal de alerta para doença trofoblástica gestacional persistente ou maligna (mola invasora, coriocarcinoma), exigindo investigação e tratamento quimioterápico conforme confirmação.', 'A: suspender o seguimento diante de um achado alterado é inadequado e arriscado. B: novo esvaziamento uterino não é a conduta padrão diante desse achado, sendo necessária investigação antes de definir tratamento. D: um aumento inesperado do beta-hCG durante o seguimento padronizado não deve ser ignorado, sendo critério de alerta estabelecido para doença persistente.', 'Em revisão', null, null, null),
  ('SIM3-046', 'simulado', '3', '46', 'Ginecologia e Obstetrícia', 'Síndrome HELLP', 'Difícil', null, null, 'Gestante de 34 semanas, com diagnóstico prévio de pré-eclâmpsia, apresenta dor epigástrica intensa, náuseas e mal-estar geral há algumas horas. Exames mostram anemia hemolítica microangiopática, elevação importante de transaminases e plaquetopenia significativa.

A hipótese diagnóstica mais provável e a conduta são', 'Síndrome HELLP; estabilização materna e interrupção da gestação, independentemente da idade gestacional, dada a gravidade do quadro', 'Esteatose hepática aguda da gestação isolada; apenas suporte nutricional, sem necessidade de interrupção da gestação', 'Gastrite aguda; iniciar apenas inibidor de bomba de prótons, sem outra conduta', 'Hepatite viral aguda; apenas suporte clínico, mantendo a gestação até o termo', 'A', 'Hemólise, elevação de enzimas hepáticas e plaquetopenia (HELLP) em gestante com pré-eclâmpsia são diagnósticas de síndrome HELLP, complicação grave que exige estabilização materna e interrupção da gestação independente da idade gestacional, pelo risco de complicações maternas graves.', 'B: o quadro laboratorial específico (hemólise, plaquetopenia, elevação de transaminases) é mais característico de HELLP do que de esteatose hepática aguda isolada, e a conduta de interrupção também se aplicaria a esta última em quadro grave. C: gastrite não explica os achados laboratoriais sistêmicos descritos (hemólise, plaquetopenia). D: o contexto de pré-eclâmpsia associado aos achados laboratoriais específicos aponta para HELLP, não hepatite viral isolada; a gestação não deve ser mantida diante da gravidade do quadro.', 'Em revisão', null, null, null),
  ('SIM3-047', 'simulado', '3', '47', 'Ginecologia e Obstetrícia', 'Câncer de mama - lesão palpável em jovem', 'Médio', null, null, 'Mulher de 32 anos identifica nódulo mamário palpável, móvel, de contornos regulares, medindo 2cm, sem sinais inflamatórios. USG de mamas mostra nódulo sólido, ovalado, com contornos regulares e paralelo à pele, classificado como BI-RADS 3.

A conduta mais adequada é', 'Indicar mastectomia imediata, independente da classificação de baixo risco', 'Tranquilizar a paciente definitivamente, sem necessidade de qualquer seguimento adicional', 'Iniciar quimioterapia empírica, sem confirmação histológica prévia', 'Seguimento com USG de mamas em 6 meses para reavaliação do nódulo, dado o baixo risco de malignidade da classificação', 'D', 'Nódulo mamário com características ultrassonográficas benignas, classificado como BI-RADS 3 (risco de malignidade muito baixo, <2%), tem indicação de seguimento com USG em 6 meses, ao invés de biópsia ou intervenção imediata.', 'A: cirurgia radical não é indicada para lesão de baixo risco de malignidade (BI-RADS 3) sem confirmação diagnóstica prévia. B: apesar do baixo risco, o seguimento é recomendado para confirmar a estabilidade da lesão, não a alta definitiva sem acompanhamento algum. C: quimioterapia não é indicada sem diagnóstico histológico confirmado de malignidade.', 'Em revisão', null, null, null),
  ('SIM3-048', 'simulado', '3', '48', 'Ginecologia e Obstetrícia', 'Corrimento genital em gestante', 'Médio', null, null, 'Gestante de 20 semanas relata corrimento vaginal amarelado, com odor forte, associado a prurido intenso, há 1 semana. Exame especular confirma corrimento abundante amarelo-esverdeado, com colo uterino hiperemiado (colo em framboesa). Exame a fresco mostra protozoário móvel flagelado.

O diagnóstico mais provável e o tratamento adequado na gestação são', 'Gonorreia; azitromicina isolada, sem necessidade de investigar outras IST', 'Vaginose bacteriana; apenas observação, sem necessidade de tratamento na gestação', 'Tricomoníase; metronidazol por via oral, seguro para uso na gestação', 'Candidíase vulvovaginal; apenas fluconazol oral em dose única', 'C', 'Corrimento amarelo-esverdeado, colo em framboesa e protozoário móvel flagelado ao exame a fresco confirmam tricomoníase; o metronidazol oral é considerado seguro para tratamento na gestação, sendo a conduta indicada.', 'A: os achados descritos não são específicos de gonorreia isoladamente; o exame a fresco com protozoário confirma tricomoníase. B: vaginose bacteriana não tratada na gestação está associada a maior risco de complicações obstétricas, devendo ser tratada quando sintomática. D: os achados descritos (protozoário flagelado, colo em framboesa) não são de candidíase, que mostraria hifas ao exame.', 'Em revisão', null, null, null),
  ('SIM3-049', 'simulado', '3', '49', 'Ginecologia e Obstetrícia', 'Câncer de colo uterino - rastreamento em gestante', 'Médio', null, null, 'Gestante de 16 semanas, sem histórico de exame preventivo prévio, comparece à primeira consulta de pré-natal, sem queixas ginecológicas.

A conduta mais adequada em relação ao rastreamento de câncer de colo uterino durante a gestação é', 'Realizar apenas colposcopia de rotina em todas as gestantes, independente de citologia prévia', 'Realizar a coleta de citologia oncótica durante o exame especular do pré-natal, já que a gestação não contraindica o procedimento quando indicado', 'Adiar completamente o rastreamento para depois do parto, pois é contraindicado durante toda a gestação', 'Não realizar nenhuma coleta durante o pré-natal, mesmo que a paciente nunca tenha feito o exame', 'B', 'A coleta de citologia oncótica pode e deve ser realizada durante a gestação quando indicada pelo histórico de rastreamento da paciente, sendo um procedimento seguro que não deve ser postergado apenas pela gestação.', 'A: colposcopia de rotina para todas as gestantes sem indicação prévia (citologia alterada) não é a conduta padrão. C: a coleta de citologia não é contraindicada durante a gestação, sendo procedimento seguro quando indicado. D: uma paciente sem rastreamento prévio se beneficia da oportunidade da consulta de pré-natal para realizar o exame.', 'Em revisão', null, null, null),
  ('SIM3-050', 'simulado', '3', '50', 'Cirurgia', 'Fratura de fêmur em idoso', 'Médio', null, null, 'Paciente de 82 anos, com osteoporose conhecida, sofre queda da própria altura em casa, evoluindo com dor intensa em quadril direito e incapacidade de deambular. Radiografia confirma fratura de colo de fêmur direito.

A conduta mais adequada é', 'Avaliação pré-operatória e correção cirúrgica precoce (idealmente nas primeiras 48 horas), associada a manejo multidisciplinar da fragilidade do idoso', 'Indicar apenas fisioterapia, sem necessidade de avaliação cirúrgica', 'Aguardar melhora espontânea da dor antes de considerar qualquer conduta', 'Tratamento conservador com repouso prolongado no leito, sem indicação cirúrgica', 'A', 'Fratura de colo de fêmur em idoso tem indicação de correção cirúrgica precoce (idealmente nas primeiras 48h), pois o tratamento conservador está associado a maior morbimortalidade (complicações do imobilismo); o manejo multidisciplinar da fragilidade melhora o desfecho.', 'B: fisioterapia isolada não trata a fratura, sendo parte da reabilitação após tratamento definitivo. C: atraso no tratamento cirúrgico está associado a pior prognóstico. D: tratamento conservador com repouso prolongado aumenta significativamente o risco de complicações (trombose, pneumonia, úlceras de pressão) em idosos.', 'Em revisão', null, null, null),
  ('SIM3-051', 'simulado', '3', '51', 'Cirurgia', 'Síndrome compartimental', 'Difícil', null, null, 'Paciente com fratura de tíbia imobilizada com gesso circular há 6 horas, apresenta dor desproporcional à lesão, que piora com a extensão passiva dos dedos, associada a parestesia progressiva no membro. Pulsos distais ainda palpáveis, porém diminuídos.

A conduta mais adequada é', 'Aumentar a dose de analgésico opioide, sem qualquer outra intervenção', 'Aguardar o desaparecimento completo dos pulsos antes de qualquer conduta', 'Manter o gesso e apenas elevar o membro, aguardando melhora espontânea da dor', 'Remoção imediata do gesso/qualquer constrição e reavaliação; se persistirem os sinais, medir a pressão compartimental e considerar fasciotomia de urgência', 'D', 'Dor desproporcional que piora com a extensão passiva, associada a parestesia, são sinais precoces de síndrome compartimental (a presença de pulsos não a exclui); a conduta é remover imediatamente qualquer constrição e reavaliar, considerando fasciotomia se os sinais persistirem.', 'A: mascarar a dor com opioide sem tratar a causa retarda o diagnóstico e agrava o prognóstico. B: aguardar o desaparecimento dos pulsos significa esperar um sinal tardio e já com dano estabelecido; a síndrome compartimental é diagnóstico clínico precoce, não deve esperar isquemia franca. C: manter o gesso perpetua a compressão e pode levar a lesão neuromuscular irreversível.', 'Em revisão', null, null, null),
  ('SIM3-052', 'simulado', '3', '52', 'Cirurgia', 'Luxação de ombro', 'Fácil', null, null, 'Paciente de 25 anos sofre queda durante prática esportiva, com trauma em ombro direito, evoluindo com dor intensa, deformidade visível (sinal da ''dragona'') e limitação total dos movimentos do braço. Radiografia confirma luxação glenoumeral anterior.

A conduta mais adequada é', 'Cirurgia de urgência como única opção terapêutica para luxação glenoumeral aguda', 'Redução da luxação sob analgesia/sedação adequada, seguida de imobilização e avaliação de lesões associadas', 'Iniciar apenas fisioterapia, sem realizar a redução da luxação', 'Aguardar redução espontânea sem qualquer intervenção médica', 'B', 'Luxação glenoumeral anterior confirmada tem indicação de redução (manobra específica) sob analgesia/sedação adequada, seguida de imobilização e avaliação de lesões associadas (neurovasculares, do manguito rotador).', 'A: cirurgia de urgência não é a primeira conduta para a maioria dos casos de luxação glenoumeral aguda, sendo a redução incruenta a conduta inicial. C: fisioterapia é parte da reabilitação após a redução, não substitui o procedimento de redução em si. D: luxações raramente reduzem espontaneamente e a demora aumenta o risco de complicações.', 'Em revisão', null, null, null),
  ('SIM3-053', 'simulado', '3', '53', 'Cirurgia', 'Lombalgia mecânica - avaliação cirúrgica', 'Médio', null, null, 'Paciente de 45 anos apresenta dor lombar com irradiação para membro inferior direito (padrão radicular em L5), associada a fraqueza para dorsiflexão do pé direito, iniciada há 2 dias após esforço físico. Ressonância magnética confirma hérnia discal L4-L5 com compressão radicular importante.

A conduta mais adequada é', 'Tratamento conservador isolado com analgesia e repouso, independente do déficit motor', 'Encaminhar para avaliação neurocirúrgica/ortopédica de urgência, dado o déficit motor progressivo associado à compressão radicular', 'Tranquilizar o paciente, pois dor lombar sempre tem resolução espontânea sem necessidade de avaliação especializada', 'Iniciar apenas fisioterapia, sem necessidade de avaliação cirúrgica diante do déficit motor', 'B', 'A presença de déficit motor (fraqueza para dorsiflexão) associado à compressão radicular confirmada por imagem é sinal de alerta que justifica avaliação especializada com urgência, diferente da lombalgia mecânica simples sem déficit neurológico.', 'A: déficit motor associado à compressão radicular significativa é indicação para avaliação especializada, não apenas tratamento conservador isolado. C: a presença de déficit neurológico é sinal de alerta que não deve ser minimizado. D: fisioterapia isolada não é suficiente diante de déficit motor com compressão radicular confirmada, sendo necessária avaliação especializada para definir conduta.', 'Em revisão', null, null, null),
  ('SIM3-054', 'simulado', '3', '54', 'Cirurgia', 'Abdome agudo hemorrágico - gravidez ectópica rota (avaliação cirúrgica)', 'Difícil', null, null, 'Cirurgião geral é acionado para avaliar mulher de 26 anos com dor abdominal aguda e choque hipovolêmico em pronto-socorro sem ginecologista disponível no momento. Beta-hCG positivo, USG com líquido livre abundante na cavidade e ausência de gestação intrauterina.

A conduta mais adequada do cirurgião nessa situação é', 'Recusar-se a intervir, por não ser da especialidade de ginecologia e obstetrícia', 'Transferir a paciente para outro serviço sem qualquer estabilização prévia', 'Estabilizar a paciente e realizar laparotomia de urgência para controle do sangramento, mesmo na ausência de ginecologista, dado o risco iminente de morte', 'Aguardar a chegada do ginecologista, independentemente do tempo necessário, mesmo com a paciente em choque', 'C', 'Em emergência com risco iminente de morte (choque hipovolêmico por provável gravidez ectópica rota) e ausência de especialista disponível, o princípio da urgência e do dever de socorro prevalece; o cirurgião geral deve estabilizar e intervir para controle do sangramento.', 'A: a gravidade e urgência da situação, associada à ausência de outro profissional disponível, justificam a intervenção pelo médico presente, dentro do dever de socorro. B: transferir sem estabilização prévia expõe a paciente a risco extremo durante o transporte. D: aguardar em uma situação de choque hemorrágico com risco iminente de morte pode ser fatal para a paciente.', 'Em revisão', null, null, null),
  ('SIM3-055', 'simulado', '3', '55', 'Cirurgia', 'Ferida por arma branca - avaliação cirúrgica', 'Difícil', null, null, 'Paciente de 28 anos chega ao PS com ferimento por arma branca em flanco esquerdo, estável hemodinamicamente, sem sinais de irritação peritoneal ao exame físico seriado, sem evisceração.

A conduta mais adequada é', 'Alta hospitalar imediata, sem qualquer período de observação', 'Realizar apenas sutura da lesão cutânea externa, sem avaliação da cavidade abdominal', 'Considerar conduta não operatória inicial com observação clínica seriada, exames de imagem complementares (TC) e reavaliação frequente', 'Indicar laparotomia exploradora obrigatória em todos os casos de ferimento por arma branca no abdome', 'C', 'Paciente estável, sem sinais de irritação peritoneal e sem evisceração após ferimento por arma branca pode ser conduzido com observação clínica seriada e exames de imagem, reservando cirurgia para sinais de deterioração ou achados que indiquem lesão de víscera.', 'A: mesmo estável, o paciente necessita de período de observação pelo risco de lesão intra-abdominal não evidente inicialmente. B: apenas suturar a lesão externa sem avaliar possível lesão de estruturas internas é insuficiente e arriscado. D: laparotomia obrigatória para todos os casos não é mais a conduta padrão; pacientes estáveis e assintomáticos podem ser observados, evitando cirurgias desnecessárias.', 'Em revisão', null, null, null),
  ('SIM3-056', 'simulado', '3', '56', 'Cirurgia', 'Hérnia umbilical em adulto', 'Fácil', null, null, 'Paciente de 45 anos, obeso, apresenta abaulamento umbilical redutível, que aumenta com esforço e manobra de Valsalva, sem dor associada, há 1 ano. Ao exame, hérnia umbilical redutível, sem sinais de encarceramento.

A conduta mais adequada é', 'Conduta expectante obrigatória, sem qualquer indicação cirúrgica, independente do tamanho', 'Apenas orientar uso de cinta abdominal, sem necessidade de avaliação cirúrgica', 'Indicar cirurgia de urgência imediata, mesmo sem sinais de complicação', 'Indicar correção cirúrgica eletiva, considerando o risco de complicações futuras (encarceramento, estrangulamento)', 'D', 'Hérnia umbilical sintomática ou com risco de complicação em adulto tem indicação de correção cirúrgica eletiva, prevenindo complicações futuras como encarceramento ou estrangulamento.', 'A: hérnias em adultos geralmente não regridem espontaneamente e têm risco cumulativo de complicações, justificando considerar correção eletiva. B: cinta abdominal não trata definitivamente a hérnia, sendo apenas medida paliativa temporária. C: sem sinais de encarceramento ou estrangulamento, não há indicação de cirurgia de urgência, sendo a cirurgia eletiva a conduta adequada.', 'Em revisão', null, null, null),
  ('SIM3-057', 'simulado', '3', '57', 'Cirurgia', 'Trauma raquimedular', 'Difícil', null, null, 'Paciente de 22 anos, vítima de mergulho em água rasa, é resgatado com queixa de ausência de movimentação e sensibilidade em membros inferiores e parte dos membros superiores. Ao exame: tetraparesia com nível sensitivo em C6, reflexos ausentes abaixo do nível da lesão, sem controle esfincteriano.

A conduta inicial mais adequada é', 'Aguardar resolução espontânea do quadro neurológico antes de qualquer conduta', 'Imobilização da coluna cervical, avaliação e suporte das vias aéreas/respiração (risco de comprometimento por lesão alta), e transporte cuidadoso para centro especializado', 'Mobilizar o paciente livremente, pois a imobilização não traz benefício em trauma raquimedular já estabelecido', 'Iniciar reabilitação motora intensiva imediatamente no local do acidente, antes de qualquer avaliação hospitalar', 'B', 'Suspeita de lesão medular cervical alta exige imobilização rigorosa da coluna, avaliação cuidadosa das vias aéreas e função respiratória (risco de comprometimento diafragmático em lesões altas) e transporte adequado para centro especializado em trauma raquimedular.', 'A: lesão medular estabelecida com esse quadro não tem resolução espontânea esperada nas primeiras horas, exigindo avaliação e conduta hospitalar imediatas. C: a imobilização é essencial para prevenir lesão medular adicional durante o transporte e manuseio inicial. D: reabilitação é etapa posterior, após estabilização e avaliação hospitalar completa, não no local do acidente.', 'Em revisão', null, null, null),
  ('SIM3-058', 'simulado', '3', '58', 'Cirurgia', 'Apendicite em gestante', 'Difícil', null, null, 'Gestante de 24 semanas apresenta dor abdominal que iniciou em região periumbilical e migrou para o flanco direito (deslocamento pela posição uterina alterada), associada a náuseas e febre baixa, há 18 horas. Leucocitose presente, considerando os valores esperados na gestação.

A conduta mais adequada é', 'Tratar apenas com antibioticoterapia isolada, sem necessidade de avaliação cirúrgica em gestantes', 'Adiar qualquer conduta cirúrgica até o final da gestação, pelo risco anestésico', 'Indicar interrupção da gestação como primeira conduta diante do quadro abdominal', 'Avaliação cirúrgica para apendicectomia, preferencialmente por via laparoscópica quando disponível, sem atraso pela gestação', 'D', 'Apendicite aguda na gestação é emergência cirúrgica como em não gestantes; o atraso no tratamento aumenta o risco de perfuração e complicações materno-fetais graves, sendo a apendicectomia (preferencialmente laparoscópica) a conduta indicada sem atraso desnecessário.', 'A: tratamento antibiótico isolado não é a conduta padrão para apendicite aguda confirmada. B: adiar a cirurgia até o final da gestação expõe a gestante a alto risco de perfuração apendicular e sepse, com grave risco materno-fetal. C: a interrupção da gestação não é a conduta indicada; o tratamento é dirigido à causa cirúrgica, mantendo a gestação sempre que possível.', 'Em revisão', null, null, null),
  ('SIM3-059', 'simulado', '3', '59', 'Cirurgia', 'Corpo estranho em via aérea', 'Médio', null, null, 'Criança de 2 anos apresenta engasgo súbito durante refeição, seguido de tosse vigorosa, estridor e cianose leve, enquanto ainda consegue tossir e emitir sons.

A conduta mais adequada nesse momento é', 'Introduzir os dedos na boca da criança às cegas para tentar remover o corpo estranho', 'Realizar manobra de Heimlich imediatamente, mesmo com tosse ainda efetiva presente', 'Aguardar passivamente sem qualquer preparo para intervenção, mesmo com sinais de obstrução', 'Encorajar a tosse espontânea da criança, mantendo-a calma, e preparar para manobras de desobstrução caso a tosse se torne inefetiva ou haja piora clínica', 'D', 'Enquanto a tosse for efetiva (a criança consegue tossir, chorar ou emitir sons), a conduta é encorajar a tosse espontânea, que é o mecanismo mais eficaz de desobstrução; manobras de desobstrução (como Heimlich modificado para crianças) são reservadas para obstrução completa com tosse inefetiva.', 'A: a introdução de dedos às cegas na boca pode empurrar o corpo estranho mais profundamente na via aérea, sendo contraindicada. B: manobras de desobstrução são indicadas quando a tosse se torna inefetiva ou há obstrução completa, não enquanto a tosse ainda é produtiva e a criança consegue emitir sons. C: a situação exige preparo e vigilância ativa para intervir prontamente se houver piora, não uma conduta passiva.', 'Em revisão', null, null, null),
  ('SIM3-060', 'simulado', '3', '60', 'Cirurgia', 'Queimadura em criança - avaliação de gravidade', 'Difícil', null, null, 'Criança de 3 anos sofre queimadura por líquido quente, atingindo face anterior do tronco e parte do membro superior direito, com bolhas e pele avermelhada e dolorosa à palpação (queimadura de segunda espessura superficial).

A conduta mais adequada é', 'Calcular a superfície corporal queimada usando tabela específica para a idade pediátrica, avaliar necessidade de internação e reposição volêmica conforme extensão', 'Utilizar a mesma regra dos nove aplicada a adultos, sem ajuste para a proporção corporal infantil', 'Tratar apenas ambulatorialmente, independente da extensão da área queimada', 'Romper as bolhas rotineiramente como parte do tratamento inicial', 'A', 'Em crianças, a proporção corporal é diferente da de adultos (cabeça proporcionalmente maior), exigindo tabelas específicas para cálculo da superfície corporal queimada (ex: tabela de Lund-Browder), que orientam a decisão sobre internação e reposição volêmica.', 'B: a regra dos nove padrão de adultos superestima a superfície de membros e subestima a da cabeça em crianças pequenas, sendo inadequada sem ajuste. C: queimaduras extensas ou em áreas específicas podem exigir internação, dependendo da avaliação da extensão e profundidade. D: romper as bolhas rotineiramente não é recomendado, pois a bolha íntegra protege contra infecção.', 'Em revisão', null, null, null),
  ('SIM3-061', 'simulado', '3', '61', 'Cirurgia', 'Torção de apêndice testicular vs torção testicular', 'Difícil', null, null, 'Menino de 10 anos apresenta dor testicular de início gradual (não súbito) há 1 dia, de intensidade leve a moderada. Ao exame: ponto doloroso localizado no polo superior do testículo, com pequeno nódulo azulado visível através da pele (''sinal do ponto azul''), reflexo cremastérico presente, testículo em posição normal.

A hipótese diagnóstica mais provável e a conduta são', 'Orquite infecciosa; iniciar antibioticoterapia empírica isolada', 'Torção de apêndice testicular; tratamento conservador com analgesia, pois geralmente é autolimitada', 'Torção testicular; exploração cirúrgica de urgência imediata, sem outra avaliação', 'Hérnia inguinal encarcerada; redução manual imediata', 'B', 'Dor de início gradual, sinal do ponto azul, reflexo cremastérico presente e testículo em posição normal são característicos de torção do apêndice testicular (hidátide de Morgagni), condição benigna e autolimitada, diferente da torção testicular verdadeira.', 'A: não há sinais sistêmicos de infecção (febre, sintomas urinários) sugestivos de orquite. C: os achados descritos (início gradual, reflexo cremastérico presente, sinal do ponto azul) são mais compatíveis com torção de apêndice testicular do que com torção testicular verdadeira, que geralmente tem início súbito e reflexo cremastérico ausente. D: os achados descritos não são compatíveis com hérnia inguinal encarcerada.', 'Em revisão', null, null, null),
  ('SIM3-062', 'simulado', '3', '62', 'Cirurgia', 'Ânus imperfurado - avaliação neonatal', 'Difícil', null, null, 'Recém-nascido, nas primeiras horas de vida, é avaliado ao exame físico de rotina, identificando-se ausência de orifício anal visível, com abaulamento perineal presente.

A conduta mais adequada é', 'Aguardar até 6 meses de vida para reavaliar a necessidade de correção cirúrgica', 'Tranquilizar os pais, pois ausência de orifício anal visível é variação da normalidade em recém-nascidos', 'Avaliação cirúrgica pediátrica para classificação da malformação anorretal (alta ou baixa) e investigação de malformações associadas antes de definir o tratamento', 'Indicar apenas dilatação manual do períneo, sem necessidade de avaliação cirúrgica especializada', 'C', 'Ânus imperfurado é malformação congênita que exige avaliação cirúrgica pediátrica precoce para classificação (malformação alta ou baixa) e investigação de anomalias associadas (síndrome VACTERL), definindo a conduta terapêutica adequada (colostomia ou correção definitiva, conforme o caso).', 'A: a avaliação e conduta devem ser precoces, ainda no período neonatal, não podendo aguardar 6 meses sem risco de complicações (obstrução intestinal). B: ausência de orifício anal visível é malformação que requer investigação e tratamento, não é variação normal. D: dilatação manual não é o tratamento adequado para ânus imperfurado, que geralmente requer correção cirúrgica.', 'Em revisão', null, null, null),
  ('SIM3-063', 'simulado', '3', '63', 'Cirurgia', 'Escroto agudo - avaliação diferencial', 'Difícil', null, null, 'Menino de 7 anos apresenta dor testicular súbita e intensa à esquerda, associada a náuseas e vômitos, há 3 horas, sem febre. Ao exame: testículo esquerdo elevado, horizontalizado e extremamente doloroso à palpação, reflexo cremastérico ausente.

A conduta mais adequada é', 'Exploração cirúrgica de urgência sem atraso, considerando a alta suspeita clínica de torção testicular', 'Iniciar apenas analgesia e observação por 24 horas antes de qualquer conduta', 'Aguardar ultrassonografia Doppler eletiva, mesmo diante da alta suspeita clínica', 'Tratar como epididimite, iniciando antibioticoterapia empírica isolada', 'A', 'Dor súbita e intensa, testículo elevado e horizontalizado, e reflexo cremastérico ausente são achados clássicos de alta suspeita para torção testicular; diante desse quadro, a exploração cirúrgica de urgência não deve ser atrasada, já que a viabilidade testicular depende do tempo até a correção.', 'B: observação prolongada sem tratamento diante de alta suspeita de torção é inadequada, pelo risco de perda do testículo. C: aguardar exame de imagem eletivo diante de alta suspeita clínica atrasa o tratamento e pode comprometer a viabilidade testicular. D: o quadro descrito (início súbito, ausência de febre, reflexo cremastérico ausente) é mais sugestivo de torção do que de epididimite infecciosa.', 'Em revisão', null, null, null),
  ('SIM3-064', 'simulado', '3', '64', 'Cirurgia', 'Onfalocele e gastrosquise - avaliação inicial', 'Difícil', null, null, 'Recém-nascido apresenta defeito de parede abdominal com alças intestinais exteriorizadas diretamente, sem membrana de revestimento e sem inserção anômala do cordão umbilical (defeito lateral ao cordão, que se insere normalmente).

O diagnóstico mais provável e a conduta imediata são', 'Onfalocele; aguardar fechamento espontâneo do defeito sem necessidade de intervenção', 'Defeito de parede sem significado clínico; alta hospitalar de rotina', 'Hérnia umbilical simples; apenas observação clínica ambulatorial', 'Gastrosquise; proteger as alças expostas com cobertura estéril e úmida, evitar perda de calor e volume, e encaminhar para correção cirúrgica', 'D', 'Defeito lateral ao cordão umbilical (que se insere normalmente), sem membrana de revestimento sobre as alças exteriorizadas, é característico de gastrosquise; a conduta imediata é proteger as alças expostas, prevenir perda de calor/volume e encaminhar para correção cirúrgica.', 'A: onfalocele tem inserção do cordão no próprio saco herniário e apresenta membrana de revestimento, diferente do quadro descrito, que é de gastrosquise. B: o defeito descrito é malformação grave que exige intervenção cirúrgica, não pode ser tratado como achado sem significado. C: o quadro descrito não é uma simples hérnia umbilical, mas malformação grave com alças expostas exigindo tratamento cirúrgico urgente.', 'Em revisão', null, null, null),
  ('SIM3-065', 'simulado', '3', '65', 'Cirurgia', 'Doença de Hirschsprung', 'Difícil', null, null, 'Recém-nascido apresenta atraso na eliminação de mecônio (além de 48 horas de vida), associado a distensão abdominal progressiva e episódios de vômitos biliosos. Ao toque retal, saída explosiva de fezes e gases após a manobra.

A hipótese diagnóstica mais provável e a conduta são', 'Estenose hipertrófica do piloro; iniciar correção cirúrgica pilórica imediata', 'Constipação funcional simples; apenas orientação dietética, sem necessidade de investigação adicional', 'Doença de Hirschsprung; biópsia retal para confirmação diagnóstica e avaliação cirúrgica pediátrica especializada', 'Alergia à proteína do leite de vaca; substituir por fórmula hidrolisada, sem outra investigação', 'C', 'Atraso na eliminação de mecônio, distensão abdominal e saída explosiva de fezes ao toque retal (sinal característico) sugerem doença de Hirschsprung (megacólon congênito); a confirmação é feita por biópsia retal, com avaliação cirúrgica especializada subsequente.', 'A: estenose pilórica causa vômitos não biliosos e não explica o atraso na eliminação de mecônio nem o achado ao toque retal. B: o atraso na eliminação de mecônio logo ao nascimento associado aos demais achados não é compatível com constipação funcional simples, que se manifesta mais tardiamente. D: APLV não explica o atraso na eliminação de mecônio nem o sinal específico ao toque retal descrito.', 'Em revisão', null, null, null),
  ('SIM3-066', 'simulado', '3', '66', 'Cirurgia', 'Refluxo vesicoureteral', 'Médio', null, null, 'Criança de 3 anos, com histórico de duas infecções do trato urinário febris nos últimos 6 meses, é investigada com uretrocistografia miccional, que confirma refluxo vesicoureteral grau III bilateral.

A conduta mais adequada é', 'Iniciar diálise preventiva, independente da função renal atual', 'Considerar profilaxia antibiótica contínua e acompanhamento nefrológico/urológico pediátrico, com reavaliação periódica da função renal e do refluxo', 'Indicar cirurgia de reimplante ureteral de urgência em todos os casos de refluxo grau III, sem tentativa de tratamento conservador', 'Não é necessária nenhuma conduta adicional após o diagnóstico, apenas observação sem seguimento', 'B', 'Refluxo vesicoureteral graus intermediários (como grau III) frequentemente têm indicação de tratamento conservador inicial com profilaxia antibiótica e acompanhamento especializado, reservando cirurgia para casos refratários, refluxos de alto grau persistentes ou com dano renal progressivo.', 'A: diálise não tem relação com o manejo padrão do refluxo vesicoureteral sem insuficiência renal estabelecida. C: cirurgia de urgência não é a conduta padrão para todos os casos de grau III, sendo o tratamento conservador considerado inicialmente na maioria dos casos. D: a criança com refluxo diagnosticado necessita de acompanhamento e conduta ativa para prevenir episódios recorrentes e dano renal.', 'Em revisão', null, null, null),
  ('SIM3-067', 'simulado', '3', '67', 'Cirurgia', 'Luxação congênita - pé torto congênito', 'Fácil', null, null, 'Recém-nascido apresenta deformidade do pé caracterizada por equino, varo, adução do antepé e cavo, bilateral, identificada ao exame físico ao nascimento, rígida à manipulação (não corrigível passivamente por completo).

A conduta mais adequada é', 'Aguardar até a criança começar a andar para iniciar qualquer tratamento', 'Indicar cirurgia extensa imediata como única opção terapêutica disponível', 'Tranquilizar os pais, pois a deformidade se corrige espontaneamente sem necessidade de tratamento', 'Encaminhar para avaliação ortopédica pediátrica precoce para início do método de Ponseti (gessos seriados) ainda nas primeiras semanas de vida', 'D', 'Pé torto congênito idiopático tem tratamento padrão-ouro com método de Ponseti (gessos seriados manipulativos), iniciado precocemente, idealmente nas primeiras semanas de vida, com excelentes resultados funcionais quando bem conduzido.', 'A: o tratamento precoce está associado a melhores resultados, não devendo ser postergado até o início da marcha. B: o método de Ponseti (gessos seriados) é o tratamento inicial padrão, reservando cirurgia extensa para casos refratários ou recidivantes. C: pé torto congênito verdadeiro (rígido) não se corrige espontaneamente sem tratamento.', 'Em revisão', null, null, null),
  ('SIM3-068', 'simulado', '3', '68', 'Cirurgia', 'Estenose subglótica / laringomalácia', 'Médio', null, null, 'Lactente de 2 meses apresenta estridor inspiratório desde as primeiras semanas de vida, que piora em decúbito dorsal, durante o choro e a alimentação, e melhora em posição prona, sem outros sinais de desconforto respiratório significativo, com bom ganho ponderal.

A hipótese diagnóstica mais provável e a conduta são', 'Corpo estranho em via aérea; realizar broncoscopia rígida de urgência sem outra avaliação', 'Estenose subglótica grave; indicar traqueostomia de urgência imediatamente', 'Crupe viral; iniciar corticoide sistêmico e nebulização com adrenalina imediatamente', 'Laringomalácia; tranquilizar os pais quanto ao caráter geralmente benigno e autolimitado, com resolução esperada até os 18-24 meses, mantendo acompanhamento', 'D', 'Estridor inspiratório desde as primeiras semanas de vida, que piora em decúbito dorsal e melhora em prona, sem comprometimento do crescimento, é característico de laringomalácia, condição benigna que geralmente resolve espontaneamente com o crescimento das vias aéreas.', 'A: o padrão crônico desde as primeiras semanas, sem episódio agudo de engasgo relatado, não é sugestivo de corpo estranho. B: o quadro descrito, com bom ganho ponderal e sem sinais de gravidade, não indica intervenção invasiva de urgência como traqueostomia. C: crupe viral tem apresentação aguda, geralmente após quadro viral, diferente do padrão crônico desde o nascimento descrito.', 'Em revisão', null, null, null),
  ('SIM3-069', 'simulado', '3', '69', 'Pediatria', 'Icterícia neonatal por incompatibilidade ABO', 'Difícil', null, null, 'Recém-nascido, mãe tipo O positivo e RN tipo A positivo, apresenta icterícia com início nas primeiras 24 horas de vida, progredindo rapidamente. Coombs direto positivo, reticulocitose presente. Exames coletados na admissão:', 'Incompatibilidade ABO; iniciar fototerapia intensiva conforme os níveis de bilirrubina e monitorar necessidade de exsanguineotransfusão', 'Icterícia do leite materno; suspender o aleitamento definitivamente', 'Icterícia fisiológica; apenas observação, sem necessidade de tratamento', 'Atresia biliar; encaminhar diretamente para cirurgia sem outra investigação', 'A', 'Icterícia de início precoce (primeiras 24h), com Coombs direto positivo e reticulocitose em RN com incompatibilidade ABO mãe-filho, confirma doença hemolítica por incompatibilidade ABO; a conduta é fototerapia intensiva conforme a curva de indicação, com monitorização para eventual exsanguineotransfusão.', 'B: icterícia do leite materno tem início mais tardio e não cursa com Coombs positivo; não há indicação de suspender o aleitamento. C: icterícia com início nas primeiras 24 horas nunca é considerada fisiológica, sempre exigindo investigação e tratamento. D: os achados (Coombs positivo, reticulocitose, início precoce) apontam para causa hemolítica, não obstrutiva biliar.', 'Em revisão', '[object Object]', null, null),
  ('SIM3-070', 'simulado', '3', '70', 'Pediatria', 'Displasia broncopulmonar', 'Difícil', null, null, 'Recém-nascido prematuro extremo (26 semanas ao nascer), com síndrome do desconforto respiratório grave ao nascimento, permanece dependente de oxigênio suplementar aos 36 semanas de idade gestacional corrigida, com radiografia de tórax mostrando padrão difuso de opacidades e áreas hiperinsufladas.

A hipótese diagnóstica mais provável e a conduta são', 'Taquipneia transitória do recém-nascido; aguardar resolução espontânea em 48 horas', 'Pneumonia bacteriana aguda; apenas antibioticoterapia isolada, sem necessidade de outro manejo', 'Displasia broncopulmonar; manejo respiratório de suporte (oxigenoterapia conforme necessidade, otimização nutricional) com acompanhamento multidisciplinar a longo prazo', 'Asma do lactente; iniciar corticoide inalatório isolado, sem necessidade de suporte respiratório', 'C', 'Dependência de oxigênio persistente até 36 semanas de idade corrigida em prematuro extremo com desconforto respiratório grave ao nascimento define displasia broncopulmonar, condição crônica que exige manejo respiratório de suporte e acompanhamento multidisciplinar prolongado.', 'A: taquipneia transitória tem resolução em horas a poucos dias, incompatível com a persistência até 36 semanas descrita. B: o quadro crônico persistente não é compatível com pneumonia bacteriana aguda isolada. D: o quadro é de doença pulmonar crônica da prematuridade, não asma do lactente, exigindo manejo mais amplo do que corticoide inalatório isolado.', 'Em revisão', null, null, null),
  ('SIM3-071', 'simulado', '3', '71', 'Pediatria', 'Persistência do canal arterial', 'Médio', null, null, 'Recém-nascido prematuro de 30 semanas, no 5º dia de vida, apresenta sopro sistólico contínuo em região infraclavicular esquerda, pulsos amplos (em salto), taquicardia e piora do desconforto respiratório, associados a dificuldade de desmame da ventilação.

A hipótese diagnóstica mais provável e a conduta são', 'Comunicação interatrial isolada; apenas acompanhamento clínico sem necessidade de tratamento específico', 'Persistência do canal arterial; considerar tratamento farmacológico (anti-inflamatório não esteroide, conforme protocolo) ou fechamento cirúrgico em casos selecionados', 'Sopro inocente da infância; tranquilizar a família, sem necessidade de investigação', 'Estenose pulmonar; encaminhar para cirurgia cardíaca de urgência imediata sem outra avaliação', 'B', 'Sopro sistólico contínuo, pulsos amplos e piora respiratória com dificuldade de desmame ventilatório em prematuro são característicos de persistência do canal arterial hemodinamicamente significativa; o tratamento pode incluir AINE (indometacina/ibuprofeno) conforme protocolo ou fechamento cirúrgico em casos selecionados.', 'A: CIA isolada não costuma causar esse padrão de sopro contínuo com pulsos amplos descrito. C: o quadro apresenta repercussão clínica significativa (piora respiratória, dificuldade de desmame), não sendo compatível com sopro inocente sem repercussão. D: o quadro descrito (sopro contínuo, pulsos em salto) não é típico de estenose pulmonar.', 'Em revisão', null, null, null),
  ('SIM3-072', 'simulado', '3', '72', 'Pediatria', 'Tetralogia de Fallot', 'Difícil', null, null, 'Lactente de 4 meses apresenta episódios de cianose que pioram com o choro e a alimentação, associados a squatting (posição de cócoras) quando começa a andar em criança maior, e sopro sistólico rude em borda esternal esquerda. Ecocardiograma confirma comunicação interventricular, estenose pulmonar, cavalgamento da aorta e hipertrofia ventricular direita.

A conduta mais adequada é', 'Tranquilizar a família, pois a tetralogia de Fallot não requer tratamento específico', 'Indicar apenas oxigenoterapia domiciliar contínua, sem necessidade de correção cirúrgica', 'Encaminhar para avaliação cardiológica pediátrica especializada, com manejo dos episódios de cianose (crise hipoxêmica) e planejamento de correção cirúrgica', 'Iniciar apenas diurético isolado, sem necessidade de avaliação cardiológica especializada', 'C', 'A tétrade clássica (CIV, estenose pulmonar, cavalgamento da aorta, hipertrofia ventricular direita) confirma tetralogia de Fallot; a conduta envolve manejo especializado dos episódios de cianose e planejamento da correção cirúrgica definitiva.', 'A: a tetralogia de Fallot é cardiopatia congênita grave que requer tratamento especializado e correção cirúrgica, não devendo ser negligenciada. B: oxigenoterapia domiciliar isolada não substitui a correção cirúrgica definitiva necessária para essa cardiopatia estrutural. D: diurético isolado não trata a anormalidade estrutural cardíaca de base.', 'Em revisão', null, null, null),
  ('SIM3-073', 'simulado', '3', '73', 'Pediatria', 'Comunicação interventricular', 'Médio', null, null, 'Lactente de 2 meses apresenta sopro holossistólico rude em borda esternal esquerda baixa, identificado em consulta de puericultura, associado a dificuldade para ganhar peso e sudorese durante as mamadas. Ecocardiograma confirma comunicação interventricular de tamanho moderado.

A conduta mais adequada é', 'Não é necessário nenhum acompanhamento especializado, apenas orientação nutricional isolada', 'Encaminhar para acompanhamento cardiológico pediátrico, com manejo clínico do quadro de insuficiência cardíaca (se presente) e avaliação da necessidade e momento da correção cirúrgica', 'Indicar cirurgia cardíaca de urgência imediata, independente da repercussão clínica atual', 'Tranquilizar a família, pois toda comunicação interventricular fecha espontaneamente sem necessidade de acompanhamento', 'B', 'CIV moderada com repercussão clínica (dificuldade de ganho ponderal, sudorese às mamadas, sugestivos de insuficiência cardíaca) exige acompanhamento cardiológico especializado, com manejo clínico e avaliação da necessidade/momento da correção cirúrgica, já que defeitos menores podem fechar espontaneamente, mas os com repercussão geralmente necessitam de intervenção.', 'A: os sinais de repercussão clínica (dificuldade de ganho ponderal, sudorese) exigem acompanhamento cardiológico especializado, não apenas orientação nutricional. C: a decisão cirúrgica depende da avaliação especializada e da gravidade, não sendo necessariamente de urgência imediata sem essa avaliação. D: nem toda CIV fecha espontaneamente, especialmente as de tamanho moderado a grande com repercussão clínica.', 'Em revisão', null, null, null),
  ('SIM3-074', 'simulado', '3', '74', 'Pediatria', 'Doença hemolítica perinatal (Rh)', 'Difícil', null, null, 'Recém-nascido de mãe Rh negativo sensibilizada (Coombs indireto positivo durante a gestação) nasce com hidropisia fetal leve, palidez importante e hepatoesplenomegalia. Hemoglobina de cordão muito baixa, Coombs direto fortemente positivo.

A conduta mais adequada é', 'Alta hospitalar precoce com acompanhamento ambulatorial de rotina, sem necessidade de conduta imediata', 'Manejo em unidade neonatal especializada, com possível necessidade de exsanguineotransfusão e/ou transfusão, além de fototerapia intensiva conforme evolução da bilirrubina', 'Aguardar resolução espontânea da anemia, sem qualquer intervenção', 'Apenas fototerapia isolada, sem necessidade de avaliação para transfusão ou exsanguineotransfusão', 'B', 'Doença hemolítica perinatal grave por isoimunização Rh, com hidropisia e anemia importante ao nascer, exige manejo em unidade neonatal especializada, com avaliação para exsanguineotransfusão/transfusão e fototerapia intensiva, dado o risco de kernicterus e descompensação hemodinâmica.', 'A: a gravidade do quadro (hidropisia, anemia importante) contraindica alta precoce sem tratamento adequado. C: o quadro grave descrito não deve ser deixado sem intervenção, pelo risco de complicações graves. D: a gravidade do quadro descrito frequentemente ultrapassa o que a fototerapia isolada consegue controlar, sendo necessária avaliação para transfusão/exsanguineotransfusão.', 'Em revisão', null, null, null),
  ('SIM3-075', 'simulado', '3', '75', 'Pediatria', 'Hipoglicemia neonatal', 'Médio', null, null, 'Recém-nascido filho de mãe diabética, com peso ao nascer de 4.200g, apresenta tremores, irritabilidade e hipotonia nas primeiras horas de vida. Glicemia capilar coletada na segunda hora de vida:', 'Hipocalcemia neonatal isolada; iniciar apenas reposição de cálcio, sem avaliar a glicemia', 'Hipoglicemia neonatal; oferecer aleitamento precoce e, se persistente ou sintomática importante, considerar infusão de glicose intravenosa', 'Quadro normal para recém-nascidos de mães diabéticas; não é necessária nenhuma conduta', 'Sepse neonatal; iniciar antibioticoterapia empírica isolada, sem necessidade de corrigir a glicemia', 'B', 'Recém-nascidos macrossômicos de mães diabéticas têm risco aumentado de hipoglicemia neonatal por hiperinsulinismo fetal; diante de sintomas e glicemia baixa confirmada, a conduta é alimentação precoce e, se persistente/sintomática, infusão de glicose intravenosa.', 'A: hipocalcemia pode coexistir, mas a glicemia deve ser avaliada e corrigida prioritariamente diante do contexto de risco e sintomas. C: filhos de mães diabéticas têm risco real e significativo de hipoglicemia sintomática, exigindo monitorização e conduta ativa. D: os sintomas descritos (tremores, hipotonia) são compatíveis com hipoglicemia, que deve ser corrigida como prioridade, embora sepse seja diagnóstico diferencial a considerar.', 'Em revisão', '[object Object]', null, null),
  ('SIM3-076', 'simulado', '3', '76', 'Pediatria', 'Taquipneia transitória do recém-nascido', 'Médio', null, null, 'Recém-nascido a termo, nascido de cesariana eletiva sem trabalho de parto, apresenta taquipneia (FR 80irpm) e discreto gemido nas primeiras horas de vida, sem outros sinais de gravidade importantes, com melhora progressiva ao longo das primeiras 24 horas.

A hipótese diagnóstica mais provável e a conduta são', 'Síndrome do desconforto respiratório (doença da membrana hialina); administrar surfactante exógeno imediatamente', 'Pneumonia neonatal bacteriana grave; iniciar antibioticoterapia intravenosa prolongada', 'Taquipneia transitória do recém-nascido; suporte com oxigenoterapia se necessário e observação, com resolução esperada em até 72 horas', 'Cardiopatia congênita cianótica; encaminhar imediatamente para cirurgia cardíaca', 'C', 'Taquipneia transitória do recém-nascido é comum após cesariana eletiva sem trabalho de parto (menor reabsorção do líquido pulmonar fetal), com quadro leve a moderado e resolução espontânea em até 72 horas, tratada com suporte conforme necessidade.', 'A: a doença da membrana hialina é mais típica de prematuros, com quadro mais grave e progressivo, diferente da melhora progressiva descrita em RN a termo. B: o quadro leve com melhora progressiva não é sugestivo de pneumonia bacteriana grave. D: não há descrição de cianose central persistente sugestiva de cardiopatia cianótica.', 'Em revisão', null, null, null),
  ('SIM3-077', 'simulado', '3', '77', 'Pediatria', 'Síndrome do desconforto respiratório (doença da membrana hialina)', 'Difícil', null, null, 'Recém-nascido prematuro de 29 semanas apresenta desconforto respiratório progressivo logo após o nascimento, com gemido expiratório, tiragem intercostal importante e necessidade crescente de oxigênio. Radiografia de tórax mostra padrão reticulogranular difuso com broncogramas aéreos.

A conduta mais adequada é', 'Aguardar resolução espontânea, pois o quadro tende à melhora sem intervenção em prematuros', 'Iniciar apenas antibioticoterapia isolada, sem necessidade de suporte respiratório específico', 'Suporte respiratório (CPAP ou ventilação mecânica conforme gravidade) associado à administração de surfactante exógeno', 'Apenas oxigenoterapia em cateter nasal de baixo fluxo, sem necessidade de outras medidas', 'C', 'Desconforto respiratório progressivo em prematuro com padrão radiográfico reticulogranular difuso e broncogramas aéreos é característico de doença da membrana hialina (deficiência de surfactante); o tratamento envolve suporte respiratório adequado associado à administração de surfactante exógeno.', 'A: sem tratamento adequado, a doença da membrana hialina pode progredir para insuficiência respiratória grave; não deve ser deixada sem intervenção. B: antibiótico isolado não trata a causa de base (deficiência de surfactante), embora possa ser considerado pela dificuldade de diferenciar de sepse neonatal. D: o quadro grave descrito frequentemente exige suporte respiratório mais avançado do que cateter nasal de baixo fluxo.', 'Em revisão', null, null, null),
  ('SIM3-078', 'simulado', '3', '78', 'Pediatria', 'Sífilis congênita', 'Difícil', null, null, 'Recém-nascido de mãe com sífilis não tratada adequadamente durante a gestação apresenta, ao exame físico, hepatoesplenomegalia, lesões cutâneas descamativas em palmas e plantas, e rinite serossanguinolenta. Radiografia de ossos longos mostra sinais de periostite.

A conduta mais adequada é', 'Aguardar até 6 meses de vida para iniciar qualquer investigação ou tratamento', 'Confirmar o diagnóstico com exames complementares (VDRL, líquor) e iniciar tratamento com penicilina cristalina, conforme protocolo para sífilis congênita', 'Apenas observação clínica, pois os achados descritos são inespecíficos e não sugerem sífilis congênita', 'Tratar apenas com penicilina benzatina em dose única, mesmo diante de sinais clínicos evidentes de doença ativa', 'B', 'Hepatoesplenomegalia, lesões cutâneas palmoplantares, rinite serossanguinolenta e periostite em RN de mãe com sífilis não tratada adequadamente são altamente sugestivos de sífilis congênita sintomática; a conduta é confirmação (incluindo avaliação liquórica) e tratamento com penicilina cristalina.', 'A: o tratamento deve ser iniciado prontamente no período neonatal, não pode ser postergado. C: os achados descritos são clássicos e específicos o suficiente para sífilis congênita, exigindo investigação e tratamento imediatos. D: penicilina benzatina em dose única é insuficiente para sífilis congênita sintomática, que exige esquema com penicilina cristalina, considerando possível neurossífilis.', 'Em revisão', null, null, null),
  ('SIM3-079', 'simulado', '3', '79', 'Pediatria', 'Toxoplasmose congênita', 'Difícil', null, null, 'Recém-nascido de mãe com toxoplasmose diagnosticada no primeiro trimestre da gestação, sem tratamento adequado, apresenta ao exame: microcefalia, hepatoesplenomegalia e coriorretinite identificada em exame de fundo de olho. Tomografia de crânio mostra calcificações intracranianas difusas.

A conduta mais adequada é', 'Aguardar até 1 ano de idade para confirmar o diagnóstico antes de iniciar qualquer tratamento', 'Apenas acompanhamento oftalmológico isolado, sem necessidade de tratamento sistêmico', 'Iniciar apenas corticoide isolado, sem necessidade de tratamento antiparasitário específico', 'Confirmar o diagnóstico com sorologia específica no recém-nascido e iniciar tratamento combinado (pirimetamina, sulfadiazina e ácido folínico) conforme protocolo', 'D', 'Microcefalia, hepatoesplenomegalia, coriorretinite e calcificações intracranianas difusas em RN de mãe com toxoplasmose gestacional não tratada são a tétrade clássica de toxoplasmose congênita; a conduta é confirmação sorológica e tratamento combinado específico prolongado.', 'A: o tratamento deve ser iniciado precocemente no período neonatal para melhor prognóstico, não pode aguardar 1 ano. B: o tratamento sistêmico é essencial para controlar a infecção ativa e prevenir progressão das lesões, não apenas acompanhamento oftalmológico. C: corticoide pode ser usado como coadjuvante em certas situações (coriorretinite ativa), mas não substitui o tratamento antiparasitário específico.', 'Em revisão', null, null, null),
  ('SIM3-080', 'simulado', '3', '80', 'Pediatria', 'Rubéola congênita', 'Difícil', null, null, 'Recém-nascido de mãe com quadro de rubéola no primeiro trimestre da gestação, sem confirmação sorológica realizada na época, apresenta catarata congênita bilateral, sopro cardíaco compatível com persistência do canal arterial, e perda auditiva identificada em triagem neonatal.

A hipótese diagnóstica mais provável e a conduta são', 'Síndrome da rubéola congênita; confirmação sorológica específica e encaminhamento multidisciplinar (oftalmologia, cardiologia, fonoaudiologia)', 'Citomegalovirose congênita; apenas acompanhamento auditivo isolado, sem necessidade de outras avaliações', 'Toxoplasmose congênita; iniciar pirimetamina e sulfadiazina isoladamente, sem outra investigação', 'Sífilis congênita; iniciar apenas penicilina benzatina, sem necessidade de avaliação multidisciplinar', 'A', 'A tríade clássica de catarata congênita, cardiopatia (frequentemente persistência do canal arterial) e surdez neurossensorial, associada a infecção materna por rubéola no primeiro trimestre, é característica da síndrome da rubéola congênita, exigindo confirmação e acompanhamento multidisciplinar.', 'B: embora CMV também possa causar surdez, o conjunto específico com catarata e cardiopatia associado ao histórico materno de rubéola aponta mais para essa etiologia. C: o quadro descrito (catarata, cardiopatia, surdez) associado ao histórico materno de rubéola é mais específico para síndrome da rubéola congênita do que toxoplasmose. D: sífilis congênita tem outro conjunto de achados característicos, diferente da tríade descrita.', 'Em revisão', null, null, null),
  ('SIM3-081', 'simulado', '3', '81', 'Pediatria', 'Citomegalovirose congênita', 'Difícil', null, null, 'Recém-nascido a termo apresenta, ao exame físico, microcefalia, petéquias generalizadas e hepatoesplenomegalia. Triagem auditiva neonatal (emissões otoacústicas) resulta alterada bilateralmente. Exame de urina do recém-nascido coletado nas primeiras 3 semanas de vida detecta o vírus por PCR.

A conduta mais adequada é', 'Confirmar o diagnóstico de citomegalovirose congênita e considerar tratamento antiviral (ganciclovir/valganciclovir) conforme gravidade, com acompanhamento auditivo e neurológico prolongado', 'Aguardar até 1 ano de vida para qualquer investigação diagnóstica ou tratamento', 'Tranquilizar a família, pois citomegalovirose congênita não tem nenhuma repercussão a longo prazo', 'Iniciar apenas antibioticoterapia bacteriana, sem necessidade de tratamento antiviral específico', 'A', 'Microcefalia, petéquias, hepatoesplenomegalia e alteração na triagem auditiva, com confirmação por PCR na urina nas primeiras 3 semanas de vida (critério para infecção congênita, e não adquirida), caracterizam citomegalovirose congênita sintomática, com indicação de considerar tratamento antiviral e acompanhamento prolongado.', 'B: o diagnóstico e a decisão terapêutica devem ser feitos precocemente, dentro do período neonatal, para melhor prognóstico. C: a citomegalovirose congênita sintomática está associada a sequelas significativas, especialmente auditivas e neurológicas, exigindo acompanhamento a longo prazo. D: o agente é viral, não bacteriano; antibioticoterapia não trata a infecção por CMV.', 'Em revisão', null, null, null),
  ('SIM3-082', 'simulado', '3', '82', 'Pediatria', 'Paralisia cerebral', 'Médio', null, null, 'Criança de 18 meses, com histórico de prematuridade extrema e hemorragia intraventricular grave no período neonatal, apresenta atraso motor importante, espasticidade em membros inferiores e reflexos exaltados, sem piora progressiva ao longo do tempo.

A conduta mais adequada é', 'Aguardar sem qualquer intervenção, pois o quadro tende à resolução espontânea completa com o crescimento', 'Iniciar investigação para doença neurodegenerativa progressiva, dado o quadro de espasticidade', 'Indicar apenas acompanhamento psiquiátrico isolado, sem necessidade de reabilitação motora', 'Encaminhar para acompanhamento multidisciplinar (fisioterapia, terapia ocupacional, fonoaudiologia) e avaliação continuada do desenvolvimento, característico de paralisia cerebral', 'D', 'Atraso motor com espasticidade não progressiva, em contexto de lesão cerebral perinatal conhecida (prematuridade extrema, hemorragia intraventricular), é compatível com paralisia cerebral; a conduta é encaminhamento para acompanhamento multidisciplinar de reabilitação.', 'A: paralisia cerebral não regride completamente, embora o quadro funcional possa melhorar com intervenção adequada e não seja progressiva. B: o caráter não progressivo do quadro (característica central da paralisia cerebral) diferencia de doenças neurodegenerativas, que cursam com piora progressiva. C: reabilitação motora multidisciplinar é essencial no manejo da paralisia cerebral, não apenas acompanhamento psiquiátrico isolado.', 'Em revisão', null, null, null),
  ('SIM3-083', 'simulado', '3', '83', 'Pediatria', 'Distrofia muscular de Duchenne', 'Difícil', null, null, 'Menino de 4 anos apresenta dificuldade progressiva para subir escadas e levantar-se do chão, utilizando as mãos para ''escalar'' o próprio corpo ao se levantar (sinal de Gowers), associada a hipertrofia de panturrilhas. CPK sérica muito elevada.

A hipótese diagnóstica mais provável e a conduta são', 'Deficiência nutricional isolada; apenas suplementação proteica, sem necessidade de outros exames', 'Paralisia cerebral; encaminhar apenas para fisioterapia, sem necessidade de investigação genética', 'Miastenia gravis juvenil; iniciar piridostigmina isoladamente, sem outra investigação', 'Distrofia muscular de Duchenne; confirmação por teste genético e encaminhamento para acompanhamento multidisciplinar especializado (neurologia, cardiologia, fisioterapia)', 'D', 'Fraqueza muscular progressiva de padrão proximal, sinal de Gowers, pseudo-hipertrofia de panturrilhas e CPK muito elevada em menino são clássicos de distrofia muscular de Duchenne (doença ligada ao X); a conduta é confirmação genética e acompanhamento multidisciplinar especializado, dado o curso progressivo e as complicações associadas (cardíacas, respiratórias).', 'A: o quadro clínico e a CPK muito elevada não são compatíveis apenas com deficiência nutricional isolada. B: paralisia cerebral é quadro não progressivo desde o nascimento, diferente da progressão descrita, e não cursaria com CPK tão elevada. C: miastenia gravis cursa com fraqueza flutuante e fatigabilidade, não com CPK elevada e sinal de Gowers característico.', 'Em revisão', null, null, null),
  ('SIM3-084', 'simulado', '3', '84', 'Pediatria', 'Transtorno de oposição desafiante', 'Médio', null, null, 'Criança de 8 anos apresenta padrão persistente de comportamento desafiador, irritabilidade e discussões frequentes com adultos e figuras de autoridade, recusando-se a seguir regras e culpando os outros por seus próprios erros, há mais de 6 meses, em múltiplos ambientes (casa e escola).

A hipótese diagnóstica mais provável é', 'Transtorno do espectro autista', 'Transtorno do déficit de atenção e hiperatividade isolado', 'Transtorno de oposição desafiante', 'Transtorno depressivo maior', 'C', 'Padrão persistente (>6 meses) de comportamento desafiador, discussões frequentes com autoridades, recusa em seguir regras e dificuldade em assumir responsabilidade pelos próprios erros, presente em múltiplos ambientes, é característico do transtorno de oposição desafiante.', 'A: TEA cursa com déficits de comunicação social e comportamentos repetitivos, não com esse padrão específico de oposição e desafio. B: TDAH tem como características centrais desatenção e/ou hiperatividade-impulsividade, diferente do padrão de oposição descrito, embora possa coexistir. D: transtorno depressivo teria outros sintomas centrais (humor deprimido, anedonia), não esse padrão predominante de oposição e desafio.', 'Em revisão', null, null, null),
  ('SIM3-085', 'simulado', '3', '85', 'Pediatria', 'Bullying / saúde mental do adolescente', 'Médio', null, null, 'Adolescente de 14 anos, trazido pelos pais à consulta, apresenta queda no rendimento escolar, isolamento social e recusa em ir à escola nos últimos 2 meses. Durante a consulta, revela ter sido vítima de agressões verbais e físicas repetidas por colegas na escola.

A conduta mais adequada é', 'Acolher o adolescente, avaliar risco de autolesão/ideação suicida, articular com a escola e a família um plano de proteção, e considerar encaminhamento para suporte psicológico especializado', 'Encaminhar apenas para mudança de escola, sem qualquer avaliação de saúde mental', 'Orientar o adolescente a ''revidar'' as agressões para resolver a situação sozinho', 'Minimizar a situação, orientando que bullying é uma fase normal da adolescência sem necessidade de intervenção', 'A', 'Diante de relato de bullying com repercussão significativa (queda de rendimento, isolamento, recusa escolar), a conduta é acolher o adolescente, avaliar risco de autolesão/suicídio (associado a bullying), articular medidas de proteção com escola e família, e considerar suporte psicológico especializado.', 'B: mudança de escola isolada, sem avaliação da saúde mental do adolescente, é insuficiente diante do impacto psicológico já demonstrado. C: orientar o adolescente a revidar não resolve a situação e pode agravar o conflito e os riscos envolvidos. D: bullying não deve ser normalizado ou minimizado, tendo repercussões significativas na saúde mental do adolescente.', 'Em revisão', null, null, null),
  ('SIM3-086', 'simulado', '3', '86', 'Pediatria', 'Obesidade infantil', 'Médio', null, null, 'Criança de 9 anos, com índice de massa corporal no escore Z acima de +2 para idade e sexo, apresenta acantose nigricans em região cervical e axilar, associada a sedentarismo importante e dieta rica em ultraprocessados, segundo relato dos pais.

A conduta mais adequada é', 'Orientar mudança de hábitos alimentares e aumento da atividade física de forma gradual e sustentável, envolvendo toda a família, e investigar comorbidades associadas (perfil glicêmico e lipídico)', 'Prescrever medicação para emagrecimento como primeira conduta em criança dessa idade', 'Tranquilizar os pais, pois obesidade infantil não traz nenhum risco à saúde atual ou futura', 'Indicar dieta com restrição calórica muito rigorosa e exercício físico intenso imediato, sem gradualismo', 'A', 'Obesidade infantil com sinais de resistência insulínica (acantose nigricans) exige abordagem multidisciplinar com mudança gradual e sustentável de hábitos alimentares e atividade física, envolvendo a família, além de investigação de comorbidades metabólicas associadas.', 'B: medicação para emagrecimento não é primeira linha de tratamento na obesidade infantil, sendo reservada para situações específicas. C: a obesidade infantil, especialmente com sinais de resistência insulínica, está associada a riscos metabólicos e cardiovasculares significativos, atuais e futuros. D: restrições muito rigorosas e exercício intenso sem gradualismo não são recomendados em crianças, podendo ser prejudiciais ao crescimento e desenvolvimento.', 'Em revisão', null, null, null),
  ('SIM3-087', 'simulado', '3', '87', 'Pediatria', 'Crise vaso-oclusiva em anemia falciforme', 'Difícil', null, null, 'Criança de 6 anos, com diagnóstico conhecido de anemia falciforme, é trazida ao PS com dor intensa em membros e região lombar, há 6 horas, associada a febre baixa. Refere episódios semelhantes anteriores, geralmente desencadeados por desidratação ou infecções.

A conduta mais adequada é', 'Analgesia adequada e precoce (conforme intensidade da dor), hidratação venosa e investigação de fator desencadeante (ex: infecção), com atenção a sinais de complicações graves', 'Tratar apenas com antitérmico, sem necessidade de analgesia específica para a crise álgica', 'Aguardar a dor melhorar espontaneamente antes de qualquer intervenção analgésica', 'Iniciar transfusão sanguínea de rotina para todos os episódios de crise álgica, independente da gravidade', 'A', 'Crise vaso-oclusiva em anemia falciforme exige analgesia precoce e adequada (fundamental para o manejo, muitas vezes subtratada), hidratação venosa e investigação de fatores desencadeantes, além de vigilância para complicações graves associadas (síndrome torácica aguda, sequestro esplênico).', 'B: a crise álgica requer analgesia específica e adequada à intensidade da dor, não apenas antitérmico. C: a dor na crise vaso-oclusiva costuma ser intensa e não deve ser subtratada, sendo a analgesia precoce parte fundamental do manejo. D: transfusão não é rotina para toda crise álgica, sendo reservada para complicações específicas ou crises muito graves/refratárias.', 'Em revisão', null, null, null),
  ('SIM3-088', 'simulado', '3', '88', 'Medicina Preventiva e Social', 'Coeficiente de letalidade', 'Médio', null, null, 'Durante um surto de doença X em uma comunidade, foram registrados 200 casos confirmados, dos quais 8 evoluíram para óbito diretamente relacionado à doença, ao longo do período de acompanhamento do surto.

O coeficiente de letalidade dessa doença, nesse surto, e sua principal diferença em relação ao coeficiente de mortalidade são', '25%; a letalidade é calculada sobre a população total, não sobre os casos da doença', '8%; ambos os indicadores medem exatamente a mesma coisa, sem diferença conceitual', '2%; letalidade e incidência são sinônimos, medindo o mesmo fenômeno', '4%; a letalidade mede a proporção de óbitos entre os casos da doença, enquanto a mortalidade mede a proporção de óbitos em relação à população total', 'D', 'Letalidade = (óbitos pela doença / casos da doença) x 100 = (8/200)x100 = 4%. A letalidade mede a gravidade da doença entre os que a contraem, enquanto a mortalidade mede o impacto na população geral, sendo conceitos distintos.', 'A: cálculo incorreto; letalidade é calculada sobre os casos da doença, não sobre a população total (isso seria mais próximo do conceito de mortalidade). B: o cálculo correto resulta em 4%, não 8%, e os dois indicadores têm significados distintos (base populacional diferente). C: cálculo incorreto e definição equivocada; letalidade e incidência são conceitos epidemiológicos diferentes.', 'Em revisão', null, null, null),
  ('SIM3-089', 'simulado', '3', '89', 'Medicina Preventiva e Social', 'Notificação compulsória - lista de doenças', 'Fácil', null, null, 'Médico de UBS atende paciente com diagnóstico clínico confirmado de tétano acidental, após ferimento contaminado sem vacinação adequada prévia.

Em relação à notificação compulsória dessa doença, é correto afirmar que', 'A notificação de tétano é facultativa, dependendo exclusivamente da gravidade do caso', 'O tétano acidental é doença de notificação compulsória, devendo ser notificado ao sistema de vigilância epidemiológica', 'Apenas o tétano neonatal deve ser notificado, sendo o tétano acidental dispensado dessa obrigação', 'Tétano não consta na lista de doenças de notificação compulsória no Brasil', 'B', 'O tétano acidental consta na lista nacional de doenças de notificação compulsória no Brasil, devendo ser notificado ao sistema de vigilância epidemiológica, contribuindo para o monitoramento e ações de controle da doença.', 'A: a notificação de doenças da lista compulsória não é facultativa, é obrigação legal do profissional de saúde. C: tanto o tétano acidental quanto o neonatal são de notificação compulsória, não havendo dispensa para a forma acidental. D: tétano acidental está incluído na lista de notificação compulsória vigente.', 'Em revisão', null, null, null),
  ('SIM3-090', 'simulado', '3', '90', 'Medicina Preventiva e Social', 'Certificado de óbito - preenchimento', 'Médio', null, null, 'Paciente falece em domicílio, sem assistência médica prévia relacionada à causa do óbito, em um município que possui Serviço de Verificação de Óbitos (SVO) disponível.

A declaração de óbito, nesse caso, deverá ser preenchida', 'Pelo Instituto Médico Legal, independentemente de haver suspeita de morte violenta', 'Não é necessária declaração de óbito para mortes domiciliares sem assistência médica prévia', 'Pelo Serviço de Verificação de Óbitos, que deverá investigar e determinar a causa mortis antes da emissão do documento', 'Por qualquer médico da rede, sem necessidade de investigação da causa da morte', 'C', 'Óbitos sem assistência médica, em municípios com SVO disponível, devem ser encaminhados a esse serviço, responsável por investigar (incluindo necropsia, se necessário) e determinar a causa mortis para preenchimento adequado da declaração de óbito.', 'A: o IML é destinado a mortes violentas ou com suspeita de causa externa, não para todo óbito domiciliar sem assistência prévia. B: toda morte requer declaração de óbito, documento legal obrigatório, independentemente do local ou circunstância. D: um médico sem conhecimento da história clínica não deve preencher a declaração sem a investigação adequada da causa da morte nesse contexto.', 'Em revisão', null, null, null),
  ('SIM3-091', 'simulado', '3', '91', 'Medicina Preventiva e Social', 'Vigilância em saúde do trabalhador - notificação de acidente', 'Médio', null, null, 'Trabalhador sofre acidente de trabalho com material perfurocortante durante atividade em hospital, com exposição a material biológico potencialmente contaminado.

Além da conduta clínica imediata (profilaxias indicadas), a providência administrativa obrigatória inclui', 'Nenhuma notificação é necessária se o trabalhador não desenvolver sintomas imediatos', 'A notificação só é obrigatória se houver confirmação de soroconversão em exames de acompanhamento', 'A notificação é responsabilidade exclusiva do próprio trabalhador, sem participação do serviço de saúde', 'Emissão da Comunicação de Acidente de Trabalho (CAT) e notificação do caso no sistema de informação em saúde do trabalhador', 'D', 'Acidentes de trabalho com exposição a material biológico exigem emissão da CAT (documento previdenciário) e notificação no sistema de informação em saúde do trabalhador, independentemente do desenvolvimento posterior de sintomas ou soroconversão.', 'A: a notificação é obrigatória pelo próprio acidente/exposição, não dependendo do desenvolvimento de sintomas. B: a notificação deve ocorrer no momento do acidente/exposição, não aguardando confirmação de soroconversão futura. C: o serviço de saúde e a empresa têm responsabilidades na notificação, não sendo exclusiva do trabalhador.', 'Em revisão', null, null, null),
  ('SIM3-092', 'simulado', '3', '92', 'Medicina Preventiva e Social', 'Sistema Único de Saúde - princípios doutrinários', 'Fácil', null, null, 'Uma gestora municipal de saúde explica à equipe os princípios doutrinários que fundamentam o SUS, destacando que todo cidadão tem direito ao acesso aos serviços de saúde, sem distinção de qualquer natureza, e que o atendimento deve considerar a pessoa como um todo, integrando ações de promoção, prevenção e recuperação.

Os princípios doutrinários descritos correspondem, respectivamente, a', 'Hierarquização e participação social', 'Equidade exclusivamente, sem relação com outros princípios', 'Universalidade e integralidade', 'Descentralização e regionalização', 'C', 'Universalidade garante acesso a todos os cidadãos sem distinção; integralidade considera a pessoa como um todo, articulando ações de promoção, prevenção, tratamento e reabilitação — ambos princípios doutrinários fundamentais do SUS.', 'A: hierarquização é princípio organizativo; participação social, embora doutrinário, não é o que está descrito no cenário. B: equidade é outro princípio doutrinário relevante, mas não descreve isoladamente o cenário apresentado, que envolve dois princípios distintos. D: descentralização e regionalização são princípios organizativos, relacionados à gestão e distribuição de serviços, não ao acesso universal e à integralidade descritos.', 'Em revisão', null, null, null),
  ('SIM3-093', 'simulado', '3', '93', 'Medicina Preventiva e Social', 'Níveis de prevenção em saúde', 'Médio', null, null, 'Uma equipe de saúde realiza rastreamento de câncer de colo uterino através de citologia oncótica em mulheres assintomáticas da população-alvo, visando detectar lesões precursoras antes do desenvolvimento de sintomas.

Essa ação corresponde a qual nível de prevenção em saúde?', 'Prevenção primária, pois visa evitar completamente a ocorrência da doença antes de qualquer alteração celular', 'Prevenção secundária, pois visa à detecção precoce de doença já instalada, ainda assintomática', 'Prevenção terciária, pois visa reabilitar sequelas já estabelecidas pela doença', 'Prevenção quaternária, pois visa evitar excesso de intervenções médicas desnecessárias', 'B', 'O rastreamento (screening) de doenças em fase pré-clínica, como a citologia oncótica para detecção precoce de lesões precursoras do câncer de colo uterino, é exemplo clássico de prevenção secundária.', 'A: prevenção primária envolve ações antes da doença se instalar (ex: vacinação, orientações sobre fatores de risco), diferente da detecção de lesões já existentes. C: prevenção terciária visa limitar incapacidades e reabilitar após a doença já estabelecida com sequelas, não a detecção precoce. D: prevenção quaternária refere-se a evitar iatrogenia e excesso de intervenção, conceito diferente do rastreamento populacional descrito.', 'Em revisão', null, null, null),
  ('SIM3-094', 'simulado', '3', '94', 'Medicina Preventiva e Social', 'Cálculo de taxa de mortalidade proporcional', 'Difícil', null, null, 'Em um município, ocorreram 500 óbitos no ano, sendo 150 óbitos atribuídos a doenças cardiovasculares, 100 a neoplasias, 50 a causas externas e o restante a outras causas.

A mortalidade proporcional por doenças cardiovasculares nesse município, nesse período, é', '30%', '3%', '15%', '50%', 'A', 'Mortalidade proporcional = (óbitos por causa específica / total de óbitos) x 100 = (150/500)x100 = 30%. Esse indicador mostra a distribuição percentual dos óbitos por diferentes causas dentro do total de mortes, sem uso de população como denominador.', 'B: cálculo incorreto, resultando em valor muito abaixo do proporcional real calculado. C: cálculo incorreto do percentual solicitado. D: 50% corresponderia a outro valor, não à proporção correta calculada para doenças cardiovasculares neste cenário.', 'Em revisão', null, null, null),
  ('SIM3-095', 'simulado', '3', '95', 'Medicina Preventiva e Social', 'Vigilância ambiental em saúde', 'Médio', null, null, 'Uma equipe de vigilância em saúde é acionada após identificação de níveis elevados de um metal pesado na água de abastecimento de um bairro, com relatos de sintomas inespecíficos entre moradores.

A área de atuação responsável primariamente por essa investigação é', 'Vigilância sanitária de alimentos, sem relação com questões de contaminação hídrica ambiental', 'Vigilância epidemiológica, responsável exclusivamente pelo monitoramento de doenças infecciosas transmissíveis', 'Vigilância em saúde ambiental, que monitora fatores ambientais de risco à saúde, como contaminação de recursos hídricos', 'Atenção primária à saúde, responsável pela análise laboratorial da água e definição de padrões de potabilidade', 'C', 'A vigilância em saúde ambiental é responsável por monitorar e investigar fatores ambientais de risco à saúde da população, incluindo contaminação de recursos hídricos por substâncias químicas, como metais pesados.', 'A: vigilância sanitária de alimentos tem outro escopo específico, diferente da contaminação de água de abastecimento por metal pesado. B: a vigilância epidemiológica tem foco predominante em doenças e agravos, especialmente transmissíveis, não sendo a principal responsável por questões de contaminação ambiental química. D: a atenção primária não tem como atribuição a definição de padrões de potabilidade ou análise laboratorial ambiental, embora participe do cuidado aos pacientes afetados.', 'Em revisão', null, null, null),
  ('SIM3-096', 'simulado', '3', '96', 'Medicina Preventiva e Social', 'Cobertura vacinal e imunidade de rebanho', 'Médio', null, null, 'Uma região apresenta queda progressiva nas taxas de cobertura vacinal contra sarampo nos últimos anos, associada a hesitação vacinal crescente na população, culminando em surtos da doença mesmo em áreas anteriormente consideradas livres de transmissão.

Esse cenário ilustra principalmente qual conceito em saúde coletiva?', 'Erradicação da doença, que se tornou permanentemente impossível após a introdução da vacina', 'Efeito adverso vacinal generalizado, causado diretamente pela própria vacinação em massa', 'Imunidade artificial passiva, adquirida exclusivamente por transferência materna', 'Perda da imunidade de rebanho (coletiva), que ocorre quando a cobertura vacinal cai abaixo do limiar necessário para interromper a cadeia de transmissão na população', 'D', 'A queda da cobertura vacinal abaixo do limiar necessário compromete a imunidade de rebanho (coletiva), que protege indiretamente até indivíduos não vacinados ao reduzir a circulação do agente na população; sua perda permite o ressurgimento de surtos de doenças antes controladas.', 'A: o cenário descreve o oposto de erradicação, mostrando ressurgimento de casos pela queda vacinal, não impossibilidade permanente de controle. B: o cenário não descreve efeitos adversos da vacina, mas sim os efeitos da falta de vacinação (hesitação vacinal). C: imunidade passiva materna é conceito diferente, relacionado à transferência de anticorpos, não ao fenômeno populacional descrito de imunidade de rebanho.', 'Em revisão', null, null, null),
  ('SIM3-097', 'simulado', '3', '97', 'Medicina Preventiva e Social', 'Determinantes sociais - modelo de Dahlgren e Whitehead', 'Difícil', null, null, 'Um professor de saúde coletiva utiliza um modelo em camadas para explicar aos alunos como diferentes fatores (desde características individuais até condições socioeconômicas, culturais e ambientais mais amplas) influenciam a saúde das populações, dispostos como camadas concêntricas ao redor do indivíduo.

Esse modelo conceitual é conhecido como', 'Modelo biomédico tradicional de causalidade única', 'Tríade ecológica (agente-hospedeiro-ambiente)', 'Modelo de determinação social da saúde de Dahlgren e Whitehead', 'Pirâmide de Maslow das necessidades humanas', 'C', 'O modelo de Dahlgren e Whitehead representa os determinantes sociais da saúde em camadas concêntricas, desde características individuais até fatores estruturais mais amplos (socioeconômicos, culturais, ambientais), sendo amplamente utilizado para explicar as iniquidades em saúde.', 'A: o modelo biomédico tradicional foca em causalidade única/biológica, oposto à abordagem multicausal em camadas descrita. B: a tríade ecológica é um modelo mais simples e específico para doenças infecciosas (agente, hospedeiro, ambiente), diferente do modelo em camadas descrito. D: a pirâmide de Maslow é um modelo psicológico de motivação humana, não um modelo de determinação social da saúde.', 'Em revisão', null, null, null),
  ('SIM3-098', 'simulado', '3', '98', 'Medicina Preventiva e Social', 'Estratégia Amamenta e Alimenta Brasil', 'Fácil', null, null, 'Uma Unidade Básica de Saúde adota estratégias de incentivo ao aleitamento materno e à alimentação complementar saudável, incluindo capacitação de profissionais, grupos de apoio a gestantes e nutrizes, e orientações padronizadas sobre introdução alimentar.

Essa iniciativa está alinhada aos objetivos de qual estratégia do Ministério da Saúde?', 'Programa Farmácia Popular, voltado ao acesso a medicamentos, sem relação com aleitamento', 'Estratégia Amamenta e Alimenta Brasil, voltada à qualificação da atenção em aleitamento materno e alimentação complementar na atenção básica', 'Programa Nacional de Imunizações, focado exclusivamente na cobertura vacinal infantil', 'Política Nacional de Atenção Oncológica, sem relação com nutrição infantil', 'B', 'A Estratégia Amamenta e Alimenta Brasil tem como objetivo qualificar as práticas de promoção, proteção e apoio ao aleitamento materno e à alimentação complementar saudável na atenção básica, capacitando profissionais e organizando ações voltadas a esse fim.', 'A: o Programa Farmácia Popular trata de acesso a medicamentos, sem relação com as ações de aleitamento e alimentação complementar descritas. C: o Programa Nacional de Imunizações tem foco em vacinação, tema diferente do descrito no cenário sobre aleitamento e alimentação complementar. D: a Política Nacional de Atenção Oncológica não tem relação com o tema de aleitamento materno descrito.', 'Em revisão', null, null, null),
  ('SIM3-099', 'simulado', '3', '99', 'Medicina Preventiva e Social', 'Rede de Atenção Psicossocial (RAPS)', 'Médio', null, null, 'Um paciente com transtorno mental grave e persistente, em acompanhamento contínuo, necessita de suporte para reinserção social e comunitária, incluindo apoio para moradia e atividades de convívio social, evitando a institucionalização prolongada.

O componente da Rede de Atenção Psicossocial mais adequado para esse suporte é', 'Isolamento domiciliar sem qualquer suporte da rede de atenção psicossocial', 'Encaminhamento exclusivo para atendimento particular, sem participação da rede pública', 'Serviços Residenciais Terapêuticos e estratégias de reabilitação psicossocial de base comunitária, alinhados aos princípios da reforma psiquiátrica', 'Internação permanente em hospital psiquiátrico de longa permanência, como única alternativa disponível', 'C', 'Os Serviços Residenciais Terapêuticos e estratégias de reabilitação psicossocial de base comunitária são componentes da RAPS voltados à reinserção social de pessoas com transtornos mentais graves, alinhados aos princípios da reforma psiquiátrica, que busca substituir a institucionalização prolongada por cuidado comunitário.', 'A: o isolamento sem suporte da rede vai contra os princípios de cuidado psicossocial e reinserção social preconizados. B: o SUS oferece componentes específicos da RAPS para esse suporte, não sendo necessário exclusivamente atendimento particular. D: a internação de longa permanência é o modelo que a reforma psiquiátrica busca superar, substituindo-o por cuidado de base comunitária.', 'Em revisão', null, null, null),
  ('SIM3-100', 'simulado', '3', '100', 'Medicina Preventiva e Social', 'Humanização da assistência hospitalar (PNH)', 'Fácil', null, null, 'Um hospital público implementa medidas alinhadas à Política Nacional de Humanização, incluindo a garantia de visita ampliada aos pacientes internados, acolhimento com classificação de risco no pronto-socorro e valorização da escuta ativa entre profissionais e usuários.

Essas medidas têm como principal objetivo', 'Restringir o acesso de acompanhantes e visitantes, para maior controle administrativo do hospital', 'Reduzir exclusivamente os custos hospitalares, sem relação com a qualidade da assistência prestada', 'Aumentar o número de leitos hospitalares disponíveis, como único objetivo da humanização', 'Promover a corresponsabilização entre profissionais, gestores e usuários, valorizando a dimensão subjetiva e social em todas as práticas de atenção e gestão no SUS', 'D', 'A Política Nacional de Humanização (PNH) busca promover mudanças nos modos de gerir e cuidar, valorizando a corresponsabilização entre profissionais, gestores e usuários, e a dimensão subjetiva e social presente nas práticas de atenção à saúde.', 'A: a PNH incentiva a ampliação do acesso de acompanhantes e visitantes como parte do acolhimento humanizado, não sua restrição. B: a humanização não tem como objetivo principal a redução de custos, embora possa haver ganhos de eficiência como consequência indireta de melhores práticas. C: aumento de leitos não é objetivo central da PNH, que foca em mudanças nas práticas de cuidado e gestão.', 'Em revisão', null, null, null)
